//! DEFLATE decoder (RFC 1951) -- first draft with tracing support.

use super::CodecError;

pub struct BitReader<'a> {
    data: &'a [u8],
    pos: usize,     // next byte to load
    bitbuf: u64,
    bitcnt: u32,
}

impl<'a> BitReader<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        BitReader { data, pos: 0, bitbuf: 0, bitcnt: 0 }
    }
    #[inline]
    fn refill(&mut self) {
        while self.bitcnt <= 56 {
            if self.pos < self.data.len() {
                self.bitbuf |= (self.data[self.pos] as u64) << self.bitcnt;
                self.pos += 1;
                self.bitcnt += 8;
            } else {
                break;
            }
        }
    }
    /// Read n bits (n <= 32). Returns None at end of input.
    #[inline]
    pub fn bits(&mut self, n: u32) -> Option<u32> {
        if n == 0 {
            return Some(0);
        }
        if self.bitcnt < n {
            self.refill();
            if self.bitcnt < n {
                return None;
            }
        }
        let v = (self.bitbuf & ((1u64 << n) - 1)) as u32;
        self.bitbuf >>= n;
        self.bitcnt -= n;
        Some(v)
    }
    #[inline]
    pub fn peek(&mut self, n: u32) -> (u32, u32) {
        if self.bitcnt < n {
            self.refill();
        }
        let avail = self.bitcnt.min(n);
        ((self.bitbuf & ((1u64 << n) - 1)) as u32, avail)
    }
    #[inline]
    pub fn consume(&mut self, n: u32) {
        self.bitbuf >>= n;
        self.bitcnt -= n;
    }
    pub fn align_byte(&mut self) {
        let r = self.bitcnt % 8;
        self.consume(r);
    }
    /// Byte position of the next unread whole byte (after align).
    pub fn byte_pos(&self) -> usize {
        self.pos - (self.bitcnt / 8) as usize
    }
    pub fn set_byte_pos(&mut self, p: usize) {
        self.pos = p;
        self.bitbuf = 0;
        self.bitcnt = 0;
    }
    pub fn data(&self) -> &'a [u8] {
        self.data
    }
}

pub const FAST_BITS: u32 = 10;

pub struct Huffman {
    // fast table: entry = (symbol << 4) | len, 0 len => slow path
    fast: Vec<u32>,
    counts: [u16; 16],
    symbols: Vec<u16>,
    pub max_len: u32,
}

impl Huffman {
    /// Build from code lengths. Returns Err(kind) on over-subscription:
    /// kind 1 = over-subscribed, 2 = incomplete.
    pub fn new(lengths: &[u8]) -> (Huffman, i32) {
        let mut counts = [0u16; 16];
        for &l in lengths {
            counts[l as usize] += 1;
        }
        counts[0] = 0;
        let mut left: i32 = 1;
        let mut status = 0;
        for len in 1..16 {
            left <<= 1;
            left -= counts[len] as i32;
            if left < 0 {
                status = 1;
                break;
            }
        }
        if status == 0 && left > 0 {
            status = 2;
        }
        let mut offs = [0u16; 16];
        for len in 1..15 {
            offs[len + 1] = offs[len] + counts[len];
        }
        let mut symbols = vec![0u16; lengths.len()];
        for (s, &l) in lengths.iter().enumerate() {
            if l != 0 {
                symbols[offs[l as usize] as usize] = s as u16;
                offs[l as usize] += 1;
            }
        }
        let max_len = (1..16).rev().find(|&l| counts[l] != 0).unwrap_or(0) as u32;
        let mut h = Huffman { fast: vec![0; 1 << FAST_BITS], counts, symbols, max_len };
        if status != 1 {
            h.build_fast(lengths);
        }
        (h, status)
    }
