    #[inline]
    pub fn decode(&self, br: &mut BitReader) -> Result<u16, bool> {
        let (bits, avail) = br.peek(FAST_BITS);
        let e = self.fast[bits as usize];
        let l = e & 15;
        if l != 0 && l <= avail {
            br.consume(l);
