import sys
def db_prefix(k, n, length):
    # FKM algorithm generator for de Bruijn sequence B(k,n)
    a = [0] * (k * n)
    out = []
    def gen():
        # iterative version of db(t, p)
        stack = [(1, 1, 0)]
        # use recursion via explicit generator (python recursion depth fine for n=3)
        def db(t, p):
            if t > n:
                if n % p == 0:
                    for v in a[1:p+1]:
                        yield v
            else:
                a[t] = a[t - p]
                yield from db(t + 1, p)
                for j in range(a[t - p] + 1, k):
                    a[t] = j
                    yield from db(t + 1, t)
        yield from db(1, 1)
    for v in gen():
        out.append(v)
        if len(out) >= length: break
    return bytes(out)
if __name__ == '__main__':
    n = int(sys.argv[1])
    sys.stdout.buffer.write(db_prefix(256, 3, n))
