const zlib = require('zlib');
function prng(n, seed) { const b = Buffer.alloc(n); let x = seed >>> 0 || 1; for (let i = 0; i < n; i++) { x ^= x << 13; x >>>= 0; x ^= x >>> 17; x ^= x << 5; x >>>= 0; b[i] = x & 0xff; } return b; }
const rnd = prng(200000, 12345);
const txt = Buffer.from('abcdefghij'.repeat(30000)); // 300 KB compressible
const cases = [
  ['createGzip', rnd, {}], ['createDeflate', rnd, {}], ['createDeflateRaw', rnd, {}], ['createBrotliCompress', rnd, {}], ['createZstdCompress', rnd, {}],
  ['createGzip', rnd, {chunkSize: 1024}], ['createGzip', rnd, {highWaterMark: 1024}],
  ['createGunzip', zlib.gzipSync(txt), {}], ['createInflate', zlib.deflateSync(txt), {}], ['createInflateRaw', zlib.deflateRawSync(txt), {}], ['createUnzip', zlib.gzipSync(txt), {}], ['createUnzip', zlib.deflateSync(txt), {}],
  ['createBrotliDecompress', zlib.brotliCompressSync(txt), {}], ['createZstdDecompress', zlib.zstdCompressSync ? zlib.zstdCompressSync(txt) : null, {}],
  ['createGunzip', zlib.gzipSync(txt), {chunkSize: 1024}],
];
(async () => {
  for (const [k, input, opts] of cases) {
    if (!zlib[k] || !input) { console.log(k + ' n/a'); continue; }
    await new Promise((res) => {
      const s = zlib[k](opts);
      const sizes = [];
      s.on('data', (d) => sizes.push(d.length));
      s.on('error', (e) => { console.log(k + ' error ' + e.message); res(); });
