const zs = zlib.zstdCompressSync ? zlib.zstdCompressSync(txt) : null;
const cases = [];
const add = (k, name, input) => cases.push([k, name, input]);
for (const [k, c] of [['createGunzip', gz], ['createInflate', df], ['createInflateRaw', raw], ['createUnzip', gz], ['createBrotliDecompress', br], ['createZstdDecompress', zs]]) {
  if (!c) continue;
  add(k, 'corrupt', Buffer.from('not gzip data at all!'));
  add(k, 'truncated', c.subarray(0, c.length >> 1));
  add(k, 'trailing', Buffer.concat([c, Buffer.from('GARBAGE')]));
  add(k, 'empty', Buffer.alloc(0));
  add(k, 'noinput', null);
  add(k, 'double', Buffer.concat([c, c]));
}
function describe(e) {
  if (!e) return String(e);
  return 'ctor=' + (e.constructor && e.constructor.name) + ' name=' + e.name + ' message=' + JSON.stringify(e.message) + ' code=' + e.code + ' errno=' + e.errno + ' keys=' + JSON.stringify(Object.keys(e)) + ' own=' + JSON.stringify(Object.getOwnPropertyNames(e));
}
(async () => {
  for (const [k, name, input] of cases) {
    await new Promise((res) => {
      if (!zlib[k]) { console.log(k + ' n/a'); return res(); }
      const s = zlib[k]();
      const ev = [];
      let tot = 0;
      s.on('data', (d) => { ev.push('data(' + d.length + ')'); tot += d.length; });
      for (const e of ['end', 'finish', 'close']) s.on(e, () => ev.push(e));
