      if (input) s.write(input, (err) => ev.push('writecb(' + (err && err.message) + ')'));
      s.end((err) => ev.push('endcb(' + (err && err.message) + ')'));
      setTimeout(() => { console.log(k + ' ' + name + ': ' + ev.join(' ') + (tot ? ' total=' + tot : '')); res(); }, 20);
    });
  }
})();
