        console.log('pipeline(err case) cb err=' + (err && err.message));
        res();
      });
      setTimeout(() => { console.log('pipeline(err case) timeout'); res(); }, 500);
    });
  } catch (e) { console.log('pipeline2 ERR ' + e.message); }
  // 3c. stream.promises.pipeline
  try {
    if (stream.promises && stream.promises.pipeline) {
      const out3 = out + '.3';
      await stream.promises.pipeline(fs.createReadStream(src), zlib.createGzip(), fs.createWriteStream(out3));
      console.log('promises.pipeline ok, roundtrip=' + zlib.gunzipSync(fs.readFileSync(out3)).equals(orig));
    } else console.log('no stream.promises.pipeline');
  } catch (e) { console.log('promises.pipeline ERR ' + e.message); }
  try {
    const sp = require('stream/promises');
    const out4 = out + '.4';
    await sp.pipeline(fs.createReadStream(src), zlib.createGzip(), fs.createWriteStream(out4));
