  } catch (e) { console.log('stream/promises ERR ' + e.message); }
  // 4. Readable.from
  try {
    const r = stream.Readable.from([Buffer.from('abc'), Buffer.from('def')]);
    const gz = r.pipe(zlib.createGzip());
    const chunks = [];
    gz.on('data', c => chunks.push(c));
