            if base <= target < base + (1 << nb):
                states[i] = u
                break
        else:
            raise ZErr('no fse cell')
    return states

def ncount_write(norm, tablelog, raw=False):
    """FSE table description (as FSE_writeNCount). raw=True: write values blindly (for invalid distributions);
    in raw mode the writer stops after the last given symbol, and does not validate."""
    bits = []
    def put(v, nb):
        for i in range(nb):
            bits.append((v >> i) & 1)
    put(tablelog - 5, 4)
    size = 1 << tablelog
    remaining = size + 1
    threshold = size
    nbBits = tablelog + 1
    symbol = 0
    alpha = len(norm)
    prev0 = False
    while symbol < alpha and (raw or remaining > 1):
        if prev0:
            start = symbol
            while symbol < alpha and norm[symbol] == 0:
                symbol += 1
            if symbol == alpha:
                break
            while symbol >= start + 24:
                start += 24
                put(0xFFFF, 16)
            while symbol >= start + 3:
                start += 3
                put(3, 2)
            put(symbol - start, 2)
        count = norm[symbol]
        symbol += 1
        mx = (2 * threshold - 1) - remaining
        remaining -= abs(count)
        count += 1
        if count >= threshold:
            count += mx
        if count < mx:
            put(count, nbBits - 1)
        else:
            put(count, nbBits)
        prev0 = (count == 1)
        if remaining < 1 and not raw:
            raise ZErr('ncount: remaining < 1')
        while remaining < threshold and threshold > 1:
            nbBits -= 1
            threshold >>= 1
    if not raw and remaining != 1:
        raise ZErr('ncount: remaining != 1 (%d)' % remaining)
    while len(bits) % 8:
        bits.append(0)
    out = bytearray()
    for i in range(0, len(bits), 8):
        b = 0
        for j in range(8):
            b |= bits[i + j] << j
        out.append(b)
    return bytes(out)

def ncount_read(data, maxsym, maxlog):
    """returns (norm, tablelog, nbytes) ; raises ZErr with description"""
    if len(data) < 1:
        raise ZErr('ncount: no data')
    val = int.from_bytes(bytes(data) + b'\0' * 8, 'little')
    bitpos = 0
    def get(nb):
        nonlocal bitpos
        v = (val >> bitpos) & ((1 << nb) - 1)
        return v
    tablelog = get(4) + 5
    bitpos += 4
    if tablelog > maxlog:
        raise ZErr('ncount: tablelog too large %d' % tablelog)
    remaining = (1 << tablelog) + 1
    threshold = 1 << tablelog
    nbBits = tablelog + 1
    norm = []
    prev0 = False
    while remaining > 1:
        if len(norm) > maxsym:
            raise ZErr('ncount: too many symbols')
        if prev0:
            while True:
                r = get(2); bitpos += 2
                norm.extend([0] * r)
                if r != 3:
                    break
