        low = get(nbBits - 1)
        if low < mx:
            count = low
            bitpos += nbBits - 1
        else:
            count = get(nbBits)
            if count >= threshold:
                count -= mx
            bitpos += nbBits
        count -= 1
        remaining -= abs(count)
        norm.append(count)
        prev0 = (count == 0)
        while remaining < threshold:
            nbBits -= 1
            threshold >>= 1
    if remaining != 1:
        raise ZErr('ncount: remaining != 1')
