    if nbytes > len(data):
        raise ZErr('ncount: overrun (%d > %d)' % (nbytes, len(data)))
    return norm, tablelog, nbytes

# ---------------------------------------------------------------- Huffman
def huff_full_weights(weights):
    """weights: explicit weights for symbols 0..n-1 (the last symbol's weight implicit). returns full list"""
    total = sum(1 << (w - 1) for w in weights if w > 0)
    if total == 0:
        raise ZErr('huff: zero total')
    maxbits = total.bit_length()  # next power of two strictly greater
    rest = (1 << maxbits) - total
    if rest & (rest - 1):
        raise ZErr('huff: rest not power of 2')
    lastw = rest.bit_length()
    return list(weights) + [lastw], maxbits

def huff_codes_from_full(full):
    total = sum(1 << (w - 1) for w in full if w > 0)
    maxbits = total.bit_length() - 1
    assert total == 1 << maxbits
    rank_start = {}
    pos = 0
    for w in range(1, maxbits + 1):
        rank_start[w] = pos
        pos += sum(1 for x in full if x == w) << (w - 1)
    codes = {}
    for s, w in enumerate(full):
        if w == 0:
            continue
        nb = maxbits + 1 - w
        st = rank_start[w]
        rank_start[w] += 1 << (w - 1)
        assert st % (1 << (w - 1)) == 0
        codes[s] = (st >> (w - 1), nb)
    return codes, maxbits

def huff_weights_for(data, maxbits=11):
    """make a (not optimal but valid) huffman weight assignment for the symbols present in data"""
    from collections import Counter
    import heapq
    cnt = Counter(data)
    syms = sorted(cnt)
    if len(syms) == 1:
        # need at least 2 symbols: add a dummy symbol
        s = syms[0]
        other = s + 1 if s < 255 else s - 1
        syms = sorted([s, other]); cnt[other] = 0
    # build huffman lengths
    heap = [(cnt[s], i, [s]) for i, s in enumerate(syms)]
    heapq.heapify(heap)
    depth = {s: 0 for s in syms}
    k = len(heap)
    while len(heap) > 1:
        a = heapq.heappop(heap); b = heapq.heappop(heap)
        for s in a[2] + b[2]:
            depth[s] += 1
        k += 1
        heapq.heappush(heap, (a[0] + b[0], k, a[2] + b[2]))
    mx = max(depth.values())
    if mx > maxbits:
        # fall back: flat-ish lengths
        n = len(syms)
        L = (n - 1).bit_length()
        depth = {s: L for s in syms}
        # fix kraft: some symbols shorter
        tot = n * (1 << (L - L))
        mx = L
        # kraft sum = n / 2^L <= 1; fill by shortening first symbols
        kraft = n
        i = 0
        while kraft < (1 << L) and i < n:
            # shortening symbol i by 1 adds 1 unit at depth L... doubles its contribution
            s = syms[i]
            d = depth[s]
            add = 1 << (L - d)
            if kraft + add <= (1 << L) and d > 1:
                depth[s] -= 1
                kraft += add
            else:
                i += 1
        assert kraft == (1 << L), (kraft, L)
    full = [0] * (max(syms) + 1)
    for s in syms:
        full[s] = mx + 1 - depth[s]
    # verify kraft
    total = sum(1 << (w - 1) for w in full if w > 0)
    assert total == 1 << mx, (total, mx)
    return full

def huff_stream(data, codes, extra_low_bits=None, marker=True):
    bw = BW()
    for b in data:
        c, nb = codes[b]
        bw.add(c, nb)
    return bw.tobytes(marker=marker, extra_low_bits=extra_low_bits)

def huff_tree_direct(full):
    """direct representation: header byte = 127 + number of explicit weights"""
    # explicit weights: all but the last nonzero symbol (which must be the last element)
    assert full[-1] > 0
    expl = full[:-1]
    n = len(expl)
    assert 1 <= n <= 128
    out = bytearray([127 + n])
    for i in range(0, n, 2):
        hi = expl[i]
        lo = expl[i + 1] if i + 1 < n else 0
        out.append((hi << 4) | lo)
    return bytes(out)

def huff_tree_direct_raw(expl):
    n = len(expl)
    out = bytearray([127 + n])
    for i in range(0, n, 2):
        hi = expl[i]
        lo = expl[i + 1] if i + 1 < n else 0
        out.append(((hi & 15) << 4) | (lo & 15))
    return bytes(out)

def fse_encode_2state(syms, norm, tablelog, ncount=None, final1=None, final2=None):
    """FSE-compressed huffman weights: returns (ncount bytes + bitstream). syms = explicit weights in order."""
    table = fse_build(norm, tablelog)
    s1 = syms[0::2]
    s2 = syms[1::2]
    st1 = fse_states(table, s1, final1)
    st2 = fse_states(table, s2, final2)
    bw = BW()
    bw.add(st1[0], tablelog)
    bw.add(st2[0], tablelog)
    n = len(syms)
    # decode order: sym0 (state1) update1, sym1 (state2) update2, ... ; last two symbols do not have updates
    # in libzstd the update after symbol n-2 overflows; we write updates for symbols 0..n-3
    for i in range(n - 2):
        if i % 2 == 0:
            j = i // 2
            s, nb, base = table[st1[j]]
            bw.add(st1[j + 1] - base, nb)
        else:
            j = i // 2
            s, nb, base = table[st2[j]]
            bw.add(st2[j + 1] - base, nb)
    nc = ncount if ncount is not None else ncount_write(norm, tablelog)
    return nc, bw.tobytes(), table, st1, st2

# ---------------------------------------------------------------- frame / block builders
def fhd_byte(fcs_flag=0, single=0, unused=0, reserved=0, checksum=0, did_flag=0):
    return (fcs_flag << 6) | (single << 5) | (unused << 4) | (reserved << 3) | (checksum << 2) | did_flag

def frame_header(fcs=None, single=None, checksum=False, did=None, did_size=None, fcs_size=None,
                 wlog=None, wdesc=None, unused=0, reserved=0, magic=MAGIC):
    """build magic + frame header. fcs: content size or None. single: Single_Segment flag (default: 1 if fcs given and wdesc/wlog not given)"""
    if single is None:
        single = 1 if (fcs is not None and wdesc is None and wlog is None) else 0
    if did is None:
        did_flag = 0
        did_bytes = b''
    else:
        if did_size is None:
            did_size = 1 if did < 256 else (2 if did < 65536 else 4)
        did_flag = {0: 0, 1: 1, 2: 2, 4: 3}[did_size]
        did_bytes = did.to_bytes(did_size, 'little') if did_size else b''
    if fcs is None:
        fcs_flag = 0
        fcs_bytes = b''
        if single:
            raise ValueError('single segment requires fcs')
    else:
        if fcs_size is None:
            if single and fcs < 256:
                fcs_size = 1
            elif 256 <= fcs < 65536 + 256:
                fcs_size = 2
            elif fcs < 256:
                fcs_size = 2 if not single else 1
            elif fcs < 1 << 32:
                fcs_size = 4
            else:
                fcs_size = 8
        if fcs_size == 1:
            assert single
            fcs_flag = 0
            fcs_bytes = bytes([fcs])
        elif fcs_size == 2:
            fcs_flag = 1
            fcs_bytes = (fcs - 256).to_bytes(2, 'little')
        elif fcs_size == 4:
            fcs_flag = 2
            fcs_bytes = fcs.to_bytes(4, 'little')
        else:
            fcs_flag = 3
            fcs_bytes = fcs.to_bytes(8, 'little')
    fhd = fhd_byte(fcs_flag, single, unused, reserved, 1 if checksum else 0, did_flag)
    out = bytearray(magic)
    out.append(fhd)
    if not single:
        if wdesc is None:
            wl = wlog if wlog is not None else 20
            wdesc = (wl - 10) << 3
        out.append(wdesc)
    out += did_bytes
    out += fcs_bytes
    return bytes(out)

def block_header(btype, size, last):
    v = (1 if last else 0) | (btype << 1) | (size << 3)
    return v.to_bytes(3, 'little')

def raw_block(data, last=True):
    return block_header(0, len(data), last) + bytes(data)

def rle_block(byte, n, last=True):
    return block_header(1, n, last) + bytes([byte])

def comp_block(content, last=True, size=None):
    return block_header(2, len(content) if size is None else size, last) + bytes(content)

def xxh64(data, seed=0):
    P1 = 11400714785074694791; P2 = 14029467366897019727; P3 = 1609587929392839161
    P4 = 9650029242287828579; P5 = 2870177450012600261
    M = (1 << 64) - 1
    def rotl(x, r): return ((x << r) | (x >> (64 - r))) & M
    def rnd(acc, inp):
        acc = (acc + inp * P2) & M
        acc = rotl(acc, 31)
        return (acc * P1) & M
    def merge(acc, val):
        val = rnd(0, val)
        acc ^= val
        return (acc * P1 + P4) & M
    n = len(data)
    p = 0
    if n >= 32:
        v1 = (seed + P1 + P2) & M; v2 = (seed + P2) & M; v3 = seed; v4 = (seed - P1) & M
        while p + 32 <= n:
            v1 = rnd(v1, int.from_bytes(data[p:p + 8], 'little')); p += 8
            v2 = rnd(v2, int.from_bytes(data[p:p + 8], 'little')); p += 8
            v3 = rnd(v3, int.from_bytes(data[p:p + 8], 'little')); p += 8
            v4 = rnd(v4, int.from_bytes(data[p:p + 8], 'little')); p += 8
        h = (rotl(v1, 1) + rotl(v2, 7) + rotl(v3, 12) + rotl(v4, 18)) & M
        h = merge(h, v1); h = merge(h, v2); h = merge(h, v3); h = merge(h, v4)
    else:
        h = (seed + P5) & M
    h = (h + n) & M
    while p + 8 <= n:
        k1 = rnd(0, int.from_bytes(data[p:p + 8], 'little'))
        h ^= k1
        h = (rotl(h, 27) * P1 + P4) & M
        p += 8
    if p + 4 <= n:
        h ^= (int.from_bytes(data[p:p + 4], 'little') * P1) & M
        h = (rotl(h, 23) * P2 + P3) & M
        p += 4
    while p < n:
        h ^= (data[p] * P5) & M
        h = (rotl(h, 11) * P1) & M
        p += 1
    h ^= h >> 33
    h = (h * P2) & M
    h ^= h >> 29
    h = (h * P3) & M
    h ^= h >> 32
    return h

def checksum(data):
    return (xxh64(bytes(data)) & 0xFFFFFFFF).to_bytes(4, 'little')

# literals sections
def lit_raw(data, fmt=None):
    n = len(data)
    if fmt is None:
        fmt = 1 if n < 32 else (2 if n < 4096 else 3)
    return lit_hdr_rawrle(0, n, fmt) + bytes(data)

def lit_rle(byte, n, fmt=None):
    if fmt is None:
        fmt = 1 if n < 32 else (2 if n < 4096 else 3)
    return lit_hdr_rawrle(1, n, fmt) + bytes([byte])

def lit_hdr_rawrle(ltype, n, fmt, sf_bit3=0):
    if fmt == 1:
        assert n < 32
        return bytes([ltype | (n << 3)])  # bit2 = 0, size in bits 3..7
    if fmt == 2:
        assert n < 4096
        v = ltype | (1 << 2) | (n << 4)
        return v.to_bytes(2, 'little')
    if fmt == 3:
        assert n < (1 << 20)
        v = ltype | (3 << 2) | (n << 4)
        return v.to_bytes(3, 'little')

def lit_hdr_comp(ltype, sf, regen, csize):
    """ltype 2 compressed / 3 treeless. sf=0: 1 stream 3 bytes (10 bits); 1: 4 streams 3 bytes; 2: 4 streams 4 bytes 14 bits; 3: 4 streams 5 bytes 18 bits"""
    if sf in (0, 1):
        nb, nbytes = 10, 3
    elif sf == 2:
        nb, nbytes = 14, 4
    else:
        nb, nbytes = 18, 5
    assert regen < (1 << nb) and csize < (1 << nb), (regen, csize, sf)
    v = ltype | (sf << 2) | (regen << 4) | (csize << (4 + nb))
    return v.to_bytes(nbytes, 'little')

def split4(data):
    n = len(data)
    seg = (n + 3) // 4
    return [data[0:seg], data[seg:2 * seg], data[2 * seg:3 * seg], data[3 * seg:]]

def lit_huff(data, full=None, streams=None, sf=None, treeless=False, tree=None, jump=None, regen=None, csize=None,
             stream_bytes=None):
    """compressed literals. full: full weight list; tree: explicit tree description bytes (default direct)."""
    data = bytes(data)
    if full is None:
        full = huff_weights_for(data)
    codes, maxbits = huff_codes_from_full(full)
    if streams is None:
        streams = 1 if len(data) < 256 else 4
    if stream_bytes is None:
        if streams == 1:
            stream_bytes = [huff_stream(data, codes)]
        else:
            stream_bytes = [huff_stream(p, codes) for p in split4(data)]
    if streams == 1:
        body = stream_bytes[0]
    else:
        if jump is None:
            jump = [len(stream_bytes[0]), len(stream_bytes[1]), len(stream_bytes[2])]
        body = b''.join(x.to_bytes(2, 'little') for x in jump) + b''.join(stream_bytes)
    if treeless:
        th = b''
    else:
        th = tree if tree is not None else huff_tree_direct(full)
    comp = th + body
    if regen is None:
        regen = len(data)
    if csize is None:
        csize = len(comp)
    if sf is None:
        if streams == 1:
            sf = 0
        else:
            m = max(regen, csize)
            sf = 1 if m < 1024 else (2 if m < 16384 else 3)
    ltype = 3 if treeless else 2
    return lit_hdr_comp(ltype, sf, regen, csize) + comp

# sequences
def nbseq_bytes(n, form=None):
    if form is None:
        form = 1 if n < 128 else (2 if n < 0x7F00 else 3)
    if form == 1:
        assert n < 128
        return bytes([n])
    if form == 2:
        assert n < 0x8000
        return bytes([(n >> 8) + 128, n & 0xFF])
    if form == 3:
        v = n - 0x7F00
        assert 0 <= v < 65536
        return bytes([255, v & 0xFF, v >> 8])

class Tab:
    """table spec for sequence encoding. kind: 'pre', 'rle', 'fse', 'rep'"""
    def __init__(self, kind, sym=None, norm=None, log=None, table=None, desc=None):
        self.kind = kind; self.sym = sym; self.norm = norm; self.log = log; self.table = table; self.desc = desc

def seq_section(seqs, ll=None, of=None, ml=None, nb_form=None, modes_extra=0, extra_low_bits=None,
                field_override=None, nbseq=None, marker=True, desc_override=None, states_override=None):
    """seqs: list of (lit_len, match_len, offset_value). returns sequences section bytes.
    ll/of/ml: Tab (default predefined). returns bytes"""
    ll = ll or Tab('pre'); of = of or Tab('pre'); ml = ml or Tab('pre')
    n = len(seqs) if nbseq is None else nbseq
    out = bytearray(nbseq_bytes(n, nb_form))
    if n == 0 and not seqs:
        return bytes(out)
    modes = 0
    descs = []
    tabs = []
    for t, dflt, dlog, kind_name in ((ll, LL_DEF, LL_DEF_LOG, 'll'), (of, OF_DEF, OF_DEF_LOG, 'of'), (ml, ML_DEF, ML_DEF_LOG, 'ml')):
        if t.kind == 'pre':
            m = 0; tab = fse_build(dflt, dlog); log = dlog; d = b''
        elif t.kind == 'rle':
            m = 1; tab = [(t.sym, 0, 0)]; log = 0; d = bytes([t.sym])
        elif t.kind == 'fse':
            m = 2; tab = fse_build(t.norm, t.log) if t.table is None else t.table; log = t.log
            d = t.desc if t.desc is not None else ncount_write(t.norm, t.log)
        elif t.kind == 'rep':
            m = 3; tab = t.table; log = t.log; d = b''
        tabs.append((tab, log))
        descs.append(d)
        modes = (modes << 2) | m
    modes = (modes << 2) | modes_extra
    out.append(modes)
    for d in descs:
        out += d
    if desc_override is not None:
        out = out[:len(out) - sum(len(d) for d in descs)] + desc_override
    (lltab, lllog), (oftab, oflog), (mltab, mllog) = tabs
    llc = [ll_code(s[0]) for s in seqs]
    mlc = [ml_code(s[1]) for s in seqs]
    ofc = [of_code(s[2]) for s in seqs]
    if states_override:
        lls, ofs, mls = states_override
    else:
        lls = fse_states(lltab, llc)
        ofs = fse_states(oftab, ofc)
        mls = fse_states(mltab, mlc)
    bw = BW()
    if seqs:
        bw.add(lls[0], lllog); bw.add(ofs[0], oflog); bw.add(mls[0], mllog)
    for i, (L, M, O) in enumerate(seqs):
        bw.add(O - (1 << ofc[i]), ofc[i])
        bw.add(M - ML_BASE[mlc[i]], ML_BITS[mlc[i]])
        bw.add(L - LL_BASE[llc[i]], LL_BITS[llc[i]])
        if i < len(seqs) - 1:
            for tab, st in ((lltab, lls), (mltab, mls), (oftab, ofs)):
                s, nb, base = tab[st[i]]
                bw.add(st[i + 1] - base, nb)
    if field_override:
        field_override(bw)
    out += bw.tobytes(marker=marker, extra_low_bits=extra_low_bits)
    return bytes(out)

def frame(blocks_bytes, fcs=None, checksum_of=None, **hdr):
    """blocks_bytes: already-built blocks. checksum_of: decoded content for checksum (or None for no checksum)"""
    h = frame_header(fcs=fcs, checksum=checksum_of is not None, **hdr)
    out = h + b''.join(blocks_bytes)
    if checksum_of is not None:
        out += checksum(checksum_of)
    return out

def skippable(n=0, content=None, magic_low=0):
    if content is None:
        content = bytes(n)
    return (0x184D2A50 + magic_low).to_bytes(4, 'little') + len(content).to_bytes(4, 'little') + bytes(content)

# ---------------------------------------------------------------- simple python decoder/parser (spec-strict, records structure)
class PyDec:
    def __init__(self, data, log=False):
        self.d = bytes(data)
        self.log = [] if log else None

    def note(self, *a):
        if self.log is not None:
            self.log.append(a)

    def decode(self):
        d = self.d
        p = 0
        out = bytearray()
        while p < len(d):
            if len(d) - p < 4:
                raise ZErr('trailing < 4 bytes')
            m = int.from_bytes(d[p:p + 4], 'little')
            if (m & 0xFFFFFFF0) == 0x184D2A50:
                if len(d) - p < 8:
                    raise ZErr('skippable header truncated')
                sz = int.from_bytes(d[p + 4:p + 8], 'little')
                self.note('skippable', p, sz)
                if p + 8 + sz > len(d):
                    raise ZErr('skippable content truncated')
                p += 8 + sz
                continue
            if m != 0xFD2FB528:
                raise ZErr('bad magic')
            p = self.frame(p + 4, out)
        return bytes(out)

    def frame(self, p, out):
        d = self.d
        start_out = len(out)
        if p >= len(d):
            raise ZErr('fhd missing')
        fhd = d[p]; p += 1
        fcs_flag = fhd >> 6; single = (fhd >> 5) & 1; reserved = (fhd >> 3) & 1; chk = (fhd >> 2) & 1; didf = fhd & 3
        if reserved:
            raise ZErr('reserved bit')
        wsize = None
        if not single:
            if p >= len(d): raise ZErr('wd missing')
            wd = d[p]; p += 1
            e = wd >> 3; mant = wd & 7
            base = 1 << (10 + e)
            wsize = base + (base >> 3) * mant
        dsz = [0, 1, 2, 4][didf]
        if p + dsz > len(d): raise ZErr('did truncated')
        did = int.from_bytes(d[p:p + dsz], 'little'); p += dsz
        fsz = [1 if single else 0, 2, 4, 8][fcs_flag]
        if p + fsz > len(d): raise ZErr('fcs truncated')
        fcs = int.from_bytes(d[p:p + fsz], 'little') if fsz else None
        if fsz == 2: fcs += 256
        p += fsz
        if single:
            wsize = fcs
        self.note('frame', dict(fhd=fhd, single=single, chk=chk, did=did, fcs=fcs, wsize=wsize))
        self.huf = None  # (codes table) for treeless
        self.fse = {'ll': None, 'of': None, 'ml': None}
        self.rep = [1, 4, 8]
        bmax = min(wsize if wsize else 1 << 17, 1 << 17)
        self.frame_start = start_out
        while True:
            if p + 3 > len(d): raise ZErr('block header truncated')
            bh = int.from_bytes(d[p:p + 3], 'little'); p += 3
            last = bh & 1; bt = (bh >> 1) & 3; bs = bh >> 3
            self.note('block', p - 3, dict(last=last, type=bt, size=bs))
            if bt == 3: raise ZErr('reserved block type')
            if bt == 1:
                if p + 1 > len(d): raise ZErr('rle truncated')
                if bs > bmax: raise ZErr('block too large')
                out += bytes([d[p]]) * bs
                p += 1
            else:
                if bs > bmax: raise ZErr('block too large')
                if p + bs > len(d): raise ZErr('block content truncated')
                if bt == 0:
                    out += d[p:p + bs]
                else:
                    blk = self.comp_block(d[p:p + bs], out, p)
                    if blk > bmax: raise ZErr('decoded block too large')
                p += bs
            if last:
                break
        if fcs is not None and len(out) - start_out != fcs:
            raise ZErr('fcs mismatch %d vs %d' % (len(out) - start_out, fcs))
        if chk:
            if p + 4 > len(d): raise ZErr('checksum truncated')
            if checksum(out[start_out:]) != d[p:p + 4]: raise ZErr('checksum mismatch')
            p += 4
        return p

    def comp_block(self, b, out, abspos):
        # literals
        if len(b) < 1: raise ZErr('empty compressed block')
        lt = b[0] & 3; sf = (b[0] >> 2) & 3
        if lt in (0, 1):
            if sf in (0, 2):
                regen = b[0] >> 3; hs = 1
            elif sf == 1:
                if len(b) < 2: raise ZErr('lit hdr trunc')
                regen = (b[0] >> 4) | (b[1] << 4); hs = 2
            else:
                if len(b) < 3: raise ZErr('lit hdr trunc')
                regen = (b[0] >> 4) | (b[1] << 4) | (b[2] << 12); hs = 3
            if lt == 0:
                if hs + regen > len(b): raise ZErr('raw literals overrun')
                lits = b[hs:hs + regen]; q = hs + regen
            else:
                if hs + 1 > len(b): raise ZErr('rle literals overrun')
                lits = bytes([b[hs]]) * regen; q = hs + 1
            self.note('lits', dict(type=lt, sf=sf, regen=regen, hs=hs))
        else:
            if sf in (0, 1):
                hs = 3; nb = 10
            elif sf == 2:
                hs = 4; nb = 14
            else:
                hs = 5; nb = 18
            if len(b) < hs: raise ZErr('lit hdr trunc')
            v = int.from_bytes(b[:hs], 'little')
            regen = (v >> 4) & ((1 << nb) - 1); csize = (v >> (4 + nb)) & ((1 << nb) - 1)
            streams = 1 if sf == 0 else 4
            if hs + csize > len(b): raise ZErr('comp literals overrun')
            c = b[hs:hs + csize]
            q = hs + csize
            tpos = 0
            info = dict(type=lt, sf=sf, regen=regen, csize=csize, hs=hs, streams=streams)
            if lt == 2:
                tsize, self.huf = self.huff_tree(c)
                info['tree_size'] = tsize
                info['tree_kind'] = 'direct' if c[0] >= 128 else 'fse'
                tpos = tsize
            else:
                if self.huf is None: raise ZErr('treeless without table')
            self.note('lits', info)
            lits = self.huff_decode(c[tpos:], regen, streams)
        # sequences
        s = b[q:]
        if len(s) < 1: raise ZErr('no seq header')
        b0 = s[0]
        if b0 == 0:
            nseq = 0; r = 1
        elif b0 < 128:
            nseq = b0; r = 1
        elif b0 < 255:
            if len(s) < 2: raise ZErr('nbseq trunc')
            nseq = ((b0 - 128) << 8) + s[1]; r = 2
        else:
            if len(s) < 3: raise ZErr('nbseq trunc')
            nseq = s[1] + (s[2] << 8) + 0x7F00; r = 3
        if nseq == 0:
            self.note('seqs', dict(nseq=0, extra=len(s) - r))
            if r != len(s): raise ZErr('nbseq 0 but extra bytes')
            out += lits
            return len(lits)
        if len(s) < r + 1: raise ZErr('modes missing')
        modes = s[r]; r += 1
        if modes & 3: raise ZErr('reserved mode bits')
        mdesc = {}
        for name, sh, dflt, dlog, maxsym, maxlog in (('ll', 6, LL_DEF, 6, 35, 9), ('of', 4, OF_DEF, 5, 31, 8), ('ml', 2, ML_DEF, 6, 52, 9)):
            m = (modes >> sh) & 3
            if m == 0:
                self.fse[name] = (fse_build(dflt, dlog), dlog)
            elif m == 1:
                if r >= len(s): raise ZErr('rle sym missing')
                sym = s[r]; r += 1
                if sym > maxsym: raise ZErr('rle sym out of range')
                self.fse[name] = ([(sym, 0, 0)], 0)
            elif m == 2:
                norm, log, nbytes = ncount_read(s[r:], maxsym, maxlog)
                self.fse[name] = (fse_build(norm, log), log)
                mdesc[name + '_desc'] = (r, nbytes)
                r += nbytes
            else:
                if self.fse[name] is None: raise ZErr('repeat without table')
            mdesc[name] = m
        self.note('seqs', dict(nseq=nseq, modes=modes, **mdesc, bitstream_off=r, bitstream_len=len(s) - r))
        br = BR(s[r:])
        (lt_, ll_log), (ot_, of_log), (mt_, ml_log) = self.fse['ll'], self.fse['of'], self.fse['ml']
        lls = br.read(ll_log); ofs = br.read(of_log); mls = br.read(ml_log)
        lp = 0
        total = 0
        for i in range(nseq):
            llc = lt_[lls][0]; ofc = ot_[ofs][0]; mlc = mt_[mls][0]
            if llc > 35 or mlc > 52: raise ZErr('code out of range')
            ov = (1 << ofc) + br.read(ofc)
            ml = ML_BASE[mlc] + br.read(ML_BITS[mlc])
            ll = LL_BASE[llc] + br.read(LL_BITS[llc])
            if ov > 3:
                off = ov - 3
                self.rep = [off, self.rep[0], self.rep[1]]
            else:
                idx = ov - 1 + (1 if ll == 0 else 0)
                if idx == 0:
                    off = self.rep[0]
                elif idx == 3:
                    off = self.rep[0] - 1
                    self.rep = [off, self.rep[0], self.rep[1]]
                else:
                    off = self.rep[idx]
                    if idx == 1:
                        self.rep = [off, self.rep[0], self.rep[2]]
                    else:
                        self.rep = [off, self.rep[0], self.rep[1]]
            if i < nseq - 1:
                s_, nb, base = lt_[lls]; lls = base + br.read(nb)
                s_, nb, base = mt_[mls]; mls = base + br.read(nb)
                s_, nb, base = ot_[ofs]; ofs = base + br.read(nb)
            if lp + ll > len(lits): raise ZErr('literal length exceeds literals')
            out += lits[lp:lp + ll]; lp += ll
            if off == 0 or off > len(out) - self.frame_start: raise ZErr('offset too large %d > %d' % (off, len(out) - self.frame_start))
            for k in range(ml):
                out.append(out[-off])
            total += ll + ml
        if br.overflow(): raise ZErr('seq bitstream overflow')
        if not br.finished(): raise ZErr('seq bitstream not fully consumed (%d bits left)' % br.pos)
        out += lits[lp:]
        total += len(lits) - lp
        return total

    def huff_tree(self, c):
        if len(c) < 1: raise ZErr('no tree')
        hb = c[0]
        if hb >= 128:
            n = hb - 127
            nbytes = (n + 1) // 2
            if 1 + nbytes > len(c): raise ZErr('tree direct trunc')
            ws = []
            for i in range(n):
                byte = c[1 + i // 2]
                ws.append(byte >> 4 if i % 2 == 0 else byte & 15)
            size = 1 + nbytes
        else:
            if 1 + hb > len(c): raise ZErr('tree fse trunc')
            fc = c[1:1 + hb]
            norm, log, nb = ncount_read(fc, 15, 6)
            table = fse_build(norm, log)
            br = BR(fc[nb:])
            s1 = br.read(log); s2 = br.read(log)
            ws = []
            while True:
                if len(ws) > 255: raise ZErr('too many weights')
                sym, nbb, base = table[s1]; ws.append(sym); s1 = base + br.read(nbb)
                if br.overflow():
                    ws.append(table[s2][0]); break
                sym, nbb, base = table[s2]; ws.append(sym); s2 = base + br.read(nbb)
                if br.overflow():
                    ws.append(table[s1][0]); break
            size = 1 + hb
        if any(w > 11 for w in ws): raise ZErr('weight > 11')
        full, maxbits = huff_full_weights(ws)
        if maxbits > 11: raise ZErr('maxbits > 11')
        codes, mb = huff_codes_from_full(full)
        dec = {}
        for s, (code, nb) in codes.items():
            dec[(code, nb)] = s
        return size, (dec, mb, ws)

    def huff_decode(self, c, regen, streams):
        dec, mb, ws = self.huf
        def one(data, n):
            br = BR(data)
            o = bytearray()
            for _ in range(n):
                v = br.peek(mb)
                for L in range(1, mb + 1):
                    code = v >> (mb - L)
                    if (code, L) in dec:
                        o.append(dec[(code, L)]); br.read(L); break
                else:
                    raise ZErr('bad huffman code')
            if br.overflow(): raise ZErr('huff stream overflow')
            if not br.finished(): raise ZErr('huff stream not fully consumed (%d)' % br.pos)
            return bytes(o)
        if streams == 1:
            return one(c, regen)
        if len(c) < 6: raise ZErr('jump table trunc')
        s1, s2, s3 = struct.unpack('<HHH', c[:6])
        if 6 + s1 + s2 + s3 > len(c): raise ZErr('jump table overrun')
        seg = (regen + 3) // 4
        p = 6
        o = b''
        sizes = [s1, s2, s3, len(c) - 6 - s1 - s2 - s3]
        for k in range(4):
            n = seg if k < 3 else regen - 3 * seg
            if n < 0: raise ZErr('regen too small for 4 streams')
            o += one(c[p:p + sizes[k]], n)
            p += sizes[k]
        return o

def pydec(data):
    try:
        return {'ok': True, 'out_hex': PyDec(data).decode().hex()}
    except ZErr as e:
        return {'ok': False, 'message': str(e)}

def parse_log(data):
    d = PyDec(data, log=True)
    try:
        d.decode()
        err = None
    except ZErr as e:
        err = str(e)
    return d.log, err

