    return 'ERR %s%s' % (r['message'], (' (%s)' % r['code']) if r.get('code') else '')

RESULTS_FILE = '/tmp/agent_b/all_results.json'

def record(results):
    db = {}
    if os.path.exists(RESULTS_FILE):
        db = json.load(open(RESULTS_FILE))
    for name, hx, o in results:
        db[name] = {'name': name, 'hex': hx, 'orig': o}
    json.dump(db, open(RESULTS_FILE, 'w'), indent=0)

def run_all(cases, show=True, ref=True, rec=True, maxhex=80):
    """cases: list of (name, bytes). prints orig/node/ref results."""
    o = run_orig(cases)
    n = run_node(cases)
    out = []
    for (name, b), ro, rn in zip(cases, o, n):
        rr = run_ref(b) if ref else None
        out.append((name, b, ro, rn, rr))
        if show:
            print('%-40s %-14s orig: %s' % (name, b.hex()[:14], fmt(ro, maxhex)))
            print('%-40s %-14s node: %s%s' % ('', '', fmt(rn, maxhex), ('   ref: ' + fmt(rr, maxhex)) if rr else ''))
    if rec:
        record([(name, b.hex(), {k: v for k, v in ro.items() if k != 'code'}) for name, b, ro, rn, rr in out])
    return out

