const zlib = require('zlib');
async function runCS(C, fmt, parts) {
  const s = new C(fmt); const w = s.writable.getWriter(); const r = s.readable.getReader();
  for (const p of parts) w.write(p);
  const cp = w.close().catch(e => 'CLOSE_ERR ' + e.message);
  const chunks = [];
  while (true) { const { done, value } = await r.read(); if (done) break; chunks.push(value); }
  await cp;
  return { chunks, all: Buffer.concat(chunks.map(c => Buffer.from(c.buffer, c.byteOffset, c.byteLength))) };
}
(async () => {
  for (const fmt of ['gzip', 'deflate', 'deflate-raw']) {
    const e1 = await runCS(CompressionStream, fmt, []);
    const e2 = await runCS(CompressionStream, fmt, [new Uint8Array(0)]);
    console.log('CS ' + fmt + ' no writes: chunks=' + e1.chunks.length + ' sizes=' + JSON.stringify(e1.chunks.map(c => c.length)) + ' hex=' + e1.all.toString('hex') + ' | one empty write: chunks=' + e2.chunks.length + ' hex=' + e2.all.toString('hex'));
    const msg = Buffer.from('single byte chunk test, abcabcabc');
    const parts = [...msg].map(b => new Uint8Array([b]));
    const s1 = await runCS(CompressionStream, fmt, parts);
    const sync = { gzip: zlib.gzipSync, deflate: zlib.deflateSync, 'deflate-raw': zlib.deflateRawSync }[fmt](msg);
    const back = await runCS(DecompressionStream, fmt, [...s1.all].map(b => new Uint8Array([b])));
    console.log('CS ' + fmt + ' single-byte chunks: chunks=' + s1.chunks.length + ' equalsSync=' + s1.all.equals(sync) + ' | DS single-byte chunks back: chunks=' + back.chunks.length + ' ok=' + back.all.equals(msg));
    // decompress of empty-compressed
    const de = await runCS(DecompressionStream, fmt, [e1.all]);
    console.log('DS ' + fmt + ' of empty-compressed: chunks=' + de.chunks.length + ' sizes=' + JSON.stringify(de.chunks.map(c => c.length)));
  }
})().catch(e => console.log('ERR ' + e.message));
