const z = require('zlib'); const fs = require('fs');
const C = z.constants;
function rng(seed) { let s = seed >>> 0; return () => { s = (s * 1664525 + 1013904223) >>> 0; return s; }; }
const inputs = [];
const r = rng(12345);
const words = 'the quick brown fox jumps over lazy dog lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua brotli compression stream window block'.split(' ');
function text(n, seed) { const g = rng(seed); let s = ''; while (s.length < n) { s += words[g() % words.length] + ((g() % 7) == 0 ? '. ' : ' '); } return Buffer.from(s.slice(0, n)); }
function rand(n, seed) { const g = rng(seed); const b = Buffer.alloc(n); for (let i = 0; i < n; i++) b[i] = g() >>> 24; return b; }
function lowent(n, seed) { const g = rng(seed); const b = Buffer.alloc(n); for (let i = 0; i < n; i++) b[i] = 97 + ((g() >>> 24) % 4); return b; }
function mixed(n, seed) { const g = rng(seed); const parts = []; let t = 0; while (t < n) { const k = g() % 3; const m = 50 + g() % 500; parts.push(k == 0 ? text(m, g()) : k == 1 ? rand(m, g()) : lowent(m, g())); t += m; } return Buffer.concat(parts).slice(0, n); }
function utf8(n, seed) { const g = rng(seed); let s = ''; const al = 'aäöüßéèêñ漢字かなカナ😀 \n'; while (Buffer.byteLength(s) < n) s += al[g() % al.length]; return Buffer.from(s).slice(0, n); }
