inputs.push(['one', Buffer.from('x')]);
inputs.push(['zeros4k', Buffer.alloc(4096)]);
inputs.push(['text200', text(200, 1)]);
inputs.push(['text5k', text(5000, 2)]);
inputs.push(['text40k', text(40000, 3)]);
inputs.push(['rand300', rand(300, 4)]);
inputs.push(['rand5k', rand(5000, 5)]);
inputs.push(['lowent8k', lowent(8000, 6)]);
inputs.push(['mixed20k', mixed(20000, 7)]);
inputs.push(['utf8_6k', utf8(6000, 8)]);
