import zlib, struct
def raw(data):
    c = zlib.compressobj(9, zlib.DEFLATED, -15)
    return c.compress(data) + c.flush()
def gz(data, flags=0, extra=b"", name=b"", comment=b"", hcrc=False):
    hdr = bytearray(b"\x1f\x8b\x08") + bytes([flags]) + b"\0\0\0\0" + b"\0\xff"
    if flags & 4: hdr += struct.pack("<H", len(extra)) + extra
    if flags & 8: hdr += name + b"\0"
    if flags & 16: hdr += comment + b"\0"
    if flags & 2: hdr += struct.pack("<H", zlib.crc32(bytes(hdr)) & 0xffff)
    return bytes(hdr) + raw(data) + struct.pack("<II", zlib.crc32(data), len(data) & 0xffffffff)
