const stream = require('stream');
const s = zlib.createGzip();
const out = [];
s.on('data', (d) => out.push(d));
s.write('part one ');
try { s.flush(); } catch (e) { console.log('flush() threw ' + e.constructor.name + ': ' + e.message); }
try { s.flush(zlib.constants.Z_SYNC_FLUSH, () => console.log('flush cb called')); } catch (e) { console.log('flush(kind, cb) threw ' + e.constructor.name + ': ' + e.message); }
try { s.flush(() => console.log('flush cb called')); } catch (e) { console.log('flush(cb) threw ' + e.constructor.name + ': ' + e.message); }
s.write('part two');
s.end();
s.on('end', () => console.log('output equals gzipSync of all: ' + Buffer.concat(out).equals(zlib.gzipSync('part one part two'))));
console.log('typeof stream.finished=' + typeof stream.finished);
if (typeof stream.finished === 'function') {
  const s2 = zlib.createGunzip();
  s2.resume();
  stream.finished(s2, (err) => console.log('finished cb (ok case) err=' + (err && err.message)));
  s2.end(zlib.gzipSync('x'));
  const s3 = zlib.createGunzip();
  s3.resume();
  s3.on('error', () => {});
  stream.finished(s3, (err) => console.log('finished cb (error case) err=' + (err && err.message)));
  s3.end(Buffer.from('bad'));
}
const { once } = require('events');
(async () => { const s4 = zlib.createDeflate(); s4.resume(); s4.end('abc'); await once(s4, 'end'); console.log('events.once(end) resolved'); })();
