  const rClosedP = r.closed.then(() => 'resolved', (e) => 'rejected ' + d(e));
  await w.write(Buffer.from('bad data'));
  const c1 = await tm(w.close());
  console.log('close1: ' + (c1 === 'HANG' ? 'HANG' : c1.err ? 'rejected ' + d(c1.err) : 'resolved'));
  console.log('writer.closed: ' + await tm(closedP, 50) + ' | reader.closed: ' + await tm(rClosedP, 50));
  console.log('states: w=' + ds.writable._state + ' r=' + ds.readable._state + ' desiredSize=' + w.desiredSize + ' ready=' + JSON.stringify(await tm(w.ready, 50)));
  const w2 = await tm(w.write(zlib.gzipSync('second')));
  console.log('write after failed close: ' + (w2 === 'HANG' ? 'HANG' : w2.err ? 'rejected ' + d(w2.err) : 'resolved'));
  const c2 = await tm(w.close());
  console.log('close2: ' + (c2 === 'HANG' ? 'HANG' : c2.err ? 'rejected ' + d(c2.err) : 'resolved'));
  const rd = await tm(r.read());
  console.log('read: ' + (rd === 'HANG' ? 'HANG' : rd.err ? 'rejected ' + d(rd.err) : JSON.stringify({ done: rd.ok.done, val: rd.ok.value && Buffer.from(rd.ok.value).toString() })));
  // abort / cancel
