  const r3 = ds2.readable.getReader();
  const rd3 = await tm(r3.read());
  console.log('read after abort: ' + (rd3 === 'HANG' ? 'HANG' : rd3.err ? 'rejected ' + d(rd3.err) : JSON.stringify(rd3.ok)));
  const ds3 = new CompressionStream('gzip');
