  console.log('cancel: ' + (cn === 'HANG' ? 'HANG' : cn.err ? 'rejected ' + d(cn.err) : 'resolved') + ' states: w=' + ds3.writable._state + ' r=' + ds3.readable._state);
  const w5 = ds3.writable.getWriter();
  const wr5 = await tm(w5.write(new Uint8Array([1])));
  console.log('write after readable cancel: ' + (wr5 === 'HANG' ? 'HANG' : wr5.err ? 'rejected ' + d(wr5.err) : 'resolved'));
  const c5 = await tm(w5.close());
  console.log('close after readable cancel: ' + (c5 === 'HANG' ? 'HANG' : c5.err ? 'rejected ' + d(c5.err) : 'resolved'));
})();
