(async () => {
  try {
    const cs = new CompressionStream('gzip');
    const w = cs.writable.getWriter();
    w.write(new TextEncoder().encode('idiom'));
    w.close();
    const ab = await new Response(cs.readable).arrayBuffer();
    console.log('idiom1 (write+close not awaited, then Response.arrayBuffer): ok len=' + ab.byteLength + ' eqSync=' + Buffer.from(ab).equals(zlib.gzipSync('idiom')));
  } catch (e) { console.log('idiom1 ERR ' + e.constructor.name + ': ' + e.message); }
  try {
    const cs = new CompressionStream('gzip');
    const w = cs.writable.getWriter();
    w.write(new TextEncoder().encode('idiom'));
    const p = w.close();
    const resp = new Response(cs.readable);
    await p;
    const ab = await resp.arrayBuffer();
    console.log('idiom2 (Response created before close resolves, arrayBuffer after): ok len=' + ab.byteLength);
  } catch (e) { console.log('idiom2 ERR ' + e.constructor.name + ': ' + e.message); }
  try {
    const ds = new DecompressionStream('gzip');
    const txt = ds.readable.pipeThrough(new TextDecoderStream());
    const w = ds.writable.getWriter();
    w.write(zlib.gzipSync('décodé')); w.close();
    const r = txt.getReader(); let s = '';
    while (true) { const { done, value } = await r.read(); if (done) break; s += value; }
    console.log('DS -> TextDecoderStream: ' + JSON.stringify(s));
  } catch (e) { console.log('TextDecoderStream ERR ' + e.constructor.name + ': ' + e.message); }
  try {
    const ab = await new Response(new Blob(['abc']).stream()).arrayBuffer();
    const blob = new Blob([zlib.gzipSync('from blob')]);
    const rd = blob.stream().pipeThrough(new DecompressionStream('gzip')).getReader();
    const { value } = await rd.read();
    console.log('blob.stream().pipeThrough(DS) via reader: ' + Buffer.from(value).toString());
  } catch (e) { console.log('blob DS ERR ' + e.message); }
  try {
    const r = await fetch('data:application/octet-stream;base64,' + zlib.gzipSync('from fetch').toString('base64'));
    const out = r.body.pipeThrough(new DecompressionStream('gzip'));
    const rd = out.getReader(); const { value } = await rd.read();
    console.log('fetch(data:).body.pipeThrough(DS): ' + Buffer.from(value).toString());
  } catch (e) { console.log('fetch data: ERR ' + e.constructor.name + ': ' + e.message); }
})();
