    """stream: wbits22, islast meta-block, literal code from code_writer(bw)->PCode, insert-only command"""
    mlen = len(data) if mlen is None else mlen
    bw = BW(); wbits(bw, 22); hdr_simple(bw, mlen)
    code = code_writer(bw)
    s, ie, ien = ins_cmd(mlen)
    write_simple(bw, 704, [s]); write_simple(bw, 64, [0])
    bw.put(ie, ien)
    if after: after(bw, code)
    else:
