  } catch (e) {
    r = { ok: false, message: String(e && e.message) };
    if (e && e.code) r.code = e.code;
    if (e && e.constructor && e.constructor.name !== 'Error') r.ctor = e.constructor.name;
  }
  out.push({ name: c.name, res: r });
}
