from common import *
import random, glob, collections, json, sys, time
seed = int(sys.argv[1]); N = int(sys.argv[2])
random.seed(seed)
seeds = []
for fn in sorted(glob.glob('/tmp/agent_c/valid2/*.zst')) + sorted(glob.glob('/tmp/x/zsc/*.zst')):
    d = open(fn, 'rb').read()
    if 20 <= len(d) <= 1500:
        seeds.append((fn.split('/')[-1], d))
for fn in glob.glob('/tmp/agent_c/res_*.json'):
    if 'sweep' in fn: continue
    for r in json.load(open(fn)):
        if r['orig']['ok'] and 10 <= len(r['hex']) // 2 <= 1500 and len(r['orig']['out_hex']) < 200000:
            seeds.append((r['name'], bytes.fromhex(r['hex'])))
known = set(json.load(open('/tmp/agent_c/known_msgs.json')))
cases = []
for i in range(N):
    nm, d = random.choice(seeds)
    d = bytearray(d)
    k = random.choice(['flip', 'byte', 'ins', 'del', 'multi', 'trunc_flip'])
    if k == 'flip':
        p = random.randrange(len(d)); d[p] ^= 1 << random.randrange(8)
    elif k == 'byte':
        p = random.randrange(len(d)); d[p] = random.randrange(256)
    elif k == 'ins':
        p = random.randrange(len(d) + 1); d[p:p] = bytes([random.randrange(256)])
    elif k == 'del':
        p = random.randrange(len(d)); del d[p]
    elif k == 'multi':
        for _ in range(random.randint(2, 6)):
            p = random.randrange(len(d)); d[p] ^= 1 << random.randrange(8)
    else:
        p = random.randrange(4, len(d)); d[p] ^= 1 << random.randrange(8); d = d[:random.randrange(p, len(d) + 1)]
    cases.append(('fz%d_%d_%s' % (seed, i, k), bytes(d)))
cnt = collections.Counter(); ex = {}
B = 200
t0 = time.time()
for b in range(0, N, B):
    chunk = cases[b:b + B]
    inf = '/tmp/agent_c/fz_in_%d.txt' % seed; outf = '/tmp/agent_c/fz_out_%d.txt' % seed
    with open(inf, 'w') as f:
        for n, d in chunk: f.write(n + '\t' + d.hex() + '\n')
    p = subprocess.run(['/tmp/orig', '/tmp/agent_c/harness_fuzz.js', inf, outf], capture_output=True, timeout=1200)
    if p.returncode != 0:
        print('batch failed', b, p.stderr[-200:]); continue
    for line in open(outf):
        r = json.loads(line)
        m = 'OK' if r['ok'] else r['message']
        cnt[m] += 1
        d = dict(chunk)[r['name']]
        if m not in ex or len(d) < len(ex[m][1]): ex[m] = (r['name'], d)
    print('batch', b, 'elapsed %.0f' % (time.time() - t0), flush=True)
for m, c in cnt.most_common():
    print('%6d %s%s' % (c, m, '' if m in known or m == 'OK' else '   <== NEW'))
json.dump({m: [ex[m][0], ex[m][1].hex()] for m in ex}, open('/tmp/agent_c/fuzz_examples_%d.json' % seed, 'w'))
EOF
