class E(Exception):
    pass

def err(m):
    raise E('zstd: ' + m)

MAXB = 131072

class Rev:
    """backward bit reader; caller checks sentinel/empty beforehand"""
    def __init__(self, data):
        self.val = int.from_bytes(bytes(data), 'little')
        last = data[-1]
        self.pos = (len(data) - 1) * 8 + last.bit_length() - 1
    def read(self, nb):
        if nb == 0:
            return 0
        p = self.pos - nb
        if p >= 0:
            v = (self.val >> p) & ((1 << nb) - 1)
        else:
            v = ((self.val & ((1 << max(self.pos, 0)) - 1)) << (-p)) & ((1 << nb) - 1) if self.pos > 0 else 0
        self.pos = p
        return v
    def peek(self, nb):
        s = self.pos
        v = self.read(nb)
        self.pos = s
        return v

