    """zero-padded NCount reader. returns (norm, log, consumed_bytes)"""
    val = int.from_bytes(bytes(data), 'little')
    bitpos = 0
    def get(nb):
        return (val >> bitpos) & ((1 << nb) - 1)
    log = get(4) + 5
    bitpos += 4
    if log > maxlog:
        err('FSE accuracy log too large')
    remaining = (1 << log) + 1
    threshold = 1 << log
    nbBits = log + 1
    norm = []
    prev0 = False
    while remaining > 1:
        if len(norm) > maxsym:
            err('too many symbols in FSE distribution')
        if prev0:
            while True:
                r = get(2)
                bitpos += 2
                norm.extend([0] * r)
                if r != 3:
                    break
            if len(norm) > maxsym + 1:
                err('too many symbols in FSE distribution')
            if len(norm) == maxsym + 1:
                err('corrupted FSE distribution')
        mx = (2 * threshold - 1) - remaining
        low = get(nbBits - 1)
        if low < mx:
            count = low
            bitpos += nbBits - 1
        else:
            count = get(nbBits)
            if count >= threshold:
                count -= mx
            bitpos += nbBits
        count -= 1
        remaining -= abs(count)
        norm.append(count)
        prev0 = (count == 0)
        while remaining < threshold:
            nbBits -= 1
            threshold >>= 1
    return norm, log, (bitpos + 7) // 8

