# structure-aware random frame generator + differential check (original vs model)
import sys, json, random, subprocess, time, collections
sys.path.insert(0, '/tmp/agent_c')
from common import *
from model import model
seed = int(sys.argv[1]); N = int(sys.argv[2])
random.seed(seed)
def rand_norm(nsym_max, log, maxsym):
    tot = 1 << log
    k = random.randint(1, min(nsym_max, tot))
    syms = sorted(random.sample(range(maxsym + 1), k))
    counts = [1] * k
    rest = tot - k
    for _ in range(rest):
        counts[random.randrange(k)] += 1
    norm = [0] * (syms[-1] + 1)
    for s, c in zip(syms, counts):
        norm[s] = c
    # sometimes convert some 1s to -1
    for s in syms:
        if norm[s] == 1 and random.random() < 0.3:
            norm[s] = -1
    return norm
def rand_huff(data):
    full = huff_weights_for(data, maxbits=11)
    return full
def rand_lits():
    n = random.choice([0, 1, 2, 3, 5, 6, 10, 31, 32, 100, 300, 1000, 1500])
    alpha = random.choice([b'ab', b'abc', b'abcdefgh', bytes(range(32, 127)), bytes(range(256)), b'a'])
    data = bytes(random.choice(alpha) for _ in range(n))
    return data
