    t = random.random()
    if t < 0.25 or len(data) == 0:
        return lit_raw(data), None
    if t < 0.35 and len(set(data)) == 1:
        return lit_rle(data[0], len(data)), None
    if len(set(data)) < 2:
        return lit_raw(data), None
    full = rand_huff(data)
    expl = full[:-1]
    streams = 1 if (len(data) < 256 and random.random() < 0.6) or len(data) > 1023 and False else 4
    if len(data) > 1023: streams = 4
    treeless = state.get('huf') is not None and random.random() < 0.3
    if treeless:
        full = state['huf']
        if any(full[b] == 0 if b < len(full) else True for b in data):
            treeless = False
            full = rand_huff(data)
    tree = None
    if not treeless and random.random() < 0.5 and len(full) - 1 <= 255:
        # FSE-compressed weights
        ex = full[:-1]
        from collections import Counter
        cnt = Counter(ex)
        log = random.choice([5, 6])
        syms = sorted(cnt)
