mod compress;

fn hexd(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}
fn hexe(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02x}", x)).collect()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match args[1].as_str() {
        // cases <codec> <tsv>: each line: name \t inhex \t OK|ERR \t outhex|message
        "cases" => {
            let codec = args[2].as_str();
            let text = std::fs::read_to_string(&args[3]).unwrap();
            let (mut ok, mut bad) = (0, 0);
            for line in text.lines() {
                let f: Vec<&str> = line.splitn(4, '\t').collect();
                if f.len() < 4 { continue; }
                let input = hexd(f[1]);
                let r = match codec {
                    "br" => compress::brotli_decode(&input),
                    "zst" => compress::zstd_decode(&input),
                    "raw" => compress::inflate_raw(&input, None),
                    "zz" => compress::zlib_decode(&input, None),
                    "gz" => compress::gzip_decode(&input),
                    _ => panic!(),
                };
                let same = match (&r, f[2]) {
                    (Ok(o), "OK") => hexe(o) == f[3],
                    (Err(e), "ERR") => e.message == f[3],
                    _ => false,
                };
                if same { ok += 1; } else {
                    bad += 1;
                    if bad <= 25 {
                        let got = match &r { Ok(o) => format!("OK {}", if o.len() > 40 { format!("len {}", o.len()) } else { hexe(o) }), Err(e) => format!("ERR {}", e.message) };
                        let want = if f[3].len() > 80 { format!("{} {}...", f[2], &f[3][..80]) } else { format!("{} {}", f[2], f[3]) };
                        println!("MISMATCH {}: got [{}] want [{}]", f[0], got, want);
                    }
                }
            }
            println!("{}: ok={} bad={}", codec, ok, bad);
        }
        "enc" => {
            // enc <fmt> <in> <out>
            let data = std::fs::read(&args[3]).unwrap();
            let o = compress::DeflateOptions::default();
            let out = match args[2].as_str() {
                "raw" => compress::deflate_raw(&data, &o),
                "zz" => compress::zlib_encode(&data, &o),
                "gz" => compress::gzip_encode(&data, &o),
                "br" => compress::brotli_encode(&data, &Default::default()),
                "zst" => compress::zstd_encode(&data, 3),
                _ => panic!(),
            };
            std::fs::write(&args[4], out).unwrap();
        }
        "dec" => {
            let data = std::fs::read(&args[3]).unwrap();
            let r = match args[2].as_str() {
                "raw" => compress::inflate_raw(&data, None),
                "zz" => compress::zlib_decode(&data, None),
                "gz" => compress::gzip_decode(&data),
                "br" => compress::brotli_decode(&data),
                "zst" => compress::zstd_decode(&data),
                _ => panic!(),
            };
            match r {
                Ok(o) => { println!("OK {}", o.len()); if args.len() > 4 { std::fs::write(&args[4], &o).unwrap(); } }
                Err(e) => println!("ERR {}", e.message),
            }
        }
        _ => {}
    }
}
