function t(label, f) { try { const r = f(); console.log(label, "=>", show(r)); } catch(e) { console.log(label, "ERR", e && e.name, e && e.code, JSON.stringify(e && e.message)); } }
const rsa = c.generateKeyPairSync('rsa', {modulusLength: 1024});
const ec = c.generateKeyPairSync('ec', {namedCurve: 'P-256'});
const ed = c.generateKeyPairSync('ed25519');
const x = c.generateKeyPairSync('x25519');
t("rsa details", ()=>rsa.publicKey.asymmetricKeyDetails);
const data = Buffer.from('hello world');
for (const alg of ['sha256','SHA256','RSA-SHA256','sha1','md5','sha512','sha384','sha224','sha512-256','sha256WithRSAEncryption','ecdsa-with-SHA256',null,undefined]) {
  t("rsa sign "+alg, ()=>{ const s=c.sign(alg, data, rsa.privateKey); return [s.length, c.verify(alg, data, rsa.publicKey, s)]; });
}
t("rsa sign deterministic", ()=>c.sign('sha256', data, rsa.privateKey).equals(c.sign('sha256', data, rsa.privateKey)));
t("ec sign", ()=>{ const s=c.sign('sha256', data, ec.privateKey); return [s.length, s.toString('hex').slice(0,8), c.verify('sha256', data, ec.publicKey, s)]; });
t("ec sign det?", ()=>c.sign('sha256', data, ec.privateKey).equals(c.sign('sha256', data, ec.privateKey)));
t("ec sign ieee", ()=>{ const s=c.sign('sha256', data, {key: ec.privateKey, dsaEncoding: 'ieee-p1363'}); return [s.length, c.verify('sha256', data, {key: ec.publicKey, dsaEncoding: 'ieee-p1363'}, s)]; });
t("ec sign null alg", ()=>{ const s=c.sign(null, data, ec.privateKey); return [s.length, c.verify(null, data, ec.publicKey, s)]; });
t("ec sign sha1", ()=>{ const s=c.sign('sha1', data, ec.privateKey); return [s.length, c.verify('sha1', data, ec.publicKey, s)]; });
t("ed sign", ()=>{ const s=c.sign(null, data, ed.privateKey); return [s.length, c.verify(null, data, ed.publicKey, s), c.sign(null, data, ed.privateKey).equals(s)]; });
t("ed sign sha256", ()=>{ const s=c.sign('sha256', data, ed.privateKey); return [s.length]; });
t("ed verify bad", ()=>{ const s=c.sign(null, data, ed.privateKey); s[0]^=1; return c.verify(null, data, ed.publicKey, s); });
