t("rsa sign with public", ()=>c.sign('sha256', data, rsa.publicKey));
t("rsa verify with private", ()=>{ const s=c.sign('sha256', data, rsa.privateKey); return c.verify('sha256', data, rsa.privateKey, s); });
t("createSign", ()=>{ const s=c.createSign('SHA256'); s.update('hello '); s.update('world'); const sig=s.sign(rsa.privateKey, 'hex'); const v=c.createVerify('sha256'); v.update('hello world'); return [sig.length, v.verify(rsa.publicKey, sig, 'hex'), c.sign('sha256', data, rsa.privateKey).toString('hex')===sig]; });
t("createSign RSA-SHA256", ()=>c.createSign('RSA-SHA256') && 'ok');
t("createSign sha224", ()=>c.createSign('sha224') && 'ok');
t("createSign bad", ()=>c.createSign('foo') && 'ok');
t("createSign ecdsa-with-SHA256", ()=>c.createSign('ecdsa-with-SHA256') && 'ok');
t("createSign sha256WithRSAEncryption", ()=>c.createSign('sha256WithRSAEncryption') && 'ok');
t("createSign RSA-SHA1", ()=>c.createSign('RSA-SHA1') && 'ok');
t("createSign rsa-sha512", ()=>c.createSign('rsa-sha512') && 'ok');
t("sign pem", ()=>{ const pem = rsa.privateKey.export({type:'pkcs8', format:'pem'}); const s=c.sign('sha256', data, pem); return c.verify('sha256', data, rsa.publicKey.export({type:'spki', format:'pem'}), s); });
t("sign pem pub from priv", ()=>{ const pem = rsa.privateKey.export({type:'pkcs8', format:'pem'}); const s=c.sign('sha256', data, pem); return c.verify('sha256', data, pem, s); });
t("verify bad sig", ()=>c.verify('sha256', data, rsa.publicKey, Buffer.alloc(128)));
t("verify short sig", ()=>c.verify('sha256', data, rsa.publicKey, Buffer.alloc(5)));
t("verify ec bad", ()=>c.verify('sha256', data, ec.publicKey, Buffer.alloc(70)));
t("sign string data", ()=>c.sign('sha256', 'hello world', rsa.privateKey).equals(c.sign('sha256', data, rsa.privateKey)));
