const c=require("crypto");
function show(r) { return r instanceof Uint8Array ? r.constructor.name+":"+Buffer.from(r).toString('hex') : (r instanceof ArrayBuffer ? "AB:"+Buffer.from(r).toString('hex') : (typeof r === 'bigint' ? r+'n' : JSON.stringify(r, (k,v)=>typeof v==='bigint'? v.toString()+'n' : v))); }
function t(label, f) { try { const r = f(); console.log(label, "=>", show(r)); } catch(e) { console.log(label, "ERR", e && e.name, e && e.code, JSON.stringify(e && e.message)); } }
t("tse eq", ()=>c.timingSafeEqual(Buffer.from('abc'), Buffer.from('abc')));
t("tse ne", ()=>c.timingSafeEqual(Buffer.from('abc'), Buffer.from('abd')));
t("tse len", ()=>c.timingSafeEqual(Buffer.from('abc'), Buffer.from('ab')));
t("tse str", ()=>c.timingSafeEqual('abc', 'abc'));
t("tse u16", ()=>c.timingSafeEqual(new Uint16Array([1]), new Uint8Array([1,0])));
t("tse num", ()=>c.timingSafeEqual(1, 1));
t("tse AB", ()=>c.timingSafeEqual(new ArrayBuffer(2), new Uint8Array(2)));
t("secret", ()=>{ const k=c.createSecretKey(Buffer.from('abc')); return [k.type, k.symmetricKeySize, k.asymmetricKeyType, k.export().toString('hex'), k.export({format:'jwk'}), k.export({format:'buffer'}).toString()]; });
t("secret str enc", ()=>c.createSecretKey('616263', 'hex').export().toString());
t("secret str", ()=>c.createSecretKey('abc').export().toString());
t("secret equals", ()=>[c.createSecretKey('abc').equals(c.createSecretKey('abc')), c.createSecretKey('abc').equals(c.createSecretKey('abd')), c.createSecretKey('abc').equals(c.createSecretKey('ab'))]);
t("secret empty", ()=>c.createSecretKey('').symmetricKeySize);
t("secret toString", ()=>[String(c.createSecretKey('abc')), Object.prototype.toString.call(c.createSecretKey('abc'))]);
t("genkey hmac", ()=>{ const k=c.generateKeySync('hmac', {length: 64}); return [k.type, k.symmetricKeySize]; });
t("genkey aes", ()=>{ const k=c.generateKeySync('aes', {length: 256}); return [k.type, k.symmetricKeySize]; });
t("genkey aes 100", ()=>{ const k=c.generateKeySync('aes', {length: 100}); return [k.type, k.symmetricKeySize]; });
t("genkey aes 7", ()=>c.generateKeySync('aes', {length: 7}));
t("genkey bad", ()=>c.generateKeySync('foo', {length: 8}));
t("genkey nolen", ()=>c.generateKeySync('hmac', {}));
const s=crypto.subtle;
s.digest('SHA-256', new TextEncoder().encode('abc')).then(r=>console.log("subtle sha256", show(r)), e=>console.log("subtle ERR", e.name, e.message));
s.digest({name:'sha-256'}, new Uint8Array([97,98,99]).buffer).then(r=>console.log("subtle sha256 obj", show(r)), e=>console.log("subtle ERR", e.name, e.message));
s.digest('SHA-1', new Uint8Array(1)).then(r=>console.log("subtle sha1", show(r)), e=>console.log("subtle sha1 ERR", e.name, e.message, e instanceof DOMException));
s.digest('SHA-512', new Uint8Array(1)).then(r=>console.log("subtle sha512", show(r)), e=>console.log("subtle sha512 ERR", e.name, e.message));
s.digest('SHA-384', new Uint8Array(1)).then(r=>console.log("subtle sha384", show(r)), e=>console.log("subtle sha384 ERR", e.name, e.message));
s.digest('SHA-256', 'abc').then(r=>console.log("subtle str", show(r)), e=>console.log("subtle str ERR", e.name, e.message));
s.digest('SHA-256', new DataView(new Uint8Array([0,97,98,99]).buffer, 1)).then(r=>console.log("subtle dv", show(r)), e=>console.log("subtle dv ERR", e.name, e.message));
s.digest(undefined, new Uint8Array(1)).then(r=>console.log("subtle undef", show(r)), e=>console.log("subtle undef ERR", e.name, e.message));
console.log(typeof s.encrypt, typeof s.sign, typeof s.importKey, typeof s.generateKey, typeof s.deriveBits);
