function dfy(y) { return 365 * (y - 1970) + Math.floor((y - 1969) / 4) - Math.floor((y - 1901) / 100) + Math.floor((y - 1601) / 400); }
function search(f, lo, hi) { while (hi - lo > 1) { const mid = Math.floor((lo + hi) / 2); if (f(mid)) lo = mid; else hi = mid; } return [lo, hi]; }
for (const base of [0, 1000, 1970, 2000, -1000, 100000]) {
  const f = y => { const r = Date.UTC(base, 12 * (y - base), 1 - dfy(y)); return r === r; };
  console.log("base", base, JSON.stringify(search(f, 200000, 400000)));
}
// negative
for (const base of [0, 1000, -1000]) {
  const f = y => { const r = Date.UTC(base, 12 * (-y - base), 1 - dfy(-y)); return r === r; };
  console.log("negbase", base, JSON.stringify(search(f, 200000, 400000)));
}
// check: maybe limit on days: Date.UTC(1970, 0, D)
const g = D => { const r = Date.UTC(1970, 0, 1 + D, 0, 0, 0, -D * 864e5); return r === r; };
console.log("dayarg", JSON.stringify(search(g, 1e8, 1e12)));
const g2 = D => { const r = Date.UTC(1970, 0, 1, 0, 0, 0, D * 864e5 - D * 864e5 ); return r === r; };
// also hours
const h = H => { const r = Date.UTC(1970, 0, 1, H, 0, 0, -H * 36e5); return r === r; };
console.log("hourarg", JSON.stringify(search(h, 1e9, 1e15)));
EOF
