function dfy(y) { return 365 * (y - 1970) + Math.floor((y - 1969) / 4) - Math.floor((y - 1901) / 100) + Math.floor((y - 1601) / 400); }
function search(f, lo, hi) { while (hi - lo > 1) { const mid = Math.floor((lo + hi) / 2); if (f(mid)) lo = mid; else hi = mid; } return [lo, hi]; }
const v = x => x === x;
// date arg limit with different base years
for (const Y of [1970, 200000, -200000]) {
  const base = dfy(Y);
  const f = D => v(Date.UTC(Y, 0, 1 + D, 0, 0, 0, -(D + base) * 864e5));
  const fn = D => v(Date.UTC(Y, 0, 1 - D, 0, 0, 0, (D - base) * 864e5));
  console.log("date Y=" + Y, JSON.stringify(search(f, 1e6, 1e13)), JSON.stringify(search(fn, 1e6, 1e13)));
}
// hours, minutes, seconds, ms
console.log("hour+", JSON.stringify(search(H => v(Date.UTC(1970, 0, 1, H, 0, 0, -H * 36e5)), 1e9, 1e17)));
console.log("hour-", JSON.stringify(search(H => v(Date.UTC(1970, 0, 1, -H, 0, 0, H * 36e5)), 1e9, 1e17)));
console.log("min+", JSON.stringify(search(M => v(Date.UTC(1970, 0, 1, 0, M, 0, -M * 6e4)), 1e9, 1e19)));
console.log("sec+", JSON.stringify(search(S => v(Date.UTC(1970, 0, 1, 0, 0, S, -S * 1e3)), 1e9, 1e20)));
console.log("ms+", JSON.stringify(search(X => v(Date.UTC(1970, 0, 1, -X / 36e5, 0, 0, X)), 1e9, 1e22)));
// hours compensated by days
console.log("hour-vs-day", JSON.stringify(search(H => v(Date.UTC(1970, 0, 1 - H / 24, H, 0, 0, 0)), 1e9, 1e17)));
// MakeTime result limit? h and m opposite
console.log("h-m", JSON.stringify(search(H => v(Date.UTC(1970, 0, 1, H, -H * 60, 0, 0)), 1e9, 1e17)));
EOF
