const k16=Buffer.alloc(16,1), iv16=Buffer.alloc(16,4), iv12=Buffer.alloc(12,5);
t("order bad key+iv", ()=>c.createCipheriv('aes-128-cbc', Buffer.alloc(5), Buffer.alloc(5)));
t("order bad name+key", ()=>c.createCipheriv('foo', 5, Buffer.alloc(5)));
t("order bad key type+iv", ()=>c.createCipheriv('aes-128-cbc', 5, Buffer.alloc(5)));
t("order bad iv type", ()=>c.createCipheriv('aes-128-cbc', k16, 5));
t("order bad iv type ecb", ()=>c.createCipheriv('aes-128-ecb', k16, 5));
t("order taglen + iv", ()=>c.createCipheriv('aes-128-gcm', k16, Buffer.alloc(0), {authTagLength: 5}));
t("order taglen + key", ()=>c.createCipheriv('aes-128-gcm', Buffer.alloc(3), iv12, {authTagLength: 5}));
t("iv string ecb empty", ()=>c.createCipheriv('aes-128-ecb', k16, '').final());
t("iv keyobject", ()=>c.createCipheriv('aes-128-cbc', k16, c.createSecretKey(iv16)).final());
t("dec nopad update", ()=>{ const e=c.createCipheriv('aes-128-cbc', k16, iv16); e.setAutoPadding(false); const ct=Buffer.concat([e.update(Buffer.alloc(32)), e.final()]); const d=c.createDecipheriv('aes-128-cbc', k16, iv16); d.setAutoPadding(false); return [d.update(ct).length, d.final().length]; });
t("dec pad then nopad", ()=>{ const e=c.createCipheriv('aes-128-cbc', k16, iv16); e.setAutoPadding(false); const ct=Buffer.concat([e.update(Buffer.alloc(32)), e.final()]); const d=c.createDecipheriv('aes-128-cbc', k16, iv16); const u=d.update(ct).length; d.setAutoPadding(false); return [u, d.final().length]; });
t("dec nopad then pad", ()=>{ const e=c.createCipheriv('aes-128-cbc', k16, iv16); const ct=Buffer.concat([e.update(Buffer.alloc(20)), e.final()]); const d=c.createDecipheriv('aes-128-cbc', k16, iv16); d.setAutoPadding(false); const u=d.update(ct).length; d.setAutoPadding(true); return [u, d.final().length]; });
