t("enc ecb pad empty", ()=>{ const e=c.createCipheriv('aes-128-ecb', k16, null); return e.final(); });
t("enc nopad empty", ()=>{ const e=c.createCipheriv('aes-128-cbc', k16, iv16); e.setAutoPadding(false); return e.final().length; });
t("final err then final", ()=>{ const d=c.createDecipheriv('aes-128-cbc', k16, iv16); d.update(Buffer.alloc(16)); try { d.final(); } catch(e) { console.log("  first:", e.message); } return d.final(); });
t("final err then update", ()=>{ const d=c.createDecipheriv('aes-128-cbc', k16, iv16); d.update(Buffer.alloc(16)); try { d.final(); } catch(e) {} return d.update('aa'); });
t("gcm final err then final", ()=>{ const d=c.createDecipheriv('aes-128-gcm', k16, iv12); d.update(Buffer.alloc(16)); try { d.final(); } catch(e) { console.log("  first:", e.message); } return d.final(); });
t("gcm final err then getAuthTag", ()=>{ const d=c.createCipheriv('aes-128-gcm', k16, iv12); d.final(); d.getAuthTag(); return d.getAuthTag().length; });
