t("ctr mid wrap", ()=>{ const iv=Buffer.alloc(16,0); iv.fill(0xff, 8); const e=c.createCipheriv('aes-128-ctr', k16, iv); return e.update(Buffer.alloc(32)).toString('hex'); });
