t("setAutoPadding after final", ()=>{ const e=c.createCipheriv('aes-128-cbc', k16, iv16); e.final(); return e.setAutoPadding(false)===e; });
t("gcm dec update holdback?", ()=>{ const d=c.createDecipheriv('aes-128-gcm', k16, iv12); return d.update(Buffer.alloc(5)).length; });
t("gcm setAAD after setAuthTag dec", ()=>{ const e=c.createCipheriv('aes-128-gcm', k16, iv12); e.setAAD(Buffer.from('a')); const ct=Buffer.concat([e.update('xyz'), e.final()]); const d=c.createDecipheriv('aes-128-gcm', k16, iv12); d.setAuthTag(e.getAuthTag()); d.setAAD(Buffer.from('a')); return d.update(ct).toString() + d.final().toString(); });
t("gcm empty", ()=>{ const e=c.createCipheriv('aes-128-gcm', k16, iv12); e.final(); return e.getAuthTag().toString('hex'); });
t("gcm aad only", ()=>{ const e=c.createCipheriv('aes-128-gcm', k16, iv12); e.setAAD(Buffer.alloc(20, 7)); e.final(); return e.getAuthTag().toString('hex'); });
t("gcm setAAD plaintextLength opt", ()=>{ const e=c.createCipheriv('aes-128-gcm', k16, iv12); e.setAAD(Buffer.alloc(20, 7), {plaintextLength: 5}); e.final(); return e.getAuthTag().toString('hex'); });
t("gcm setAAD non-buffer", ()=>{ const e=c.createCipheriv('aes-128-gcm', k16, iv12); e.setAAD(5); return 1; });
t("gcm setAAD empty then update", ()=>{ const e=c.createCipheriv('aes-128-gcm', k16, iv12); e.setAAD(Buffer.alloc(0)); e.update('a'); e.final(); return e.getAuthTag().toString('hex'); });
t("gcm update empty then setAAD", ()=>{ const e=c.createCipheriv('aes-128-gcm', k16, iv12); e.update(''); e.setAAD(Buffer.alloc(1)); return 1; });
