                    for s in &f[3.min(f.len())..] { if s.is_empty() { continue; } ss.push(s.split('.').map(|x| u32::from_str_radix(x, 16).unwrap()).collect()); }
                    d.strs.insert(f[1].to_string(), (r, ss));
