        let mut d = Data { props: HashMap::new(), strs: HashMap::new(), prop_alias: HashMap::new(), val_alias: HashMap::new(), scf: Vec::new(), legacy: Vec::new() };
        let mut parent: HashMap<u32, u32> = HashMap::new();
        fn find(p: &mut HashMap<u32, u32>, x: u32) -> u32 {
            let mut r = x;
            while let Some(&q) = p.get(&r) { if q == r { break; } r = q; }
            r
        }
        for line in txt.lines() {
            let f: Vec<&str> = line.split(' ').collect();
            match f[0] {
                "P" => { d.props.insert((f[1].to_string(), f[2].to_string()), parse_ranges(f.get(3).copied().unwrap_or(""))); }
                "S" => {
                    let r = parse_ranges(f.get(2).copied().unwrap_or(""));
                    let mut ss = Vec::new();
                    for s in &f[3.min(f.len())..] { if s.is_empty() { continue; } ss.push(s.split('.').map(|x| u32::from_str_radix(x, 16).unwrap()).collect()); }
                    d.strs.insert(f[1].to_string(), (r, ss));
                }
                "A" => { d.prop_alias.insert(f[1].to_string(), f[2].to_string()); }
                "V" => { d.val_alias.insert((f[1].to_string(), f[2].to_string()), f[3].to_string()); }
                "F" => {
                    let a = u32::from_str_radix(f[1], 16).unwrap();
                    for x in &f[2..] {
                        let b = u32::from_str_radix(x, 16).unwrap();
                        parent.entry(a).or_insert(a);
                        parent.entry(b).or_insert(b);
                        let ra = find(&mut parent, a);
                        let rb = find(&mut parent, b);
                        if ra != rb { let (lo, hi) = if ra < rb { (ra, rb) } else { (rb, ra) }; parent.insert(hi, lo); }
                    }
                }
                _ => {}
            }
        }
        // also ASCII-ish simple folds not in iu-mappings (iu-mappings only lists non-trivial extras): add std lowercase pairs
        for c in 0u32..0x110000 {
            if let Some(ch) = char::from_u32(c) {
                let mut l = ch.to_lowercase();
                if let (Some(lc), None) = (l.next(), l.next()) {
                    let lc = lc as u32;
                    if lc != c && c != 0x130 {
                        parent.entry(c).or_insert(c);
                        parent.entry(lc).or_insert(lc);
                        let ra = find(&mut parent, c);
                        let rb = find(&mut parent, lc);
                        if ra != rb { let (lo, hi) = if ra < rb { (ra, rb) } else { (rb, ra) }; parent.insert(hi, lo); }
                    }
                }
            }
        }
        let keys: Vec<u32> = parent.keys().copied().collect();
        for k in keys { let r = find(&mut parent, k); if r != k { d.scf.push((k, r)); } }
        d.scf.sort();
        for c in 0u32..0x10000 {
            let v = legacy_canon_compute(c);
            if v != c { d.legacy.push((c, v)); }
        }
        d
    })
}

fn legacy_canon_compute(c: u32) -> u32 {
    let ch = match char::from_u32(c) { Some(ch) => ch, None => return c };
    let mut u = ch.to_uppercase();
    let first = u.next();
    if u.next().is_some() { return c; }
    let cu = match first { Some(x) => x as u32, None => return c };
    if cu > 0xFFFF { return c; }
    if c >= 128 && cu < 128 { return c; }
    cu
}

fn in_ranges(r: &[(u32, u32)], c: u32) -> bool {
    r.binary_search_by(|&(a, b)| if b < c { std::cmp::Ordering::Less } else if a > c { std::cmp::Ordering::Greater } else { std::cmp::Ordering::Equal }).is_ok()
}

fn bin(name: &str) -> &'static [(u32, u32)] {
    data().props.get(&("Binary_Property".to_string(), name.to_string())).map(|v| v.as_slice()).unwrap_or(&[])
}

pub fn is_id_start(c: u32) -> bool { in_ranges(bin("ID_Start"), c) }
pub fn is_id_continue(c: u32) -> bool { in_ranges(bin("ID_Continue"), c) }
pub fn is_js_id_start(c: u32) -> bool { c == '$' as u32 || c == '_' as u32 || is_id_start(c) }
pub fn is_js_id_continue(c: u32) -> bool { c == '$' as u32 || c == 0x200C || c == 0x200D || is_id_continue(c) }
pub fn is_js_whitespace(c: u32) -> bool {
    matches!(c, 9 | 0xB | 0xC | 0x20 | 0xA0 | 0xFEFF | 0x1680 | 0x2000..=0x200A | 0x202F | 0x205F | 0x3000)
}
pub fn is_line_terminator(c: u32) -> bool { matches!(c, 0xA | 0xD | 0x2028 | 0x2029) }

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum GeneralCategory { Lu, Ll, Lt, Lm, Lo, Mn, Mc, Me, Nd, Nl, No, Pc, Pd, Ps, Pe, Pi, Pf, Po, Sm, Sc, Sk, So, Zs, Zl, Zp, Cc, Cf, Cs, Co, Cn }

pub fn general_category(c: u32) -> GeneralCategory {
    use GeneralCategory::*;
    let table: [(&str, GeneralCategory); 29] = [("Uppercase_Letter", Lu), ("Lowercase_Letter", Ll), ("Titlecase_Letter", Lt), ("Modifier_Letter", Lm), ("Other_Letter", Lo), ("Nonspacing_Mark", Mn), ("Spacing_Mark", Mc), ("Enclosing_Mark", Me), ("Decimal_Number", Nd), ("Letter_Number", Nl), ("Other_Number", No), ("Connector_Punctuation", Pc), ("Dash_Punctuation", Pd), ("Open_Punctuation", Ps), ("Close_Punctuation", Pe), ("Initial_Punctuation", Pi), ("Final_Punctuation", Pf), ("Other_Punctuation", Po), ("Math_Symbol", Sm), ("Currency_Symbol", Sc), ("Modifier_Symbol", Sk), ("Other_Symbol", So), ("Space_Separator", Zs), ("Line_Separator", Zl), ("Paragraph_Separator", Zp), ("Control", Cc), ("Format", Cf), ("Surrogate", Cs), ("Private_Use", Co)];
    for (n, g) in table.iter() {
        if let Some(r) = data().props.get(&("General_Category".to_string(), n.to_string())) { if in_ranges(r, c) { return *g; } }
    }
    Cn
}

pub fn property_ranges(name: &str, value: Option<&str>) -> Option<Vec<(u32, u32)>> {
    let d = data();
    match value {
        None => {
            if let Some(canon) = d.val_alias.get(&("General_Category".to_string(), name.to_string())) {
                return d.props.get(&("General_Category".to_string(), canon.clone())).cloned();
            }
            let long = d.prop_alias.get(name).cloned().unwrap_or_else(|| name.to_string());
            if long != name && !d.prop_alias.contains_key(name) { return None; }
            d.props.get(&("Binary_Property".to_string(), long)).cloned()
        }
        Some(v) => {
            let (kind, vprop) = match name {
                "General_Category" | "gc" => ("General_Category", "General_Category"),
                "Script" | "sc" => ("Script", "Script"),
                "Script_Extensions" | "scx" => ("Script_Extensions", "Script"),
                _ => return None,
            };
            let canon = d.val_alias.get(&(vprop.to_string(), v.to_string()))?;
            d.props.get(&(kind.to_string(), canon.clone())).cloned()
        }
    }
}

pub fn string_property(name: &str) -> Option<(Vec<(u32, u32)>, Vec<Vec<u32>>)> { data().strs.get(name).cloned() }

pub fn simple_case_fold_table() -> &'static [(u32, u32)] { &data().scf }
pub fn simple_case_fold(c: u32) -> u32 {
    let t = simple_case_fold_table();
    match t.binary_search_by_key(&c, |&(a, _)| a) { Ok(i) => t[i].1, Err(_) => c }
}
pub fn legacy_canonicalize_table() -> &'static [(u32, u32)] { &data().legacy }
pub fn legacy_canonicalize(c: u32) -> u32 {
    let t = legacy_canonicalize_table();
    match t.binary_search_by_key(&c, |&(a, _)| a) { Ok(i) => t[i].1, Err(_) => c }
}
