use datelib::datetime as dt;
use std::io::{self, BufRead, Write};

fn num(x: f64) -> String {
    // JS-like number formatting for integers and NaN (enough for our corpus)
    if x.is_nan() { return "NaN".into(); }
    if x == x.trunc() && x.abs() < 1e21 { return format!("{}", x as i128); }
    format!("{}", x)
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let (cmd, rest) = line.split_once(' ').unwrap_or((&line, ""));
        match cmd {
            "fmt" => {
                let t: f64 = rest.trim().parse().unwrap();
                let t = dt::time_clip(t);
                let iso = dt::to_iso_string(t).unwrap_or_else(|| "THROW".into());
                writeln!(out, "{}|{}|{}|{}|{}|{}|{} {} {} {} {} {} {} {} {}", num(t), dt::to_date_string(t), dt::to_date_only_string(t), dt::to_time_only_string(t), iso, dt::to_utc_string(t),
                    num(dt::year_from_time(t)), num(dt::month_from_time(t)), num(dt::date_from_time(t)), num(dt::week_day(t)), num(dt::hour_from_time(t)), num(dt::min_from_time(t)), num(dt::sec_from_time(t)), num(dt::ms_from_time(t)), dt::in_leap_year(t)).unwrap();
            }
            "utc" => {
                let v: Vec<f64> = rest.split_whitespace().map(|s| s.parse().unwrap()).collect();
                let mut y = v[0];
                let yi = y.trunc();
                if y.is_finite() && (0.0..=99.0).contains(&yi) { y = 1900.0 + yi; }
                let g = |i: usize, d: f64| if i < v.len() { v[i] } else { d };
                let r = dt::time_clip(dt::make_date(dt::make_day(y, g(1, 0.0), g(2, 1.0)), dt::make_time(g(3, 0.0), g(4, 0.0), g(5, 0.0), g(6, 0.0))));
                writeln!(out, "{}", num(r)).unwrap();
            }
            _ => { writeln!(out, "?").unwrap(); }
        }
    }
}
