cd /tmp/unicode_dev && cat > case_probe.js <<'EOF'
const up = [], lo = [];
for (let c = 0; c < 0x110000; c++) {
  if (c >= 0xD800 && c <= 0xDFFF) continue;
  const s = String.fromCodePoint(c);
  const u = s.toUpperCase(), l = s.toLowerCase();
  if (u !== s) up.push([c, Array.from(u).map(x => x.codePointAt(0))]);
  if (l !== s) lo.push([c, Array.from(l).map(x => x.codePointAt(0))]);
}
// surrogates
const sur = [];
for (let c = 0xD800; c <= 0xDFFF; c++) { const s = String.fromCharCode(c); if (s.toUpperCase() !== s || s.toLowerCase() !== s) sur.push(c); }
console.log(JSON.stringify({up, lo, sur}));
EOF
time /tmp/orig case_probe.js > case17.json && python3 -c "
import json; d=json.load(open('/tmp/unicode_dev/case17.json')); print(len(d['up']), len(d['lo']), d['sur'])"
mkdir -p /tmp/unicode_dev/rs && cat > /tmp/unicode_dev/rs/case_dump.rs <<'EOF'
fn main() {
    let mut up = Vec::new(); let mut lo = Vec::new();
    for c in 0u32..0x110000 {
        if let Some(ch) = char::from_u32(c) {
            let u: Vec<u32> = ch.to_uppercase().map(|x| x as u32).collect();
            let l: Vec<u32> = ch.to_lowercase().map(|x| x as u32).collect();
            if u != vec![c] { up.push(format!("[{},[{}]]", c, u.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(","))); }
            if l != vec![c] { lo.push(format!("[{},[{}]]", c, l.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(","))); }
        }
    }
    println!("{{\"up\":[{}],\"lo\":[{}]}}", up.join(","), lo.join(","));
}
EOF
rustc -O -o /tmp/unicode_dev/rs/case_dump /tmp/unicode_dev/rs/case_dump.rs && /tmp/unicode_dev/rs/case_dump > case_rust.json && python3 - <<'EOF'
import json
a = json.load(open('/tmp/unicode_dev/case17.json'))
b = json.load(open('/tmp/unicode_dev/case_rust.json'))
for k in ('up','lo'):
    da = {c: m for c, m in a[k]}; db = {c: m for c, m in b[k]}
    diffs = [(c, da.get(c), db.get(c)) for c in sorted(set(da)|set(db)) if da.get(c) != db.get(c)]
    print(k, "orig", len(da), "rust", len(db), "diffs", len(diffs))
    for d in diffs[:20]: print("  %04X orig=%s rust=%s" % (d[0], d[1], d[2]))
EOF

