// ============================================================================
// Parsing
// ============================================================================

/// `Date.parse(s)`: the ISO format first, then the legacy free-form parser.
/// Returns NaN when unrecognised.  NOTE: values produced by the legacy parser
/// are *not* TimeClip'ed (the original returns e.g. 8640000086400000 for
/// "Sep 14 275760"), and its arithmetic wraps like i64.
pub fn parse(s: &str) -> f64 {
    let iso = parse_iso(s);
    if !iso.is_nan() {
        return iso;
    }
    parse_legacy(s).unwrap_or(f64::NAN)
}

/// String parsing used by `new Date(string)`: the original only accepts the
/// ISO format there (legacy strings such as "Mar 7 2020" or even its own
/// toString() output give an Invalid Date).  The result is already
/// TimeClip'ed.
pub fn parse_for_constructor(s: &str) -> f64 {
    parse_iso(s)
}

struct IsoCursor<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> IsoCursor<'a> {
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.i += 1;
            true
        } else {
            false
        }
    }
    /// Exactly `n` ASCII digits.
    fn digits(&mut self, n: usize) -> Option<i64> {
        let mut v: i64 = 0;
        for k in 0..n {
            let c = *self.b.get(self.i + k)?;
            if !c.is_ascii_digit() {
                return None;
            }
