function esc(s) { return s.replace(/[\\^$.*+?()[\]{}|\/-]/g, "\\$&"); }
let t0 = Date.now();
const cand = new Set();
for (let c = 0; c < 0x110000; c++) {
  if (c >= 0xD800 && c <= 0xDFFF) continue;
  const s = String.fromCodePoint(c);
  const u = s.toUpperCase(), l = s.toLowerCase();
  if (u !== s || l !== s) {
    cand.add(c);
    for (const t of [u, l]) { const a = Array.from(t); if (a.length === 1) cand.add(a[0].codePointAt(0)); }
  }
}
const candArr = [...cand].sort((a, b) => a - b);
console.log("cands", candArr.length, Date.now() - t0); t0 = Date.now();
const S = String.fromCodePoint(...candArr);
let n = 0;
for (let i = 0; i < 200; i++) {
  const c = candArr[i];
  const re = new RegExp(esc(String.fromCodePoint(c)), "giu");
  for (const m of S.matchAll(re)) n++;
}
console.log("200 regexes", n, Date.now() - t0);
EOF
