fn pbkdf2_vectors() {
    for (a, pw, salt, it, kl, expect) in PBKDF2_VECTORS {
        assert_eq!(hex(&pbkdf2(alg(a), &unhex(pw), &unhex(salt), *it, *kl)), *expect, "{} it {}", a, it);
    }
