        .wrapping_add(h * 3_600_000 + mi * 60_000 + sec * 1000 + ms)
        .wrapping_sub(offset_min * 60_000);
    let t = t as f64;
    if t.abs() > MAX_TIME {
        return None;
    }
    Some(t + 0.0)
}
