// generate realistic date strings using node's formatters
let seed = 42; function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
const out = new Set();
const locs = ['en-US', 'en-GB', 'de-DE', 'fr-FR', 'ja-JP', 'es-ES', 'ru-RU', 'zh-CN', 'ko-KR', 'pt-BR', 'nl-NL', 'sv-SE', 'it-IT', 'en-CA', 'en-IN'];
const optsList = [undefined, {dateStyle: 'full'}, {dateStyle: 'long'}, {dateStyle: 'medium'}, {dateStyle: 'short'}, {dateStyle: 'full', timeStyle: 'long'}, {dateStyle: 'medium', timeStyle: 'short'}, {weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'}, {month: 'long', day: 'numeric', year: 'numeric'}, {timeZone: 'America/New_York', timeZoneName: 'short'}];
for (let i = 0; i < 3000; i++) {
  const r = rnd();
  let t;
  if (r < 0.7) t = Math.floor((rnd() - 0.3) * 4e12); else t = Math.floor((rnd() - 0.5) * 1.7e16);
  const d = new Date(t);
  if (isNaN(d)) continue;
  const k = Math.floor(rnd() * 12);
  let s;
  try {
    if (k === 0) s = d.toString();
    else if (k === 1) s = d.toUTCString();
    else if (k === 2) s = d.toISOString();
    else if (k === 3) s = d.toDateString();
    else if (k === 4) s = d.toLocaleString(locs[Math.floor(rnd() * locs.length)], optsList[Math.floor(rnd() * optsList.length)]);
    else if (k === 5) s = d.toLocaleDateString(locs[Math.floor(rnd() * locs.length)]);
    else if (k === 6) s = d.toISOString().replace('T', ' ').replace('Z', '');
    else if (k === 7) s = d.toISOString().slice(0, 10);
    else if (k === 8) s = d.toISOString().slice(0, 19);
    else if (k === 9) s = d.toString().replace(/ \(.*\)/, '');
    else if (k === 10) s = d.toUTCString().replace('GMT', ['+0000', '-0500', 'EST', 'PDT', 'UT', 'Z', 'GMT+0100'][Math.floor(rnd() * 7)]);
    else s = (d.getUTCMonth() + 1) + '/' + d.getUTCDate() + '/' + d.getUTCFullYear() + ' ' + d.getUTCHours() + ':' + String(d.getUTCMinutes()).padStart(2, '0') + [' AM', ' PM', ''][Math.floor(rnd() * 3)];
  } catch (e) { continue; }
  out.add(s);
}
for (const s of out) console.log(JSON.stringify(s));
EOF
node gen_real.js > real.jsonl; wc -l real.jsonl; ./cmp_parse.sh real.jsonl 10

