mod bigint;
mod numconv;

use bigint::BigInt;
use std::io::{BufRead, Write};

fn hex_to_f64(h: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(h, 16).unwrap())
}

fn f64_hex(x: f64) -> String {
    format!("{:016x}", x.to_bits())
}

fn utf16_from_hex(h: &str) -> Vec<u16> {
    if h == "-" {
        return Vec::new();
    }
    (0..h.len() / 4).map(|i| u16::from_str_radix(&h[i * 4..i * 4 + 4], 16).unwrap()).collect()
}

fn big(h: &str) -> BigInt {
    BigInt::from_str_radix(h, 16).unwrap()
}

fn res(r: Result<BigInt, bigint::BigIntError>) -> String {
    match r {
        Ok(v) => v.to_string_radix(16),
        Err(e) => format!("ERR {}", e.message()),
    }
}

fn opt(r: Option<BigInt>) -> String {
    match r {
        Some(v) => v.to_string_radix(16),
        None => "ERR Division by zero".to_string(),
    }
}

fn main() {
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split(' ').collect();
        let r: String = match parts[0] {
            "s" => numconv::number_to_string(hex_to_f64(parts[1])),
            "r" => numconv::number_to_string_radix(hex_to_f64(parts[1]), parts[2].parse().unwrap()),
            "f" => numconv::to_fixed(hex_to_f64(parts[1]), parts[2].parse().unwrap()),
            "e" => {
                let d = if parts[2] == "-" { None } else { Some(parts[2].parse().unwrap()) };
                numconv::to_exponential(hex_to_f64(parts[1]), d)
            }
            "p" => numconv::to_precision(hex_to_f64(parts[1]), parts[2].parse().unwrap()),
            "n" => f64_hex(numconv::string_to_number(&utf16_from_hex(parts[1]))),
            "pf" => f64_hex(numconv::parse_float(&utf16_from_hex(parts[1]))),
            "pi" => f64_hex(numconv::parse_int(&utf16_from_hex(parts[1]), parts[2].parse().unwrap())),
            "lit" => match numconv::parse_numeric_literal(parts[1]) {
                Some(v) => f64_hex(v),
                None => "none".to_string(),
            },
            "b+" => big(parts[1]).add(&big(parts[2])).to_string_radix(16),
            "b-" => big(parts[1]).sub(&big(parts[2])).to_string_radix(16),
            "b*" => big(parts[1]).mul(&big(parts[2])).to_string_radix(16),
            "b/" => opt(big(parts[1]).div(&big(parts[2]))),
            "b%" => opt(big(parts[1]).rem(&big(parts[2]))),
            "b**" => res(big(parts[1]).pow(&big(parts[2]))),
            "b&" => big(parts[1]).bitand(&big(parts[2])).to_string_radix(16),
            "b|" => big(parts[1]).bitor(&big(parts[2])).to_string_radix(16),
            "b^" => big(parts[1]).bitxor(&big(parts[2])).to_string_radix(16),
            "b~" => big(parts[1]).not().to_string_radix(16),
            "bneg" => big(parts[1]).neg().to_string_radix(16),
            "b<<" => res(big(parts[1]).shl(&big(parts[2]))),
            "b>>" => res(big(parts[1]).shr(&big(parts[2]))),
            "bin" => res(big(parts[1]).as_int_n(parts[2].parse().unwrap())),
            "bun" => res(big(parts[1]).as_uint_n(parts[2].parse().unwrap())),
            "bts" => big(parts[1]).to_string_radix(parts[2].parse().unwrap()),
            "bps" => match BigInt::parse(&utf16_from_hex(parts[1])) {
                Some(v) => v.to_string_radix(16),
                None => "none".to_string(),
            },
            "bf" => f64_hex(big(parts[1]).to_f64()),
            "bff" => match BigInt::from_f64(hex_to_f64(parts[1])) {
                Some(v) => v.to_string_radix(16),
                None => "none".to_string(),
            },
            "bc" => match big(parts[1]).cmp_f64(hex_to_f64(parts[2])) {
                Some(std::cmp::Ordering::Less) => "lt".to_string(),
                Some(std::cmp::Ordering::Equal) => "eq".to_string(),
                Some(std::cmp::Ordering::Greater) => "gt".to_string(),
                None => "none".to_string(),
            },
            "bi64" => big(parts[1]).to_i64_wrapping().to_string(),
            "bu64" => big(parts[1]).to_u64_wrapping().to_string(),
            "bdec" => big(parts[1]).to_string_radix(10),
            "bpdec" => match BigInt::from_str_radix(parts[1], 10) {
                Some(v) => v.to_string_radix(16),
                None => "none".to_string(),
            },
            other => format!("unknown command {}", other),
        };
        writeln!(out, "{}", r).unwrap();
    }
}

