emoji = sorted(toset(p17["\\p{Emoji}"]))
ebase = set(toset(p17["\\p{Emoji_Modifier_Base}"]))
tones = list(range(0x1F3FB, 0x1F400))
ZWJ = 0x200D; VS = 0xFE0F
zwj15 = [tuple(s) for s in s15['RGI_Emoji_ZWJ_Sequence']['strings']]
C = set()
# a. append direction
for s in zwj15: C.add(s + (ZWJ, 0x27A1, VS))
# b. direction patterns
persons = [0x1F6B6, 0x1F3C3, 0x1F9CE, 0x1F9D1, 0x1F468, 0x1F469]
for p in persons:
    for t in [None] + tones:
        base = (p,) if t is None else (p, t)
        C.add(base + (ZWJ, 0x27A1, VS))
        for g in (0x2640, 0x2642):
            C.add(base + (ZWJ, g, VS, ZWJ, 0x27A1, VS))
        for obj in (0x1F9AF, 0x1F9BC, 0x1F9BD):
            C.add(base + (ZWJ, obj, ZWJ, 0x27A1, VS))
            C.add(base + (ZWJ, obj))
# c. families
fam = [0x1F468, 0x1F469, 0x1F9D1, 0x1F466, 0x1F467, 0x1F9D2]
for k in (2, 3, 4):
    for combo in itertools.product(fam, repeat=k):
        seq = []
        for i, x in enumerate(combo):
            if i: seq.append(ZWJ)
            seq.append(x)
        C.add(tuple(seq))
# d. P1 [T1] ZWJ X [FE0F] ZWJ P2 [T2]
ps = [0x1F9D1, 0x1F468, 0x1F469]
pvars = []
for p in ps:
    pvars.append((p,))
    for t in tones: pvars.append((p, t))
xs = []
for x in emoji:
    xs.append((x,)); xs.append((x, VS))
for p1 in pvars:
    for x in xs:
        for p2 in pvars:
            C.add(p1 + (ZWJ,) + x + (ZWJ,) + p2)
# g. tone variants of 15.0 sequences
for s in zwj15:
    # split into components by ZWJ
    comps = []; cur = []
    for c in s:
        if c == ZWJ: comps.append(tuple(cur)); cur = []
        else: cur.append(c)
    comps.append(tuple(cur))
    opts = []
    for comp in comps:
