            rest = tuple(x for x in comp[1:] if not (0x1F3FB <= x <= 0x1F3FF))
            o = [v + rest for v in o]
            opts.append(o)
        else:
            opts.append([comp])
    for combo in itertools.product(*opts):
        seq = []
        for i, comp in enumerate(combo):
            if i: seq.append(ZWJ)
            seq.extend(comp)
        C.add(tuple(seq))
C -= set(zwj15)
print("candidates", len(C))
