function big(h) { return h.startsWith('-') ? -BigInt('0x' + h.slice(1)) : BigInt('0x' + h); }
function t(fn) { try { return fn(); } catch (e) { return 'none'; } }
const out = [];
for (const line of lines) {
  if (!line) continue;
  const p = line.split(' ');
  let r;
  try {
    switch (p[0]) {
      case 's': r = String(f(p[1])); break;
      case 'r': r = f(p[1]).toString(+p[2]); break;
      case 'f': r = f(p[1]).toFixed(+p[2]); break;
      case 'e': r = p[2] === '-' ? f(p[1]).toExponential() : f(p[1]).toExponential(+p[2]); break;
      case 'p': r = f(p[1]).toPrecision(+p[2]); break;
      case 'n': r = hx(Number(u16(p[1]))); break;
      case 'pf': r = hx(parseFloat(u16(p[1]))); break;
      case 'pi': r = hx(parseInt(u16(p[1]), +p[2])); break;
      case 'lit': r = t(() => hx(eval(p[1]))); break;
      case 'b+': r = (big(p[1]) + big(p[2])).toString(16); break;
      case 'b-': r = (big(p[1]) - big(p[2])).toString(16); break;
      case 'b*': r = (big(p[1]) * big(p[2])).toString(16); break;
      case 'b/': r = (big(p[1]) / big(p[2])).toString(16); break;
      case 'b%': r = (big(p[1]) % big(p[2])).toString(16); break;
      case 'b**': r = (big(p[1]) ** big(p[2])).toString(16); break;
      case 'b&': r = (big(p[1]) & big(p[2])).toString(16); break;
      case 'b|': r = (big(p[1]) | big(p[2])).toString(16); break;
      case 'b^': r = (big(p[1]) ^ big(p[2])).toString(16); break;
      case 'b~': r = (~big(p[1])).toString(16); break;
      case 'bneg': r = (-big(p[1])).toString(16); break;
      case 'b<<': r = (big(p[1]) << big(p[2])).toString(16); break;
      case 'b>>': r = (big(p[1]) >> big(p[2])).toString(16); break;
      case 'bin': r = BigInt.asIntN(+p[2], big(p[1])).toString(16); break;
      case 'bun': r = BigInt.asUintN(+p[2], big(p[1])).toString(16); break;
      case 'bts': r = big(p[1]).toString(+p[2]); break;
      case 'bps': r = t(() => BigInt(u16(p[1])).toString(16)); break;
      case 'bf': r = hx(Number(big(p[1]))); break;
      case 'bff': r = t(() => BigInt(f(p[1])).toString(16)); break;
      case 'bc': { const a = big(p[1]), x = f(p[2]); r = a < x ? 'lt' : a > x ? 'gt' : a == x ? 'eq' : 'none'; break; }
      case 'bi64': r = BigInt.asIntN(64, big(p[1])).toString(); break;
