      case 'bdec': r = big(p[1]).toString(); break;
      case 'bpdec': r = t(() => BigInt(p[1]).toString(16)); break;
      default: r = 'unknown command ' + p[0];
    }
  } catch (e) { r = 'ERR ' + e.message; }
  out.push(r);
}
process.stdout.write(out.join('\n') + '\n');
