def hexf(x): return '%016x' % bits_of(x)
def rand_double():
    k = rng.random()
    if k < 0.2:
        while True:
            b = rng.getrandbits(64)
            x = struct.unpack('>d', struct.pack('>Q', b))[0]
            if x == x and abs(x) != float('inf'): return x
    if k < 0.3:
        e = rng.randint(1023 - 80, 1023 + 80)
        b = (rng.getrandbits(1) << 63) | (e << 52) | rng.getrandbits(52)
        return struct.unpack('>d', struct.pack('>Q', b))[0]
    if k < 0.4: return rng.randint(0, 10**6) / 10 ** rng.randint(0, 8)
    if k < 0.5: return (rng.randint(-100000, 100000)) / 8
    if k < 0.55: return rng.randint(0, 10**5) + 0.5
    if k < 0.6: return rng.randint(0, 2**30) * 2.0 ** rng.randint(-70, 70)
    if k < 0.65: return float(rng.randint(-2**53, 2**53))
    if k < 0.7: return float(rng.randint(0, 10**22)) * rng.choice([1, -1])
    if k < 0.75: return rng.choice([0.0, -0.0, 5e-324, -5e-324, 1.7976931348623157e308, 2.2250738585072014e-308, 1e21, 1e-7, 1e-6, 0.1, 0.5, 2**53, 2**64, 2**63, 2**64 - 2048, 1e20, 999999999999999999999.0, 0.000001, 123.456, 2.5, 1.005, 1.45])
    if k < 0.85: return float('%de%d' % (rng.randint(1, 10**rng.randint(1, 17)), rng.randint(-330, 310)))
    # short decimals near rounding boundaries
    d = rng.randint(1, 20)
    return float('0.' + ''.join(rng.choice('0123456789') for _ in range(d)) + '5') * 10 ** rng.randint(-5, 10)

WS = [0x9, 0xa, 0xb, 0xc, 0xd, 0x20, 0xa0, 0x1680, 0x2000, 0x2005, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0xfeff, 0x180e, 0x200b, 0x85]
def rand_numeric_string():
    parts = []
    k = rng.random()
    ws = lambda: ''.join(chr(rng.choice(WS)) for _ in range(rng.randint(0, 2))) if rng.random() < 0.3 else ''
    s = ws()
    if rng.random() < 0.3: s += rng.choice(['+', '-', '', '--', '+-'])
    if k < 0.15:
        s += rng.choice(['0x', '0X', '0o', '0O', '0b', '0B', 'x', '0'])
        s += ''.join(rng.choice('0123456789abcdefABCDEFgz') for _ in range(rng.randint(0, 30)))
    elif k < 0.2:
        s += rng.choice(['Infinity', 'infinity', 'Infinit', 'Infinityx', 'NaN', 'INFINITY', 'Inf'])
    else:
        nd = rng.choice([0, 1, 2, 5, 10, 15, 16, 17, 18, 19, 20, 25, 40, 100, 400])
        s += ''.join(rng.choice('0123456789') for _ in range(nd))
        if rng.random() < 0.5:
            s += '.' + ''.join(rng.choice('0123456789') for _ in range(rng.choice([0, 1, 3, 10, 20, 50])))
        if rng.random() < 0.4:
            s += rng.choice('eE') + rng.choice(['', '+', '-']) + ''.join(rng.choice('0123456789') for _ in range(rng.choice([0, 1, 2, 3, 4, 20])))
        if rng.random() < 0.1: s += rng.choice(['_', '_1', 'n', 'abc', '.', 'e', 'x', ' 1', 'é'])
