out = []
for _ in range(count):
    if kind == 'num':
        x = rand_double()
        h = hexf(x)
        c = rng.random()
        if c < 0.15: out.append('s ' + h)
        elif c < 0.3: out.append('r %s %d' % (h, rng.choice([2, 3, 4, 5, 7, 8, 9, 11, 16, 20, 32, 35, 36])))
        elif c < 0.5: out.append('f %s %d' % (h, rng.choice([0, 1, 2, 3, 5, 10, 20, rng.randint(0, 100)])))
        elif c < 0.7: out.append('e %s %s' % (h, rng.choice(['-', '0', '1', '2', '5', '10', '16', '20', str(rng.randint(0, 100))])))
