        elif c < 0.26: out.append('b* %s %s' % (bh(a), bh(b)))
        elif c < 0.36: out.append('b/ %s %s' % (bh(a), bh(b if rng.random() < 0.95 else 0)))
        elif c < 0.44: out.append('b%% %s %s' % (bh(a), bh(b if rng.random() < 0.95 else 0)))
        elif c < 0.47: out.append('b** %s %s' % (bh(rand_big(64)), bh(rng.choice([0, 1, 2, 3, 7, 20, 100, -1, rng.randint(0, 300)]))))
        elif c < 0.52: out.append('b& %s %s' % (bh(a), bh(b)))
        elif c < 0.57: out.append('b| %s %s' % (bh(a), bh(b)))
        elif c < 0.62: out.append('b^ %s %s' % (bh(a), bh(b)))
        elif c < 0.64: out.append('b~ %s' % bh(a))
        elif c < 0.69: out.append('b<< %s %s' % (bh(a), bh(rng.randint(-400, 400))))
        elif c < 0.74: out.append('b>> %s %s' % (bh(a), bh(rng.randint(-400, 4000))))
        elif c < 0.78: out.append('bin %s %d' % (bh(a), rng.choice([0, 1, 2, 3, 8, 63, 64, 65, 128, rng.randint(0, 4000)])))
        elif c < 0.82: out.append('bun %s %d' % (bh(a), rng.choice([0, 1, 2, 3, 8, 63, 64, 65, 128, rng.randint(0, 4000)])))
        elif c < 0.9: out.append('bts %s %d' % (bh(a), rng.randint(2, 36)))
        elif c < 0.93: out.append('bf %s' % bh(rand_big(1100)))
        elif c < 0.95: out.append('bff %s' % hexf(rand_double()))
