import random, struct, sys
seed = int(sys.argv[1]); kind = sys.argv[2]; count = int(sys.argv[3])
rng = random.Random(seed)
def bits_of(x): return struct.unpack('>Q', struct.pack('>d', x))[0]
def hexf(x): return '%016x' % bits_of(x)
def rand_double():
    k = rng.random()
    if k < 0.2:
        while True:
            b = rng.getrandbits(64)
            x = struct.unpack('>d', struct.pack('>Q', b))[0]
            if x == x and abs(x) != float('inf'): return x
    if k < 0.3:
        e = rng.randint(1023 - 80, 1023 + 80)
        b = (rng.getrandbits(1) << 63) | (e << 52) | rng.getrandbits(52)
        return struct.unpack('>d', struct.pack('>Q', b))[0]
    if k < 0.4: return rng.randint(0, 10**6) / 10 ** rng.randint(0, 8)
    if k < 0.5: return (rng.randint(-100000, 100000)) / 8
    if k < 0.55: return rng.randint(0, 10**5) + 0.5
    if k < 0.6: return rng.randint(0, 2**30) * 2.0 ** rng.randint(-70, 70)
    if k < 0.65: return float(rng.randint(-2**53, 2**53))
    if k < 0.7: return float(rng.randint(0, 10**22)) * rng.choice([1, -1])
    if k < 0.75: return rng.choice([0.0, -0.0, 5e-324, -5e-324, 1.7976931348623157e308, 2.2250738585072014e-308, 1e21, 1e-7, 1e-6, 0.1, 0.5, 2**53, 2**64, 2**63, 2**64 - 2048, 1e20, 999999999999999999999.0, 0.000001, 123.456, 2.5, 1.005, 1.45])
    if k < 0.85: return float('%de%d' % (rng.randint(1, 10**rng.randint(1, 17)), rng.randint(-330, 310)))
    # short decimals near rounding boundaries
    d = rng.randint(1, 20)
    return float('0.' + ''.join(rng.choice('0123456789') for _ in range(d)) + '5') * 10 ** rng.randint(-5, 10)

WS = [0x9, 0xa, 0xb, 0xc, 0xd, 0x20, 0xa0, 0x1680, 0x2000, 0x2005, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0xfeff, 0x180e, 0x200b, 0x85]
def rand_numeric_string():
    parts = []
    k = rng.random()
    ws = lambda: ''.join(chr(rng.choice(WS)) for _ in range(rng.randint(0, 2))) if rng.random() < 0.3 else ''
    s = ws()
    if rng.random() < 0.3: s += rng.choice(['+', '-', '', '--', '+-'])
    if k < 0.15:
        s += rng.choice(['0x', '0X', '0o', '0O', '0b', '0B', 'x', '0'])
        s += ''.join(rng.choice('0123456789abcdefABCDEFgz') for _ in range(rng.randint(0, 30)))
    elif k < 0.2:
        s += rng.choice(['Infinity', 'infinity', 'Infinit', 'Infinityx', 'NaN', 'INFINITY', 'Inf'])
    else:
        nd = rng.choice([0, 1, 2, 5, 10, 15, 16, 17, 18, 19, 20, 25, 40, 100, 400])
        s += ''.join(rng.choice('0123456789') for _ in range(nd))
        if rng.random() < 0.5:
            s += '.' + ''.join(rng.choice('0123456789') for _ in range(rng.choice([0, 1, 3, 10, 20, 50])))
        if rng.random() < 0.4:
            s += rng.choice('eE') + rng.choice(['', '+', '-']) + ''.join(rng.choice('0123456789') for _ in range(rng.choice([0, 1, 2, 3, 4, 20])))
        if rng.random() < 0.1: s += rng.choice(['_', '_1', 'n', 'abc', '.', 'e', 'x', ' 1', 'é'])
    s += ws()
    return s

def u16hex(s):
    if s == '': return '-'
    b = s.encode('utf-16-be')
    return b.hex()

def rand_big(maxbits=3000):
    k = rng.random()
    if k < 0.1: v = rng.choice([0, 1, 2, 3, 2**63, 2**64, 2**64 - 1, 2**128, 2**64 + 1, 10**19, 2**63 - 1])
    elif k < 0.2: v = (1 << rng.randint(0, maxbits)) - rng.choice([0, 1])
    elif k < 0.5: v = rng.getrandbits(rng.randint(1, 200))
    elif k < 0.95: v = rng.getrandbits(rng.randint(1, maxbits))
    else: v = rng.getrandbits(rng.randint(maxbits, maxbits * 4))
    if rng.random() < 0.5: v = -v
    return v
def bh(v): return ('-' if v < 0 else '') + format(abs(v), 'x')

out = []
for _ in range(count):
    if kind == 'num':
        x = rand_double()
        h = hexf(x)
        c = rng.random()
        if c < 0.15: out.append('s ' + h)
        elif c < 0.3: out.append('r %s %d' % (h, rng.choice([2, 3, 4, 5, 7, 8, 9, 11, 16, 20, 32, 35, 36])))
        elif c < 0.5: out.append('f %s %d' % (h, rng.choice([0, 1, 2, 3, 5, 10, 20, rng.randint(0, 100)])))
        elif c < 0.7: out.append('e %s %s' % (h, rng.choice(['-', '0', '1', '2', '5', '10', '16', '20', str(rng.randint(0, 100))])))
        else: out.append('p %s %d' % (h, rng.choice([1, 2, 3, 5, 10, 15, 16, 17, 18, 21, rng.randint(1, 100)])))
    elif kind == 'str':
        s = rand_numeric_string()
        c = rng.random()
        if c < 0.4: out.append('n ' + u16hex(s))
        elif c < 0.7: out.append('pf ' + u16hex(s))
        else: out.append('pi %s %d' % (u16hex(s), rng.choice([0, 0, 0, 2, 8, 10, 16, 36, 1, 37, -1, rng.randint(2, 36)])))
    elif kind == 'big':
        a = rand_big(); b = rand_big()
        c = rng.random()
        if c < 0.08: out.append('b+ %s %s' % (bh(a), bh(b)))
        elif c < 0.16: out.append('b- %s %s' % (bh(a), bh(b)))
        elif c < 0.26: out.append('b* %s %s' % (bh(a), bh(b)))
        elif c < 0.36: out.append('b/ %s %s' % (bh(a), bh(b if rng.random() < 0.95 else 0)))
        elif c < 0.44: out.append('b%% %s %s' % (bh(a), bh(b if rng.random() < 0.95 else 0)))
        elif c < 0.47: out.append('b** %s %s' % (bh(rand_big(64)), bh(rng.choice([0, 1, 2, 3, 7, 20, 100, -1, rng.randint(0, 300)]))))
        elif c < 0.52: out.append('b& %s %s' % (bh(a), bh(b)))
        elif c < 0.57: out.append('b| %s %s' % (bh(a), bh(b)))
        elif c < 0.62: out.append('b^ %s %s' % (bh(a), bh(b)))
        elif c < 0.64: out.append('b~ %s' % bh(a))
        elif c < 0.69: out.append('b<< %s %s' % (bh(a), bh(rng.randint(-400, 400))))
        elif c < 0.74: out.append('b>> %s %s' % (bh(a), bh(rng.randint(-400, 4000))))
        elif c < 0.78: out.append('bin %s %d' % (bh(a), rng.choice([0, 1, 2, 3, 8, 63, 64, 65, 128, rng.randint(0, 4000)])))
        elif c < 0.82: out.append('bun %s %d' % (bh(a), rng.choice([0, 1, 2, 3, 8, 63, 64, 65, 128, rng.randint(0, 4000)])))
        elif c < 0.9: out.append('bts %s %d' % (bh(a), rng.randint(2, 36)))
        elif c < 0.93: out.append('bf %s' % bh(rand_big(1100)))
        elif c < 0.95: out.append('bff %s' % hexf(rand_double()))
        elif c < 0.97:
            x = rand_double()
            v = int(x) if rng.random() < 0.5 and abs(x) < 1e300 else rand_big(1100)
            v += rng.choice([0, 0, 1, -1])
            out.append('bc %s %s' % (bh(v), hexf(x)))
        elif c < 0.98: out.append('bi64 %s' % bh(a))
        elif c < 0.99: out.append('bu64 %s' % bh(a))
        else: out.append('bdec %s' % bh(a))
    elif kind == 'bps':
        k = rng.random()
        if k < 0.5: s = str(rand_big(400))
        else:
            s = rng.choice(['', ' ', '+', '-', '0x', '0X', '0o', '0b', '-0x', '+0x'])
            s += ''.join(rng.choice('0123456789abcdefxXoOb_. ') for _ in range(rng.randint(0, 20)))
        if rng.random() < 0.3: s = chr(rng.choice(WS)) + s + chr(rng.choice(WS))
        out.append('bps ' + u16hex(s))
print('\n'.join(out))
