'; ls -la /tmp/cp/*.pem; cat > /tmp/cp/p36.js <<'EOF'
const c=require("crypto"); const fs=require("fs");
function show(r) { return r instanceof Uint8Array ? r.constructor.name+":"+Buffer.from(r).toString('hex') : (r instanceof ArrayBuffer ? "AB:"+Buffer.from(r).toString('hex') : (typeof r === 'bigint' ? r+'n' : JSON.stringify(r, (k,v)=>typeof v==='bigint'? v.toString()+'n' : v))); }
function t(label, f) { try { const r = f(); console.log(label, "=>", show(r)); } catch(e) { console.log(label, "ERR", e && e.name, e && e.code, JSON.stringify(e && e.message)); } }
const pem = fs.readFileSync('/tmp/cp/rsa1024.pem', 'utf8');
const priv = c.createPrivateKey(pem);
const pub = c.createPublicKey(pem);
const data = Buffer.from('hello world');
t("details", ()=>[priv.asymmetricKeyType, priv.asymmetricKeyDetails, pub.asymmetricKeyDetails]);
t("sign sha256", ()=>c.sign('sha256', data, priv));
t("sign md5", ()=>c.sign('md5', data, priv));
t("sign sha1", ()=>c.sign('sha1', data, priv));
t("sign sha384", ()=>c.sign('sha384', data, priv));
t("sign sha512", ()=>c.sign('sha512', data, priv));
t("sign sha512-224", ()=>c.sign('sha512-224', data, priv));
t("pss salt0", ()=>c.sign('sha256', data, {key: priv, padding: 6, saltLength: 0}));
t("pss verify auto", ()=>{ const s = c.sign('sha256', data, {key: priv, padding: 6, saltLength: 10}); return [c.verify('sha256', data, {key: pub, padding: 6}, s), c.verify('sha256', data, {key: pub, padding: 6, saltLength: 10}, s), c.verify('sha256', data, {key: pub, padding: 6, saltLength: 11}, s), c.verify('sha256', data, {key: pub, padding: 6, saltLength: -2}, s), c.verify('sha256', data, {key: pub, padding: 6, saltLength: -1}, s)]; });
t("pss default salt len", ()=>{ const s = c.sign('sha256', data, {key: priv, padding: 6}); return [c.verify('sha256', data, {key: pub, padding: 6, saltLength: 32}, s), c.verify('sha256', data, {key: pub, padding: 6, saltLength: 128-32-2}, s)]; });
t("pss saltlen -1", ()=>{ const s = c.sign('sha256', data, {key: priv, padding: 6, saltLength: -1}); return [c.verify('sha256', data, {key: pub, padding: 6, saltLength: 32}, s)]; });
t("pss saltlen -2", ()=>{ const s = c.sign('sha256', data, {key: priv, padding: 6, saltLength: -2}); return [c.verify('sha256', data, {key: pub, padding: 6, saltLength: 128-32-2}, s)]; });
t("pss saltlen too big", ()=>c.sign('sha256', data, {key: priv, padding: 6, saltLength: 1000}));
t("pss md5", ()=>c.sign('md5', data, {key: priv, padding: 6, saltLength: 0}));
t("pss sha512-256", ()=>c.sign('sha512-256', data, {key: priv, padding: 6, saltLength: 0}));
t("bad padding sign", ()=>c.sign('sha256', data, {key: priv, padding: 3}));
t("bad padding sign 4", ()=>c.sign('sha256', data, {key: priv, padding: 4}));
t("publicEncrypt default (oaep)", ()=>{ const ct = c.publicEncrypt(pub, data); return [ct.length, c.privateDecrypt(priv, ct).toString()]; });
t("publicEncrypt oaep sha256", ()=>{ const ct = c.publicEncrypt({key: pub, oaepHash: 'sha256'}, data); return [ct.length, c.privateDecrypt({key: priv, oaepHash: 'sha256'}, ct).toString()]; });
t("publicEncrypt oaep label", ()=>{ const ct = c.publicEncrypt({key: pub, oaepHash: 'sha256', oaepLabel: Buffer.from('lbl')}, data); return [ct.length, c.privateDecrypt({key: priv, oaepHash: 'sha256', oaepLabel: Buffer.from('lbl')}, ct).toString()]; });
t("oaep wrong label", ()=>{ const ct = c.publicEncrypt({key: pub, oaepHash: 'sha256', oaepLabel: Buffer.from('lbl')}, data); return c.privateDecrypt({key: priv, oaepHash: 'sha256'}, ct).toString(); });
t("oaep wrong hash", ()=>{ const ct = c.publicEncrypt({key: pub, oaepHash: 'sha256'}, data); return c.privateDecrypt({key: priv}, ct).toString(); });
t("oaep too long", ()=>c.publicEncrypt(pub, Buffer.alloc(128-2*20-2+1)));
t("oaep max", ()=>c.publicEncrypt(pub, Buffer.alloc(128-2*20-2)).length);
t("oaep bad hash", ()=>c.publicEncrypt({key: pub, oaepHash: 'sha3-256'}, data));
t("pkcs1 enc", ()=>{ const ct = c.publicEncrypt({key: pub, padding: 1}, data); return [ct.length, c.privateDecrypt({key: priv, padding: 1}, ct)]; });
t("pkcs1 enc too long", ()=>c.publicEncrypt({key: pub, padding: 1}, Buffer.alloc(118)));
t("pkcs1 enc max", ()=>c.publicEncrypt({key: pub, padding: 1}, Buffer.alloc(117)).length);
t("nopad enc", ()=>{ const m = Buffer.alloc(128, 1); const ct = c.publicEncrypt({key: pub, padding: 3}, m); return [ct.length, c.privateDecrypt({key: priv, padding: 3}, ct).equals(m)]; });
t("nopad enc short", ()=>c.publicEncrypt({key: pub, padding: 3}, Buffer.alloc(10, 1)));
t("nopad enc too big", ()=>c.publicEncrypt({key: pub, padding: 3}, Buffer.alloc(128, 0xff)));
t("privateEncrypt", ()=>{ const ct = c.privateEncrypt(priv, data); return [ct.toString('hex'), c.publicDecrypt(pub, ct).toString()]; });
t("privateEncrypt nopad", ()=>{ const m = Buffer.alloc(128, 1); const ct = c.privateEncrypt({key: priv, padding: 3}, m); return [ct.length, c.publicDecrypt({key: pub, padding: 3}, ct).equals(m)]; });
t("privateEncrypt too long", ()=>c.privateEncrypt(priv, Buffer.alloc(118)));
t("publicDecrypt bad", ()=>c.publicDecrypt(pub, Buffer.alloc(128, 1)));
t("privateDecrypt bad oaep", ()=>c.privateDecrypt(priv, Buffer.alloc(128, 1)));
t("privateDecrypt wrong len", ()=>c.privateDecrypt(priv, Buffer.alloc(100, 1)));
t("privateDecrypt too big", ()=>c.privateDecrypt(priv, Buffer.alloc(128, 0xff)));
t("publicEncrypt with private key obj", ()=>{ const ct = c.publicEncrypt(priv, data); return c.privateDecrypt(priv, ct).toString(); });
t("publicEncrypt pem string", ()=>{ const ct = c.publicEncrypt(pem, data); return c.privateDecrypt(pem, ct).toString(); });
t("pkcs1 export", ()=>priv.export({type:'pkcs1', format:'pem'}) === fs.readFileSync('/tmp/cp/rsa1024_pkcs1.pem','utf8'));
t("pkcs8 export", ()=>priv.export({type:'pkcs8', format:'pem'}) === pem);
t("pub pkcs1", ()=>pub.export({type:'pkcs1', format:'der'}).toString('hex').slice(0,20));
t("jwk roundtrip", ()=>{ const j = priv.export({format:'jwk'}); const k = c.createPrivateKey({key: j, format: 'jwk'}); return k.export({type:'pkcs8', format:'pem'}) === pem; });
EOF
/tmp/orig /tmp/cp/p36.js > /tmp/cp/p36.orig.txt 2>&1; node /tmp/cp/p36.js > /tmp/cp/p36.node.txt 2>&1; diff /tmp/cp/p36.orig.txt /tmp/cp/p36.node.txt; echo ====; cat /tmp/cp/p36.orig.txt

