        if r.len() <= 4 {
            for &(a, b) in r {
                if c < a {
                    return false;
                }
                if c <= b {
                    return true;
                }
            }
            return false;
        }
        let mut lo = 0usize;
        let mut hi = r.len();
        while lo < hi {
            let mid = (lo + hi) / 2;
            let (a, b) = r[mid];
            if c < a {
                hi = mid;
            } else if c > b {
                lo = mid + 1;
            } else {
                return true;
            }
        }
        false
    }

    pub(crate) fn union(&self, o: &CharSet) -> CharSet {
        if o.r.is_empty() {
            return self.clone();
        }
        if self.r.is_empty() {
            return o.clone();
        }
        let mut v = Vec::with_capacity(self.r.len() + o.r.len());
        v.extend_from_slice(&self.r);
        v.extend_from_slice(&o.r);
