arguments.command:
cat > /tmp/gen/gen_bigint.py <<'EOF'
import random
random.seed(42)
out = ["pub const BIGINT_VECTORS: &[(&str, &str, &str, &str, &str, &str, &str)] = &["]
# (a, b, a*b, a//b, a%b, a+b, a-b or "-")
def rnd(bits):
    if bits == 0: return 0
    k = random.randint(1, bits)
    v = random.getrandbits(k)
    if random.random() < 0.2:  # patterns with many ff / 00 limbs
        v = (1 << k) - 1 - random.getrandbits(random.randint(1, max(1,k//2)))
    return v
for i in range(400):
    a = rnd(random.choice([64, 128, 200, 512, 1100, 2100]))
    b = rnd(random.choice([1, 63, 64, 65, 128, 300, 512, 1024]))
    if b == 0: b = 1
    if random.random() < 0.1: b = a // random.randint(1, 1000) or 1
    out.append('    ("%x", "%x", "%x", "%x", "%x", "%x", "%s"),' % (a, b, a*b, a//b, a%b, a+b, ("%x" % (a-b)) if a>=b else "-"))
out.append("];")
out.append("pub const MODPOW_VECTORS: &[(&str, &str, &str, &str)] = &[")
for i in range(120):
    mbits = random.choice([64, 127, 256, 521, 1024, 2048])
    m = random.getrandbits(mbits) | (1 << (mbits-1))
    if random.random() < 0.7: m |= 1
    a = random.getrandbits(mbits + random.randint(-10, 10))
    e = random.getrandbits(random.choice([1, 17, 64, 256, mbits]))
    out.append('    ("%x", "%x", "%x", "%x"),' % (a, e, m, pow(a, e, m)))
out.append("];")
out.append("pub const MODINV_VECTORS: &[(&str, &str, &str)] = &[")
import math
for i in range(80):
    mbits = random.choice([64, 128, 256, 1024])
    m = random.getrandbits(mbits) | 1
    a = random.getrandbits(mbits)
    inv = pow(a, -1, m) if math.gcd(a, m) == 1 else None
    out.append('    ("%x", "%x", "%s"),' % (a, m, ("%x" % inv) if inv is not None else "-"))
out.append("];")
print("\n".join(out))
EOF
python3 /tmp/gen/gen_bigint.py > /tmp/crypto_dev/src/crypto/test_vectors_bigint.rs; wc -c /tmp/crypto_dev/src/crypto/test_vectors_bigint.rs
cd /tmp/crypto_dev && python3 - <<'EOF'
p='/tmp/crypto_dev/src/crypto/mod.rs'
s=open(p).read()
s=s.replace("pub mod argon2;\n", "pub mod argon2;\npub mod bigint;\n")
s=s.replace("#[cfg(test)]\nmod test_vectors_cipher;", "#[cfg(test)]\nmod test_vectors_cipher;\n#[cfg(test)]\nmod test_vectors_bigint;")
s=s.replace("pub use blake2b::", "pub use bigint::BigUint;\npub use blake2b::")
open(p,'w').write(s)
EOF
cat >> src/crypto/tests.rs <<'EOF'

#[test]
fn bigint_vectors() {
    use super::test_vectors_bigint::*;
    let h = |s: &str| BigUint::from_hex(s).unwrap();
    for (a, b, prod, q, r, sum, diff) in BIGINT_VECTORS {
        let (a, b) = (h(a), h(b));
        assert_eq!(a.mul(&b).to_hex(), *prod);
        let (qq, rr) = a.divrem(&b);
        assert_eq!(qq.to_hex(), *q, "a={:?} b={:?}", a, b);
        assert_eq!(rr.to_hex(), *r);
        assert_eq!(a.add(&b).to_hex(), *sum);
        match a.checked_sub(&b) {
            Some(d) => assert_eq!(d.to_hex(), *diff),
            None => assert_eq!(*diff, "-"),
        }
        assert_eq!(BigUint::from_bytes_be(&a.to_bytes_be()), a);
        assert_eq!(a.shl(77).shr(77), a);
        assert_eq!(BigUint::from_decimal(&a.to_decimal()).unwrap(), a);
    }
    for (a, e, m, r) in MODPOW_VECTORS {
        assert_eq!(h(a).modpow(&h(e), &h(m)).to_hex(), *r, "modpow");
    }
    for (a, m, inv) in MODINV_VECTORS {
        match h(a).modinv(&h(m)) {
            Some(v) => assert_eq!(v.to_hex(), *inv),
            None => assert_eq!(*inv, "-"),
        }
    }
    assert_eq!(BigUint::from_u64(255).to_bytes_be_padded(3), vec![0, 0, 255]);
    assert!(BigUint::zero().to_bytes_be().is_empty());
    assert_eq!(BigUint::from_hex("0").unwrap(), BigUint::zero());
}
EOF
cargo test --release bigint 2>&1 | grep -E "test |result|error|panicked" | head

