    let e = dd.exp;
    if e < -6 || e >= p as i32 {
        out.push(d[0] as char);
        if p > 1 {
            out.push('.');
            push_ascii(&mut out, &d[1..]);
        }
        push_exponent(&mut out, e);
    } else if e == p as i32 - 1 {
        push_ascii(&mut out, d);
    } else if e >= 0 {
        let k = e as usize + 1;
        push_ascii(&mut out, &d[..k]);
        out.push('.');
        push_ascii(&mut out, &d[k..]);
    } else {
        out.push_str("0.");
        for _ in 0..(-(e + 1)) {
            out.push('0');
        }
        push_ascii(&mut out, d);
    }
    out
}

