cd /tmp/date_dev/tz && cat > orig_offsets.js <<'EOF'
const fs = require('fs');
const names = fs.readFileSync(process.argv[process.argv.length - 2], 'utf8').split('\n').filter(x => x);
const step = Number(process.argv[process.argv.length - 1]);
const out = [];
const start = Date.UTC(1900, 0, 1), end = Date.UTC(2040, 0, 1);
for (const z of names) {
  const f = new Intl.DateTimeFormat('en', {timeZone: z, year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric', hourCycle: 'h23'});
  const offs = [];
  for (let t = start; t < end; t += step) {
    const p = f.formatToParts(t);
    const g = {}; for (const x of p) g[x.type] = Number(x.value);
    const local = Date.UTC(g.year, g.month - 1, g.day, g.hour, g.minute, g.second);
    offs.push(Math.round((local - Math.floor(t / 1000) * 1000) / 1000));
  }
  out.push(z + '\t' + offs.join(','));
}
