import random, sys
rng = random.Random(int(sys.argv[1])); count = int(sys.argv[2])
def rb():
    bits = rng.choice([64, 128, 2000, 2560, 2600, 5000, 10000, 30000, 70000, 150000])
    k = rng.random()
    if k < 0.15: v = (1 << bits) - 1
    elif k < 0.25: v = 1 << bits
    else: v = rng.getrandbits(bits) | (1 << (bits - 1))
    return -v if rng.random() < 0.3 else v
def bh(v): return ('-' if v < 0 else '') + format(abs(v), 'x')
out = []
for _ in range(count):
    a, b = rb(), rb()
    c = rng.random()
    if c < 0.3: out.append('b* %s %s' % (bh(a), bh(b)))
    elif c < 0.5: out.append('b/ %s %s' % (bh(a), bh(b)))
    elif c < 0.65: out.append('b%% %s %s' % (bh(a), bh(b)))
    elif c < 0.8: out.append('bdec %s' % bh(a))
    elif c < 0.9: out.append('bts %s %d' % (bh(a), rng.choice([3, 7, 10, 36, 8, 32])))
    else:
        # decimal parse round trip
        out.append('bpdec %s' % str(a))
print('\n'.join(out))
EOF
