cd /tmp/numtest && cat > genradix.py <<'EOF'
import random, struct, sys, math
rng = random.Random(int(sys.argv[1])); count = int(sys.argv[2])
def hexf(x): return '%016x' % struct.unpack('>Q', struct.pack('>d', x))[0]
out = []
for _ in range(count):
    k = rng.random()
    if k < 0.3:
        while True:
            x = struct.unpack('>d', struct.pack('>Q', rng.getrandbits(64)))[0]
            if math.isfinite(x): break
    elif k < 0.5: x = rng.random() * 10 ** rng.randint(-10, 25)
    elif k < 0.6: x = rng.randint(0, 2**64) * rng.choice([1.0, -1.0])
    elif k < 0.7: x = rng.randint(1, 1000) / rng.randint(1, 1000)
    elif k < 0.8: x = rng.random() * 2.0 ** rng.randint(-1074, -900)
    elif k < 0.9: x = rng.choice([0.0, -0.0, 2**64, 2**64 - 2048, 2**63, 2**53, 2**53 + 2, 1e21, 0.1, 0.5, 1/3, math.pi, math.e, 5e-324, 1.7976931348623157e308, float('nan'), float('inf'), -float('inf')])
    else: x = rng.randint(0, 2**53) / 2.0 ** rng.randint(0, 60)
    out.append('r %s %d' % (hexf(x), rng.randint(2, 36)))
print('\n'.join(out))
EOF
for s in 1 2 3; do python3 genradix.py $s 25000 > rx.txt; ./cmp.sh rx.txt | tail -1; done

