import json, re
orig = json.load(open('/tmp/unicode_dev/norm17.json'))
def units(cps):
    out = []
    for c in cps:
        if c < 0x10000: out.append(c)
        else:
            d = c - 0x10000; out += [0xD800 + (d >> 10), 0xDC00 + (d & 0x3FF)]
    return out
O = {k: {c: units(m) for c, m in orig[k]} for k in ('nfd', 'nfkd', 'nfc', 'nfkc')}
M = {k: {} for k in O}
for line in open('/tmp/unicode_dev/norm_mine.txt'):
    c, rest = line.split(' ', 1)
    c = int(c)
    parts = re.findall(r'\[[^\]]*\]', rest)
    s = units([c])
    for k, p in zip(('nfd', 'nfkd', 'nfc', 'nfkc'), parts):
        v = json.loads(p)
        if v != s: M[k][c] = v
for k in O:
    bad = [c for c in set(O[k]) | set(M[k]) if O[k].get(c) != M[k].get(c)]
    print(k, "orig", len(O[k]), "mine", len(M[k]), "mismatches", len(bad), [hex(c) for c in sorted(bad)[:10]])
EOF

