// usage: lumen harness.js cases.jsonl  -> one result line per case
const fs = require('fs');
const lines = fs.readFileSync(process.argv[2], 'utf8').split('\n');
const out = [];
for (const line of lines) {
  if (!line.trim()) continue;
  const [p, f, s, li] = JSON.parse(line);
  let r;
  try {
    const re = new RegExp(p, f.includes('d') ? f : f + 'd');
    re.lastIndex = li || 0;
    const m = re.exec(s);
    if (m === null) r = 'N';
    else {
      const idx = '[' + Array.from(m.indices, x => x === undefined ? 'null' : '[' + x[0] + ',' + x[1] + ']').join(',') + ']';
      let g = '-';
      if (m.indices.groups !== undefined) {
        const parts = [];
        for (const k of Object.keys(m.indices.groups)) { const v = m.indices.groups[k]; if (v !== undefined) parts.push(JSON.stringify(k) + ':[' + v[0] + ',' + v[1] + ']'); }
        g = '{' + parts.join(',') + '}';
      }
      r = 'M:' + idx + '|' + g;
    }
  } catch (e) { r = 'E:' + e.message; }
  out.push(r);
}
console.log(out.join('\n'));
