    }
    fn parse(v: &str) -> Option<Self> {
        Some(match v {
            "numeric" => MonthStyle::Numeric,
            "2-digit" => MonthStyle::TwoDigit,
            "narrow" => MonthStyle::Narrow,
            "short" => MonthStyle::Short,
            "long" => MonthStyle::Long,
            _ => return None,
        })
    }
}

impl HourCycle {
    pub fn as_str(self) -> &'static str {
        match self {
            HourCycle::H11 => "h11",
            HourCycle::H12 => "h12",
            HourCycle::H23 => "h23",
            HourCycle::H24 => "h24",
        }
    }
    fn parse(v: &str) -> Option<Self> {
        Some(match v {
            "h11" => HourCycle::H11,
