#[cfg(test)]
mod limit_tests {
    use crate::bigint::*;
    fn b(v: i64) -> BigInt { BigInt::from_i64(v) }
    fn p2(n: i64) -> BigInt { BigInt::one().shl(&b(n)).unwrap() }
    fn ok<T>(r: Result<T, BigIntError>) -> &'static str { if r.is_ok() { "ok" } else { "TooLarge" } }
    #[test]
    fn limits() {
        let r = vec![
            ok(b(1).shl(&b(1073741824))), ok(b(1).shl(&b(1073741825))), ok(b(3).shl(&b(1073741824))),
            ok(b(-1).shl(&b(1073741825))), ok(b(0).shl(&b(10000000000))), ok(b(5).shr(&b(-1073741825))),
            ok(b(-1).as_uint_n(67108864)), ok(b(-1).as_uint_n(67108865)), ok(b(5).as_uint_n(67108865)),
            ok(p2(67108864).as_uint_n(67108865)), ok(p2(67108865).as_uint_n(67108865)),
            ok(p2(67108864).as_int_n(67108866)), ok(p2(67108864).as_int_n(67108865)),
            ok(p2(67108864).neg().as_int_n(67108866)), ok(p2(67108865).neg().as_int_n(67108866)),
            ok(p2(67108865).sub(&b(1)).as_int_n(67108866)), ok(b(-1).as_int_n((1 << 53) - 1)),
            ok(b(-1).as_uint_n((1 << 53) - 1)), ok(b(2).pow(&b(1073741824))), ok(b(2).pow(&b(1073741825))),
        ];
        println!("LIMITS {}", r.join(" "));
        assert_eq!(p2(67108864).as_int_n(67108864).unwrap(), BigInt::zero());
        assert_eq!(p2(67108864).neg().as_int_n(67108864).unwrap(), BigInt::zero());
        assert!(p2(67108863).neg().as_int_n(67108864).unwrap().is_negative());
        assert!(p2(67108863).as_int_n(67108864).unwrap().is_negative());
    }
}
