import ast
prefer = {'Antarctica/DumontDUrville': 'Pacific/Port_Moresby', 'Pacific/Chuuk': 'Pacific/Port_Moresby', 'Pacific/Truk': 'Pacific/Port_Moresby', 'Pacific/Yap': 'Pacific/Port_Moresby',
