cat > orig_at.js <<'EOF'
// input lines: zone \t comma-separated unix seconds ; output: zone \t offsets
const fs = require('fs');
const lines = fs.readFileSync(process.argv[process.argv.length - 1], 'utf8').split('\n').filter(x => x);
const out = [];
for (const l of lines) {
  const [z, ts] = l.split('\t');
  const f = new Intl.DateTimeFormat('en', {timeZone: z, year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric', hourCycle: 'h23'});
  const offs = ts.split(',').map(Number).map(s => {
    const t = s * 1000;
    const p = f.formatToParts(t); const g = {}; for (const x of p) g[x.type] = Number(x.value);
    const local = Date.UTC(g.year, g.month - 1, g.day, g.hour, g.minute, g.second);
    // handle years < 100 via setUTCFullYear
    let lt = local; if (g.year < 100 && g.year >= 0) { const d = new Date(local); d.setUTCFullYear(g.year); lt = d.getTime(); }
    return Math.round((lt - t) / 1000);
  });
  out.push(z + '\t' + offs.join(','));
}
console.log(out.join('\n'));
EOF
