//! Ed25519 (RFC 8032) and X25519 (RFC 7748).

use super::bigint::BigUint;
use super::hash::{HashAlg, Hasher};

const MASK: u64 = (1u64 << 51) - 1;

#[derive(Clone, Copy, Debug)]
struct F([u64; 5]);

fn load8(b: &[u8]) -> u64 {
    let mut w = [0u8; 8];
    w.copy_from_slice(&b[..8]);
    u64::from_le_bytes(w)
}

impl F {
    const ZERO: F = F([0; 5]);
    const ONE: F = F([1, 0, 0, 0, 0]);

    fn from_bytes(b: &[u8; 32]) -> F {
        F([
            load8(&b[0..8]) & MASK,
            (load8(&b[6..14]) >> 3) & MASK,
            (load8(&b[12..20]) >> 6) & MASK,
            (load8(&b[19..27]) >> 1) & MASK,
            (load8(&b[24..32]) >> 12) & MASK,
        ])
    }

    fn carry(mut t: [u64; 5]) -> F {
        let mut c;
        c = t[0] >> 51;
        t[0] &= MASK;
        t[1] += c;
        c = t[1] >> 51;
        t[1] &= MASK;
        t[2] += c;
        c = t[2] >> 51;
        t[2] &= MASK;
        t[3] += c;
        c = t[3] >> 51;
        t[3] &= MASK;
        t[4] += c;
        c = t[4] >> 51;
        t[4] &= MASK;
        t[0] += c * 19;
        c = t[0] >> 51;
        t[0] &= MASK;
        t[1] += c;
        F(t)
    }

    fn to_bytes(&self) -> [u8; 32] {
        let mut t = F::carry(F::carry(self.0).0).0;
        // Now t < 2^255 + small; subtract p if t >= p.
        let mut q = (t[0] + 19) >> 51;
        q = (t[1] + q) >> 51;
        q = (t[2] + q) >> 51;
        q = (t[3] + q) >> 51;
        q = (t[4] + q) >> 51;
        t[0] += 19 * q;
        let mut c = t[0] >> 51;
        t[0] &= MASK;
        t[1] += c;
        c = t[1] >> 51;
        t[1] &= MASK;
        t[2] += c;
        c = t[2] >> 51;
        t[2] &= MASK;
        t[3] += c;
        c = t[3] >> 51;
        t[3] &= MASK;
        t[4] += c;
        t[4] &= MASK;
        let mut out = [0u8; 32];
        let words = [
            t[0] | (t[1] << 51),
            (t[1] >> 13) | (t[2] << 38),
            (t[2] >> 26) | (t[3] << 25),
            (t[3] >> 39) | (t[4] << 12),
        ];
        for (i, w) in words.iter().enumerate() {
            out[i * 8..i * 8 + 8].copy_from_slice(&w.to_le_bytes());
        }
        out
    }

    fn add(&self, o: &F) -> F {
        let a = self.0;
        let b = o.0;
        F::carry([a[0] + b[0], a[1] + b[1], a[2] + b[2], a[3] + b[3], a[4] + b[4]])
    }

    fn sub(&self, o: &F) -> F {
        // a + 4p - b
        let a = self.0;
        let b = o.0;
        F::carry([
            a[0] + 0x1fffffffffffb4 - b[0],
            a[1] + 0x1ffffffffffffc - b[1],
            a[2] + 0x1ffffffffffffc - b[2],
            a[3] + 0x1ffffffffffffc - b[3],
            a[4] + 0x1ffffffffffffc - b[4],
        ])
    }

    fn neg(&self) -> F {
        F::ZERO.sub(self)
    }

    fn mul(&self, o: &F) -> F {
        let a = self.0.map(|x| x as u128);
        let b = o.0.map(|x| x as u128);
        let b1 = b[1] * 19;
        let b2 = b[2] * 19;
        let b3 = b[3] * 19;
        let b4 = b[4] * 19;
        let r0 = a[0] * b[0] + a[1] * b4 + a[2] * b3 + a[3] * b2 + a[4] * b1;
        let r1 = a[0] * b[1] + a[1] * b[0] + a[2] * b4 + a[3] * b3 + a[4] * b2;
        let r2 = a[0] * b[2] + a[1] * b[1] + a[2] * b[0] + a[3] * b4 + a[4] * b3;
        let r3 = a[0] * b[3] + a[1] * b[2] + a[2] * b[1] + a[3] * b[0] + a[4] * b4;
        let r4 = a[0] * b[4] + a[1] * b[3] + a[2] * b[2] + a[3] * b[1] + a[4] * b[0];
        let m = MASK as u128;
        let mut c;
        let mut t = [0u64; 5];
