        c = r1 >> 51;
        t[1] = (r1 & m) as u64;
        let r2 = r2 + c;
        c = r2 >> 51;
        t[2] = (r2 & m) as u64;
        let r3 = r3 + c;
        c = r3 >> 51;
        t[3] = (r3 & m) as u64;
        let r4 = r4 + c;
        c = r4 >> 51;
        t[4] = (r4 & m) as u64;
        let t0 = t[0] as u128 + c * 19;
        t[0] = (t0 & m) as u64;
        t[1] += (t0 >> 51) as u64;
        F(t)
    }

    fn sq(&self) -> F {
        self.mul(self)
    }

    fn mul_small(&self, k: u64) -> F {
        let a = self.0.map(|x| x as u128);
        let k = k as u128;
        let m = MASK as u128;
        let mut t = [0u64; 5];
        let mut c: u128 = 0;
        for i in 0..5 {
            let v = a[i] * k + c;
            t[i] = (v & m) as u64;
            c = v >> 51;
        }
        let t0 = t[0] as u128 + c * 19;
        t[0] = (t0 & m) as u64;
        t[1] += (t0 >> 51) as u64;
        F(t)
    }

    /// `self^e` with `e` given as little-endian bytes.
    fn pow_le(&self, e: &[u8; 32]) -> F {
        let mut r = F::ONE;
        for i in (0..256).rev() {
            r = r.sq();
            if (e[i / 8] >> (i % 8)) & 1 == 1 {
                r = r.mul(self);
            }
        }
        r
    }

    fn invert(&self) -> F {
        // p - 2 = 2^255 - 21
        let mut e = [0xffu8; 32];
        e[0] = 0xeb;
        e[31] = 0x7f;
        self.pow_le(&e)
    }

    fn eq(&self, o: &F) -> bool {
        self.to_bytes() == o.to_bytes()
    }

    fn is_zero(&self) -> bool {
        self.to_bytes() == [0u8; 32]
    }

    fn is_negative(&self) -> bool {
        self.to_bytes()[0] & 1 == 1
    }
}

fn fe_from_hex_le(be_hex: &str) -> F {
    let v = BigUint::from_hex(be_hex).unwrap();
    let mut b = [0u8; 32];
    b.copy_from_slice(&v.to_bytes_le_padded(32));
    F::from_bytes(&b)
}

fn ed_d() -> F {
    fe_from_hex_le("52036cee2b6ffe738cc740797779e89800700a4d4141d8ab75eb4dca135978a3")
}

fn sqrt_m1() -> F {
    fe_from_hex_le("2b8324804fc1df0b2b4d00993dfbd7a72f431806ad2fe478c4ee1b274a0ea0b0")
}

