    let t = Instant::now(); let r = property_ranges("L", None).unwrap(); println!("L {} {:?}", r.len(), t.elapsed());
    let t = Instant::now(); let r = string_property("RGI_Emoji").unwrap(); println!("RGI {} {:?}", r.1.len(), t.elapsed());
    let t = Instant::now(); let mut k = 0u64; for c in 0..0x110000u32 { k += simple_case_fold(c) as u64; } println!("scf scan {} {:?}", k, t.elapsed());
}
