t("keyobject props", ()=>Object.getOwnPropertyNames(c.KeyObject.prototype));
t("keyobject static", ()=>Object.getOwnPropertyNames(c.KeyObject));
t("toCryptoKey", ()=>typeof ec.publicKey.toCryptoKey);
