cd /tmp/date_dev/probes && /tmp/orig -e '
const d = new Date(0);
const out = [];
function p(label, f) { try { out.push(label + " => " + JSON.stringify(f())); } catch (e) { out.push(label + " => THROW " + (e && e.constructor && e.constructor.name) + ": " + e.message); } }
p("[5]", () => d.toLocaleString([5]));
p("[null]", () => d.toLocaleString([null]));
p("null", () => d.toLocaleString(null));
p("arraylike", () => d.toLocaleString({length: 1, 0: "de"}));
p("obj elem", () => d.toLocaleString([{toString() { return "de"; }}]));
p("Intl.Locale", () => typeof Intl.Locale === "function" ? d.toLocaleString([new Intl.Locale("de")]) : "no Intl.Locale");
p("opts 5", () => d.toLocaleString("en", 5));
p("opts true", () => d.toLocaleString("en", true));
p("opts fn", () => d.toLocaleString("en", function() {}));
p("non-date this", () => Date.prototype.toLocaleString.call({}));
p("non-date this2", () => Date.prototype.toLocaleDateString.call(5));
p("DTF call no new", () => Intl.DateTimeFormat("de").format(0));
p("format bound", () => { const f = new Intl.DateTimeFormat("de").format; return f(0); });
p("toLocaleString(undefined, {timeZone: undefined})", () => d.toLocaleString(undefined, {timeZone: undefined}));
p("hour12 undefined w/ hourCycle", () => d.toLocaleString("en", {hour12: undefined, hourCycle: "h23"}));
console.log(out.join("\n"));
'

