const c = require('crypto'); const fs = require('fs');
const out = [];
const q = JSON.stringify;
const pem = fs.readFileSync('/tmp/cp/rsa1024.pem', 'utf8');
const priv = c.createPrivateKey(pem); const pub = c.createPublicKey(pem);
out.push('pub const RSA_PKCS8_PEM: &str = ' + q(pem) + ';');
out.push('pub const RSA_PKCS1_DER: &str = ' + q(priv.export({type:'pkcs1', format:'der'}).toString('hex')) + ';');
out.push('pub const RSA_SPKI_DER: &str = ' + q(pub.export({type:'spki', format:'der'}).toString('hex')) + ';');
out.push('pub const RSA_PUB_PKCS1_DER: &str = ' + q(pub.export({type:'pkcs1', format:'der'}).toString('hex')) + ';');
out.push('pub const RSA_JWK: &[(&str, &str)] = &[' + Object.entries(priv.export({format:'jwk'})).map(([k,v]) => `(${q(k)}, ${q(v)})`).join(', ') + '];');
const msg = Buffer.from('hello world');
out.push('pub const RSA_SIGS: &[(&str, &str)] = &[' + ['md5','sha1','sha256','sha384','sha512'].map(a => `(${q(a)}, ${q(c.sign(a, msg, priv).toString('hex'))})`).join(', ') + '];');
out.push('pub const RSA_PSS0_SIGS: &[(&str, &str)] = &[' + ['sha1','sha256','sha512','md5'].map(a => `(${q(a)}, ${q(c.sign(a, msg, {key: priv, padding: 6, saltLength: 0}).toString('hex'))})`).join(', ') + '];');
out.push('pub const RSA_PSS_RANDOM: &[(&str, i32, &str)] = &[' + [['sha256', 32], ['sha256', 94], ['sha1', 20], ['sha512', 10]].map(([a, s]) => `(${q(a)}, ${s}, ${q(c.sign(a, msg, {key: priv, padding: 6, saltLength: s}).toString('hex'))})`).join(', ') + '];');
out.push('pub const RSA_OAEP_CTS: &[(&str, &str, &str)] = &[' + [['sha1', ''], ['sha256', ''], ['sha256', 'lbl'], ['sha512', 'x']].map(([a, l]) => `(${q(a)}, ${q(l)}, ${q(c.publicEncrypt({key: pub, oaepHash: a, oaepLabel: Buffer.from(l)}, msg).toString('hex'))})`).join(', ') + '];');
out.push('pub const RSA_PKCS1_CT: &str = ' + q(c.publicEncrypt({key: pub, padding: 1}, msg).toString('hex')) + ';');
out.push('pub const RSA_PRIV_ENC: &str = ' + q(c.privateEncrypt(priv, msg).toString('hex')) + ';');
// EC / Ed25519 / X25519 fixed keys (JWK from earlier probes)
const ecPriv = c.createPrivateKey({key: {kty:"EC",crv:"P-256",x:"ERemROMgg4ENVdfWgETXRUlHcdWroE-5gIvIGSRtoC8",y:"L_gHoJ1x1ezotLPjjlalWI2NEIORN1wug_UEG1TzlKg",d:"weTIJvmDKUCYvLuW5JA8x8exKJ0PqkW4L2qbBxcyDC8"}, format:'jwk'});
out.push('pub const EC_PKCS8_DER: &str = ' + q(ecPriv.export({type:'pkcs8', format:'der'}).toString('hex')) + ';');
out.push('pub const EC_SEC1_DER: &str = ' + q(ecPriv.export({type:'sec1', format:'der'}).toString('hex')) + ';');
out.push('pub const EC_SPKI_DER: &str = ' + q(c.createPublicKey(ecPriv).export({type:'spki', format:'der'}).toString('hex')) + ';');
out.push('pub const EC_SIG_DER: &str = ' + q(c.sign('sha256', msg, ecPriv).toString('hex')) + ';');
out.push('pub const EC_SIG_P1363: &str = ' + q(c.sign('sha256', msg, {key: ecPriv, dsaEncoding: 'ieee-p1363'}).toString('hex')) + ';');
const edPriv = c.createPrivateKey({key: {kty:"OKP",crv:"Ed25519",x:"P9CtSwbhh57CdbDRk-2pEuKtpZEo9k7NyJD-f0tvM_4",d:"NF8xANRqJAOHLeZKt6WHRMUr-sBEvWbwMpG50y-9QlI"}, format:'jwk'});
out.push('pub const ED_PKCS8_DER: &str = ' + q(edPriv.export({type:'pkcs8', format:'der'}).toString('hex')) + ';');
out.push('pub const ED_SPKI_DER: &str = ' + q(c.createPublicKey(edPriv).export({type:'spki', format:'der'}).toString('hex')) + ';');
const xPriv = c.createPrivateKey({key: {kty:"OKP",crv:"X25519",x:"wQ2HUYNRI4TIpQ3qxnUZyqPRl8WWEbCL7ZXxgoeW4SQ",d:"sGe2Kn_2E6fj0Xedua4aEqCV4WMcjdFCUMuZ54JwXrY"}, format:'jwk'});
out.push('pub const X_PKCS8_DER: &str = ' + q(xPriv.export({type:'pkcs8', format:'der'}).toString('hex')) + ';');
out.push('pub const X_SPKI_DER: &str = ' + q(c.createPublicKey(xPriv).export({type:'spki', format:'der'}).toString('hex')) + ';');
for (const f of ['rsa_cert', 'leaf_cert', 'ec_cert', 'attr_cert', 'rsa_md5', 'ec_sha384']) out.push(`pub const CERT_${f.toUpperCase()}: &str = ${q(fs.readFileSync('/tmp/cp/certs/' + f + '.pem', 'utf8'))};`);
console.log('// Generated by /tmp/gen/gen_asym.js (node; deterministic outputs equal the original).\n' + out.join('\n'));
EOF
