        assert_eq!(to_locale_date_string(t, &loc("de-DE"), &full).unwrap(), "Saturday, März 7, 2020");
        let mut h = DateTimeFormatOptions::new();
        h.set_hour12(false);
        assert_eq!(to_locale_time_string(t, &loc("en-US"), &h).unwrap(), "15:04:05");
