        let l = opts(&[("timeZone", "Europe/London"), ("timeZoneName", "long")]);
        assert_eq!(DateTimeFormat::new(&loc("en"), &l).unwrap().format(t).unwrap(), "7/15/2020 Europe/Guernsey");
