        let z = TimeZone::from_name("America/New_York").unwrap();
        assert_eq!(z.offset_ms(2_162_376_000_000.0), -18_000_000.0); // 2038-07-10
        assert_eq!(z.offset_ms(2_131_012_800_000.0), -14_400_000.0); // 2037-07-12
    }
