2	//! arena AST. Error messages replicate the original runtime's SyntaxError texts.
3	
4	use super::charset::{self, CharSet, ClassSet, MAX_CP};
5	
6	pub(crate) type NodeId = u32;
7	
8	#[derive(Clone, Debug)]
9	pub(crate) enum Node {
10	    Empty,
11	    /// A single literal character (case-sensitive).
12	    Char(u32),
13	    /// A set of characters (classes, escapes, case-insensitive chars, dot).
14	    Set(u32),
15	    /// v-mode class containing strings: alternatives (strings longest first, then the
16	    /// single-character set). Index into `Ast::string_classes`.
17	    StringClass(u32),
