616	/// Matches the captured text input[s..e] at `pos` (forward) or ending at `pos` (backward).
617	fn backref_match<const U: bool>(input: &[u16], s: usize, e: usize, pos: usize, icase: bool, back: bool) -> Option<usize> {
618	    let n = e - s;
619	    let (from, to) = if back {
620	        if n > pos {
621	            return None;
622	        }
623	        (pos - n, pos)
624	    } else {
625	        if pos + n > input.len() {
626	            return None;
627	        }
628	        (pos, pos + n)
629	    };
630	    if U {
631	        // must not split surrogate pairs at the boundaries
632	        if back && from > 0 && n > 0 && (input[from] & 0xFC00) == 0xDC00 && (input[from - 1] & 0xFC00) == 0xD800 {
633	            return None;
634	        }
635	        if !back && to < input.len() && n > 0 && (input[to - 1] & 0xFC00) == 0xD800 && (input[to] & 0xFC00) == 0xDC00 {
636	            return None;
637	        }
638	    }
639	    if !icase {
640	        if input[s..e] == input[from..to] {
641	            return Some(if back { from } else { to });
642	        }
643	        return None;
644	    }
645	    if U {
646	        let mut i = s;
647	        let mut j = from;
648	        while i < e {
649	            let (a, ni) = fwd::<true>(&input[..e], i)?;
650	            let (b, nj) = fwd::<true>(&input[..to], j)?;
651	            if a != b && scf(a) != scf(b) {
652	                return None;
653	            }
654	            i = ni;
655	            j = nj;
656	        }
657	        if j != to {
658	            return None;
659	        }
660	    } else {
661	        for k in 0..n {
662	            let a = input[s + k] as u32;
663	            let b = input[from + k] as u32;
664	            if a != b && legacy_canon(a) != legacy_canon(b) {
665	                return None;
666	            }
667	        }
668	    }
669	    Some(if back { from } else { to })
670	}
