337	    /// RegExpBuiltinExec core: finds a match starting the search at `last_index`
338	    /// (sticky: only at `last_index`). Returns code-unit spans for groups
339	    /// 0..=capture_count.
340	    pub fn exec(&self, input: &[u16], last_index: usize) -> Option<Vec<Option<(usize, usize)>>> {
341	        let inner = &*self.inner;
342	        if input.len() >= u32::MAX as usize {
343	            // positions are stored as u32 internally
344	            return None;
345	        }
346	        let mut guard = inner.vm.try_borrow_mut().ok();
347	        let mut local;
348	        let vm: &mut vm::Vm = match guard.as_mut() {
349	            Some(g) => g.get_or_insert_with(vm::Vm::new),
350	            None => {
351	                local = vm::Vm::new();
352	                &mut local
353	            }
354	        };
355	        if !search(&inner.prog, inner.flags.sticky, vm, input, last_index) {
356	            return None;
357	        }
358	        let n = inner.prog.ncap + 1;
359	        let mut out = Vec::with_capacity(n);
360	        for g in 0..n {
361	            let (s, e) = (vm.caps[2 * g], vm.caps[2 * g + 1]);
362	            if s == u32::MAX || e == u32::MAX {
363	                out.push(None);
364	            } else {
365	                out.push(Some((s as usize, e as usize)));
366	            }
367	        }
368	        Some(out)
369	    }
370	}
