372	/// The search loop over start positions. On success the VM's capture slots hold the
373	/// match.
374	fn search(prog: &compiler::Program, sticky: bool, vm: &mut vm::Vm, input: &[u16], last_index: usize) -> bool {
375	    let len = input.len();
376	    if last_index > len {
377	        return false;
378	    }
379	    let mut start = last_index;
380	    let unicode = prog.unicode;
381	    if unicode && start > 0 && start < len && is_low(input[start]) && is_high(input[start - 1]) {
382	        // inside a surrogate pair: the match attempt starts at the pair
383	        start -= 1;
384	    }
385	    // every match contains a member of `required` at or after its start: `req_next` is
386	    // the first such position >= the current candidate (found lazily, scanning forward)
387	    let find_req = |from: usize| -> Option<usize> {
388	        match &prog.required {
389	            None => Some(from),
390	            Some(req) => input[from..].iter().position(|&u| req.contains(u as u32)).map(|p| from + p),
391	        }
392	    };
393	    let mut req_next = match find_req(start) {
394	        None => return false,
395	        Some(p) => p,
396	    };
397	    if sticky {
398	        return vm.run(prog, input, start);
399	    }
400	    if prog.anchored {
401	        return start == 0 && vm.run(prog, input, 0);
402	    }
403	    let is_lt = |u: u16| u == 0x0A || u == 0x0D || u == 0x2028 || u == 0x2029;
404	    let mut s = start;
405	    loop {
406	        if s > req_next {
407	            match find_req(s) {
408	                None => return false,
409	                Some(p) => req_next = p,
410	            }
411	        }
412	        // candidate filters
413	        if !prog.prefix.is_empty() {
414	            let pre = &prog.prefix[..];
415	            let first = pre[0];
416	            let mut i = s;
417	            loop {
418	                if i + pre.len() > len {
419	                    return false;
420	                }
421	                if input[i] == first && input[i..i + pre.len()] == *pre {
422	                    break;
423	                }
424	                i += 1;
425	            }
426	            s = i;
427	        } else if let Some(first) = &prog.first {
428	            while s < len && !first.contains(input[s] as u32) {
429	                s += 1;
430	            }
431	            if s >= len {
432	                return false;
433	            }
434	        } else if prog.line_anchored {
435	            while s > 0 && s < len && !is_lt(input[s - 1]) {
436	                s += 1;
437	            }
438	            if s > 0 && !is_lt(input[s - 1]) {
439	                return false;
440	            }
441	        }
442	        if s > req_next {
443	            match find_req(s) {
444	                None => return false,
445	                Some(p) => req_next = p,
446	            }
447	        }
448	        if unicode && s > start && s < len && is_low(input[s]) && is_high(input[s - 1]) {
449	            // not a code point boundary
450	            s += 1;
451	            continue;
452	        }
453	        if vm.run(prog, input, s) {
454	            return true;
455	        }
456	        if let Some((m, _min)) = prog.lead_repeat {
457	            // the attempt at s failed: every start inside the run of `m` fails too
458	            let mut q = s;
459	            loop {
460	                let (c, nq) = if unicode && q + 1 < len && is_high(input[q]) && is_low(input[q + 1]) {
461	                    (0x10000 + (((input[q] as u32) - 0xD800) << 10) + ((input[q + 1] as u32) - 0xDC00), q + 2)
462	                } else if q < len {
463	                    (input[q] as u32, q + 1)
464	                } else {
465	                    break;
466	                };
467	                let ok = match m {
468	                    compiler::CharMatcher::Char(x) => c == x,
469	                    compiler::CharMatcher::Set(k) => prog.sets[k as usize].contains(c),
470	                };
471	                if !ok {
472	                    break;
473	                }
474	                q = nq;
475	            }
476	            if q > s {
477	                s = q;
478	            }
479	        }
480	        if s >= len {
481	            return false;
482	        }
483	        s += if unicode && s + 1 < len && is_high(input[s]) && is_low(input[s + 1]) { 2 } else { 1 };
484	    }
485	}
