487	/// RegExp.prototype.source rendering of a pattern (EscapeRegExpPattern).
488	pub fn escape_source(pattern: &[u16]) -> Vec<u16> {
489	    if pattern.is_empty() {
490	        return "(?:)".encode_utf16().collect();
491	    }
492	    let mut out = Vec::with_capacity(pattern.len() + 4);
493	    let mut in_class = false;
494	    let mut i = 0;
495	    while i < pattern.len() {
496	        let c = pattern[i];
497	        match c {
498	            0x5C => {
499	                // backslash: copy the escape verbatim (unless followed by a line terminator)
500	                out.push(c);
501	                if i + 1 < pattern.len() {
502	                    let d = pattern[i + 1];
503	                    match d {
504	                        0x0A => out.extend("n".encode_utf16()),
505	                        0x0D => out.extend("r".encode_utf16()),
506	                        0x2028 => out.extend("u2028".encode_utf16()),
507	                        0x2029 => out.extend("u2029".encode_utf16()),
508	                        _ => out.push(d),
509	                    }
510	                    i += 2;
511	                    continue;
512	                }
513	            }
514	            0x2F => {
515	                if in_class {
516	                    out.push(c);
517	                } else {
518	                    out.extend("\\/".encode_utf16());
519	                }
520	            }
521	            0x5B => {
522	                in_class = true;
523	                out.push(c);
524	            }
525	            0x5D => {
526	                in_class = false;
527	                out.push(c);
528	            }
529	            0x0A => out.extend("\\n".encode_utf16()),
530	            0x0D => out.extend("\\r".encode_utf16()),
531	            0x2028 => out.extend("\\u2028".encode_utf16()),
532	            0x2029 => out.extend("\\u2029".encode_utf16()),
533	            _ => out.push(c),
534	        }
535	        i += 1;
536	    }
537	    out
538	}
