    "#",
];

pub struct Lexer {
    pub src: Vec<char>,
    pub pos: usize,
    pub line: u32,
    pub is_module: bool,
}

fn is_line_term(c: char) -> bool {
    matches!(c, '\n' | '\r' | '\u{2028}' | '\u{2029}')
}

fn is_ws(c: char) -> bool {
    match c {
        '\t' | '\u{b}' | '\u{c}' | ' ' | '\u{a0}' | '\u{feff}' => true,
        _ if (c as u32) < 128 => false,
        _ => unicode::is_js_whitespace(c as u32),
