impl Lexer {
    pub fn new(src: &str, is_module: bool) -> Lexer {
        Lexer { src: src.chars().collect(), pos: 0, line: 1, is_module }
    }

    fn peek(&self) -> Option<char> {
        self.src.get(self.pos).copied()
    }
    fn peek_at(&self, n: usize) -> Option<char> {
