            let mut v = 0u32;
            for _ in 0..4 {
                let d = self.peek()?.to_digit(16)?;
                v = v * 16 + d;
                self.pos += 1;
            }
            Some(v)
        }
    }

    fn read_number(&mut self, start: usize, line: u32, nl: bool) -> Result<Token, LexError> {
