            _ => false,
        }
    }
}

impl From<f64> for Value {
    fn from(n: f64) -> Value {
        Value::Num(n)
    }
}
impl From<bool> for Value {
    fn from(b: bool) -> Value {
        Value::Bool(b)
    }
}
impl From<JsStr> for Value {
    fn from(s: JsStr) -> Value {
        Value::Str(s)
    }
}
impl From<Obj> for Value {
    fn from(o: Obj) -> Value {
        Value::Obj(o)
    }
}
impl From<&str> for Value {
    fn from(s: &str) -> Value {
        Value::str(s)
    }
}
impl From<i32> for Value {
    fn from(n: i32) -> Value {
        Value::Num(n as f64)
    }
}
impl From<u32> for Value {
    fn from(n: u32) -> Value {
        Value::Num(n as f64)
    }
}
impl From<usize> for Value {
    fn from(n: usize) -> Value {
        Value::Num(n as f64)
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::Undefined => write!(f, "undefined"),
            Value::Null => write!(f, "null"),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Num(n) => write!(f, "{}", n),
            Value::Str(s) => write!(f, "{:?}", s),
            Value::Sym(s) => write!(f, "{}", s.descriptive_string()),
            Value::BigInt(b) => write!(f, "{}n", b.to_string_radix(10)),
            Value::Obj(_) => write!(f, "[object]"),
            Value::Empty => write!(f, "<empty>"),
        }
    }
}

/// Key wrapper implementing SameValueZero hashing for Map/Set.
#[derive(Clone)]
pub struct MapKey(pub Value);

impl PartialEq for MapKey {
    fn eq(&self, o: &MapKey) -> bool {
        Value::same_value_zero(&self.0, &o.0)
    }
}
impl Eq for MapKey {}
impl Hash for MapKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match &self.0 {
            Value::Undefined => 0u8.hash(state),
            Value::Null => 1u8.hash(state),
            Value::Bool(b) => {
                2u8.hash(state);
                b.hash(state)
            }
            Value::Num(n) => {
                3u8.hash(state);
                let n = if *n == 0.0 { 0.0 } else { *n };
                if n.is_nan() {
                    u64::MAX.hash(state)
                } else {
                    n.to_bits().hash(state)
                }
            }
            Value::Str(s) => {
                4u8.hash(state);
                s.hash(state)
            }
            Value::Sym(s) => {
                5u8.hash(state);
                s.hash(state)
            }
            Value::BigInt(b) => {
                6u8.hash(state);
                b.hash(state)
            }
            Value::Obj(o) => {
                7u8.hash(state);
                o.addr().hash(state)
            }
            Value::Empty => 8u8.hash(state),
        }
    }
}

/// Simple fast hasher (FxHash-like) for internal maps.
#[derive(Default, Clone, Copy)]
pub struct FxHasher {
    hash: u64,
}
impl Hasher for FxHasher {
    fn finish(&self) -> u64 {
        self.hash
    }
    fn write(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.hash = (self.hash.rotate_left(5) ^ b as u64).wrapping_mul(0x517cc1b727220a95);
        }
    }
    fn write_u8(&mut self, i: u8) {
        self.hash = (self.hash.rotate_left(5) ^ i as u64).wrapping_mul(0x517cc1b727220a95);
    }
    fn write_u64(&mut self, i: u64) {
        self.hash = (self.hash.rotate_left(5) ^ i).wrapping_mul(0x517cc1b727220a95);
    }
    fn write_usize(&mut self, i: usize) {
        self.write_u64(i as u64)
    }
}
#[derive(Default, Clone, Copy)]
pub struct FxBuild;
