    // a function declaration as the body of if/label in sloppy mode gets its own scope
    if let Stmt::Function(f) = s {
        let id = self.push_scope(ScopeKind::Block, self.strict());
        let _ = id;
        if let Some(n) = &f.name {
            self.declare(id, &n.name, BindKind::Function, n.line)?;
        }
        let r = self.walk_stmt(s);
        self.pop_scope();
        return r;
    }
    self.walk_stmt(s)
}

