        ObjKind::Iterator(s) => match &**s {
            IterState::Zip(z) => (z.iters.clone(), z.mode, z.padding.clone(), z.done, z.keys.clone()),
            _ => return Err(vm.make_error("TypeError", "incompatible receiver")),
        },
        _ => return Err(vm.make_error("TypeError", "incompatible receiver")),
    };
