        return Ok(vm.iter_result(Value::Undefined, true));
    }
    let mut results = Vec::new();
    let mut new_iters = iters.clone();
    let mut any_done = false;
    let mut all_done = true;
    for (i, it) in iters.iter().enumerate() {
