        return vm.throw_type("iterators have different lengths");
    }
    if (mode == 1 || mode == 2) && new_iters.iter().all(|x| x.is_none()) {
        set_zip_done(&o);
        return Ok(vm.iter_result(Value::Undefined, true));
    }
