fn iter_to_array(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (it, next, _) = eager_prelude(vm, a, "toArray", false)?;
    let mut out = Vec::new();
    while let Some(v) = vm.iter_step(&it, &next)? {
