fn iter_for_each(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (it, next, f) = eager_prelude(vm, a, "forEach", true)?;
    let mut c = 0.0;
    while let Some(v) = vm.iter_step(&it, &next)? {
        if let Err(e) = vm.call(&f, Value::Undefined, &[v, Value::Num(c)]) {
