    let ov = Value::Obj(o.clone());
    let mut n = 0u64;
    for k in 0..len {
        if has_idx(vm, &o, k)? {
            let v = get_idx(vm, &o, k)?;
            let r = vm.call(&f, t.clone(), &[v.clone(), Value::Num(k as f64), ov.clone()])?;
            if r.truthy() {
                vm.create_data_property_or_throw(&arr, idx_key(n), v)?;
                n += 1;
            }
        }
    }
