fn is_well_formed(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = this_str(vm, a)?;
    let u = s.units();
    let mut i = 0;
    while i < u.len() {
        let c = u[i];
        if (0xD800..0xDC00).contains(&c) {
            if i + 1 < u.len() && (0xDC00..0xE000).contains(&u[i + 1]) {
                i += 2;
                continue;
            }
            return Ok(Value::Bool(false));
        }
        if (0xDC00..0xE000).contains(&c) {
            return Ok(Value::Bool(false));
        }
        i += 1;
    }
    Ok(Value::Bool(true))
