fn trim_impl(s: &JsStr, start: bool, end: bool) -> JsStr {
    let u = s.units();
    let mut a = 0;
    let mut b = u.len();
    if start {
        while a < b && is_ws(u[a]) {
            a += 1;
        }
    }
    if end {
        while b > a && is_ws(u[b - 1]) {
            b -= 1;
        }
    }
    s.substring(a, b)
}

