            let called = Value::Obj(Obj::new(None, ObjKind::Host(Box::new(Cell::new(false)))));
            let (onf, onr) = match kind {
                0 => {
                    let f = vm.native_closure("", 1, all_resolve_element, vec![state.clone(), idx, cap.resolve.clone(), called]);
