                _ => (cap.resolve.clone(), cap.reject.clone()),
            };
            let then = match vm.get_prop_of(&next_p, &vm.intr.key_then.clone()) {
                Ok(t) => t,
                Err(e) => {
                    let _ = vm.iterator_close(&itv);
                    return Err(e);
                }
            };
            if let Err(e) = vm.call(&then, next_p, &[onf, onr]) {
