        let done = vm.get(&ro, &vm.intr.key_done.clone(), &v)?.truthy();
        if done {
            let _ = crate::builtins::array::set_length(vm, &arr, idx);
            vm.call(&cap.resolve, Value::Undefined, &[Value::Obj(arr)])?;
            return Ok(Value::Undefined);
        }
