        fa_fail(vm, st, e, true);
        return Ok(Value::Undefined);
    }
    fa_advance(vm, st);
    Ok(Value::Undefined)
}

fn fa_advance(vm: &mut Vm, st: &Value) {
    {
        let b = fa_state(st);
        if let ObjKind::Host(h) = &b.kind {
            let s = h.downcast_ref::<FromAsync>().unwrap();
            s.index.set(s.index.get() + 1);
        }
    }
    fa_step(vm, st);
}

