    let g = g.as_obj().unwrap().clone();
    if let ObjKind::AsyncGenerator(ag) = &mut g.borrow_mut().kind {
        ag.awaiting_return = false;
        ag.state = GenState::Completed;
    }
    complete_step(vm, &g, Ok(v), true);
    drain(vm, &g);
    Ok(Value::Undefined)
