                default.clone()
            } else {
                sp
            }
        } else {
            return vm.throw_type("constructor is not an object");
        }
    };
    let splitter = vm.construct(&c, &[Value::Obj(rx.clone()), Value::str(&new_flags)], None)?;
    let sp = splitter.as_obj().unwrap().clone();
