    let tv = vm.to_primitive(&ov, crate::ops::Hint::Number)?;
    if let Value::Num(n) = tv {
        if !n.is_finite() {
            return Ok(Value::Null);
        }
    }
    let f = vm.get_str(&o, "toISOString")?;
    if !f.is_callable() {
