        let m = a / 2f64.powi(-24);
        let r = round_half_even(m) as u16;
        return sign | r;
    }
    let mant = a / 2f64.powi(e) - 1.0; // [0,1)
    let mut m = round_half_even(mant * 1024.0) as u32;
    let mut e = e;
    if m == 1024 {
        m = 0;
        e += 1;
    }
    if e > 15 {
        return sign | 0x7c00;
    }
    sign | (((e + 15) as u16) << 10) | m as u16
}

fn round_half_even(x: f64) -> f64 {
    let f = x.floor();
    let d = x - f;
    if d > 0.5 {
        f + 1.0
    } else if d < 0.5 {
        f
    } else if f % 2.0 == 0.0 {
