fn reflect_own_keys(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = target_obj(vm, &a.arg(0), "ownKeys")?;
    let keys = vm.own_property_keys(&o)?;
    let v: Vec<Value> = keys.iter().map(key_val).collect();
