            ("year", -1) => Some("last year"),
            ("year", 0) => Some("this year"),
            ("year", 1) => Some("next year"),
            ("month", -1) => Some("last month"),
            ("month", 0) => Some("this month"),
            ("month", 1) => Some("next month"),
            ("week", -1) => Some("last week"),
            ("week", 0) => Some("this week"),
            ("week", 1) => Some("next week"),
