    let rest = match &b.kind {
        ObjKind::Host(h) => {
            let s = h.downcast_ref::<SdState>().unwrap();
            let mut p = s.pending.borrow_mut();
            let r = if p.is_empty() { JsStr::empty() } else { decode_bytes(&p, s.encoding) };
            p.clear();
            r
        }
        _ => JsStr::empty(),
    };
