import re,glob
for p in glob.glob('src/builtins/*.rs'):
    s=open(p).read()
    # pattern: if let Some(X) = OBJ.borrow_mut().props.remove(&KEY) {\n  OBJ.borrow_mut().props.insert(KEY, X);\n }
    pat = re.compile(r"if let Some\((\w+)\) = (\w+)\.borrow_mut\(\)\.props\.remove\(&(vm\.intr\.\w+)\.clone\(\)\) \{\n(\s*)(\w+)\.borrow_mut\(\)\.props\.insert\(([^;]*)\);\n(\s*)\}")
    def rep(m):
        var, obj, key, ind, obj2, args, ind2 = m.groups()
        return f"move_to_end(&{obj}, &{key}.clone());"
    s2 = pat.sub(rep, s)
    # error.rs special: if let Some(c) = ...remove { let _ = c; }
    s2 = s2.replace("""    if let Some(c) = ep.borrow_mut().props.remove(&vm.intr.key_constructor.clone()) {
        let _ = c;
    }""", """    let removed = ep.borrow_mut().props.remove(&vm.intr.key_constructor.clone());
    drop(removed);""")
    if s2 != s:
        if 'use crate::object::move_to_end' not in s2 and 'move_to_end' in s2:
            s2 = s2.replace("use crate::object::*;", "use crate::object::*;", 1)
        open(p,'w').write(s2)
        print("fixed", p)
