const fs = require('fs');
const fsp = require('fs/promises');
const P = '/tmp/fsagent/out/fh.txt';
fs.writeFileSync(P, 'hello world');
const show = (x) => JSON.stringify(x, (k, v) => (v && v.type === 'Buffer' && Array.isArray(v.data)) ? 'Buffer(' + Buffer.from(v.data).toString() + ')' : v);
(async () => {
  const fh = await fsp.open(P, 'r+');
  console.log('fh', fh.constructor.name, Object.keys(fh).join(), typeof fh.fd, fh instanceof fsp.FileHandle);
  const b = Buffer.alloc(5);
  let r = await fh.read(b, 0, 5, 0);
  console.log('read', show(r), Object.keys(r).join(), r.buffer === b);
  r = await fh.read({ buffer: Buffer.alloc(3), position: 6 });
  console.log('read obj', show(r));
  r = await fh.read();
  console.log('read noarg', r.bytesRead, r.buffer.length);
  try { r = await fh.read(Buffer.alloc(2)); console.log('read buf only', show(r)); } catch (e) { console.log('read buf only err', e.message); }
  const w = await fh.write('XY', 0);
  console.log('write', show(w), Object.keys(w).join());
  const w2 = await fh.write(Buffer.from('ZZ'), 0, 2, 3);
  console.log('write buf', show(w2));
  console.log('readFile', show(await fh.readFile('utf8')));
  console.log('readFile buf', show(await fh.readFile()));
  console.log('stat', (await fh.stat()).size, (await fh.stat()).constructor.name);
  await fh.truncate(4);
  console.log('after truncate', fs.readFileSync(P, 'utf8'));
  await fh.writeFile('NEW');
  console.log('after writeFile', fs.readFileSync(P, 'utf8'));
  await fh.appendFile('+A');
  console.log('after appendFile', fs.readFileSync(P, 'utf8'));
  console.log('sync', await fh.sync(), await fh.datasync());
  console.log('chmod', await fh.chmod(0o600), (fs.statSync(P).mode & 0o777).toString(8));
  console.log('utimes', await fh.utimes(1000, 2000), fs.statSync(P).mtimeMs);
  const rv = await fh.readv([Buffer.alloc(2), Buffer.alloc(2)], 0);
  console.log('readv', show(rv), Object.keys(rv).join());
  const wv = await fh.writev([Buffer.from('ab'), Buffer.from('cd')], 0);
  console.log('writev', show(wv), Object.keys(wv).join());
  console.log('close', await fh.close(), fh.fd);
  console.log('close again', await fh.close());
  try { await fh.read(Buffer.alloc(1)); } catch (e) { console.log('read after close', e.constructor.name, e.message); }
  try { await fh.stat(); } catch (e) { console.log('stat after close', e.constructor.name, e.message); }
  // promises.readFile with FileHandle
  const fh2 = await fsp.open(P);
  console.log('p.readFile(fh)', await fsp.readFile(fh2, 'utf8'));
  await fsp.writeFile(fh2, 'zz').then(() => console.log('p.writeFile(fh) ok'), e => console.log('p.writeFile(fh) err', e.message));
  await fh2.close();
  const fh3 = await fsp.open(P, 'w');
  await fsp.writeFile(fh3, 'via fh');
  await fsp.appendFile(fh3, '+more');
  await fh3.close();
  console.log('content', fs.readFileSync(P, 'utf8'));
  try { await fsp.open('/nonexistent/x'); } catch (e) { console.log('open err', e.message); }
  const fh4 = await fsp.open(P);
  console.log(typeof fh4[Symbol.asyncDispose], Object.getOwnPropertyNames(Object.getPrototypeOf(fh4)).join());
  const fd4 = fh4.fd;
  await fh4[Symbol.asyncDispose]();
  console.log('disposed', fh4.fd);
  // fsp functions
  console.log(await fsp.readdir('/tmp/fsagent/out/../out').then(x => Array.isArray(x)));
  console.log(await fsp.access(P), await fsp.stat(P).then(s => s.size));
  await fsp.mkdir('/tmp/fsagent/out/pd/a', { recursive: true }).then(r => console.log('mkdir rec', r));
  await fsp.rm('/tmp/fsagent/out/pd', { recursive: true }).then(r => console.log('rm', r));
  await fsp.access('/nonexistent').catch(e => console.log('access err', e.message, e.code));
  const it = fsp.glob('*.txt', { cwd: '/tmp/fsagent/out' });
  console.log('glob', typeof it.next, typeof it[Symbol.asyncIterator]);
  const d = await fsp.opendir('/tmp/fsagent');
  console.log('opendir', d.constructor.name, typeof (await d.read()));
  for await (const e of d) { }
  console.log('dir iter done');
  const fh5 = await fsp.open(P);
  const rs = fh5.createReadStream();
  rs.on('data', c => console.log('fh rs data', c.toString()));
  rs.on('end', () => console.log('fh rs end'));
  rs.on('close', async () => { console.log('fh rs close', fh5.fd); await fh5.close(); });
})();

