const fs = require('fs');
const P = '/tmp/fsagent/out/ws1.txt';
const log = (...a) => console.log(a.map(x => typeof x === 'object' && x !== null ? (Buffer.isBuffer(x) ? 'Buffer(' + x.toString() + ')' : JSON.stringify(x)) : String(x)).join(' '));
const ws = fs.createWriteStream(P);
log('created', ws.fd, ws.path, ws.flags, ws.bytesWritten, ws.pos, ws.writable, ws._encoding);
log('keys', Object.keys(ws).join(','));
log('wstate', JSON.stringify(Object.keys(ws._writableState)));
for (const ev of ['open', 'ready', 'finish', 'close', 'error', 'drain', 'pipe', 'unpipe']) {
  ws.on(ev, (...args) => log('ws event', ev, ...args));
}
log('write1', ws.write('hello '));
log('write2', ws.write(Buffer.from('world'), () => log('write2 cb')));
log('end', ws.end('!\n', () => log('end cb')) === ws);
process.nextTick(() => log('tick'));
Promise.resolve().then(() => log('micro'));
setImmediate(() => log('immediate'));
setTimeout(() => { log('timeout', ws.bytesWritten, ws.fd, JSON.stringify(fs.readFileSync(P, 'utf8')), ws._writableState.finished); }, 20);

