const { Writable, Readable } = require('stream');
const log = (...a) => console.log(a.map(x => typeof x === 'object' && x !== null ? (Buffer.isBuffer(x) ? 'Buffer(' + x.toString() + ')' : JSON.stringify(x)) : String(x)).join(' '));
(async () => {
  {
    log('=== drain');
    const w = new Writable({ highWaterMark: 4, write(c, e, cb) { log('  _write', c.length); cb(); } });
    log('  hwm', w.writableHighWaterMark, w.writableLength);
    w.on('drain', () => log('  drain', w.writableLength));
