                    let i = i as usize;
                    if i < a.dense.len() {
                        a.dense[i] = value;
                        return;
                    }
                    if i == a.dense.len() {
                        a.dense.push(value);
                        if a.len < (i + 1) as u32 {
                            a.len = (i + 1) as u32;
                        }
                        return;
                    }
                }
            }
        }
        o.props.insert(key, Prop::Data { value, flags });
