fn mkdtemp_sync(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let prefix = to_path(vm, &a.arg(0))?;
    let dir = mkdtemp_impl(vm, &prefix)?;
    let enc = enc_of(vm, &a.arg(1))?;
