fn ftruncate_impl(vm: &mut Vm, fdv: &Value, len: &Value) -> JsResult<Value> {
    let n = num_or_zero(vm, len)?;
    let len = if n.is_nan() || n <= 0.0 { 0 } else { n as u64 };
    fd_op(vm, fdv, "ftruncate", |f| f.set_len(len))
}

