fn truncate_sync(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let p = a.arg(0);
    if let Value::Num(_) = p {
        return ftruncate_impl(vm, &p, &a.arg(1));
    }
    let fd = open_impl(vm, &p, &Value::str("r+"))?;
    let r = ftruncate_impl(vm, &fd, &a.arg(1));
    if let Value::Num(n) = fd {
        close_fd_num(n);
    }
    r
}

