/// tick body: cb(...slots[1..])
fn tick_cb_args(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let cb = a.slot(0);
    let mut args = Vec::new();
    let n = match &a.callee.borrow().kind {
        ObjKind::Native(nf) => nf.slots.len(),
        _ => 0,
    };
    for i in 1..n {
        args.push(a.slot(i));
    }
    call_cb(vm, &cb, &args)?;
    Ok(Value::Undefined)
}

