}

fn glob_cb_tick(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let r = glob_impl(vm, &a.slot(0), &a.slot(1)).map(|v| vec![Value::Obj(vm.new_array(v))]);
    cb_try(vm, &a.slot(2), r)?;
