/// `(...args) => promisedCall(() => syncFn(...args))`
fn promise_wrapper(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let f = a.slot(0);
    let r = vm.call(&f, Value::Undefined, a.args);
    Ok(settle(vm, r))
}

