const fs = require('fs');
const path = require('path');
const os = require('os');

const dir = path.join(os.tmpdir(), 'fsagent-basic-test');
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });

const file = path.join(dir, 'hello.txt');
fs.writeFileSync(file, 'Hello, World!\n');
console.log('exists:', fs.existsSync(file));
console.log('content:', JSON.stringify(fs.readFileSync(file, 'utf8')));
fs.appendFileSync(file, 'Second line\n');
const content = fs.readFileSync(file, 'utf-8');
console.log('lines:', content.split('\n').filter(Boolean).length);
const buf = fs.readFileSync(file);
console.log('isBuffer:', Buffer.isBuffer(buf), 'length:', buf.length, 'first byte:', buf[0]);
console.log('hex:', buf.slice(0, 5).toString('hex'));

const st = fs.statSync(file);
console.log('size:', st.size, 'isFile:', st.isFile(), 'isDirectory:', st.isDirectory());
console.log('mtime is Date:', st.mtime instanceof Date, typeof st.mtimeMs);
console.log('mode:', (st.mode & 0o777).toString(8));

fs.mkdirSync(path.join(dir, 'sub', 'deep'), { recursive: true });
fs.writeFileSync(path.join(dir, 'sub', 'a.json'), JSON.stringify({ a: 1, b: [1, 2, 3] }, null, 2));
const obj = JSON.parse(fs.readFileSync(path.join(dir, 'sub', 'a.json'), 'utf8'));
console.log('json:', obj.a, obj.b.join('+'));

console.log('readdir:', fs.readdirSync(dir).join(', '));
for (const e of fs.readdirSync(path.join(dir, 'sub'), { withFileTypes: true }).sort((x, y) => x.name.localeCompare(y.name))) {
  console.log(' -', e.name, e.isDirectory() ? 'dir' : 'file');
}

fs.renameSync(file, path.join(dir, 'renamed.txt'));
