const fs = require('fs');
const path = require('path');
const { once } = require('events');

const dir = '/tmp/fsagent/out/t_streams';
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
const src = path.join(dir, 'src.txt');
const lines = [];
for (let i = 0; i < 2000; i++) lines.push('line ' + i + ' ' + 'x'.repeat(i % 50));
fs.writeFileSync(src, lines.join('\n'));
console.log('src size:', fs.statSync(src).size);

async function run() {
  // read with data events
  let total = 0, chunks = 0;
  await new Promise((resolve, reject) => {
    fs.createReadStream(src)
      .on('data', (c) => { total += c.length; chunks++; })
      .on('end', () => { console.log('read total', total, 'chunks', chunks); resolve(); })
      .on('error', reject);
  });
  // encoding + highWaterMark
  let strChunks = [];
  const rs = fs.createReadStream(src, { encoding: 'utf8', highWaterMark: 16384 });
  rs.on('data', (c) => strChunks.push(c));
  await once(rs, 'end');
  console.log('str chunks', strChunks.length, typeof strChunks[0], strChunks.join('').length);
  // for await
  let n = 0;
  for await (const chunk of fs.createReadStream(src, { start: 0, end: 99 })) n += chunk.length;
  console.log('for await bytes', n);
  // write stream
  const out = path.join(dir, 'out.txt');
  const ws = fs.createWriteStream(out);
  for (let i = 0; i < 5; i++) ws.write('row ' + i + '\n');
  ws.end('end\n');
  await once(ws, 'finish');
  console.log('written:', JSON.stringify(fs.readFileSync(out, 'utf8')), ws.bytesWritten);
  // pipe copy
  const copy = path.join(dir, 'copy.txt');
  await new Promise((resolve) => {
    const w = fs.createWriteStream(copy);
    w.on('close', resolve);
    fs.createReadStream(src).pipe(w);
  });
  console.log('copy same:', fs.readFileSync(copy, 'utf8') === fs.readFileSync(src, 'utf8'));
  // stream errors
  const bad = fs.createReadStream(path.join(dir, 'missing.txt'));
  bad.on('error', (e) => console.log('stream error:', e.message.replace(dir, '<dir>'), e.code));
  await new Promise(r => setTimeout(r, 10));
  // append mode
  const ap = fs.createWriteStream(out, { flags: 'a' });
  ap.write('appended\n');
  ap.end();
  await once(ap, 'close');
  console.log('after append lines:', fs.readFileSync(out, 'utf8').trim().split('\n').length);
  console.log('ReadStream?', rs instanceof fs.ReadStream, ws instanceof fs.WriteStream);
  fs.rmSync(dir, { recursive: true });
}
run().catch(e => console.log('FAIL', e));

