const fs = require('fs');
const log = (...a) => console.log(a.map(x => typeof x === 'object' && x !== null ? (Buffer.isBuffer(x) ? 'Buffer(' + x.toString().slice(0, 20) + ')' : JSON.stringify(x)) : String(x)).join(' '));
const which = process.argv[2];
const P = '/tmp/fsagent/out/ws3_' + which + '.txt';
fs.writeFileSync(P, 'abcdefghijklmnopqrstuvwxyz');
if (which === '1') {
  const rs = fs.createReadStream(P, { highWaterMark: 5 });
  rs.on('data', (c) => { log('data', c); rs.pause(); setTimeout(() => rs.resume(), 2); });
  rs.on('end', () => log('end', rs.bytesRead));
  rs.on('close', () => log('close'));
} else if (which === '2') {
  const rs = fs.createReadStream(P, { highWaterMark: 4 });
  rs.on('readable', () => { let c; while ((c = rs.read(3)) !== null) log('read3', c); log('readable done', rs.readableLength); });
  rs.on('end', () => log('end'));
} else if (which === '3') {
  const rs = fs.createReadStream(P, { start: 30 });
  rs.on('data', (c) => log('data', c));
  rs.on('end', () => log('end', rs.bytesRead));
  rs.on('close', () => log('close'));
} else if (which === '4') {
  const rs = fs.createReadStream(P, { start: 5, end: 3 });
  rs.on('data', (c) => log('data', c));
  rs.on('end', () => log('end', rs.bytesRead));
} else if (which === '5') {
  const rs = fs.createReadStream(P, { start: 25, end: 100 });
  rs.on('data', (c) => log('data', c));
  rs.on('end', () => log('end', rs.bytesRead));
} else if (which === '6') {
  const ws = fs.createWriteStream(P);
  const big = Buffer.alloc(70000, 65);
  log('write big', ws.write(big), ws.writableLength, ws._writableState.needDrain);
  ws.on('drain', () => log('drain', ws.writableLength));
  ws.on('finish', () => log('finish', fs.statSync(P).size));
  log('write small', ws.write('x'));
  ws.end();
} else if (which === '7') {
  const ws = fs.createWriteStream(P);
  ws.end('done');
  ws.write('late', (err) => log('late cb', err && err.message));
  ws.on('error', (e) => log('error', e.message));
  ws.on('finish', () => log('finish'));
  ws.on('close', () => log('close', fs.readFileSync(P, 'utf8')));
} else if (which === '8') {
  const ws = fs.createWriteStream(P);
  ws.on('error', (e) => log('error', e.message));
  ws.on('close', () => log('close'));
  ws.destroy();
  log('destroyed', ws.writable, ws._writableState.destroyed);
  ws.write('x', (e) => log('cb', e && e.message));
} else if (which === '9') {
  const rs = fs.createReadStream(P);
  const chunks = [];
  rs.setEncoding('base64');
  rs.on('data', (c) => chunks.push(c));
  rs.on('end', () => log('base64', chunks.join('')));
} else if (which === '10') {
  const rs = fs.createReadStream(P, { highWaterMark: 10 });
  const ws1 = fs.createWriteStream(P + '.a');
  const ws2 = fs.createWriteStream(P + '.b');
  rs.pipe(ws1);
  rs.pipe(ws2);
  let n = 0;
  const done = () => { if (++n === 2) log('both', fs.readFileSync(P + '.a', 'utf8'), fs.readFileSync(P + '.b', 'utf8')); };
  ws1.on('close', done); ws2.on('close', done);
} else if (which === '11') {
  const rs = fs.createReadStream(P);
  rs.on('data', (c) => { log('data', c); throw new Error('boom in data'); });
  rs.on('error', (e) => log('error event', e.message));
  rs.on('close', () => log('close'));
} else if (which === '12') {
  const fd = fs.openSync(P, 'r');
  const rs = fs.createReadStream(null, { fd, start: 2, end: 6 });
  rs.on('data', (c) => log('data', c));
  rs.on('close', () => { log('close', rs.fd); try { fs.fstatSync(fd); log('fd still open'); } catch (e) { log(e.message); } });
} else if (which === '13') {
  const fd = fs.openSync(P, 'r', 0o666);
  const rs = fs.createReadStream('', { fd, autoClose: true });
  rs.on('end', () => log('end'));
  rs.on('close', () => { try { fs.fstatSync(fd); log('fd still open'); } catch (e) { log(e.message); } });
  rs.resume();
} else if (which === '14') {
  const ws = fs.createWriteStream(P, { encoding: 'hex' });
  ws.write('414243');
  ws.write(Buffer.from('DEF'));
  ws.write('4748', 'hex');
  ws.write('ij', 'utf8');
  ws.end(() => log('content', fs.readFileSync(P, 'utf8')));
} else if (which === '15') {
  const ws = fs.createWriteStream(P);
  ws.cork();
  ws.write('a');
  ws.write('b');
  process.nextTick(() => ws.uncork());
  ws.end('c');
  ws.on('finish', () => log('content', fs.readFileSync(P, 'utf8')));
} else if (which === '16') {
  const rs = fs.createReadStream(P, { highWaterMark: 8, encoding: 'utf8' });
  rs.once('data', (c) => log('once', c));
  setTimeout(() => log('later', rs._readableState.buffer.length, rs._readableState.flowing), 5);
} else if (which === '17') {
