const fs = require('fs');
const which = process.argv[2];
if (which === '1') {
  fs.readFile('/nonexistent', (err, data) => { if (err) throw err; console.log(data); });
  setTimeout(() => console.log('after timeout'), 10);
} else if (which === '2') {
  fs.promises.readFile('/nonexistent');
  setTimeout(() => console.log('after timeout'), 10);
} else if (which === '3') {
  (async () => { await fs.promises.readFile('/nonexistent'); })();
  setTimeout(() => console.log('after timeout'), 10);
} else if (which === '4') {
  fs.readFileSync('/nonexistent');
} else if (which === '5') {
  fs.createReadStream('/nonexistent');
  setTimeout(() => console.log('after timeout'), 10);
} else if (which === '6') {
  const ws = fs.createWriteStream('/nonexistent/x');
  ws.write('x');
  setTimeout(() => console.log('after timeout'), 10);
} else if (which === '7') {
  fs.mkdir('/tmp', (err) => { console.log('cb', err.code); throw new TypeError('in cb'); });
  process.on('exit', (c) => console.log('exit', c));
} else if (which === '8') {
  process.on('uncaughtException', (e) => console.log('handler', e.message));
  fs.readFile('/nonexistent', (err) => { throw err; });
  setTimeout(() => console.log('after'), 10);
} else if (which === '9') {
  process.on('unhandledRejection', (r) => console.log('unhandled', r.code));
  fs.promises.stat('/nonexistent');
  setTimeout(() => console.log('after'), 10);
}

