const fs = require('fs');
const path = require('path');
const root = '/tmp/fsagent/out/walk';
fs.rmSync(root, { recursive: true, force: true });
const tree = { 'a.txt': 'aaa', 'b': { 'c.js': 'console.log(1)', 'd': { 'e.md': '# title\n\ntext', 'f.json': '{"x":1}' } }, 'g': {}, 'h.log': 'x'.repeat(1000) };
function build(dir, t) {
