    match data {
        Value::Str(_) => {
            let frames: Vec<&str> = if enc.truthy() && !matches!(enc, Value::Str(_)) {
                vec![caller, "from", "bytesFromString", "normEncoding"]
            } else {
                vec![caller, "from", "bytesFromString"]
            };
            with_frames(vm, &frames, |vm| to_buffer(vm, data, enc))
        }
        _ => with_frames(vm, &[caller, "from"], |vm| to_buffer(vm, data, enc)),
    }
}

