const fs = require('fs');
const fsp = fs.promises;
const N = '/nonexistent/x';
const show = (k, e) => console.log(k, '|', e && e.message ? e.message.slice(0, 30) : e, '|', String(e && e.stack).split('\n').slice(1).map(s => s.trim()).join(' / '));
(async function main() {
  const P = '/tmp/fsagent/out/stk.txt';
  fs.writeFileSync(P, 'data');
  const fh = await fsp.open(P, 'r');
  await fh.read(undefined).catch(e => show('fh.read', e));
  await fh.write('x').catch(e => show('fh.write', e));
  await fh.write(5).catch(e => show('fh.write num', e));
  await fh.readFile('bogus').catch(e => show('fh.readFile enc', e));
  await fh.writeFile(5).catch(e => show('fh.writeFile num', e));
  await fh.appendFile('x').catch(e => show('fh.appendFile', e));
  await fh.chmod(0o644).catch(e => show('fh.chmod', e));
  await fh.truncate(1).catch(e => show('fh.truncate', e));
  await fh.close();
  await fh.stat().catch(e => show('fh.stat closed', e));
  await fh.readv([Buffer.alloc(1)]).catch(e => show('fh.readv closed', e));
  await fh.writev([Buffer.alloc(1)]).catch(e => show('fh.writev closed', e));
