const fs = require('fs');
const P = '/tmp/fsagent/out/sub.txt';
fs.writeFileSync(P, 'line1\nline2\n');
class Upper extends fs.ReadStream {
  push(chunk) { return super.push(chunk === null ? null : Buffer.from(chunk.toString().toUpperCase())); }
}
const u = new Upper(P);
console.log(u instanceof fs.ReadStream, u instanceof Upper, u.constructor.name, Object.keys(u).length);
u.on('data', (c) => console.log('upper data', JSON.stringify(c.toString())));
u.on('end', () => console.log('upper end'));
class Counting extends fs.WriteStream {
  constructor(p) { super(p); this.count = 0; }
  _write(chunk, enc, cb) { this.count++; super._write(chunk, enc, cb); }
}
const c = new Counting(P + '.out');
c.write('a'); c.write('b');
c.end('c', () => console.log('counting done', c.count, fs.readFileSync(P + '.out', 'utf8')));
class MyStats extends fs.Stats { describe() { return this.size + ' bytes'; } }
const ms = new MyStats({ size: 42, kind: 'file' });
console.log(ms.describe(), ms.isFile(), ms instanceof fs.Stats);
const d = new fs.Dirent('x', 'symlink', '/p');
console.log(d.isSymbolicLink(), d.name);
const rs2 = Reflect.construct(fs.ReadStream, [P], Object);
console.log(Object.getPrototypeOf(rs2) === Object.prototype, typeof rs2.fd);
setTimeout(() => {}, 20);

