// Calls every fs export with a grid of odd arguments; prints normalized outcomes.
const fs = require('fs');
const S = '/tmp/fsagent/out/fuzz';
const seedArg = Number(process.argv[2] || 1);
function reset() {
  fs.rmSync(S, { recursive: true, force: true });
  fs.mkdirSync(S + '/d', { recursive: true });
  fs.writeFileSync(S + '/f', 'content');
  process.chdir(S);
}
reset();
const vals = [undefined, null, 0, 1, -1, 2.5, NaN, '', 'f', 'd', 'nope', S + '/f', S + '/d', true, {}, [], ['f'], Buffer.from('f'), () => 1, Symbol('s'), 10n, { encoding: 'hex' }, { recursive: true }, 'utf8', 'r+', 'w'];
const names = Object.keys(fs).filter(k => typeof fs[k] === 'function' && !/^(watch|watchFile|unwatchFile|Stats|Dirent|Dir|StatWatcher|ReadStream|WriteStream|FileReadStream|FileWriteStream|createReadStream|createWriteStream|openAsBlob)$/.test(k) && /Sync$|^(readvBytes|_toUnixTimestamp)$/.test(k));
let rnd = seedArg;
const rand = (n) => { rnd = (rnd * 1103515245 + 12345) % 2147483648; return rnd % n; };
function fmt(v) {
  try {
    if (v === undefined) return 'undefined';
    if (typeof v === 'symbol') return 'sym';
    if (typeof v === 'bigint') return v + 'n';
    if (typeof v === 'function') return 'fn';
    if (Buffer.isBuffer(v)) return 'Buf(' + v.length + ')';
    if (v && typeof v === 'object') {
      if (v instanceof fs.Stats) return 'Stats(' + v._kind + ',' + v.size + ')';
      if (v instanceof fs.Dir) return 'Dir';
      if (Array.isArray(v)) return '[' + v.map(fmt).join(',') + ']';
      if (v.constructor && v.constructor.name === 'Dirent') return 'Dirent(' + v.name + ')';
      return '{' + Object.keys(v).join(',') + '}';
    }
    return JSON.stringify(v);
  } catch (e) { return '?'; }
}
let count = 0;
for (const name of names) {
  for (let i = 0; i < 25; i++) {
    const nargs = rand(4);
    const args = [];
    for (let j = 0; j < nargs; j++) args.push(vals[rand(vals.length)]);
    let out;
    try { out = 'OK ' + fmt(fs[name](...args)); } catch (e) { out = 'ERR ' + (e && e.constructor && e.constructor.name) + ' ' + String(e && e.message).split(S).join('$S').replace(/[0-9a-f]{6}[0-9a-f]{4}/g, 'XXXX'); }
    console.log(name, '(' + args.map(fmt).join(', ') + ')', '=>', out);
    count++;
    if (count % 50 === 0) reset();
  }
}
fs.rmSync(S, { recursive: true, force: true });

