27	        ("isUndefined", 1, |_vm, a| Ok(Value::Bool(a.arg(0).is_undefined()))),
28	        ("isObject", 1, |_vm, a| Ok(Value::Bool(matches!(a.arg(0), Value::Obj(ref o) if !o.is_callable())))),
29	        ("isPrimitive", 1, |_vm, a| Ok(Value::Bool(!a.arg(0).is_object()))),
30	        ("isBuffer", 1, |vm, a| Ok(Value::Bool(crate::runtime::buffer::is_buffer(vm, &a.arg(0))))),
31	        ("isSymbol", 1, |_vm, a| Ok(Value::Bool(matches!(a.arg(0), Value::Sym(_))))),
32	        ("isDeepStrictEqual", 2, |vm, a| Ok(Value::Bool(deep_equal(vm, &a.arg(0), &a.arg(1), true)?))),
33	        ("stripVTControlCharacters", 1, strip_vt),
34	        ("toUSVString", 1, to_usv_string),
35	        ("styleText", 2, |vm, a| Ok(Value::Str(vm.to_string(&a.arg(1))?))),
36	        ("getSystemErrorName", 1, |vm, a| {
37	            let n = vm.to_number(&a.arg(0))? as i32;
38	            Ok(Value::str(errno_name(-n)))
39	        }),
40	        ("debuglog", 1, |vm, _a| Ok(Value::Obj(vm.native_fn("debug", 0, |_vm, _a| Ok(Value::Undefined))))),
41	        ("aborted", 2, |vm, _a| Ok(vm.new_promise_capability_intrinsic().promise)),
42	        ("parseArgs", 1, parse_args),
43	    ];
44	    for (n, l, f) in fns {
45	        vm.def_method(&o, n, *l, *f);
46	    }
47	    if let Some(Value::Obj(insp)) = o.get_own_str("inspect") {
48	        let custom = vm.symbol_for("nodejs.util.inspect.custom");
49	        insp.set_prop(PropKey::from_str("custom"), Value::Sym(custom), WEC);
50	        let dflt = vm.obj_from(vec![("depth", Value::Num(2.0))]);
51	        insp.set_prop(PropKey::from_str("defaultOptions"), Value::Obj(dflt), WEC);
52	    }
53	    if let Some(Value::Obj(p)) = o.get_own_str("promisify") {
54	        let custom = vm.symbol_for("nodejs.util.promisify.custom");
55	        p.set_prop(PropKey::from_str("custom"), Value::Sym(custom), WEC);
56	    }
57	    if let Some(Value::Obj(d)) = o.get_own_str("debuglog") {
58	        o.set_prop(PropKey::from_str("debug"), Value::Obj(d), WEC);
59	    }
60	    let types = create_types(vm);
61	    o.set_str("types", types, WEC);
62	    for n in ["TextEncoder", "TextDecoder"] {
63	        if let Some(v) = vm.global.get_own_str(n) {
64	            o.set_str(n, v, WEC);
65	        }
66	    }
67	    crate::runtime::reorder_enum(vm, &o, crate::runtime::UTIL_KEYS);
68	    Value::Obj(o)
69	}
