128	pub fn describe_received(vm: &mut Vm, v: &Value) -> String {
129	    match v {
130	        Value::Undefined => "undefined".into(),
131	        Value::Null => "null".into(),
132	        Value::Bool(b) => format!("type boolean ({})", b),
133	        Value::Num(n) => format!("type number ({})", crate::numconv::number_to_string(*n)),
134	        Value::Str(s) => {
135	            let st = s.to_rust_string();
136	            let shown = if st.chars().count() > 28 { format!("{}...", st.chars().take(25).collect::<String>()) } else { st };
137	            format!("type string ('{}')", shown)
138	        }
139	        Value::Sym(s) => format!("type symbol ({})", s.descriptive_string()),
140	        Value::BigInt(b) => format!("type bigint ({}n)", b.to_string_radix(10)),
141	        Value::Obj(o) => {
142	            if o.is_callable() {
143	                let n = match o.get_own_str("name") {
144	                    Some(Value::Str(s)) if !s.is_empty() => s.to_rust_string(),
145	                    _ => String::new(),
146	                };
147	                if n.is_empty() {
148	                    "function ".into()
149	                } else {
150	                    format!("function {}", n)
151	                }
152	            } else {
153	                let cname = constructor_name(vm, o);
154	                match cname {
155	                    Some(c) if !c.is_empty() => format!("an instance of {}", c),
156	                    _ => {
157	                        let s = inspect_value(vm, v, 0).unwrap_or_default();
158	                        s
159	                    }
160	                }
161	            }
162	        }
163	        Value::Empty => "undefined".into(),
164	    }
165	}
