558	fn promisified_call(vm: &mut Vm, a: &Args) -> JsResult<Value> {
559	    let cap = vm.new_promise_capability_intrinsic();
560	    let cb = vm.native_closure("", 2, promisify_cb, vec![cap.resolve.clone(), cap.reject.clone()]);
561	    let mut args = a.args.to_vec();
562	    args.push(Value::Obj(cb));
563	    if let Err(e) = vm.call(&a.slot(0), a.this.clone(), &args) {
564	        vm.call(&cap.reject, Value::Undefined, &[e])?;
565	    }
566	    Ok(cap.promise)
567	}
568	
569	fn promisify_cb(vm: &mut Vm, a: &Args) -> JsResult<Value> {
570	    let err = a.arg(0);
571	    if !err.is_nullish() {
572	        vm.call(&a.slot(1), Value::Undefined, &[err])?;
573	    } else {
574	        vm.call(&a.slot(0), Value::Undefined, &[a.arg(1)])?;
575	    }
576	    Ok(Value::Undefined)
577	}
578	
579	fn callbackify(vm: &mut Vm, a: &Args) -> JsResult<Value> {
580	    let f = a.arg(0);
581	    if !f.is_callable() {
582	        return vm.throw_type("The \"original\" argument must be of type function");
583	    }
584	    Ok(Value::Obj(vm.native_closure("callbackified", 0, callbackified_call, vec![f])))
585	}
586	
587	fn callbackified_call(vm: &mut Vm, a: &Args) -> JsResult<Value> {
588	    let mut args = a.args.to_vec();
589	    let cb = args.pop().unwrap_or(Value::Undefined);
590	    if !cb.is_callable() {
591	        return vm.throw_type("The last argument must be of type function");
592	    }
593	    let p = vm.call(&a.slot(0), a.this.clone(), &args)?;
594	    let p = crate::builtins::promise::promise_resolve_intrinsic(vm, p)?;
595	    let on_ok = vm.native_closure("", 1, |vm, a| {
596	        let cb = a.slot(0);
597	        vm.host.callbacks.push_back((cb, vec![Value::Null, a.arg(0)]));
598	        Ok(Value::Undefined)
599	    }, vec![cb.clone()]);
600	    let on_err = vm.native_closure("", 1, |vm, a| {
601	        let cb = a.slot(0);
602	        vm.host.callbacks.push_back((cb, vec![a.arg(0)]));
603	        Ok(Value::Undefined)
604	    }, vec![cb]);
605	    crate::builtins::promise::promise_then(vm, &p, Value::Obj(on_ok), Value::Obj(on_err))?;
606	    Ok(Value::Undefined)
607	}
