        self.depth -= 1;
        match r {
            Ok(Completion::Return(v)) => Ok(v),
            Ok(_) => Ok(Value::Undefined),
            Err(e) => Err(e),
        }
    }

    pub fn construct(&mut self, f: &Value, args: &[Value], new_target: Option<&Value>) -> JsResult<Value> {
        let fo = match f {
            Value::Obj(o) if o.is_constructor() => o.clone(),
