// --- Writable ---

fn writable_init(vm: &mut Vm, o: &Obj, opts: &Value) -> JsResult<()> {
    crate::runtime::events::init_emitter(vm, o);
    let this = Value::Obj(o.clone());
    let om = getp(vm, opts, "objectMode")?.truthy() || getp(vm, opts, "writableObjectMode")?.truthy();
    let hwm = getp(vm, opts, "highWaterMark")?;
    let hwm = if hwm.is_undefined() { Value::Num(default_hwm(om)) } else { Value::Num(to_num(vm, &hwm)?) };
    let cork = Value::Obj(vm.new_array(Vec::new()));
    let tail = resolved(vm, Value::Undefined);
    let st = vm.obj_from(vec![
        ("ended", Value::Bool(false)),
        ("finished", Value::Bool(false)),
        ("destroyed", Value::Bool(false)),
        ("corked", Value::Num(0.0)),
        ("corkBuffer", cork),
        ("errored", Value::Null),
        ("tail", tail),
        ("objectMode", Value::Bool(om)),
        ("highWaterMark", hwm),
        ("length", Value::Num(0.0)),
        ("needDrain", Value::Bool(false)),
    ]);
    setp(vm, &this, "_writableState", Value::Obj(st))?;
    setp(vm, &this, "writable", Value::Bool(true))?;
    for (opt, prop) in [("write", "_write"), ("writev", "_writev"), ("final", "_final")] {
        let f = getp(vm, opts, opt)?;
        if f.is_callable() {
            setp(vm, &this, prop, f)?;
        }
    }
    Ok(())
}

fn writable_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let nt = require_new(vm, a)?;
    let fb = vm.intr.object_proto.clone();
    let proto = vm.proto_from_nt(&Some(nt), &fb)?;
    let o = Obj::new(Some(proto), ObjKind::Ordinary);
    let opts = if a.arg(0).is_undefined() { Value::Obj(vm.new_object()) } else { a.arg(0) };
    writable_init(vm, &o, &opts)?;
    Ok(Value::Obj(o))
}

fn writable_default_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    vm.call(&a.arg(2), Value::Undefined, &[])
}

fn then_on(vm: &mut Vm, p: &Value, f: Value) -> JsResult<Value> {
    match p {
        Value::Obj(po) if crate::builtins::promise::is_promise(p) => crate::builtins::promise::promise_then(vm, po, f, Value::Undefined),
        _ => call_method(vm, p, "then", &[f]),
    }
}

/// state.tail = state.tail.then(() => new Promise(resolve => stream._write(chunk, enc, err => { completeWrite(...); resolve(); })))
fn queue_write(vm: &mut Vm, this: &Value, entry: &Value) -> JsResult<()> {
    let st = wstate(vm, this)?;
    let tail = sget(vm, &st, "tail")?;
    let h = closure(vm, "", 0, write_job, vec![this.clone(), entry.clone()]);
    let nt = then_on(vm, &tail, h)?;
    sset(vm, &st, "tail", nt)
}

fn write_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, entry) = (a.slot(0), a.slot(1));
    let cap = vm.new_promise_capability_intrinsic();
    let done = closure(vm, "", 1, write_done, vec![this.clone(), entry.clone(), cap.resolve.clone()]);
    let chunk = getp(vm, &entry, "chunk")?;
    let enc = getp(vm, &entry, "encoding")?;
    if let Err(e) = call_method(vm, &this, "_write", &[chunk, enc, done]) {
        vm.call(&cap.reject, Value::Undefined, &[e])?;
    }
    Ok(cap.promise)
}

fn write_done(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    complete_write(vm, &a.slot(0), &a.slot(1), &a.arg(0))?;
    vm.call(&a.slot(2), Value::Undefined, &[])?;
    Ok(Value::Undefined)
}

fn complete_write(vm: &mut Vm, this: &Value, entry: &Value, err: &Value) -> JsResult<()> {
    let st = wstate(vm, this)?;
    let l = getp(vm, entry, "length")?;
    let l = to_num(vm, &l)?;
    let cur = snum(vm, &st, "length")?;
    sset(vm, &st, "length", Value::Num(cur - l))?;
    if err.truthy() {
        emit(vm, this, "error", &[err.clone()])?;
    }
    let cb = getp(vm, entry, "cb")?;
    if cb.truthy() {
        vm.call(&cb, Value::Undefined, &[err.clone()])?;
    }
    if sget(vm, &st, "needDrain")?.truthy() {
        let len = snum(vm, &st, "length")?;
        let hwm = snum(vm, &st, "highWaterMark")?;
        if len < hwm {
            sset(vm, &st, "needDrain", Value::Bool(false))?;
            let f = closure(vm, "", 0, emit_drain_job, vec![this.clone()]);
            queue_microtask(vm, f);
        }
    }
    Ok(())
}

fn emit_drain_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    emit(vm, &a.slot(0), "drain", &[])?;
    Ok(Value::Undefined)
}

fn write_after_end_cb(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    vm.call(&a.slot(0), Value::Undefined, &[a.slot(1)])
}

fn writable_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let chunk = a.arg(0);
    let (mut enc, mut cb) = (a.arg(1), a.arg(2));
    if enc.is_callable() {
        cb = enc;
        enc = Value::Null;
    }
    let st = wstate(vm, &this)?;
    if sget(vm, &st, "ended")?.truthy() {
        let err = plain_err(vm, "write after end");
        if cb.truthy() {
            let f = closure(vm, "", 0, write_after_end_cb, vec![cb, err]);
            queue_microtask(vm, f);
        } else {
            emit(vm, &this, "error", &[err])?;
        }
        return Ok(Value::Bool(false));
    }
    let length = if sget(vm, &st, "objectMode")?.truthy() {
        1.0
    } else {
        let l = if chunk.truthy() { getp(vm, &chunk, "length")? } else { Value::Undefined };
        if !l.is_undefined() {
            to_num(vm, &l)?
        } else {
            let s = string_of(vm, &chunk)?;
            let e = match &enc {
                Value::Str(x) => crate::runtime::buffer::norm_encoding(&x.to_rust_string()).unwrap_or("utf8"),
                _ => "utf8",
            };
            crate::runtime::buffer::encode_string(&JsStr::from_str(&s), e).len() as f64
        }
    };
    let cur = snum(vm, &st, "length")?;
    sset(vm, &st, "length", Value::Num(cur + length))?;
    let entry = Value::Obj(vm.obj_from(vec![("chunk", chunk), ("encoding", enc), ("cb", cb), ("length", Value::Num(length))]));
    if snum(vm, &st, "corked")? != 0.0 && sget(vm, &st, "corked")?.truthy() {
        let cbuf = sget(vm, &st, "corkBuffer")?;
        call_method(vm, &cbuf, "push", &[entry])?;
    } else {
        queue_write(vm, &this, &entry)?;
    }
    let len = snum(vm, &st, "length")?;
    let hwm = snum(vm, &st, "highWaterMark")?;
    if len >= hwm {
        sset(vm, &st, "needDrain", Value::Bool(true))?;
    }
    Ok(Value::Bool(!sget(vm, &st, "needDrain")?.truthy()))
}

fn writable_queue_batch(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let entries = a.arg(0);
    let list = crate::builtins::array::array_like_to_vec(vm, &entries)?;
    let writev = getp(vm, &this, "_writev")?;
    if list.len() > 1 && writev.is_callable() {
        let st = wstate(vm, &this)?;
        let tail = sget(vm, &st, "tail")?;
        let h = closure(vm, "", 0, writev_job, vec![this.clone(), entries.clone()]);
        let nt = then_on(vm, &tail, h)?;
        sset(vm, &st, "tail", nt)?;
    } else {
        for e in list {
            queue_write(vm, &this, &e)?;
        }
    }
    Ok(Value::Undefined)
}

fn writev_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, entries) = (a.slot(0), a.slot(1));
    let cap = vm.new_promise_capability_intrinsic();
    let list = crate::builtins::array::array_like_to_vec(vm, &entries)?;
    let mut chunks = Vec::new();
    for e in &list {
        let c = getp(vm, e, "chunk")?;
        let en = getp(vm, e, "encoding")?;
        chunks.push(Value::Obj(vm.obj_from(vec![("chunk", c), ("encoding", en)])));
    }
    let arr = Value::Obj(vm.new_array(chunks));
    let done = closure(vm, "", 1, writev_done, vec![this.clone(), entries, cap.resolve.clone()]);
    if let Err(e) = call_method(vm, &this, "_writev", &[arr, done]) {
        vm.call(&cap.reject, Value::Undefined, &[e])?;
    }
    Ok(cap.promise)
}

fn writev_done(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    let list = crate::builtins::array::array_like_to_vec(vm, &a.slot(1))?;
    for e in list {
        complete_write(vm, &this, &e, &a.arg(0))?;
    }
    vm.call(&a.slot(2), Value::Undefined, &[])?;
    Ok(Value::Undefined)
}

fn writable_end(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let (mut chunk, mut enc, mut cb) = (a.arg(0), a.arg(1), a.arg(2));
    if chunk.is_callable() {
        cb = chunk;
        chunk = Value::Null;
    } else if enc.is_callable() {
        cb = enc;
        enc = Value::Null;
    }
    let st = wstate(vm, &this)?;
    if !chunk.is_nullish() {
        call_method(vm, &this, "write", &[chunk, enc])?;
    }
    sset(vm, &st, "ended", Value::Bool(true))?;
    if sget(vm, &st, "corked")?.truthy() {
        sset(vm, &st, "corked", Value::Num(0.0))?;
        let cbuf = sget(vm, &st, "corkBuffer")?;
        let entries = call_method(vm, &cbuf, "splice", &[Value::Num(0.0)])?;
        call_method(vm, &this, "_queueBatch", &[entries])?;
    }
    let tail = sget(vm, &st, "tail")?;
    let h = closure(vm, "", 0, end_job, vec![this.clone(), cb]);
    then_on(vm, &tail, h)?;
    Ok(this)
}

fn end_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, cb) = (a.slot(0), a.slot(1));
    let st = wstate(vm, &this)?;
    if sget(vm, &st, "finished")?.truthy() {
        return Ok(Value::Undefined);
    }
    let fin = getp(vm, &this, "_final")?;
    if fin.truthy() {
        let f = closure(vm, "", 1, final_done, vec![this.clone(), cb]);
        vm.call(&fin, this, &[f])?;
    } else {
        end_finish(vm, &this, &cb)?;
    }
    Ok(Value::Undefined)
}

fn end_finish(vm: &mut Vm, this: &Value, cb: &Value) -> JsResult<()> {
    let st = wstate(vm, this)?;
    sset(vm, &st, "finished", Value::Bool(true))?;
    if cb.truthy() {
        vm.call(cb, Value::Undefined, &[])?;
    }
    emit(vm, this, "finish", &[])?;
    Ok(())
}

fn final_done(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, cb) = (a.slot(0), a.slot(1));
    let err = a.arg(0);
    if err.truthy() {
        emit(vm, &this, "error", &[err])?;
    } else {
        end_finish(vm, &this, &cb)?;
    }
    Ok(Value::Undefined)
}

fn writable_cork(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    let c = snum(vm, &st, "corked")?;
    sset(vm, &st, "corked", Value::Num(c + 1.0))?;
    Ok(Value::Undefined)
}

fn writable_uncork(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    if sget(vm, &st, "corked")?.truthy() {
        let c = snum(vm, &st, "corked")?;
        sset(vm, &st, "corked", Value::Num(c - 1.0))?;
    }
    let corked = sget(vm, &st, "corked")?.truthy();
    let cbuf = sget(vm, &st, "corkBuffer")?;
    if !corked && array_len(vm, &cbuf)? > 0.0 {
        let entries = call_method(vm, &cbuf, "splice", &[Value::Num(0.0)])?;
        call_method(vm, &a.this, "_queueBatch", &[entries])?;
    }
    Ok(Value::Undefined)
}

fn writable_destroy(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let st = wstate(vm, &this)?;
    if sget(vm, &st, "destroyed")?.truthy() {
        return Ok(this);
    }
    sset(vm, &st, "destroyed", Value::Bool(true))?;
    let err = a.arg(0);
    if err.truthy() {
        sset(vm, &st, "errored", err.clone())?;
        let rs = getp(vm, &this, "_readableState")?;
        if rs.truthy() {
            sset(vm, &rs, "errored", err.clone())?;
        }
    }
    setp(vm, &this, "writable", Value::Bool(false))?;
    let job = closure(vm, "", 0, destroy_job, vec![this.clone(), err]);
    queue_microtask(vm, job);
    Ok(this)
}

fn writable_length(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    sget(vm, &st, "length")
}

fn writable_hwm(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    sget(vm, &st, "highWaterMark")
}

fn writable_object_mode(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    sget(vm, &st, "objectMode")
}

// --- fs.ReadStream / fs.WriteStream ---

/// normalizeStreamOpts: a string is the encoding, otherwise `options || {}`.
fn normalize_stream_opts(vm: &mut Vm, opts: &Value) -> JsResult<Value> {
    match opts {
        Value::Str(_) => Ok(Value::Obj(vm.obj_from(vec![("encoding", opts.clone())]))),
        v if v.truthy() => Ok(v.clone()),
        _ => Ok(Value::Obj(vm.new_object())),
    }
}

// node: builtin module registry and the CommonJS loader.

use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, TraceEntry, Vm};
use std::path::{Path, PathBuf};

pub const BUILTIN_NAMES: &[&str] = &[
    "buffer", "path", "os", "fs", "module", "events", "util", "sys", "console", "timers", "timers/promises", "crypto",
    "querystring", "url", "net", "assert", "assert/strict", "string_decoder", "tty", "async_hooks", "zlib", "stream",
    "stream/web", "stream/promises", "stream/consumers", "http", "https", "http2", "perf_hooks", "fs/promises",
    "path/posix", "path/win32", "child_process", "dns", "dns/promises", "v8", "inspector", "inspector/promises",
    "worker_threads", "readline", "readline/promises", "test", "tls", "process", "diagnostics_channel", "domain",
    "trace_events", "vm", "repl", "cluster", "dgram", "wasi",
];

pub fn setup_globals(vm: &mut Vm) {
    let g = vm.global.clone();
    g.set_prop(PropKey::from_str("global"), Value::Obj(g.clone()), WC);
    let cwd = std::env::current_dir().map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
    let r = make_require(vm, &cwd, None);
    vm.def_global("require", Value::Obj(r));
    let names: Vec<Value> = BUILTIN_NAMES.iter().map(|s| Value::str(s)).collect();
    let _ = names;
}

pub fn make_stdin(vm: &mut Vm) -> Value {
    let s = vm.new_object();
    crate::runtime::events::install_methods(vm, &s);
    crate::runtime::events::init_emitter(vm, &s);
    s.set_prop(PropKey::from_str("fd"), Value::Num(0.0), WEC);
    s.set_prop(PropKey::from_str("isTTY"), Value::Bool(false), WEC);
    vm.def_method(&s, "setEncoding", 1, |_vm, a| Ok(a.this.clone()));
    vm.def_method(&s, "resume", 0, stdin_resume);
    vm.def_method(&s, "pause", 0, |_vm, a| Ok(a.this.clone()));
    vm.def_method(&s, "setRawMode", 1, |_vm, a| Ok(a.this.clone()));
    vm.def_method(&s, "unref", 0, |_vm, a| Ok(a.this.clone()));
    vm.def_method(&s, "ref", 0, |_vm, a| Ok(a.this.clone()));
    Value::Obj(s)
}

/// Read all of stdin and emit 'data' + 'end' (used when a script listens to process.stdin).
fn stdin_resume(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let already = matches!(this.as_obj().and_then(|o| o.get_own_str("__reading")), Some(Value::Bool(true)));
    if already {
        return Ok(this);
    }
    if let Value::Obj(o) = &this {
        o.set_prop(PropKey::from_str("__reading"), Value::Bool(true), WC);
    }
    let target = this.clone();
    crate::runtime::spawn_op(
        vm,
        || {
            use std::io::Read;
            let mut buf = Vec::new();
            let _ = std::io::stdin().read_to_end(&mut buf);
            buf
        },
        move |vm: &mut Vm, buf: Vec<u8>| {
            if !buf.is_empty() {
                let s = String::from_utf8_lossy(&buf).to_string();
                let _ = crate::runtime::events::emit_event(vm, &target, &Value::str("data"), &[Value::str(&s)]);
            }
            let _ = crate::runtime::events::emit_event(vm, &target, &Value::str("end"), &[]);
            let _ = crate::runtime::events::emit_event(vm, &target, &Value::str("close"), &[]);
        },
    );
    Ok(this)
}

/// Get (creating if necessary) a builtin module's exports.
pub fn builtin_module(vm: &mut Vm, name: &str) -> JsResult<Option<Value>> {
    let name = if name == "sys" { "util" } else { name };
    if let Some(v) = vm.host.builtin_cache.get(name) {
        return Ok(Some(v.clone()));
    }
    let v = match name {
        "path" | "path/posix" => crate::runtime::path::create_module(vm),
        "path/win32" => crate::runtime::path::create_module(vm),
        "fs" => crate::runtime::fs::create_module(vm),
        "fs/promises" => {
            let fs = builtin_module(vm, "fs")?.unwrap();
            vm.get_prop_of(&fs, &PropKey::from_str("promises"))?
        }
        "events" => crate::runtime::events::create_module(vm),
        "util" => crate::runtime::util::create_module(vm),
        "buffer" => crate::runtime::buffer::create_module(vm),
        "zlib" => crate::runtime::zlib::create_module(vm),
        "crypto" => crate::runtime::cryptomod::create_module(vm),
        "os" => create_os(vm),
        "process" => Value::Obj(vm.host.process_obj.clone().unwrap()),
        "console" => vm.global.get_own_str("console").unwrap_or(Value::Undefined),
        "timers" => create_timers(vm),
        "timers/promises" => crate::runtime::web::create_timers_promises(vm),
        "url" => crate::runtime::web::create_url_module(vm),
        "string_decoder" => crate::runtime::buffer::create_string_decoder_module(vm),
        "querystring" => crate::runtime::web::create_querystring_module(vm),
        "assert" | "assert/strict" => crate::runtime::util::create_assert_module(vm),
        "module" => create_module_module(vm),
        "perf_hooks" => {
            let o = vm.new_object();
            let p = vm.global.get_own_str("performance").unwrap_or(Value::Undefined);
            o.set_str("performance", p, WEC);
            Value::Obj(o)
        }
        "async_hooks" => crate::runtime::util::create_async_hooks_module(vm),
        "worker_threads" => {
            let o = vm.new_object();
            o.set_str("isMainThread", Value::Bool(true), WEC);
            o.set_str("parentPort", Value::Null, WEC);
            o.set_str("workerData", Value::Null, WEC);
            o.set_str("threadId", Value::Num(0.0), WEC);
            Value::Obj(o)
        }
        "stream" | "stream/promises" | "stream/consumers" | "stream/web" => crate::runtime::nodestream::create_module(vm, name),
        "child_process" => crate::runtime::child_process::create_module(vm, name),
        "readline" | "readline/promises" => crate::runtime::readline::create_module(vm, name),
        "http" | "https" | "http2" => crate::runtime::http::create_module(vm, name),
        "net" | "tls" | "dgram" | "dns" | "dns/promises" => crate::runtime::net::create_module(vm, name),
        "vm" | "v8" => crate::runtime::vmmod::create_module(vm, name),
        "tty" => {
            let o = vm.new_object();
            vm.def_method(&o, "isatty", 1, |_vm, _a| Ok(Value::Bool(false)));
            Value::Obj(o)
        }
        _ => {
            if BUILTIN_NAMES.contains(&name) {
                Value::Obj(vm.new_object())
            } else {
                return Ok(None);
            }
        }
    };
    vm.host.builtin_cache.insert(name.to_string(), v.clone());
    Ok(Some(v))
}

fn create_timers(vm: &mut Vm) -> Value {
    let o = vm.new_object();
    for n in ["setTimeout", "setInterval", "clearTimeout", "clearInterval", "setImmediate", "queueMicrotask"] {
        if let Some(v) = vm.global.get_own_str(n) {
            o.set_str(n, v, WEC);
        }
    }
    vm.def_method(&o, "clearImmediate", 1, |_vm, _a| Ok(Value::Undefined));
    Value::Obj(o)
}

fn create_module_module(vm: &mut Vm) -> Value {
    let o = vm.new_object();
    vm.def_method(&o, "createRequire", 1, create_require);
    let names: Vec<Value> = BUILTIN_NAMES.iter().map(|s| Value::str(s)).collect();
    let arr = vm.new_array(names);
    o.set_str("builtinModules", Value::Obj(arr), WEC);
    vm.def_method(&o, "isBuiltin", 1, |vm, a| {
        let s = vm.to_string(&a.arg(0))?.to_rust_string();
        let n = s.strip_prefix("node:").unwrap_or(&s);
        Ok(Value::Bool(BUILTIN_NAMES.contains(&n)))
    });
    Value::Obj(o)
}

fn create_require(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let mut p = vm.to_string(&a.arg(0))?.to_rust_string();
    if let Some(rest) = p.strip_prefix("file://") {
        p = rest.to_string();
    }
    let dir = Path::new(&p).parent().map(|d| d.to_string_lossy().to_string()).unwrap_or_else(|| ".".into());
    Ok(Value::Obj(make_require(vm, &dir, None)))
}

fn create_os(vm: &mut Vm) -> Value {
    let o = vm.new_object();
    o.set_str("EOL", Value::str("\n"), WEC);
    let fns: &[(&str, NativeFn)] = &[
        ("platform", |_vm, _a| Ok(Value::str(std::env::consts::OS))),
        ("type", |_vm, _a| Ok(Value::str("Linux"))),
        ("arch", |_vm, _a| {
            Ok(Value::str(match std::env::consts::ARCH {
                "aarch64" => "arm64",
                "x86_64" => "x64",
                o => o,
            }))
        }),
        ("homedir", |_vm, _a| Ok(Value::str(&std::env::var("HOME").unwrap_or_else(|_| "/".into())))),
        ("tmpdir", |_vm, _a| Ok(Value::str(&std::env::var("TMPDIR").unwrap_or_else(|_| "/tmp".into())))),
        ("hostname", |_vm, _a| Ok(Value::str(std::fs::read_to_string("/etc/hostname").unwrap_or_else(|_| "localhost".into()).trim()))),
        ("release", |_vm, _a| Ok(Value::str(std::fs::read_to_string("/proc/sys/kernel/osrelease").unwrap_or_default().trim()))),
        ("uptime", |_vm, _a| {
            let u = std::fs::read_to_string("/proc/uptime").ok().and_then(|s| s.split_whitespace().next().and_then(|x| x.parse::<f64>().ok())).unwrap_or(0.0);
            Ok(Value::Num(u.floor()))
        }),
        ("totalmem", |_vm, _a| Ok(Value::Num(meminfo("MemTotal")))),
        ("freemem", |_vm, _a| Ok(Value::Num(meminfo("MemAvailable")))),
        ("endianness", |_vm, _a| Ok(Value::str("LE"))),
        ("availableParallelism", |_vm, _a| Ok(Value::Num(std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1) as f64))),
        ("loadavg", |vm, _a| {
            let s = std::fs::read_to_string("/proc/loadavg").unwrap_or_default();
            let v: Vec<Value> = s.split_whitespace().take(3).map(|x| Value::Num(x.parse().unwrap_or(0.0))).collect();
            Ok(Value::Obj(vm.new_array(v)))
        }),
        ("cpus", |vm, _a| {
            let n = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1);
            let mut v = Vec::new();
            for _ in 0..n {
                let times = vm.obj_from(vec![("user", Value::Num(0.0)), ("nice", Value::Num(0.0)), ("sys", Value::Num(0.0)), ("idle", Value::Num(0.0)), ("irq", Value::Num(0.0))]);
                let c = vm.obj_from(vec![("model", Value::str("cpu")), ("speed", Value::Num(0.0)), ("times", Value::Obj(times))]);
                v.push(Value::Obj(c));
            }
            Ok(Value::Obj(vm.new_array(v)))
        }),
        ("networkInterfaces", |vm, _a| Ok(Value::Obj(vm.new_object()))),
        ("userInfo", |vm, _a| {
            let user = std::env::var("USER").unwrap_or_else(|_| "user".into());
            let home = std::env::var("HOME").unwrap_or_else(|_| "/".into());
            Ok(Value::Obj(vm.obj_from(vec![
                ("uid", Value::Num(0.0)),
                ("gid", Value::Num(0.0)),
                ("username", Value::str(&user)),
                ("homedir", Value::str(&home)),
                ("shell", Value::str(&std::env::var("SHELL").unwrap_or_default())),
            ])))
        }),
        ("version", |_vm, _a| Ok(Value::str(std::fs::read_to_string("/proc/sys/kernel/version").unwrap_or_default().trim()))),
        ("machine", |_vm, _a| Ok(Value::str(std::env::consts::ARCH))),
    ];
    for (n, f) in fns {
        vm.def_method(&o, n, 0, *f);
    }
    let constants = vm.new_object();
    let signals = vm.obj_from(vec![("SIGINT", Value::Num(2.0)), ("SIGTERM", Value::Num(15.0)), ("SIGKILL", Value::Num(9.0)), ("SIGHUP", Value::Num(1.0))]);
    constants.set_str("signals", Value::Obj(signals), WEC);
    o.set_str("constants", Value::Obj(constants), WEC);
    o.set_str("devNull", Value::str("/dev/null"), WEC);
    Value::Obj(o)
}

fn meminfo(key: &str) -> f64 {
    if let Ok(s) = std::fs::read_to_string("/proc/meminfo") {
        for line in s.lines() {
            if let Some(rest) = line.strip_prefix(&format!("{}:", key)) {
                let kb: f64 = rest.trim().trim_end_matches("kB").trim().parse().unwrap_or(0.0);
                return kb * 1024.0;
            }
        }
    }
    0.0
}

// ---------------- CommonJS ----------------

pub fn make_require(vm: &mut Vm, dir: &str, module: Option<Obj>) -> Obj {
    let r = vm.native_closure("require", 1, require_fn, vec![Value::str(dir), module.clone().map(Value::Obj).unwrap_or(Value::Undefined)]);
    let resolve = vm.native_closure("resolve", 1, require_resolve, vec![Value::str(dir)]);
    r.set_prop(PropKey::from_str("resolve"), Value::Obj(resolve), WEC);
    let cache = vm.new_object();
    r.set_prop(PropKey::from_str("cache"), Value::Obj(cache), WEC);
    let main = vm.host.main_module.clone().map(Value::Obj).unwrap_or(Value::Undefined);
    r.set_prop(PropKey::from_str("main"), main, WEC);
    r
}

pub enum Resolved {
    Builtin(String),
    File(PathBuf),
}

fn try_file(p: &Path) -> Option<PathBuf> {
    if p.is_file() {
        return Some(p.to_path_buf());
    }
    for ext in ["js", "json", "cjs", "mjs", "node", "jsx", "ts"] {
        let mut s = p.as_os_str().to_owned();
        s.push(".");
        s.push(ext);
        let c = PathBuf::from(s);
        if c.is_file() {
            return Some(c);
        }
    }
    None
}

fn try_dir(p: &Path) -> Option<PathBuf> {
    if !p.is_dir() {
        return None;
    }
    let pj = p.join("package.json");
    if pj.is_file() {
        if let Ok(src) = std::fs::read_to_string(&pj) {
            if let Some(main) = json_string_field(&src, "main") {
                let m = p.join(&main);
                if let Some(f) = try_file(&m) {
                    return Some(f);
                }
                if let Some(f) = try_index(&m) {
                    return Some(f);
                }

}
            }
        }
    }
    try_index(p)
}

fn try_index(p: &Path) -> Option<PathBuf> {
    for n in ["index.js", "index.json", "index.cjs", "index.mjs"] {
        let c = p.join(n);
        if c.is_file() {
            return Some(c);
        }
    }
    None
}

/// Very small JSON field extractor for package.json ("main", "type")
pub fn json_string_field(src: &str, field: &str) -> Option<String> {
    let pat = format!("\"{}\"", field);
    let i = src.find(&pat)?;
    let rest = &src[i + pat.len()..];
    let rest = rest.trim_start();
    let rest = rest.strip_prefix(':')?.trim_start();
    let rest = rest.strip_prefix('"')?;
    let end = rest.find('"')?;
    Some(rest[..end].to_string())
}

fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            std::path::Component::ParentDir => {
                out.pop();
            }
            std::path::Component::CurDir => {}
            other => out.push(other.as_os_str()),
        }
    }
    out
}

pub fn resolve(spec: &str, dir: &str) -> Option<Resolved> {
    if let Some(n) = spec.strip_prefix("node:") {
        return if BUILTIN_NAMES.contains(&n) { Some(Resolved::Builtin(n.to_string())) } else { None };
    }
    if BUILTIN_NAMES.contains(&spec) {
        return Some(Resolved::Builtin(spec.to_string()));
    }
    if spec.starts_with("./") || spec.starts_with("../") || spec.starts_with('/') || spec == "." || spec == ".." {
        let p = if spec.starts_with('/') { PathBuf::from(spec) } else { Path::new(dir).join(spec) };
        let p = normalize(&p);
        if let Some(f) = try_file(&p) {
            return Some(Resolved::File(f));
        }
        if let Some(f) = try_dir(&p) {
            return Some(Resolved::File(f));
        }
        return None;
    }
    // node_modules lookup
    let mut d = Some(PathBuf::from(dir));
    while let Some(cur) = d {
        let nm = cur.join("node_modules").join(spec);
        if let Some(f) = try_file(&nm) {
            return Some(Resolved::File(f));
        }
        if let Some(f) = try_dir(&nm) {
            return Some(Resolved::File(f));
        }
        d = cur.parent().map(|p| p.to_path_buf());
    }
    None
}

fn not_found(vm: &mut Vm, spec: &str, dir: &str) -> Value {
    let rel = spec.starts_with("./") || spec.starts_with("../") || spec.starts_with('/');
    let msg = if rel { format!("Cannot find module '{}' from '{}'", spec, dir) } else { format!("Cannot find module '{}'", spec) };
    let e = vm.make_error("Error", &msg);
    if let Value::Obj(o) = &e {
        o.set_prop(PropKey::from_str("code"), Value::str("MODULE_NOT_FOUND"), WEC);
    }
    e
}

fn require_resolve(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let spec = vm.to_string(&a.arg(0))?.to_rust_string();
    let dir = a.slot(0).as_obj().map(|_| String::new()).unwrap_or_else(|| match a.slot(0) {
        Value::Str(s) => s.to_rust_string(),
        _ => ".".into(),
    });
    match resolve(&spec, &dir) {
        Some(Resolved::Builtin(n)) => Ok(Value::str(&n)),
        Some(Resolved::File(p)) => Ok(Value::str(&p.to_string_lossy())),
        None => Err(not_found(vm, &spec, &dir)),
    }
}

fn require_fn(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let spec = match a.arg(0) {
        Value::Str(s) => s.to_rust_string(),
        other => {
            let d = crate::runtime::util::describe_received(vm, &other);
            return vm.throw_type(format!("The \"id\" argument must be of type string. Received {}", d));
        }
    };
    let dir = match a.slot(0) {
        Value::Str(s) => s.to_rust_string(),
        _ => ".".into(),
    };
    let parent = a.slot(1).as_obj().cloned();
    require_spec(vm, &spec, &dir, parent)
}

pub fn require_spec(vm: &mut Vm, spec: &str, dir: &str, parent: Option<Obj>) -> JsResult<Value> {
    match resolve(spec, dir) {
        Some(Resolved::Builtin(n)) => match builtin_module(vm, &n)? {
            Some(v) => Ok(v),
            None => Err(not_found(vm, spec, dir)),
        },
        Some(Resolved::File(p)) => load_cjs(vm, &p, parent),
        None => Err(not_found(vm, spec, dir)),
    }
}

fn new_module_obj(vm: &mut Vm, path: &str, id: &str, parent: Option<Obj>) -> Obj {
    let m = vm.new_object();
    m.set_str("id", Value::str(id), WEC);
    m.set_str("filename", Value::str(path), WEC);
    m.set_str("loaded", Value::Bool(false), WEC);
    let exports = vm.new_object();
    m.set_str("exports", Value::Obj(exports), WEC);
    m.set_str("parent", parent.clone().map(Value::Obj).unwrap_or(Value::Null), WEC);
    let children = vm.new_array(Vec::new());
    m.set_str("children", Value::Obj(children), WEC);
    let paths = vm.new_array(Vec::new());
    m.set_str("paths", Value::Obj(paths), WEC);
    if let Some(p) = parent {
        if let Some(Value::Obj(ch)) = p.get_own_str("children") {
            crate::vm::array_push_raw(&ch, Value::Obj(m.clone()));
        }
    }
    m
}

pub fn load_cjs(vm: &mut Vm, path: &Path, parent: Option<Obj>) -> JsResult<Value> {
    let key = path.to_string_lossy().to_string();
    if let Some(m) = vm.host.cjs_cache.get(&key).cloned() {
        if let Some(p) = &parent {
            if let Some(Value::Obj(ch)) = p.get_own_str("children") {
                let already = crate::builtins::array::array_like_to_vec(vm, &Value::Obj(ch.clone()))?.iter().any(|c| matches!(c, Value::Obj(co) if co.ptr_eq(&m)));
                if !already {
                    crate::vm::array_push_raw(&ch, Value::Obj(m.clone()));
                }
            }
        }
        return vm.get_str(&m, "exports");
    }
    let ext = path.extension().map(|e| e.to_string_lossy().to_string()).unwrap_or_default();
    if ext == "mjs" {
        let ns = crate::modules::load_esm_sync(vm, path)?;
        return Ok(ns);
    }
    let m = new_module_obj(vm, &key, &key, parent);
    vm.host.cjs_cache.insert(key.clone(), m.clone());
    let src = match std::fs::read(path) {
        Ok(b) => String::from_utf8_lossy(&b).to_string(),
        Err(_) => return Err(not_found(vm, &key, "")),
    };
    if ext == "json" {
        let v = crate::builtins::json::json_parse(vm, &JsStr::from_str(&src))?;
        m.set_str("exports", v.clone(), WEC);
        m.set_str("loaded", Value::Bool(true), WEC);
        return Ok(v);
    }
    run_cjs_source(vm, &m, &key, &src, false)?;
    m.set_str("loaded", Value::Bool(true), WEC);
    vm.get_str(&m, "exports")
}

/// Compile and run CommonJS source with the module wrapper.
pub fn run_cjs_source(vm: &mut Vm, module: &Obj, filename: &str, src: &str, is_main: bool) -> JsResult<()> {
    let dir = Path::new(filename).parent().map(|d| d.to_string_lossy().to_string()).unwrap_or_else(|| ".".into());
    let mut body = src.to_string();
    if body.starts_with("#!") {
        body = format!("//{}", &body[2..]);
    }
    let wrapped = format!("(function (exports, require, module, __filename, __dirname) {{{}\n}})", body);
    let f = match compile_wrapper(vm, &wrapped) {
        Ok(f) => f,
        Err(e) => return Err(e),
    };
    let req = make_require(vm, &dir, Some(module.clone()));
    if is_main {
        req.set_prop(PropKey::from_str("main"), Value::Obj(module.clone()), WEC);
    }
    let exports = vm.get_str(module, "exports")?;
    let args = vec![exports.clone(), Value::Obj(req), Value::Obj(module.clone()), Value::str(filename), Value::str(&dir)];
    if is_main {
        vm.trace.push(TraceEntry { name: JsStr::from_str("runMain") });
        vm.trace.push(TraceEntry { name: JsStr::from_str(".js") });
        vm.trace.push(TraceEntry { name: JsStr::from_str("compileCommonJS") });
        vm.depth_offset += 4;
        let r = vm.call(&Value::Obj(f), exports, &args);
        vm.depth_offset -= 4;
        vm.trace.truncate(vm.trace.len() - 3);
        r?;
    } else {
        vm.call(&Value::Obj(f), exports, &args)?;
    }
    Ok(())
}

pub struct CjsSyntaxError {
    pub msg: String,
    pub line: u32,
}

thread_local! {
    pub static LAST_SYNTAX: std::cell::RefCell<Option<CjsSyntaxError>> = std::cell::RefCell::new(None);
}

fn compile_wrapper(vm: &mut Vm, wrapped: &str) -> JsResult<Obj> {
    let opts = crate::parser::ParseOptions {
        is_module: false,
        strict: false,
        in_function: false,
        allow_super_prop: false,
        allow_super_call: false,
        allow_new_target: false,
        in_field_init: false,
        allow_return: false,
        in_async: false,
        in_generator: false,
        repl: false,
    };
    let code = match crate::loader::compile_program(wrapped, crate::resolver::ScopeKind::Eval, Some(&opts), false) {
        Ok(c) => c,
        Err(e) => {
            LAST_SYNTAX.with(|l| *l.borrow_mut() = Some(CjsSyntaxError { msg: e.msg.clone(), line: e.line }));
            return Err(crate::loader::syntax_error_value(vm, &e));
        }
    };
    let this = Value::Obj(vm.global.clone());
    let mut frame = crate::vm::Frame::new(code, None, this, None, Value::Undefined, Vec::new(), None);
    match vm.run_frame(&mut frame)? {
        crate::vm::Completion::Return(Value::Obj(f)) => Ok(f),
        _ => vm.throw_syntax("invalid module"),
    }
}

/// Run the main CommonJS module.
pub fn run_cjs_main(vm: &mut Vm, path: &Path, src: &str) -> JsResult<()> {
    let key = path.to_string_lossy().to_string();
    let m = new_module_obj(vm, &key, ".", None);
    vm.host.main_module = Some(m.clone());
    vm.host.cjs_cache.insert(key.clone(), m.clone());
    run_cjs_source(vm, &m, &key, src, true)?;
    m.set_str("loaded", Value::Bool(true), WEC);
    Ok(())
}

// Intl (subset) and locale-sensitive helpers.

use crate::datetime as dt;
use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, Vm};

pub fn setup(vm: &mut Vm) {
    let intl = vm.new_object();
    vm.def_method(&intl, "getCanonicalLocales", 1, get_canonical_locales);
    vm.def_method(&intl, "supportedValuesOf", 1, supported_values_of);
    // DateTimeFormat
    let dtfp = vm.new_object();
    let dtfc = vm.native_ctor("DateTimeFormat", 0, dtf_ctor, &dtfp);
    vm.def_getter(&dtfp, "format", dtf_format_getter);
    vm.def_method(&dtfp, "formatToParts", 1, dtf_format_to_parts);
    vm.def_method(&dtfp, "resolvedOptions", 0, dtf_resolved_options);
    vm.def_method(&dtfc, "supportedLocalesOf", 1, supported_locales_of);
    vm.set_tag(&dtfp, "Intl.DateTimeFormat");
    intl.set_prop(PropKey::from_str("DateTimeFormat"), Value::Obj(dtfc), WC);
    // NumberFormat (basic)
    let nfp = vm.new_object();
    let nfc = vm.native_ctor("NumberFormat", 0, nf_ctor, &nfp);
    vm.def_getter(&nfp, "format", nf_format_getter);
    vm.def_method(&nfp, "resolvedOptions", 0, nf_resolved_options);
    vm.def_method(&nfc, "supportedLocalesOf", 1, supported_locales_of);
    vm.set_tag(&nfp, "Intl.NumberFormat");
    intl.set_prop(PropKey::from_str("NumberFormat"), Value::Obj(nfc), WC);
    // Collator
    let cp = vm.new_object();
    let cc = vm.native_ctor("Collator", 0, collator_ctor, &cp);
    vm.def_getter(&cp, "compare", collator_compare_getter);
    vm.def_method(&cc, "supportedLocalesOf", 1, supported_locales_of);
    vm.set_tag(&cp, "Intl.Collator");
    intl.set_prop(PropKey::from_str("Collator"), Value::Obj(cc), WC);
    // PluralRules
    let pp = vm.new_object();
    let pc = vm.native_ctor("PluralRules", 0, plural_ctor, &pp);
    vm.def_method(&pp, "select", 1, plural_select);
    vm.set_tag(&pp, "Intl.PluralRules");
    intl.set_prop(PropKey::from_str("PluralRules"), Value::Obj(pc), WC);
    // ListFormat
    let lp = vm.new_object();
    let lc = vm.native_ctor("ListFormat", 0, list_ctor, &lp);
    vm.def_method(&lp, "format", 1, list_format);
    vm.set_tag(&lp, "Intl.ListFormat");
    intl.set_prop(PropKey::from_str("ListFormat"), Value::Obj(lc), WC);
    // RelativeTimeFormat
    let rp = vm.new_object();
    let rc = vm.native_ctor("RelativeTimeFormat", 0, rtf_ctor, &rp);
    vm.def_method(&rp, "format", 2, rtf_format);
    vm.set_tag(&rp, "Intl.RelativeTimeFormat");
    intl.set_prop(PropKey::from_str("RelativeTimeFormat"), Value::Obj(rc), WC);
    vm.set_tag(&intl, "Intl");
    vm.def_global("Intl", Value::Obj(intl));
}

pub fn throw_dt_error<T>(vm: &mut Vm, e: dt::DateTimeError) -> JsResult<T> {
    match e.kind {
        dt::ErrorKind::Range => vm.throw_range(e.message),
        dt::ErrorKind::Type => vm.throw_type(e.message),
    }
}

pub fn locale_list(vm: &mut Vm, v: &Value) -> JsResult<Vec<String>> {
    let raw: Vec<String> = match v {
        Value::Undefined => Vec::new(),
        Value::Null => return vm.throw_type("Cannot convert null to object"),
        Value::Str(s) => vec![s.to_rust_string()],
        Value::Obj(o) => {
            let vals = crate::builtins::array::array_like_to_vec(vm, &Value::Obj(o.clone()))?;
            let mut out = Vec::new();
            for x in vals {
                match x {
                    Value::Str(s) => out.push(s.to_rust_string()),
                    Value::Obj(_) => out.push(vm.to_string(&x)?.to_rust_string()),
                    _ => return vm.throw_type("locale must be a string or object"),
                }
            }
            out
        }
        _ => {
            let o = vm.to_object(v)?;
            let vals = crate::builtins::array::array_like_to_vec(vm, &Value::Obj(o))?;
            let mut out = Vec::new();
            for x in vals {
                out.push(vm.to_string(&x)?.to_rust_string());
            }
            out
        }
    };
    match dt::canonicalize_locale_list(&raw) {
        Ok(l) => Ok(l),
        Err(e) => throw_dt_error(vm, e),
    }
}

pub fn read_dtf_options(vm: &mut Vm, v: &Value) -> JsResult<dt::DateTimeFormatOptions> {
    let mut o = dt::DateTimeFormatOptions::new();
    let obj = match v {
        Value::Undefined => return Ok(o),
        Value::Obj(ob) => ob.clone(),
        Value::Null => return vm.throw_type("options must be an object"),
        _ => return vm.throw_type("options must be an object"),
    };
    let order = [
        "localeMatcher",
        "calendar",
        "numberingSystem",
        "hour12",
        "hourCycle",
        "timeZone",
        "weekday",
        "era",
        "year",
        "month",
        "day",
        "dayPeriod",
        "hour",
        "minute",
        "second",
        "fractionalSecondDigits",
        "timeZoneName",
        "formatMatcher",
        "dateStyle",
        "timeStyle",
    ];
    for name in order {
        let val = vm.get_str(&obj, name)?;
        if val.is_undefined() {
            continue;
        }
        match name {
            "hour12" => o.set_hour12(val.truthy()),
            "fractionalSecondDigits" => {
                let n = vm.to_number(&val)?;
                if let Err(e) = o.set_fractional_second_digits(n) {
                    return throw_dt_error(vm, e);
                }
            }
            _ => {
                let s = vm.to_string(&val)?.to_rust_string();
                if let Err(e) = o.set(name, &s) {
                    return throw_dt_error(vm, e);
                }
            }
        }
    }
    Ok(o)
}

fn get_canonical_locales(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let l = locale_list(vm, &a.arg(0))?;
    let v: Vec<Value> = l.into_iter().map(|s| Value::str(&s)).collect();
    Ok(Value::Obj(vm.new_array(v)))
}

fn supported_locales_of(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let l = locale_list(vm, &a.arg(0))?;
    let r = match dt::supported_locales_of(&l) {
        Ok(r) => r,
        Err(e) => return throw_dt_error(vm, e),
    };
    let v: Vec<Value> = r.into_iter().map(|s| Value::str(&s)).collect();
    Ok(Value::Obj(vm.new_array(v)))
}

fn supported_values_of(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let k = vm.to_string(&a.arg(0))?.to_rust_string();
    let vals: Vec<&str> = match k.as_str() {
        "calendar" => vec!["buddhist", "gregory", "iso8601", "japanese", "roc"],
        "collation" => vec!["default"],
        "currency" => vec!["EUR", "GBP", "JPY", "USD"],
        "numberingSystem" => vec!["arab", "latn"],
        "timeZone" => vec!["UTC"],
        "unit" => vec!["byte", "kilometer", "meter", "second"],
        _ => return vm.throw_range(format!("invalid key: {}", k)),
    };
    let v: Vec<Value> = vals.into_iter().map(Value::str).collect();
    Ok(Value::Obj(vm.new_array(v)))
}

struct DtfData(dt::DateTimeFormat);

fn dtf_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let locales = locale_list(vm, &a.arg(0))?;
    let opts = read_dtf_options(vm, &a.arg(1))?;
    let f = match dt::DateTimeFormat::new(&locales, &opts) {
        Ok(f) => f,
        Err(e) => return throw_dt_error(vm, e),
    };
    let nt = a.new_target.clone().or_else(|| Some(a.callee.clone()));
    let fallback = vm.get(a.callee, &vm.intr.key_prototype.clone(), &Value::Obj(a.callee.clone()))?.as_obj().cloned().unwrap();
    let proto = vm.proto_from_nt(&nt, &fallback)?;
    Ok(Value::Obj(Obj::new(Some(proto), ObjKind::Host(Box::new(DtfData(f))))))
}

fn with_dtf<R>(vm: &mut Vm, v: &Value, f: impl FnOnce(&dt::DateTimeFormat) -> R) -> JsResult<R> {
    if let Value::Obj(o) = v {
        if let ObjKind::Host(h) = &o.borrow().kind {
            if let Some(d) = h.downcast_ref::<DtfData>() {
                return Ok(f(&d.0));
            }
        }
    }
    vm.throw_type("Method Intl.DateTimeFormat.prototype.format called on incompatible receiver")
}

fn date_arg(vm: &mut Vm, v: &Value) -> JsResult<f64> {
    match v {
        Value::Undefined => Ok(dt::now_ms()),
        Value::Obj(o) if matches!(o.borrow().kind, ObjKind::Date(_)) => match &o.borrow().kind {
            ObjKind::Date(t) => Ok(*t),
            _ => unreachable!(),
        },
        other => vm.to_number(other),
    }
}

fn dtf_bound_format(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let fmt = a.slot(0);
    let t = date_arg(vm, &a.arg(0))?;
    let r = with_dtf(vm, &fmt, |f| f.format(t))?;
    match r {
        Ok(s) => Ok(Value::str(&s)),
        Err(e) => throw_dt_error(vm, e),
    }
}

fn dtf_format_getter(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    with_dtf(vm, &a.this, |_| ())?;
    let f = vm.native_closure("", 1, dtf_bound_format, vec![a.this.clone()]);
    Ok(Value::Obj(f))
}

fn dtf_format_to_parts(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let t = date_arg(vm, &a.arg(0))?;
    let r = with_dtf(vm, &a.this, |f| f.format_to_parts(t))?;
    match r {
        Ok(parts) => {
            let mut out = Vec::new();
            for p in parts {
                let o = vm.new_object();
                o.set_str("type", Value::str(p.kind), WEC);
                o.set_str("value", Value::str(&p.value), WEC);
                out.push(Value::Obj(o));
            }
            Ok(Value::Obj(vm.new_array(out)))
        }
        Err(e) => throw_dt_error(vm, e),
    }
}

fn dtf_resolved_options(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let r = with_dtf(vm, &a.this, |f| f.resolved_options())?;
    let o = vm.new_object();
    for (k, v) in r {
        let val = match v {
            dt::ResolvedValue::Str(s) => Value::str(&s),
            dt::ResolvedValue::Bool(b) => Value::Bool(b),
            dt::ResolvedValue::Number(n) => Value::Num(n as f64),
        };
        o.set_str(k, val, WEC);
    }
    Ok(Value::Obj(o))
}

// ---------------- numbers ----------------

pub fn group_digits_str(s: &str, sep: &str) -> String {
    let (neg, digits) = if let Some(rest) = s.strip_prefix('-') { (true, rest) } else { (false, s) };
    let mut out = String::new();
    let n = digits.len();
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (n - i) % 3 == 0 {
            out.push_str(sep);
        }
        out.push(c);
    }
    if neg {
        format!("-{}", out)
    } else {
        out
    }
}

#[derive(Clone)]
pub struct NumFmt {
    pub locale: String,
    pub style: String,
    pub currency: Option<String>,
    pub min_int: u32,
    pub min_frac: u32,
    pub max_frac: u32,
    pub grouping: bool,
    pub unit: Option<String>,
}

fn locale_seps(locale: &str) -> (&'static str, &'static str) {
    let lang = locale.split('-').next().unwrap_or("en");
    match lang {
        "de" | "es" | "it" | "nl" | "pt" | "id" | "tr" | "da" => (".", ","),
        "fr" => ("\u{202f}", ","),
        "ru" | "pl" | "cs" | "sv" | "fi" | "nb" | "uk" => ("\u{a0}", ","),
        _ => (",", "."),
    }
}

pub fn format_number(nf: &NumFmt, x: f64) -> String {
    if x.is_nan() {
        return "NaN".to_string();
    }
    let (gsep, dsep) = locale_seps(&nf.locale);
    let neg = x < 0.0 || (x == 0.0 && x.is_sign_negative() && false);
    let mut v = x.abs();
    if nf.style == "percent" {
        v *= 100.0;
    }
    if v.is_infinite() {
        return format!("{}∞", if neg { "-" } else { "" });
    }
    let s = crate::numconv::to_fixed(v, nf.max_frac);
    let (int_part, frac_part) = match s.find('.') {
        Some(p) => (s[..p].to_string(), s[p + 1..].to_string()),
        None => (s.clone(), String::new()),
    };
    let mut frac = frac_part.trim_end_matches('0').to_string();
    while (frac.len() as u32) < nf.min_frac {
        frac.push('0');
    }
    let mut int_s = int_part;
    while (int_s.len() as u32) < nf.min_int {
        int_s.insert(0, '0');
    }
    let grouped = if nf.grouping {
        if nf.locale.starts_with("en-IN") || nf.locale.starts_with("hi") {
            // Indian grouping: last 3 then groups of 2
            let n = int_s.len();
            if n <= 3 {
                int_s.clone()
            } else {
                let (head, tail) = int_s.split_at(n - 3);
                let mut out = String::new();
                let hn = head.len();
                for (i, c) in head.chars().enumerate() {
                    if i > 0 && (hn - i) % 2 == 0 {
                        out.push_str(gsep);
                    }
                    out.push(c);
                }
                format!("{}{}{}", out, gsep, tail)
            }
        } else if nf.locale.starts_with("es") && int_s.len() <= 4 {
            int_s.clone()
        } else {
            group_digits_str(&int_s, gsep)
        }
    } else {
        int_s.clone()
    };
    let mut num = grouped;
    if !frac.is_empty() {
        num.push_str(dsep);
        num.push_str(&frac);
    }
    let sign = if neg && x != 0.0 { "-" } else { "" };
    match nf.style.as_str() {
        "percent" => format!("{}{}%", sign, num),
        "currency" => {
            let cur = nf.currency.clone().unwrap_or_default();
            let sym = match cur.as_str() {
                "USD" => "$",
                "EUR" => "€",
                "GBP" => "£",
                "JPY" => "¥",
                "INR" => "₹",
                "CNY" => "CN¥",
                _ => cur.as_str(),
            }
            .to_string();
            let lang = nf.locale.split('-').next().unwrap_or("en");
            if matches!(lang, "de" | "fr" | "es" | "it" | "nl" | "pt" | "ru" | "pl") {
                format!("{}{}\u{a0}{}", sign, num, sym)
            } else {
                format!("{}{}{}", sign, sym, num)
            }
        }
        "unit" => {
            let u = nf.unit.clone().unwrap_or_default();
            let short = match u.as_str() {
                "kilometer" => "km",
                "meter" => "m",
                "second" => "sec",
                "byte" => "byte",
                "kilogram" => "kg",
                "celsius" => "°C",
                "percent" => "%",
                other => other,
            };
            format!("{}{} {}", sign, num, short)
        }
        _ => format!("{}{}", sign, num),
    }
}

pub fn read_nf_options(vm: &mut Vm, locales: &Value, opts: &Value) -> JsResult<NumFmt> {
    let ll = locale_list(vm, locales)?;
    let locale = ll.first().cloned().unwrap_or_else(|| "en".to_string());
    let mut nf = NumFmt { locale, style: "decimal".into(), currency: None, min_int: 1, min_frac: 0, max_frac: 3, grouping: true, unit: None };
    if let Value::Obj(o) = opts {
        let st = vm.get_str(o, "style")?;
        if !st.is_undefined() {
            nf.style = vm.to_string(&st)?.to_rust_string();
        }
        let cur = vm.get_str(o, "currency")?;
        if !cur.is_undefined() {
            nf.currency = Some(vm.to_string(&cur)?.to_rust_string().to_uppercase());
        }
        if nf.style == "currency" {
            if nf.currency.is_none() {
                return vm.throw_type("Currency code is required with currency style.");
            }
            let c = nf.currency.clone().unwrap();
            let d = if c == "JPY" || c == "KRW" { 0 } else { 2 };
            nf.min_frac = d;
            nf.max_frac = d;
        }
        if nf.style == "percent" {
            nf.max_frac = 0;
        }
        let unit = vm.get_str(o, "unit")?;
        if !unit.is_undefined() {
            nf.unit = Some(vm.to_string(&unit)?.to_rust_string());
        }
        let mi = vm.get_str(o, "minimumIntegerDigits")?;
        if !mi.is_undefined() {
            nf.min_int = vm.to_number(&mi)? as u32;
        }
        let mnf = vm.get_str(o, "minimumFractionDigits")?;
        let mxf = vm.get_str(o, "maximumFractionDigits")?;
        if !mnf.is_undefined() {
            nf.min_frac = vm.to_number(&mnf)? as u32;
            if nf.max_frac < nf.min_frac {
                nf.max_frac = nf.min_frac;
            }
        }
        if !mxf.is_undefined() {
            nf.max_frac = vm.to_number(&mxf)? as u32;
            if nf.min_frac > nf.max_frac {
                nf.min_frac = nf.max_frac;
            }
        }
        let g = vm.get_str(o, "useGrouping")?;
        if !g.is_undefined() {
            nf.grouping = g.truthy();
        }
    }
    Ok(nf)
}

pub fn number_to_locale_string(vm: &mut Vm, x: f64, locales: &Value, opts: &Value) -> JsResult<Value> {
    let nf = read_nf_options(vm, locales, opts)?;
    Ok(Value::str(&format_number(&nf, x)))
}

struct NfData(NumFmt);

fn nf_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let nf = read_nf_options(vm, &a.arg(0), &a.arg(1))?;
    let nt = a.new_target.clone().or_else(|| Some(a.callee.clone()));
    let fallback = vm.get(a.callee, &vm.intr.key_prototype.clone(), &Value::Obj(a.callee.clone()))?.as_obj().cloned().unwrap();
    let proto = vm.proto_from_nt(&nt, &fallback)?;
    Ok(Value::Obj(Obj::new(Some(proto), ObjKind::Host(Box::new(NfData(nf))))))
}

fn get_nf(vm: &mut Vm, v: &Value) -> JsResult<NumFmt> {
    if let Value::Obj(o) = v {
        if let ObjKind::Host(h) = &o.borrow().kind {
            if let Some(d) = h.downcast_ref::<NfData>() {
                return Ok(d.0.clone());
            }
        }
    }
    vm.throw_type("Method Intl.NumberFormat.prototype.format called on incompatible receiver")
}

fn nf_bound_format(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let nf = get_nf(vm, &a.slot(0))?;
    let x = match vm.to_numeric(&a.arg(0))? {
        Value::BigInt(b) => b.to_f64(),
        Value::Num(n) => n,
        _ => f64::NAN,
    };
    Ok(Value::str(&format_number(&nf, x)))
}

fn nf_format_getter(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    get_nf(vm, &a.this)?;
    Ok(Value::Obj(vm.native_closure("", 1, nf_bound_format, vec![a.this.clone()])))
}

fn nf_resolved_options(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let nf = get_nf(vm, &a.this)?;
    let o = vm.new_object();
    o.set_str("locale", Value::str(&nf.locale), WEC);
    o.set_str("numberingSystem", Value::str("latn"), WEC);
    o.set_str("style", Value::str(&nf.style), WEC);
    if let Some(c) = &nf.currency {
        o.set_str("currency", Value::str(c), WEC);
    }
    o.set_str("minimumIntegerDigits", Value::Num(nf.min_int as f64), WEC);
    o.set_str("minimumFractionDigits", Value::Num(nf.min_frac as f64), WEC);
    o.set_str("maximumFractionDigits", Value::Num(nf.max_frac as f64), WEC);
    o.set_str("useGrouping", Value::str("auto"), WEC);
    o.set_str("notation", Value::str("standard"), WEC);
    o.set_str("signDisplay", Value::str("auto"), WEC);
    o.set_str("roundingIncrement", Value::Num(1.0), WEC);
    o.set_str("roundingMode", Value::str("halfExpand"), WEC);
    o.set_str("roundingPriority", Value::str("auto"), WEC);
    o.set_str("trailingZeroDisplay", Value::str("auto"), WEC);
    Ok(Value::Obj(o))
}

// ---------------- Collator ----------------

struct CollatorData {
    sensitivity: u8,
    numeric: bool,
}

fn collator_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let _ = locale_list(vm, &a.arg(0))?;
    let mut sens = 3u8;
    let mut numeric = false;
    if let Value::Obj(o) = a.arg(1) {
        let s = vm.get_str(&o, "sensitivity")?;
        if let Value::Str(x) = s {
            sens = match x.to_rust_string().as_str() {
                "base" => 0,
                "accent" => 1,
                "case" => 2,
                _ => 3,
            };
        }
        numeric = vm.get_str(&o, "numeric")?.truthy();
    }
    let nt = a.new_target.clone().or_else(|| Some(a.callee.clone()));
    let fallback = vm.get(a.callee, &vm.intr.key_prototype.clone(), &Value::Obj(a.callee.clone()))?.as_obj().cloned().unwrap();
    let proto = vm.proto_from_nt(&nt, &fallback)?;
    Ok(Value::Obj(Obj::new(Some(proto), ObjKind::Host(Box::new(CollatorData { sensitivity: sens, numeric })))))
}

fn collator_compare_fn(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (sens, numeric) = match &a.slot(0) {
        Value::Obj(o) => match &o.borrow().kind {
            ObjKind::Host(h) => match h.downcast_ref::<CollatorData>() {
                Some(c) => (c.sensitivity, c.numeric),
                None => (3, false),
            },
            _ => (3, false),
        },
        _ => (3, false),
    };
    let x = vm.to_string(&a.arg(0))?;
    let y = vm.to_string(&a.arg(1))?;
    if numeric {
        let xs = x.to_rust_string();
        let ys = y.to_rust_string();
        if let (Ok(xn), Ok(yn)) = (xs.parse::<f64>(), ys.parse::<f64>()) {
            return Ok(Value::Num(if xn < yn { -1.0 } else if xn > yn { 1.0 } else { 0.0 }));
        }
    }
    Ok(Value::Num(crate::builtins::string::locale_cmp(x.units(), y.units(), sens) as f64))
}

fn collator_compare_getter(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    Ok(Value::Obj(vm.native_closure("", 2, collator_compare_fn, vec![a.this.clone()])))
}

