205	pub fn norm_encoding(s: &str) -> Option<&'static str> {
206	    Some(match s.to_ascii_lowercase().as_str() {
207	        "utf8" | "utf-8" => "utf8",
208	        "hex" => "hex",
209	        "base64" => "base64",
210	        "base64url" => "base64url",
211	        "latin1" | "binary" => "latin1",
212	        "ascii" => "ascii",
213	        "ucs2" | "ucs-2" | "utf16le" | "utf-16le" => "utf16le",
214	        _ => return None,
215	    })
216	}
