669	fn buf_fill(vm: &mut Vm, a: &Args) -> JsResult<Value> {
670	    let (o, b) = this_bytes(vm, &a.this)?;
671	    let mut encv = Value::Undefined;
672	    let (s, e) = match a.arg(1) {
673	        Value::Str(_) => {
674	            encv = a.arg(1);
675	            (0, b.len())
676	        }
677	        v => {
678	            let s = clamp_idx(vm, &v, b.len(), 0)?;
679	            match a.arg(2) {
680	                Value::Str(_) => {
681	                    encv = a.arg(2);
682	                    (s, b.len())
683	                }
684	                v2 => {
685	                    encv = a.arg(3);
686	                    (s, clamp_idx(vm, &v2, b.len(), b.len())?)
687	                }
688	            }
689	        }
690	    };
691	    let pattern = match &a.arg(0) {
692	        Value::Str(st) => {
693	            let en = encoding_arg(vm, &encv)?;
694	            encode_string(st, en)
695	        }
696	        Value::Num(x) => vec![crate::builtins::number::to_uint32(*x) as u8],
697	        Value::Bool(x) => vec![*x as u8],
698	        other => bytes_of(vm, other)?,
699	    };
700	    if !pattern.is_empty() && s < e {
701	        let data: Vec<u8> = (0..e - s).map(|i| pattern[i % pattern.len()]).collect();
702	        write_bytes(&o, s, &data);
703	    }
704	    Ok(a.this.clone())
705	}
