756	fn buf_read_num(vm: &mut Vm, a: &Args) -> JsResult<Value> {
757	    let kind = a.slot(0).as_num().unwrap() as u8;
758	    let size = a.slot(1).as_num().unwrap() as usize;
759	    let little = a.slot(2).truthy();
760	    let (_, b) = this_bytes(vm, &a.this)?;
761	    let off = offset_arg(vm, &a.arg(0), b.len(), size)?;
762	    let tk = match (kind, size) {
763	        (0, 1) => TAKind::Uint8,
764	        (1, 1) => TAKind::Int8,
765	        (0, 2) => TAKind::Uint16,
766	        (1, 2) => TAKind::Int16,
767	        (0, 4) => TAKind::Uint32,
768	        (1, 4) => TAKind::Int32,
769	        (2, _) => TAKind::Float32,
770	        (3, _) => TAKind::Float64,
771	        (4, _) => TAKind::BigInt64,
772	        _ => TAKind::BigUint64,
773	    };
774	    Ok(crate::builtins::typedarray::read_elem(&b, off, tk, little))
775	}
