817	fn buf_read_var(vm: &mut Vm, a: &Args) -> JsResult<Value> {
818	    let signed = a.slot(0).truthy();
819	    let little = a.slot(1).truthy();
820	    let (_, b) = this_bytes(vm, &a.this)?;
821	    let bl = vm.to_number(&a.arg(1))? as usize;
822	    let off = offset_arg(vm, &a.arg(0), b.len(), bl)?;
823	    let bytes = &b[off..off + bl];
824	    let mut v: u64 = 0;
825	    if little {
826	        for (i, x) in bytes.iter().enumerate() {
827	            v |= (*x as u64) << (8 * i);
828	        }
829	    } else {
830	        for x in bytes {
831	            v = (v << 8) | *x as u64;
832	        }
833	    }
834	    let r = if signed && bl < 8 && v & (1 << (8 * bl - 1)) != 0 { v as i64 - (1i64 << (8 * bl)) } else { v as i64 };
835	    Ok(Value::Num(r as f64))
836	}
837	
838	fn buf_write_var(vm: &mut Vm, a: &Args) -> JsResult<Value> {
839	    let little = a.slot(1).truthy();
840	    let (o, b) = this_bytes(vm, &a.this)?;
841	    let n = vm.to_number(&a.arg(0))?;
842	    let bl = vm.to_number(&a.arg(2))? as usize;
843	    let off = offset_arg(vm, &a.arg(1), b.len(), bl)?;
844	    let v = n as i64 as u64;
845	    let mut tmp = vec![0u8; bl];
846	    for i in 0..bl {
847	        let byte = ((v >> (8 * i)) & 0xff) as u8;
848	        if little {
849	            tmp[i] = byte;
850	        } else {
851	            tmp[bl - 1 - i] = byte;
852	        }
853	    }
854	    write_bytes(&o, off, &tmp);
855	    Ok(Value::Num((off + bl) as f64))
856	}
857	
858	// ---------------- string_decoder ----------------
859	
860	pub fn create_string_decoder_module(vm: &mut Vm) -> Value {
861	    let proto = vm.new_object();
862	    let ctor = vm.native_ctor("StringDecoder", 1, sd_ctor, &proto);
863	    vm.def_method(&proto, "write", 1, sd_write);
864	    vm.def_method(&proto, "end", 1, sd_end);
865	    let m = vm.new_object();
866	    m.set_str("StringDecoder", Value::Obj(ctor), WEC);
867	    Value::Obj(m)
868	}
869	
870	struct SdState {
871	    encoding: &'static str,
872	    pending: RefCell<Vec<u8>>,
873	}
874	
875	fn sd_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
876	    let e = encoding_arg(vm, &a.arg(0))?;
877	    let fallback = vm.get(a.callee, &vm.intr.key_prototype.clone(), &Value::Obj(a.callee.clone()))?.as_obj().cloned().unwrap();
878	    let p = vm.proto_from_nt(&a.new_target, &fallback)?;
879	    let o = Obj::new(Some(p), ObjKind::Host(Box::new(SdState { encoding: e, pending: RefCell::new(Vec::new()) })));
880	    o.set_prop(PropKey::from_str("encoding"), Value::str(e), WEC);
881	    Ok(Value::Obj(o))
882	}
883	
884	fn utf8_complete_prefix(b: &[u8]) -> usize {
885	    // length of the longest prefix that does not end in an incomplete sequence
886	    let n = b.len();
887	    let mut i = n;
888	    let mut back = 0;
889	    while i > 0 && back < 4 {
890	        i -= 1;
891	        back += 1;
892	        let c = b[i];
893	        if c & 0xC0 == 0x80 {
894	            continue;
895	        }
896	        let need = if c & 0x80 == 0 {
897	            1
898	        } else if c & 0xE0 == 0xC0 {
899	            2
900	        } else if c & 0xF0 == 0xE0 {
901	            3
902	        } else if c & 0xF8 == 0xF0 {
903	            4
904	        } else {
905	            1
906	        };
907	        return if n - i >= need { n } else { i };
908	    }
909	    n
910	}
911	
912	fn sd_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
913	    let data = bytes_of(vm, &a.arg(0))?;
914	    let st = match &a.this {
915	        Value::Obj(o) => o.clone(),
916	        _ => return vm.throw_type("incompatible receiver"),
917	    };
918	    let b = st.borrow();
919	    let s = match &b.kind {
920	        ObjKind::Host(h) => h.downcast_ref::<SdState>().unwrap(),
921	        _ => return Ok(Value::str("")),
922	    };
923	    let mut p = s.pending.borrow_mut();
924	    p.extend(data);
925	    let out = match s.encoding {
926	        "utf8" => {
927	            let k = utf8_complete_prefix(&p);
928	            let r = decode_bytes(&p[..k], "utf8");
929	            p.drain(..k);
930	            r
931	        }
932	        "utf16le" => {
933	            let k = p.len() / 2 * 2;
934	            let r = decode_bytes(&p[..k], "utf16le");
935	            p.drain(..k);
936	            r
937	        }
938	        "base64" => {
939	            let k = p.len() / 3 * 3;
940	            let r = decode_bytes(&p[..k], "base64");
941	            p.drain(..k);
942	            r
943	        }
944	        e => {
945	            let r = decode_bytes(&p, e);
946	            p.clear();
947	            r
948	        }
949	    };
950	    Ok(Value::Str(out))
951	}
952	
953	fn sd_end(vm: &mut Vm, a: &Args) -> JsResult<Value> {
954	    let mut prefix = JsStr::empty();
955	    if !a.arg(0).is_undefined() {
956	        if let Value::Str(s) = sd_write(vm, a)? {
957	            prefix = s;
958	        }
959	    }
960	    let st = match &a.this {
961	        Value::Obj(o) => o.clone(),
962	        _ => return vm.throw_type("incompatible receiver"),
963	    };
964	    let b = st.borrow();
965	    let rest = match &b.kind {
966	        ObjKind::Host(h) => {
967	            let s = h.downcast_ref::<SdState>().unwrap();
968	            let mut p = s.pending.borrow_mut();
969	            let r = if p.is_empty() { JsStr::empty() } else { decode_bytes(&p, s.encoding) };
970	            p.clear();
971	            r
972	        }
973	        _ => JsStr::empty(),
974	    };
975	    Ok(Value::Str(JsStr::concat(&prefix, &rest)))
976	}
977	
978	pub fn _unused(_: Rc<()>) {}
979

}

fn emit_error_tick(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    emit(vm, &a.slot(0), "error", &[a.slot(1)])?;
    Ok(Value::Undefined)
}

fn emit_close_tick(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    emit(vm, &a.slot(0), "close", &[])?;
    Ok(Value::Undefined)
}

/// open the stream's file (nodeFs.openSync(path, flags, mode)); on failure fd = null and the
/// error is emitted on the next tick. Returns false when opening failed.
fn stream_open(vm: &mut Vm, this: &Value, path: &Value, o: &Value) -> JsResult<bool> {
    let fd = getp(vm, o, "fd")?;
    if !fd.is_nullish() {
        setp(vm, this, "fd", fd)?;
        return Ok(true);
    }
    let flags = getp(vm, this, "flags")?;
    getp(vm, o, "mode")?;
    match open_impl(vm, path, &flags) {
        Ok(n) => {
            setp(vm, this, "fd", n)?;
            Ok(true)
        }
        Err(e) => {
            setp(vm, this, "fd", Value::Null)?;
            let t = closure(vm, "", 0, emit_error_tick, vec![this.clone(), e]);
            next_tick(vm, t)?;
            Ok(false)
        }
    }
}

framed!(read_stream_ctor, ["ReadStream"], read_stream_ctor_);

fn read_stream_ctor_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = instance(vm, a, |c| c.read_stream.clone())?;
    let this = Value::Obj(o.clone());
    let path = a.arg(0);
    let opts = normalize_stream_opts(vm, &a.arg(1))?;
    let enc = getp(vm, &opts, "encoding")?;
    let hwm = getp(vm, &opts, "highWaterMark")?;
    let ropts = Value::Obj(vm.obj_from(vec![("encoding", enc), ("highWaterMark", hwm.clone())]));
    readable_init(vm, &o, &ropts)?;
    setp(vm, &this, "path", path.clone())?;
    let flags = getp(vm, &opts, "flags")?;
    setp(vm, &this, "flags", if flags.truthy() { flags } else { Value::str("r") })?;
    setp(vm, &this, "bytesRead", Value::Num(0.0))?;
    let start = getp(vm, &opts, "start")?;
    setp(vm, &this, "pos", if start.truthy() { start } else { Value::Num(0.0) })?;
    let end = getp(vm, &opts, "end")?;
    setp(vm, &this, "_end", if end.is_nullish() { Value::Num(f64::INFINITY) } else { end })?;
    setp(vm, &this, "_chunk", if hwm.truthy() { hwm } else { Value::Num(65536.0) })?;
    let ac = getp(vm, &opts, "autoClose")?;
    setp(vm, &this, "_autoClose", Value::Bool(!matches!(ac, Value::Bool(false))))?;
    let fd = getp(vm, &opts, "fd")?;
    setp(vm, &this, "_ownFd", Value::Bool(fd.is_nullish()))?;
    if !stream_open(vm, &this, &path, &opts)? {
        return Ok(this);
    }
    let t = closure(vm, "", 0, read_stream_open_tick, vec![this.clone()]);
    next_tick(vm, t)?;
    Ok(this)
}

framed!(read_stream_open_tick, ["<anonymous>"], read_stream_open_tick_);

fn read_stream_open_tick_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    let fd = getp(vm, &this, "fd")?;
    if fd.is_nullish() {
        return Ok(Value::Undefined);
    }
    emit(vm, &this, "open", &[fd])?;
    emit(vm, &this, "ready", &[])?;
    call_method(vm, &this, "_pump", &[])?;
    Ok(Value::Undefined)
}

framed!(read_stream_pump, ["_pump"], read_stream_pump_);

fn read_stream_pump_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let r = (|| -> JsResult<()> {
        loop {
            // JS semantics on purpose: `start`/`end` options are used as given
            let pos = getp(vm, &this, "pos")?;
            let end = getp(vm, &this, "_end")?;
            if !vm.op_compare(crate::bytecode::Op::Le, &pos, &end)? {
                break;
            }
            let chunk = getp(vm, &this, "_chunk")?;
            let want = if Value::strict_eq(&end, &Value::Num(f64::INFINITY)) {
                chunk
            } else {
                let diff = vm.op_arith(crate::bytecode::Op::Sub, &end, &pos)?;
                let rest = vm.op_add(&diff, &Value::Num(1.0))?;
                let a = vm.to_number(&chunk)?;
                let b = vm.to_number(&rest)?;
                Value::Num(if a.is_nan() || b.is_nan() { f64::NAN } else { a.min(b) })
            };
            let fd = getp(vm, &this, "fd")?;
            let len = len_arg(vm, &want)?;
            let bytes = pread(vm, &fd, len, pos_arg(&pos))?;
            if bytes.is_empty() {
                break;
            }
            let n = bytes.len() as f64;
            let p = getp(vm, &this, "pos")?;
            let p = vm.op_add(&p, &Value::Num(n))?;
            setp(vm, &this, "pos", p)?;
            let br = getp(vm, &this, "bytesRead")?;
            let br = vm.op_add(&br, &Value::Num(n))?;
            setp(vm, &this, "bytesRead", br)?;
            let buf = new_buffer(vm, bytes)?;
            call_method(vm, &this, "push", &[buf])?;
        }
        call_method(vm, &this, "push", &[Value::Null])?;
        call_method(vm, &this, "_closeStream", &[Value::Null])?;
        Ok(())
    })();
    if let Err(e) = r {
        call_method(vm, &this, "_closeStream", &[e])?;
    }
    Ok(Value::Undefined)
}

fn read_stream_close_stream(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let err = a.arg(0);
    let own = getp(vm, &this, "_ownFd")?.truthy();
    if own && getp(vm, &this, "_autoClose")?.truthy() {
        let fd = getp(vm, &this, "fd")?;
        if !fd.is_nullish() {
            if let Ok(n) = to_num(vm, &fd) {
                close_fd_num(n);
            }
        }
    }
    setp(vm, &this, "fd", Value::Null)?;
    if err.truthy() {
        let t = closure(vm, "", 0, emit_error_tick, vec![this.clone(), err]);
        next_tick(vm, t)?;
    }
    let t = closure(vm, "", 0, emit_close_tick, vec![this]);
    next_tick(vm, t)?;
    Ok(Value::Undefined)
}

fn read_stream_close(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let cb = a.arg(0);
    if cb.truthy() {
        call_method(vm, &this, "once", &[Value::str("close"), cb])?;
    }
    let fd = getp(vm, &this, "fd")?;
    if !fd.is_nullish() && getp(vm, &this, "_ownFd")?.truthy() {
        if let Ok(n) = to_num(vm, &fd) {
            close_fd_num(n);
        }
        setp(vm, &this, "fd", Value::Null)?;
    }
    Ok(Value::Undefined)
}

framed!(write_stream_ctor, ["WriteStream"], write_stream_ctor_);

fn write_stream_ctor_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = instance(vm, a, |c| c.write_stream.clone())?;
    let this = Value::Obj(o.clone());
    let path = a.arg(0);
    let opts = normalize_stream_opts(vm, &a.arg(1))?;
    let empty = Value::Obj(vm.new_object());
    writable_init(vm, &o, &empty)?;
    setp(vm, &this, "path", path.clone())?;
    let flags = getp(vm, &opts, "flags")?;
    setp(vm, &this, "flags", if flags.truthy() { flags } else { Value::str("w") })?;
    setp(vm, &this, "bytesWritten", Value::Num(0.0))?;
    let start = getp(vm, &opts, "start")?;
    setp(vm, &this, "pos", start)?;
    let enc = getp(vm, &opts, "encoding")?;
    setp(vm, &this, "_encoding", if enc.truthy() { enc } else { Value::str("utf8") })?;
    let ac = getp(vm, &opts, "autoClose")?;
    setp(vm, &this, "_autoClose", Value::Bool(!matches!(ac, Value::Bool(false))))?;
    let fd = getp(vm, &opts, "fd")?;
    setp(vm, &this, "_ownFd", Value::Bool(fd.is_nullish()))?;
    if !stream_open(vm, &this, &path, &opts)? {
        return Ok(this);
    }
    let onfinish = closure(vm, "", 0, write_stream_on_finish, vec![this.clone()]);
    call_method(vm, &this, "on", &[Value::str("finish"), onfinish])?;
    let t = closure(vm, "", 0, write_stream_open_tick, vec![this.clone()]);
    next_tick(vm, t)?;
    Ok(this)
}

fn write_stream_on_finish(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    if getp(vm, &this, "_autoClose")?.truthy() {
        let t = closure(vm, "", 0, emit_close_tick, vec![this]);
        next_tick(vm, t)?;
    }
    Ok(Value::Undefined)
}

fn write_stream_open_tick(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    let fd = getp(vm, &this, "fd")?;
    if fd.is_nullish() {
        return Ok(Value::Undefined);
    }
    emit(vm, &this, "open", &[fd])?;
    emit(vm, &this, "ready", &[])?;
    Ok(Value::Undefined)
}

fn write_stream_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let (chunk, enc, cb) = (a.arg(0), a.arg(1), a.arg(2));
    let r = (|| -> JsResult<()> {
        let e = if enc.truthy() { enc.clone() } else { getp(vm, &this, "_encoding")? };
        let buf = to_buffer(vm, &chunk, &e)?;
        let posv = getp(vm, &this, "pos")?;
        let pos = pos_arg(&posv);
        let fd = getp(vm, &this, "fd")?;
        let n = pwrite(vm, &fd, &buf, pos)? as f64;
        let bw = getp(vm, &this, "bytesWritten")?;
        let bw = vm.op_add(&bw, &Value::Num(n))?;
        setp(vm, &this, "bytesWritten", bw)?;
        if !posv.is_nullish() {
            let p = getp(vm, &this, "pos")?;
            let p = vm.op_add(&p, &Value::Num(n))?;
            setp(vm, &this, "pos", p)?;
        }
        vm.call(&cb, Value::Undefined, &[])?;
        Ok(())
    })();
    if let Err(e) = r {
        vm.call(&cb, Value::Undefined, &[e])?;
    }
    Ok(Value::Undefined)
}

fn write_stream_final(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let cb = a.arg(0);
    let own = getp(vm, &this, "_ownFd")?.truthy() && getp(vm, &this, "_autoClose")?.truthy();
    let fd = getp(vm, &this, "fd")?;
    if own && !fd.is_nullish() {
        let r = (|| -> JsResult<()> {
            let n = vm.to_number(&fd)?;
            close_fd_num(n);
            setp(vm, &this, "fd", Value::Null)?;
            vm.call(&cb, Value::Undefined, &[])?;
            Ok(())
        })();
        if let Err(e) = r {
            vm.call(&cb, Value::Undefined, &[e])?;
        }
    } else {
        vm.call(&cb, Value::Undefined, &[])?;
    }
    Ok(Value::Undefined)
}

fn write_stream_close(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let cb = a.arg(0);
    if cb.truthy() {
        call_method(vm, &this, "once", &[Value::str("close"), cb])?;
    }
    call_method(vm, &this, "end", &[])?;
    Ok(Value::Undefined)
}

