fn calendar_eras(info: &LocaleInfo) -> (&'static [&'static str; 3], &'static [[&'static str; 2]; 3]) {
    let key = if std::ptr::eq(info, &LOCALE_ZH_HANT) { "zh-TW" } else { info.lang };
    let row = CALENDAR_ERAS
        .iter()
        .find(|(l, _, _)| *l == key)
        .unwrap_or(&CALENDAR_ERAS[0]);
    (&row.1, &row.2)
}

