// dump sources of all functions reachable from a module's exports
const name = process.argv[2];
const m = require(name);
const seen = new Set();
function dump(path, v, depth) {
  if (depth > 3) return;
  if (v === null || (typeof v !== 'object' && typeof v !== 'function')) return;
  if (seen.has(v)) { console.log('// ' + path + ' -> (seen)'); return; }
  seen.add(v);
  if (typeof v === 'function') {
    console.log('// ===== ' + path);
    console.log(String(v));
  }
  for (const k of Object.getOwnPropertyNames(v)) {
    if (k === 'prototype' && typeof v === 'function') {
      const p = v.prototype;
      if (p) {
        for (const pk of Object.getOwnPropertyNames(p)) {
          if (pk === 'constructor') continue;
          const d = Object.getOwnPropertyDescriptor(p, pk);
          if (d.get) { console.log('// ===== ' + path + '.prototype.get ' + pk); console.log(String(d.get)); }
          if (d.set) { console.log('// ===== ' + path + '.prototype.set ' + pk); console.log(String(d.set)); }
          if (typeof d.value === 'function' && !String(v).includes(String(d.value))) dump(path + '.prototype.' + pk, d.value, depth + 1);
        }
      }
      continue;
    }
    let d;
    try { d = Object.getOwnPropertyDescriptor(v, k); } catch (e) { continue; }
    if (!d) continue;
    if (d.get) { console.log('// ===== ' + path + '.get ' + k); console.log(String(d.get)); continue; }
    if (k === 'length' || k === 'name') continue;
    dump(path + '.' + k, d.value, depth + 1);
  }
}
dump(name, m, 0);

