    moveCursor(dx, dy) { return this._push(() => {}); }
    commit() {
      for (const op of this._ops) op();
      this._ops = [];
      return Promise.resolve();
    }
    rollback() {
      this._ops = [];
      return Promise.resolve();
    }
  }

// The runtime: host state, event loop, CLI entry.

pub mod buffer;
