210	    pub fn enter(&mut self) -> JsResult<()> {
211	        if self.depth + self.depth_offset >= MAX_DEPTH {
212	            return self.throw_range("Maximum call stack size exceeded");
213	        }
214	        self.depth += 1;
215	        Ok(())
216	    }
217	
218	    pub fn call_obj(&mut self, o: &Obj, this: Value, args: &[Value]) -> JsResult<Value> {
219	        enum K {
220	            Closure(Rc<FunctionCode>, Option<Env>, Option<Obj>, bool),
221	            Native(NativeFn),
222	            Bound(Obj, Value, Vec<Value>),
223	            Proxy,
224	            NotCallable,
225	        }
226	        let k = {
227	            let b = o.borrow();
228	            match &b.kind {
229	                ObjKind::Closure(c) => K::Closure(c.code.clone(), c.env.clone(), c.home_object.clone(), c.is_class_ctor),
230	                ObjKind::Native(n) => K::Native(n.f),
231	                ObjKind::Bound(bf) => K::Bound(bf.target.clone(), bf.this.clone(), bf.args.clone()),
232	                ObjKind::Proxy(p) if p.callable => K::Proxy,
233	                _ => K::NotCallable,
234	            }
235	        };
236	        match k {
237	            K::Closure(code, env, home, is_class) => {
238	                if is_class {
239	                    return self.throw_type("Class constructor cannot be invoked without 'new'");
240	                }
241	                self.call_closure(o, code, env, home, this, args, Value::Undefined)
242	            }
243	            K::Native(f) => {
244	                self.enter()?;
245	                let r = f(self, &Args { this, args, callee: o, new_target: None });
246	                self.depth -= 1;
247	                r
248	            }
249	            K::Bound(target, bthis, bargs) => {
250	                let mut all = bargs;
251	                all.extend_from_slice(args);
252	                self.enter()?;
253	                let r = self.call_obj(&target, bthis, &all);
254	                self.depth -= 1;
255	                r
256	            }
257	            K::Proxy => crate::builtins::proxy::proxy_call(self, o, this, args),
258	            K::NotCallable => self.throw_type("object is not a function"),
259	        }
260	    }
261	
262	    #[allow(clippy::too_many_arguments)]
263	    pub fn call_closure(
264	        &mut self,
265	        f: &Obj,
266	        code: Rc<FunctionCode>,
267	        env: Option<Env>,
268	        home: Option<Obj>,
269	        this: Value,
270	        args: &[Value],
271	        new_target: Value,
272	    ) -> JsResult<Value> {
273	        let this = if code.strict || code.is_arrow {
274	            this
275	        } else {
276	            match this {
277	                Value::Undefined | Value::Null => Value::Obj(self.global.clone()),
278	                Value::Obj(_) => this,
279	                other => Value::Obj(self.to_object(&other)?),
280	            }
281	        };
282	        let mut frame = Frame::new(code.clone(), env, this, Some(f.clone()), new_target, args.to_vec(), home);
283	        if code.is_generator {
284	            return self.start_generator(f, frame);
285	        }
286	        if code.is_async {
287	            return Ok(self.start_async(frame));
288	        }
289	        self.enter()?;
290	        self.trace.push(TraceEntry { name: trace_name(&code) });
291	        let r = self.run_frame(&mut frame);
292	        self.trace.pop();
293	        self.depth -= 1;
294	        match r {
295	            Ok(Completion::Return(v)) => Ok(v),
296	            Ok(_) => Ok(Value::Undefined),
297	            Err(e) => Err(e),
298	        }
299	    }
300	
301	    pub fn construct(&mut self, f: &Value, args: &[Value], new_target: Option<&Value>) -> JsResult<Value> {
302	        let fo = match f {
303	            Value::Obj(o) if o.is_constructor() => o.clone(),
304	            _ => {
305	                let d = self.describe_for_new(f);
306	                return self.throw_type(format!("{} is not a constructor", d));
307	            }
308	        };
309	        let nt = new_target.cloned().unwrap_or_else(|| f.clone());
310	        self.construct_obj(&fo, args, nt)
311	    }
312	
313	    pub fn describe_for_new(&self, v: &Value) -> String {
314	        self.describe_for_call(v)
315	    }
316	
317	    pub fn construct_obj(&mut self, fo: &Obj, args: &[Value], nt: Value) -> JsResult<Value> {
318	        enum K {
319	            Closure(Rc<FunctionCode>, Option<Env>, Option<Obj>, bool, Option<Rc<Vec<ClassField>>>),
320	            Native(NativeFn),
321	            Bound(Obj, Vec<Value>),
322	            Proxy,
323	        }
324	        let k = {
325	            let b = fo.borrow();
326	            match &b.kind {
327	                ObjKind::Closure(c) => K::Closure(c.code.clone(), c.env.clone(), c.home_object.clone(), c.derived, c.fields.clone()),
328	                ObjKind::Native(n) => K::Native(n.f),
329	                ObjKind::Bound(bf) => K::Bound(bf.target.clone(), bf.args.clone()),
330	                ObjKind::Proxy(_) => K::Proxy,
331	                _ => return self.throw_type("object is not a constructor"),
332	            }
333	        };
334	        match k {
335	            K::Closure(code, env, home, derived, fields) => {
336	                let this = if derived {
337	                    Value::Empty
338	                } else {
339	                    let proto = self.get_prototype_from_ctor(&nt, ProtoKind::Object)?;
340	                    let obj = Obj::new(Some(proto), ObjKind::Ordinary);
341	                    if let Some(fl) = &fields {
342	                        self.init_fields(&obj, fl)?;
343	                    }
344	                    Value::Obj(obj)
345	                };
346	                let mut frame = Frame::new(code.clone(), env, this.clone(), Some(fo.clone()), nt, args.to_vec(), home);
347	                self.enter()?;
348	                self.trace.push(TraceEntry { name: trace_name(&code) });
349	                let r = self.run_frame(&mut frame);
350	                self.trace.pop();
351	                self.depth -= 1;
352	                let v = match r? {
353	                    Completion::Return(v) => v,
354	                    _ => Value::Undefined,
355	                };
356	                if let Value::Obj(_) = v {
357	                    return Ok(v);
358	                }
359	                if derived {
360	                    if !v.is_undefined() {
361	                        return self.throw_type("Derived constructors may only return object or undefined");
362	                    }
363	                    if frame.this.is_empty() {
364	                        return self.throw_ref("must call super constructor before accessing 'this' or returning from derived constructor");
365	                    }
366	                    return Ok(frame.this.clone());
367	                }
368	                Ok(this)
369	            }
370	            K::Native(f) => {
371	                self.enter()?;
372	                let nt_obj = nt.as_obj().cloned();
373	                let r = f(self, &Args { this: Value::Undefined, args, callee: fo, new_target: nt_obj });
374	                self.depth -= 1;
375	                r
376	            }
377	            K::Bound(target, bargs) => {
378	                let mut all = bargs;
379	                all.extend_from_slice(args);
380	                let nt = if let Value::Obj(n) = &nt {
381	                    if n.ptr_eq(fo) {
382	                        Value::Obj(target.clone())
383	                    } else {
384	                        nt
385	                    }
386	                } else {
387	                    nt
388	                };
389	                self.construct_obj(&target, &all, nt)
390	            }
391	            K::Proxy => crate::builtins::proxy::proxy_construct(self, fo, args, nt),
392	        }
393	    }
394	
395	    pub fn init_fields(&mut self, obj: &Obj, fields: &Rc<Vec<ClassField>>) -> JsResult<()> {
396	        // private methods first
397	        for f in fields.iter() {
398	            if let FieldKey::PrivateMethod(sym, prop) = &f.key {
399	                let k = PropKey::Sym(sym.clone());
400	                if obj.borrow().props.contains(&k) {
401	                    return self.throw_type("Cannot initialize private methods of class twice on the same object");
402	                }
403	                obj.borrow_mut().props.insert(k, prop.clone());
404	            }
405	        }
406	        for f in fields.iter() {
407	            let v = match &f.init {
408	                Some(init) => self.call_obj(init, Value::Obj(obj.clone()), &[])?,
409	                None => Value::Undefined,
410	            };
411	            match &f.key {
412	                FieldKey::Key(k) => {
413	                    if !self.create_data_property(obj, k.clone(), v)? {
414	                        return self.throw_type(format!("Cannot redefine property: {}", k.to_display()));
415	                    }
416	                }
417	                FieldKey::Private(sym) => {
418	                    let k = PropKey::Sym(sym.clone());
419	                    if obj.borrow().props.contains(&k) {
420	                        return self.throw_type(format!(
421	                            "Cannot initialize {} twice on the same object",
422	                            sym.0.description.as_ref().map(|d| d.to_rust_string()).unwrap_or_default()
423	                        ));
424	                    }
425	                    obj.borrow_mut().props.insert(k, Prop::Data { value: v, flags: WRITABLE });
426	                }
427	                FieldKey::PrivateMethod(..) => {}
428	            }
429	        }
430	        Ok(())
431	    }
