551	    pub fn iter_result(&mut self, value: Value, done: bool) -> Value {
552	        let o = Obj::new(Some(self.intr.object_proto.clone()), ObjKind::Ordinary);
553	        {
554	            let mut b = o.borrow_mut();
555	            b.props.insert(self.intr.key_value.clone(), Prop::Data { value, flags: WEC });
556	            b.props.insert(self.intr.key_done.clone(), Prop::Data { value: Value::Bool(done), flags: WEC });
557	        }
558	        Value::Obj(o)
559	    }
