561	    fn start_async(&mut self, frame: Frame) -> Value {
562	        let cap = self.new_promise_capability_intrinsic();
563	        let co = Obj::new(None, ObjKind::AsyncFn(Box::new(AsyncFnData { frame: Some(Box::new(frame)), capability: cap.clone() })));
564	        self.async_step(&co, ResumeMode::Next, Value::Undefined, true);
565	        cap.promise
566	    }
