1884	    pub fn run_one_job(&mut self) -> bool {
1885	        match self.jobs.pop_front() {
1886	            Some(j) => {
1887	                self.run_job(j);
1888	                true
1889	            }
1890	            None => false,
1891	        }
1892	    }
