1965	    pub fn set_function_name(&mut self, f: &Obj, key: &PropKey, prefix: Option<&str>) {
1966	        let base = match key {
1967	            PropKey::Str(s) => s.to_rust_string(),
1968	            PropKey::Sym(s) => match &s.0.description {
1969	                Some(d) => format!("[{}]", d),
1970	                None => String::new(),
1971	            },
1972	        };
1973	        let name = match prefix {
1974	            Some(p) => format!("{} {}", p, base),
1975	            None => base,
1976	        };
1977	        // only set if the function has no own name already (anonymous)
1978	        let has_name = matches!(f.get_own_data(&self.intr.key_name), Some(Value::Str(ref s)) if !s.is_empty());
1979	        if !has_name || prefix.is_some() {
1980	            f.borrow_mut().props.insert(self.intr.key_name.clone(), Prop::Data { value: Value::str(&name), flags: CONFIGURABLE });
1981	        }
1982	    }
