2000	    pub fn create_arguments(&mut self, frame: &Frame) -> Obj {
2001	        let o = Obj::with_class(Some(self.intr.object_proto.clone()), ObjKind::Arguments(Box::new(ArgumentsData { mapped: Vec::new() })), "Arguments");
