2141	    fn create_class(&mut self, frame: &Frame, ctor_code: Rc<FunctionCode>, heritage: Option<Value>) -> JsResult<(Obj, Obj)> {
2142	        let (proto_parent, ctor_parent) = match &heritage {
2143	            None => (Some(self.intr.object_proto.clone()), self.intr.function_proto.clone()),
2144	            Some(Value::Null) => (None, self.intr.function_proto.clone()),
2145	            Some(h) => {
