2147	                    Value::Obj(o) if o.is_constructor() => o.clone(),
2148	                    _ => {
2149	                        let d = self.display_for_error(h);
2150	                        return self.throw_type(format!("Class extends value {} is not a constructor or null", d));
2151	                    }
2152	                };
2153	                let pp = self.get(&ho, &self.intr.key_prototype.clone(), h)?;
2154	                let pp = match pp {
2155	                    Value::Obj(o) => Some(o),
2156	                    Value::Null => None,
2157	                    _ => return self.throw_type("Class extends value does not have valid prototype property"),
2158	                };
2159	                (pp, ho)
