2161	        };
2162	        let proto = Obj::new(proto_parent, ObjKind::Ordinary);
2163	        let f = self.make_closure(ctor_code, frame.env.clone(), Some(proto.clone()));
2164	        {
2165	            let mut b = f.borrow_mut();
2166	            b.proto = Some(ctor_parent);
2167	            if let ObjKind::Closure(c) = &mut b.kind {
2168	                c.is_class_ctor = true;
2169	                c.derived = heritage.is_some();
