2403	    /// For sloppy direct eval inside functions: the variable environment receiving `var`s.
2404	    fn eval_var_env(&self, frame: &Frame) -> Option<Env> {
2405	        if !frame.code.is_eval || frame.code.strict {
2406	            return None;
2407	        }
2408	        // eval frames carry the caller env; find the nearest function-level env
2409	        let mut e = frame.env.clone();
2410	        while let Some(env) = e {
2411	            if let Some(info) = &env.0.info {
2412	                if info.is_function {
2413	                    return Some(env);
2414	                }
2415	            }
2416	            e = env.0.parent.clone();
2417	        }
2418	        None
2419	    }
