// node:events EventEmitter (state kept in JS-visible `_events`, like Node).

use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, Vm};

pub fn create_module(vm: &mut Vm) -> Value {
    let proto = vm.new_object();
    let ctor = vm.native_ctor("EventEmitter", 0, ee_ctor, &proto);
    install_methods(vm, &proto);
    ctor.set_prop(PropKey::from_str("EventEmitter"), Value::Obj(ctor.clone()), WC);
    ctor.set_prop(PropKey::from_str("defaultMaxListeners"), Value::Num(10.0), WEC);
    let em = Sym::new(Some(JsStr::from_str("events.errorMonitor")));
    ctor.set_prop(PropKey::from_str("errorMonitor"), Value::Sym(em), WEC);
    let cr = Sym::new(Some(JsStr::from_str("nodejs.rejection")));
    ctor.set_prop(PropKey::from_str("captureRejectionSymbol"), Value::Sym(cr), WEC);
    ctor.set_prop(PropKey::from_str("captureRejections"), Value::Bool(false), WEC);
    vm.def_method(&ctor, "once", 2, static_once);
    vm.def_method(&ctor, "on", 2, static_on);
    vm.def_method(&ctor, "listenerCount", 2, static_listener_count);
    vm.def_method(&ctor, "getEventListeners", 2, static_get_event_listeners);
    vm.def_method(&ctor, "setMaxListeners", 1, |_vm, _a| Ok(Value::Undefined));
    vm.def_method(&ctor, "init", 0, ee_init);
    Value::Obj(ctor)
}

pub fn install_methods(vm: &mut Vm, proto: &Obj) {
    let methods: &[(&str, u32, NativeFn)] = &[
        ("setMaxListeners", 1, set_max_listeners),
        ("getMaxListeners", 0, get_max_listeners),
        ("emit", 1, emit),
        ("addListener", 2, on),
        ("on", 2, on),
        ("prependListener", 2, prepend_listener),
        ("once", 2, once),
        ("prependOnceListener", 2, prepend_once_listener),
        ("removeListener", 2, remove_listener),
        ("off", 2, remove_listener),
        ("removeAllListeners", 1, remove_all_listeners),
        ("listeners", 1, listeners),
        ("rawListeners", 1, raw_listeners),
        ("listenerCount", 1, listener_count),
        ("eventNames", 0, event_names),
    ];
    for (n, l, f) in methods {
        vm.def_method(proto, n, *l, *f);
    }
}

pub fn init_emitter(vm: &mut Vm, o: &Obj) {
    let ev = Obj::new(None, ObjKind::Ordinary);
    o.set_prop(PropKey::from_str("_events"), Value::Obj(ev), WEC);
    o.set_prop(PropKey::from_str("_eventsCount"), Value::Num(0.0), WEC);
    o.set_prop(PropKey::from_str("_maxListeners"), Value::Undefined, WEC);
    let _ = vm;
}

fn ee_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = match &a.new_target {
        Some(_) => {
            let fallback = vm.get(a.callee, &vm.intr.key_prototype.clone(), &Value::Obj(a.callee.clone()))?.as_obj().cloned().unwrap();
            let p = vm.proto_from_nt(&a.new_target, &fallback)?;
            Obj::new(Some(p), ObjKind::Ordinary)
        }
        None => match &a.this {
            Value::Obj(o) => o.clone(),
            _ => return Ok(Value::Undefined),
        },
    };
    init_emitter(vm, &o);
    if a.new_target.is_none() {
        return Ok(Value::Undefined);
    }
    Ok(Value::Obj(o))
}

fn ee_init(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if let Value::Obj(o) = &a.this {
        init_emitter(vm, o);
    }
    Ok(Value::Undefined)
}

fn events_obj(vm: &mut Vm, this: &Value) -> JsResult<Obj> {
    let o = match this {
        Value::Obj(o) => o.clone(),
        _ => return vm.throw_type("EventEmitter method called on non-object"),
    };
    let ev = vm.get_str(&o, "_events")?;
    match ev {
        Value::Obj(e) => Ok(e),
        _ => {
            init_emitter(vm, &o);
            match vm.get_str(&o, "_events")? {
                Value::Obj(e) => Ok(e),
                _ => vm.throw_type("cannot initialize events"),
            }
        }
    }
}

fn get_list(vm: &mut Vm, ev: &Obj, key: &PropKey) -> JsResult<Vec<Value>> {
    let v = match ev.get_own_data(key) {
        Some(v) => v,
        None => return Ok(Vec::new()),
    };
    match &v {
        Value::Obj(o) if o.is_array() => crate::builtins::array::array_like_to_vec(vm, &v),
        Value::Undefined => Ok(Vec::new()),
        _ => Ok(vec![v]),
    }
}

fn set_list(vm: &mut Vm, this: &Value, ev: &Obj, key: &PropKey, list: Vec<Value>) {
    let had = ev.get_own_data(key).is_some();
    if list.is_empty() {
        ev.borrow_mut().props.remove(key);
        if had {
            adjust_count(vm, this, -1.0);
        }
    } else if list.len() == 1 {
        ev.set_prop(key.clone(), list[0].clone(), WEC);
        if !had {
            adjust_count(vm, this, 1.0);
        }
    } else {
        let arr = vm.new_array(list);
        ev.set_prop(key.clone(), Value::Obj(arr), WEC);
        if !had {
            adjust_count(vm, this, 1.0);
        }
    }
}

fn adjust_count(_vm: &mut Vm, this: &Value, d: f64) {
    if let Value::Obj(o) = this {
        let c = o.get_own_str("_eventsCount").and_then(|v| v.as_num()).unwrap_or(0.0);
        o.set_prop(PropKey::from_str("_eventsCount"), Value::Num((c + d).max(0.0)), WEC);
    }
}

// Object model: objects, properties, internal kinds.

use crate::bigint::BigInt;
use crate::bytecode::FunctionCode;
use crate::value::*;
use crate::vm::{Env, Frame, JsResult, Vm};
use std::cell::{Ref, RefCell, RefMut};
use std::collections::HashMap;
use std::rc::{Rc, Weak};

pub const WRITABLE: u8 = 1;
pub const ENUMERABLE: u8 = 2;
pub const CONFIGURABLE: u8 = 4;
pub const WEC: u8 = 7;
pub const WC: u8 = WRITABLE | CONFIGURABLE;

#[derive(Clone)]
pub enum Prop {
    Data { value: Value, flags: u8 },
    Accessor { get: Option<Obj>, set: Option<Obj>, flags: u8 },
}

impl Prop {
    pub fn data(value: Value, flags: u8) -> Prop {
        Prop::Data { value, flags }
    }
    pub fn flags(&self) -> u8 {
        match self {
            Prop::Data { flags, .. } => *flags,
            Prop::Accessor { flags, .. } => *flags,
        }
    }
    pub fn enumerable(&self) -> bool {
        self.flags() & ENUMERABLE != 0
    }
    pub fn configurable(&self) -> bool {
        self.flags() & CONFIGURABLE != 0
    }
    pub fn writable(&self) -> bool {
        match self {
            Prop::Data { flags, .. } => flags & WRITABLE != 0,
            _ => false,
        }
    }
}

/// Ordered property map.
#[derive(Default)]
pub struct PropMap {
    keys: Vec<PropKey>,
    vals: Vec<Prop>,
    index: Option<FxHashMap<PropKey, u32>>,
}

const INDEX_THRESHOLD: usize = 8;

impl PropMap {
    pub fn new() -> PropMap {
        PropMap { keys: Vec::new(), vals: Vec::new(), index: None }
    }
    pub fn len(&self) -> usize {
        self.keys.len()
    }
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }
    fn find(&self, k: &PropKey) -> Option<usize> {
        if let Some(idx) = &self.index {
            return idx.get(k).map(|i| *i as usize);
        }
        // pointer-equality fast path then content
        for (i, key) in self.keys.iter().enumerate() {
            match (key, k) {
                (PropKey::Str(a), PropKey::Str(b)) => {
                    if a.ptr_eq(b) || a == b {
                        return Some(i);
                    }
                }
                (PropKey::Sym(a), PropKey::Sym(b)) => {
                    if a == b {
                        return Some(i);
                    }
                }
                _ => {}
            }
        }
        None
    }
    pub fn get(&self, k: &PropKey) -> Option<&Prop> {
        self.find(k).map(|i| &self.vals[i])
    }
    pub fn get_mut(&mut self, k: &PropKey) -> Option<&mut Prop> {
        match self.find(k) {
            Some(i) => Some(&mut self.vals[i]),
            None => None,
        }
    }
    pub fn contains(&self, k: &PropKey) -> bool {
        self.find(k).is_some()
    }
    pub fn insert(&mut self, k: PropKey, p: Prop) {
        if let Some(i) = self.find(&k) {
            self.vals[i] = p;
            return;
        }
        let i = self.keys.len();
        if let Some(idx) = &mut self.index {
            idx.insert(k.clone(), i as u32);
        }
        self.keys.push(k);
        self.vals.push(p);
        if self.index.is_none() && self.keys.len() > INDEX_THRESHOLD {
            self.rebuild_index();
        }
    }
    fn rebuild_index(&mut self) {
        let mut m = new_fx_map();
        for (i, k) in self.keys.iter().enumerate() {
            m.insert(k.clone(), i as u32);
        }
        self.index = Some(m);
    }
    pub fn remove(&mut self, k: &PropKey) -> Option<Prop> {
        let i = self.find(k)?;
        self.keys.remove(i);
        let p = self.vals.remove(i);
        if self.index.is_some() {
            if self.keys.len() > INDEX_THRESHOLD {
                self.rebuild_index();
            } else {
                self.index = None;
            }
        }
        Some(p)
    }
    pub fn keys(&self) -> &[PropKey] {
        &self.keys
    }
    pub fn iter(&self) -> impl Iterator<Item = (&PropKey, &Prop)> {
        self.keys.iter().zip(self.vals.iter())
    }
    pub fn values_mut(&mut self) -> impl Iterator<Item = &mut Prop> {
        self.vals.iter_mut()
    }
    pub fn clear(&mut self) {
        self.keys.clear();
        self.vals.clear();
        self.index = None;
    }
    /// Keys in spec order: integer indices ascending, then strings, then symbols (insertion order).
    pub fn ordered_keys(&self) -> Vec<PropKey> {
        let mut ints: Vec<(u64, PropKey)> = Vec::new();
        let mut strs = Vec::new();
        let mut syms = Vec::new();
        for k in &self.keys {
            match k {
                PropKey::Str(s) => {
                    if let Some(i) = s.as_array_index() {
                        ints.push((i as u64, k.clone()));
                    } else {
                        strs.push(k.clone());
                    }
                }
                PropKey::Sym(s) => {
                    if !s.is_private() {
                        syms.push(k.clone())
                    }
                }
            }
        }
        if ints.len() > 1 {
            ints.sort_by_key(|(i, _)| *i);
        }
        let mut out: Vec<PropKey> = ints.into_iter().map(|(_, k)| k).collect();
        out.extend(strs);
        out.extend(syms);
        out
    }
}

pub struct ArrayData {
    /// dense element storage; Value::Empty marks holes
    pub dense: Vec<Value>,
    pub len: u32,
    /// when true, all elements live in the property map
    pub sparse: bool,
    pub length_writable: bool,
}

pub type NativeFn = fn(&mut Vm, &Args) -> JsResult<Value>;

pub struct Args<'a> {
    pub this: Value,
    pub args: &'a [Value],
    pub callee: &'a Obj,
    pub new_target: Option<Obj>,
}

impl<'a> Args<'a> {
    #[inline]
    pub fn arg(&self, i: usize) -> Value {
        self.args.get(i).cloned().unwrap_or(Value::Undefined)
    }

    pub fn len(&self) -> usize {
        self.args.len()
    }
    pub fn slot(&self, i: usize) -> Value {
        let o = self.callee.borrow();
        match &o.kind {
            ObjKind::Native(n) => n.slots.get(i).cloned().unwrap_or(Value::Undefined),
            _ => Value::Undefined,
