fn check_listener(vm: &mut Vm, f: &Value) -> JsResult<()> {
    if !f.is_callable() {
        let d = crate::runtime::util::describe_received(vm, f);
        return vm.throw_type(format!("The \"listener\" argument must be of type function. Received {}", d));
    }
    Ok(())
}

pub fn add_listener(vm: &mut Vm, this: &Value, name: &Value, f: Value, prepend: bool) -> JsResult<()> {
    check_listener(vm, &f)?;
    let ev = events_obj(vm, this)?;
    // newListener event
    let nl = PropKey::from_str("newListener");
    if ev.get_own_data(&nl).is_some() {
        let real = match &f {
            Value::Obj(fo) => fo.get_own_str("listener").unwrap_or_else(|| f.clone()),
            _ => f.clone(),
        };
        emit_event(vm, this, &Value::str("newListener"), &[name.clone(), real])?;
    }
    let key = vm.to_property_key(name)?;
    let ev = events_obj(vm, this)?;
    let mut list = get_list(vm, &ev, &key)?;
    if prepend {
        list.insert(0, f);
    } else {
        list.push(f);
    }
    set_list(vm, this, &ev, &key, list);
    Ok(())
}

fn on(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    add_listener(vm, &a.this, &a.arg(0), a.arg(1), false)?;
    Ok(a.this.clone())
}

fn prepend_listener(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    add_listener(vm, &a.this, &a.arg(0), a.arg(1), true)?;
    Ok(a.this.clone())
}

fn once_wrapper(vm: &mut Vm, this: &Value, name: &Value, f: &Value) -> Value {
    let w = vm.native_closure("bound onceWrapper", 0, once_fire, vec![this.clone(), name.clone(), f.clone(), Value::Bool(false)]);
    w.set_prop(PropKey::from_str("listener"), f.clone(), WEC);
    Value::Obj(w)
}

fn once_fire(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let fired = a.slot(3).truthy();
    if fired {
        return Ok(Value::Undefined);
    }
    if let ObjKind::Native(n) = &mut a.callee.borrow_mut().kind {
        n.slots[3] = Value::Bool(true);
    }
    let target = a.slot(0);
    let name = a.slot(1);
    let f = a.slot(2);
    remove_one(vm, &target, &name, &Value::Obj(a.callee.clone()))?;
    vm.call(&f, target, a.args)
}

fn once(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let f = a.arg(1);
    check_listener(vm, &f)?;
    let w = once_wrapper(vm, &a.this, &a.arg(0), &f);
    add_listener(vm, &a.this, &a.arg(0), w, false)?;
    Ok(a.this.clone())
}

fn prepend_once_listener(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let f = a.arg(1);
    check_listener(vm, &f)?;
    let w = once_wrapper(vm, &a.this, &a.arg(0), &f);
    add_listener(vm, &a.this, &a.arg(0), w, true)?;
    Ok(a.this.clone())
}

fn matches_listener(l: &Value, f: &Value) -> bool {
    if Value::strict_eq(l, f) {
        return true;
    }
    if let Value::Obj(lo) = l {
        if let Some(inner) = lo.get_own_str("listener") {
            return Value::strict_eq(&inner, f);
        }
    }
    false
}

fn remove_one(vm: &mut Vm, this: &Value, name: &Value, f: &Value) -> JsResult<bool> {
    let ev = events_obj(vm, this)?;
    let key = vm.to_property_key(name)?;
    let mut list = get_list(vm, &ev, &key)?;
    let pos = list.iter().rposition(|l| matches_listener(l, f));
    match pos {
        Some(p) => {
            let removed = list.remove(p);
            set_list(vm, this, &ev, &key, list);
            let rl = PropKey::from_str("removeListener");
            if ev.get_own_data(&rl).is_some() {
                let real = match &removed {
                    Value::Obj(ro) => ro.get_own_str("listener").unwrap_or(removed.clone()),
                    _ => removed.clone(),
                };
                emit_event(vm, this, &Value::str("removeListener"), &[name.clone(), real])?;
            }
            Ok(true)
        }
        None => Ok(false),
    }
}

fn remove_listener(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    check_listener(vm, &a.arg(1))?;
    remove_one(vm, &a.this, &a.arg(0), &a.arg(1))?;
    Ok(a.this.clone())
}

fn remove_all_listeners(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let ev = events_obj(vm, &a.this)?;
    if a.arg(0).is_undefined() {
        let keys: Vec<PropKey> = ev.borrow().props.keys().to_vec();
        for k in keys {
            ev.borrow_mut().props.remove(&k);
        }
        if let Value::Obj(o) = &a.this {
            o.set_prop(PropKey::from_str("_eventsCount"), Value::Num(0.0), WEC);
        }
    } else {
        let key = vm.to_property_key(&a.arg(0))?;
        if ev.get_own_data(&key).is_some() {
            ev.borrow_mut().props.remove(&key);
            adjust_count(vm, &a.this, -1.0);
        }
    }
    Ok(a.this.clone())
}

pub fn emit_event(vm: &mut Vm, this: &Value, name: &Value, args: &[Value]) -> JsResult<bool> {
    let ev = events_obj(vm, this)?;
    let key = vm.to_property_key(name)?;
    let list = get_list(vm, &ev, &key)?;
    if list.is_empty() {
        if key.eq_str("error") {
            let err = args.first().cloned().unwrap_or(Value::Undefined);
            if let Value::Obj(_) = &err {
                if matches!(err.as_obj().unwrap().borrow().kind, ObjKind::Error) {
                    return Err(err);
                }
            }
            let d = crate::runtime::util::inspect_value(vm, &err, 2)?;
            let e = vm.make_error("Error", &format!("Unhandled error. ({})", d));
            if let Value::Obj(eo) = &e {
                eo.set_prop(PropKey::from_str("code"), Value::str("ERR_UNHANDLED_ERROR"), WC);
                eo.set_prop(PropKey::from_str("context"), err, WC);
            }
            return Err(e);
        }
        return Ok(false);
    }
    for l in list {
        vm.call(&l, this.clone(), args)?;
    }
    Ok(true)
}

fn emit(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let rest = if a.args.len() > 1 { &a.args[1..] } else { &[][..] };
    Ok(Value::Bool(emit_event(vm, &a.this, &a.arg(0), rest)?))
}

fn listeners(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let ev = events_obj(vm, &a.this)?;
    let key = vm.to_property_key(&a.arg(0))?;
    let list = get_list(vm, &ev, &key)?;
    let unwrapped: Vec<Value> = list
        .into_iter()
        .map(|l| match &l {
            Value::Obj(o) => o.get_own_str("listener").unwrap_or(l.clone()),
            _ => l,
        })
        .collect();
    Ok(Value::Obj(vm.new_array(unwrapped)))
}

fn raw_listeners(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let ev = events_obj(vm, &a.this)?;
    let key = vm.to_property_key(&a.arg(0))?;
    let list = get_list(vm, &ev, &key)?;
    Ok(Value::Obj(vm.new_array(list)))
}

fn listener_count(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let ev = events_obj(vm, &a.this)?;
    let key = vm.to_property_key(&a.arg(0))?;
    let list = get_list(vm, &ev, &key)?;
    let n = if a.arg(1).is_undefined() { list.len() } else { list.iter().filter(|l| matches_listener(l, &a.arg(1))).count() };
    Ok(Value::Num(n as f64))
}

fn event_names(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let ev = events_obj(vm, &a.this)?;
    let keys = vm.own_property_keys(&ev)?;
    let v: Vec<Value> = keys
        .into_iter()
        .map(|k| match k {
            PropKey::Str(s) => Value::Str(s),
            PropKey::Sym(s) => Value::Sym(s),
        })
        .collect();
    Ok(Value::Obj(vm.new_array(v)))
}

fn set_max_listeners(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let n = vm.to_number(&a.arg(0))?;
    if n.is_nan() || n < 0.0 {
        return vm.throw_range(format!("The value of \"n\" is out of range. It must be a non-negative number. Received {}", crate::numconv::number_to_string(n)));
    }
    if let Value::Obj(o) = &a.this {
        o.set_prop(PropKey::from_str("_maxListeners"), Value::Num(n), WEC);
    }
    Ok(a.this.clone())
}

fn get_max_listeners(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if let Value::Obj(o) = &a.this {
        let m = vm.get_str(o, "_maxListeners")?;
        if !m.is_undefined() {
            return Ok(m);
        }
    }
    Ok(Value::Num(10.0))
}

fn static_once(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let emitter = a.arg(0);
    let name = a.arg(1);
    let cap = vm.new_promise_capability_intrinsic();
    let resolver = vm.native_closure("", 0, static_once_resolve, vec![cap.resolve.clone()]);
    let w = once_wrapper(vm, &emitter, &name, &Value::Obj(resolver));
    let add = vm.get_prop_of(&emitter, &PropKey::from_str("on"))?;
    if add.is_callable() {
        vm.call(&add, emitter.clone(), &[name.clone(), w])?;
        if !name.is_object() {
            let is_error = matches!(&name, Value::Str(s) if s.eq_str("error"));
            if !is_error {
                let rej = vm.native_closure("", 1, static_once_reject, vec![cap.reject.clone()]);
                let w2 = once_wrapper(vm, &emitter, &Value::str("error"), &Value::Obj(rej));
                vm.call(&add, emitter, &[Value::str("error"), w2])?;
            }
        }
    } else {
        // EventTarget
        let ael = vm.get_prop_of(&emitter, &PropKey::from_str("addEventListener"))?;
        let resolver2 = vm.native_closure("", 0, static_once_resolve, vec![cap.resolve.clone()]);
        let opts = vm.obj_from(vec![("once", Value::Bool(true))]);
        vm.call(&ael, emitter, &[name, Value::Obj(resolver2), Value::Obj(opts)])?;
    }
    Ok(cap.promise)
}

fn static_once_resolve(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let arr = vm.new_array(a.args.to_vec());
    vm.call(&a.slot(0), Value::Undefined, &[Value::Obj(arr)])?;
    Ok(Value::Undefined)
}

fn static_once_reject(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    vm.call(&a.slot(0), Value::Undefined, &[a.arg(0)])?;
    Ok(Value::Undefined)
}

fn static_on(vm: &mut Vm, _a: &Args) -> JsResult<Value> {
    vm.throw_type("events.on is not supported")
}

fn static_listener_count(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let f = vm.get_prop_of(&a.arg(0), &PropKey::from_str("listenerCount"))?;
    vm.call(&f, a.arg(0), &[a.arg(1)])
}

fn static_get_event_listeners(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let f = vm.get_prop_of(&a.arg(0), &PropKey::from_str("listeners"))?;
    if f.is_callable() {
        return vm.call(&f, a.arg(0), &[a.arg(1)]);
    }
    Ok(Value::Obj(vm.new_array(Vec::new())))
}

// Core value types: Value, JsStr (UTF-16 rope), Sym, PropKey.

use crate::bigint::BigInt;
use crate::object::Obj;
use std::cell::{Cell, OnceCell, RefCell};
use std::fmt;
use std::hash::{Hash, Hasher};
use std::rc::Rc;

// ---------------- JsStr ----------------

pub struct StrNode {
    flat: OnceCell<Box<[u16]>>,
    rope: RefCell<Option<(JsStr, JsStr)>>,
    len: usize,
    hash: Cell<u64>,
    /// cached: is every code unit < 128
    ascii: Cell<u8>, // 0 unknown, 1 yes, 2 no
}

#[derive(Clone)]
pub struct JsStr(Rc<StrNode>);

impl Drop for StrNode {
    fn drop(&mut self) {
        // iterative drop of deep ropes
        let mut stack: Vec<JsStr> = Vec::new();
        if let Some((a, b)) = self.rope.get_mut().take() {
            stack.push(a);
            stack.push(b);
        }
        while let Some(s) = stack.pop() {
            if let Ok(mut node) = Rc::try_unwrap(s.0) {
                if let Some((a, b)) = node.rope.get_mut().take() {
                    stack.push(a);
                    stack.push(b);
                }
                // node dropped here with no children
            }
        }
    }
}

pub fn fx_hash_u16(s: &[u16]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &c in s {
        h = (h.rotate_left(5) ^ c as u64).wrapping_mul(0x517cc1b727220a95);
    }
    h
}

impl JsStr {
    pub fn from_units(v: Vec<u16>) -> JsStr {
        let len = v.len();
        let cell = OnceCell::new();
        let _ = cell.set(v.into_boxed_slice());
        JsStr(Rc::new(StrNode { flat: cell, rope: RefCell::new(None), len, hash: Cell::new(0), ascii: Cell::new(0) }))
    }
    pub fn from_slice(v: &[u16]) -> JsStr {
        JsStr::from_units(v.to_vec())
    }
    pub fn from_str(s: &str) -> JsStr {
        JsStr::from_units(s.encode_utf16().collect())
    }
    pub fn empty() -> JsStr {
        thread_local! {
            static EMPTY: JsStr = JsStr::from_units(Vec::new());
        }
        EMPTY.with(|e| e.clone())
    }
    pub fn len(&self) -> usize {
        self.0.len
    }
    pub fn is_empty(&self) -> bool {
        self.0.len == 0
    }
    pub fn ptr_eq(&self, o: &JsStr) -> bool {
        Rc::ptr_eq(&self.0, &o.0)
    }

    /// Flattened UTF-16 code units.
    pub fn units(&self) -> &[u16] {
        if let Some(f) = self.0.flat.get() {
            return f;
        }
        let mut out: Vec<u16> = Vec::with_capacity(self.0.len);
        let mut stack: Vec<JsStr> = Vec::new();
        {
            let r = self.0.rope.borrow();
            let (a, b) = r.as_ref().expect("rope");
            stack.push(b.clone());
            stack.push(a.clone());
        }
        while let Some(n) = stack.pop() {
            if let Some(f) = n.0.flat.get() {
                out.extend_from_slice(f);
                continue;
            }
            let r = n.0.rope.borrow();
            let (a, b) = r.as_ref().expect("rope");
            stack.push(b.clone());
            stack.push(a.clone());
        }
        let _ = self.0.flat.set(out.into_boxed_slice());
        // release children
        let children = self.0.rope.borrow_mut().take();
        drop(children);
        self.0.flat.get().unwrap()
    }

    pub fn concat(a: &JsStr, b: &JsStr) -> JsStr {
        if a.is_empty() {
            return b.clone();
        }
        if b.is_empty() {
            return a.clone();
        }
        let len = a.len() + b.len();
        if len <= 64 {
            let mut v = Vec::with_capacity(len);
            v.extend_from_slice(a.units());
            v.extend_from_slice(b.units());
            return JsStr::from_units(v);
        }
        JsStr(Rc::new(StrNode {
            flat: OnceCell::new(),
            rope: RefCell::new(Some((a.clone(), b.clone()))),
            len,
            hash: Cell::new(0),
            ascii: Cell::new(0),
        }))
    }

    pub fn hash_value(&self) -> u64 {
        let h = self.0.hash.get();
        if h != 0 {
            return h;
        }
        let mut h = fx_hash_u16(self.units());
        if h == 0 {
            h = 1;
        }
        self.0.hash.set(h);
        h
    }

    pub fn is_ascii(&self) -> bool {
        match self.0.ascii.get() {
            1 => true,
            2 => false,
            _ => {
                let r = self.units().iter().all(|&c| c < 128);
                self.0.ascii.set(if r { 1 } else { 2 });
                r
            }
        }
    }

    pub fn to_rust_string(&self) -> String {
        String::from_utf16_lossy(self.units())
    }

    pub fn eq_str(&self, s: &str) -> bool {
        let u = self.units();
        let mut i = 0;
        for c in s.encode_utf16() {
            if i >= u.len() || u[i] != c {
                return false;
            }
            i += 1;
        }
        i == u.len()
    }

    pub fn at(&self, i: usize) -> u16 {
        self.units()[i]
    }

    pub fn substring(&self, start: usize, end: usize) -> JsStr {
        if start == 0 && end == self.len() {
            return self.clone();
        }
        JsStr::from_slice(&self.units()[start..end])
    }

    /// If this string is a canonical array index (0..2^32-2), return it.
    pub fn as_array_index(&self) -> Option<u32> {
        let u = self.units();
        if u.is_empty() || u.len() > 10 {
            return None;
        }
        if u[0] == b'0' as u16 {
            return if u.len() == 1 { Some(0) } else { None };
        }
        let mut v: u64 = 0;
        for &c in u {
            if !(b'0' as u16..=b'9' as u16).contains(&c) {
                return None;
            }
            v = v * 10 + (c - b'0' as u16) as u64;

v = v * 10 + (c - b'0' as u16) as u64;
        }
        if v < 4294967295 {
            Some(v as u32)
        } else {
            None
        }
    }

    /// Canonical numeric string check for integer-index keys (used for typed arrays & ordering)
    pub fn as_integer_key(&self) -> Option<u64> {
        let u = self.units();
        if u.is_empty() || u.len() > 16 {
            return None;
        }
        if u[0] == b'0' as u16 {
            return if u.len() == 1 { Some(0) } else { None };
        }
        let mut v: u64 = 0;
        for &c in u {
            if !(b'0' as u16..=b'9' as u16).contains(&c) {
                return None;
            }
            v = v * 10 + (c - b'0' as u16) as u64;
        }
        Some(v)
    }

    pub fn index_of(&self, pat: &[u16], from: usize) -> Option<usize> {
        let s = self.units();
        if pat.is_empty() {
            return if from <= s.len() { Some(from) } else { None };
        }
        if pat.len() > s.len() {
            return None;
        }
        let last = s.len() - pat.len();
        let first = pat[0];
        let mut i = from;
        while i <= last {
            if s[i] == first && &s[i..i + pat.len()] == pat {
                return Some(i);
            }
            i += 1;
        }
        None
    }
}

impl PartialEq for JsStr {
    fn eq(&self, other: &JsStr) -> bool {
        if Rc::ptr_eq(&self.0, &other.0) {
            return true;
        }
        if self.len() != other.len() {
            return false;
        }
        let (h1, h2) = (self.0.hash.get(), other.0.hash.get());
        if h1 != 0 && h2 != 0 && h1 != h2 {
            return false;
        }
        self.units() == other.units()
    }
}
impl Eq for JsStr {}
impl Hash for JsStr {
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write_u64(self.hash_value());
    }
}
impl PartialOrd for JsStr {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for JsStr {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.units().cmp(other.units())
    }
}

impl fmt::Debug for JsStr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}", self.to_rust_string())
    }
}
impl fmt::Display for JsStr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_rust_string())
    }
}

impl From<&str> for JsStr {
    fn from(s: &str) -> JsStr {
        JsStr::from_str(s)
    }
}
impl From<String> for JsStr {
    fn from(s: String) -> JsStr {
        JsStr::from_str(&s)
    }
}

// ---------------- Symbols ----------------

pub struct SymbolData {
    pub description: Option<JsStr>,
    pub registered: bool,
    pub private: bool,
}

#[derive(Clone)]
pub struct Sym(pub Rc<SymbolData>);

impl Sym {
    pub fn new(desc: Option<JsStr>) -> Sym {
        Sym(Rc::new(SymbolData { description: desc, registered: false, private: false }))
    }
    pub fn new_private(desc: JsStr) -> Sym {
        Sym(Rc::new(SymbolData { description: Some(desc), registered: false, private: true }))
    }
    pub fn ptr_eq(&self, o: &Sym) -> bool {
        Rc::ptr_eq(&self.0, &o.0)
    }
    pub fn descriptive_string(&self) -> String {
        match &self.0.description {
            Some(d) => format!("Symbol({})", d),
            None => "Symbol()".to_string(),
        }
    }
    pub fn is_private(&self) -> bool {
        self.0.private
    }
}
impl PartialEq for Sym {
    fn eq(&self, o: &Sym) -> bool {
        Rc::ptr_eq(&self.0, &o.0)
    }
}
impl Eq for Sym {}
impl Hash for Sym {
    fn hash<H: Hasher>(&self, state: &mut H) {
        (Rc::as_ptr(&self.0) as usize).hash(state)
    }
}

// ---------------- PropKey ----------------

#[derive(Clone, PartialEq, Eq, Hash)]
pub enum PropKey {
    Str(JsStr),
    Sym(Sym),
}

impl PropKey {
    pub fn from_str(s: &str) -> PropKey {
        PropKey::Str(JsStr::from_str(s))
    }
    pub fn as_index(&self) -> Option<u32> {
        match self {
            PropKey::Str(s) => s.as_array_index(),
            _ => None,
        }
    }
    pub fn is_symbol(&self) -> bool {
        matches!(self, PropKey::Sym(_))
    }
    pub fn is_private(&self) -> bool {
        matches!(self, PropKey::Sym(s) if s.is_private())
    }
    pub fn to_display(&self) -> String {
        match self {
            PropKey::Str(s) => s.to_rust_string(),
            PropKey::Sym(s) => s.descriptive_string(),
        }
    }
    pub fn from_index(i: u32) -> PropKey {
        PropKey::Str(index_to_jsstr(i as u64))
    }
    pub fn as_jsstr(&self) -> Option<&JsStr> {
        match self {
            PropKey::Str(s) => Some(s),
            _ => None,
        }
    }
    pub fn eq_str(&self, s: &str) -> bool {
        match self {
            PropKey::Str(x) => x.eq_str(s),
            _ => false,
        }
    }
}

impl fmt::Debug for PropKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_display())
    }
}

thread_local! {
    static SMALL_INTS: Vec<JsStr> = (0..1024u32).map(|i| JsStr::from_str(&i.to_string())).collect();
}

pub fn index_to_jsstr(i: u64) -> JsStr {
    if i < 1024 {
        SMALL_INTS.with(|v| v[i as usize].clone())
    } else {
        JsStr::from_str(&i.to_string())
    }
}

// ---------------- Value ----------------

#[derive(Clone)]
pub enum Value {
    Undefined,
    Null,
    Bool(bool),
    Num(f64),
    Str(JsStr),
    Sym(Sym),
    BigInt(Rc<BigInt>),
    Obj(Obj),
    /// internal: uninitialized binding / array hole. Never visible to JS.
    Empty,
}

impl Default for Value {
    fn default() -> Self {
        Value::Undefined
    }
}

impl Value {
    pub fn str(s: &str) -> Value {
        Value::Str(JsStr::from_str(s))
    }
    pub fn is_undefined(&self) -> bool {
        matches!(self, Value::Undefined)
    }
    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }
    pub fn is_nullish(&self) -> bool {
        matches!(self, Value::Undefined | Value::Null)
    }
    pub fn is_object(&self) -> bool {
        matches!(self, Value::Obj(_))
    }
    pub fn is_empty(&self) -> bool {
        matches!(self, Value::Empty)
    }
    pub fn as_obj(&self) -> Option<&Obj> {
        match self {
            Value::Obj(o) => Some(o),
            _ => None,
        }
    }
    pub fn as_num(&self) -> Option<f64> {
        match self {
            Value::Num(n) => Some(*n),
            _ => None,
        }
    }
    pub fn type_of(&self) -> &'static str {
        match self {
            Value::Undefined | Value::Empty => "undefined",
            Value::Null => "object",
            Value::Bool(_) => "boolean",
            Value::Num(_) => "number",
            Value::Str(_) => "string",
            Value::Sym(_) => "symbol",
            Value::BigInt(_) => "bigint",
            Value::Obj(o) => {
                if o.is_callable() {
                    "function"
                } else if o.is_htmldda() {
                    "undefined"
                } else {
                    "object"
                }
            }
        }
    }
    pub fn truthy(&self) -> bool {
        match self {
            Value::Undefined | Value::Null | Value::Empty => false,
            Value::Bool(b) => *b,
            Value::Num(n) => !(*n == 0.0 || n.is_nan()),
            Value::Str(s) => !s.is_empty(),
            Value::Sym(_) => true,
            Value::BigInt(b) => !b.is_zero(),
            Value::Obj(o) => !o.is_htmldda(),
        }
    }
    pub fn is_callable(&self) -> bool {
        match self {
            Value::Obj(o) => o.is_callable(),
            _ => false,
        }
    }
    pub fn same_value(a: &Value, b: &Value) -> bool {
        match (a, b) {
            (Value::Num(x), Value::Num(y)) => {
                if x.is_nan() && y.is_nan() {
                    true
                } else {
                    x == y && x.is_sign_negative() == y.is_sign_negative()
                }
            }
            _ => Value::strict_eq(a, b),
        }
    }
    pub fn same_value_zero(a: &Value, b: &Value) -> bool {
        match (a, b) {
            (Value::Num(x), Value::Num(y)) => (x.is_nan() && y.is_nan()) || x == y,
            _ => Value::strict_eq(a, b),
        }
    }
    pub fn strict_eq(a: &Value, b: &Value) -> bool {
        match (a, b) {
            (Value::Undefined, Value::Undefined) => true,
            (Value::Null, Value::Null) => true,
            (Value::Bool(x), Value::Bool(y)) => x == y,
            (Value::Num(x), Value::Num(y)) => x == y,
            (Value::Str(x), Value::Str(y)) => x == y,
            (Value::Sym(x), Value::Sym(y)) => x == y,
            (Value::BigInt(x), Value::BigInt(y)) => x == y,
            (Value::Obj(x), Value::Obj(y)) => x.ptr_eq(y),
            (Value::Empty, Value::Empty) => true,
            _ => false,
        }
    }
}

impl From<f64> for Value {
    fn from(n: f64) -> Value {
        Value::Num(n)
    }
}
impl From<bool> for Value {
    fn from(b: bool) -> Value {
        Value::Bool(b)
    }
}
impl From<JsStr> for Value {
    fn from(s: JsStr) -> Value {
        Value::Str(s)
    }
}
impl From<Obj> for Value {
