931	    // ---------------- [[Delete]] ----------------
932	
933	    pub fn delete(&mut self, o: &Obj, key: &PropKey) -> JsResult<bool> {
934	        if o.is_proxy() {
935	            return proxy::proxy_delete(self, o, key);
936	        }
937	        let mut b = o.borrow_mut();
938	        match &mut b.kind {
939	            ObjKind::Array(a) => {
940	                if key.eq_str("length") {
941	                    return Ok(false);
942	                }
943	                if !a.sparse {
944	                    if let Some(i) = key.as_index() {
945	                        let i = i as usize;
946	                        if i < a.dense.len() {
947	                            if i + 1 == a.dense.len() {
948	                                a.dense.pop();
949	                                while matches!(a.dense.last(), Some(Value::Empty)) {
950	                                    a.dense.pop();
951	                                }
952	                            } else {
953	                                a.dense[i] = Value::Empty;
954	                            }
955	                        }
956	                        return Ok(true);
957	                    }
958	                }
959	            }
960	            ObjKind::String(s) => {
961	                if let Some(i) = key.as_index() {
962	                    if (i as usize) < s.len() {
963	                        return Ok(false);
964	                    }
965	                }
966	                if key.eq_str("length") {
967	                    return Ok(false);
968	                }
969	            }
970	            ObjKind::TypedArray(t) => {
971	                if let Some(n) = canonical_numeric(key) {
972	                    return Ok(!ta::ta_valid_index(t, n));
973	                }
974	            }
975	            ObjKind::Namespace(_) => {
976	                drop(b);
977	                return crate::modules::namespace_delete(self, o, key);
978	            }
979	            ObjKind::Arguments(ad) => {
980	                if let Some(i) = key.as_index() {
981	                    if let Some(m) = ad.mapped.get_mut(i as usize) {
982	                        *m = None;
983	                    }
984	                }
985	            }
986	            _ => {}
987	        }
988	        match b.props.get(key) {
989	            None => Ok(true),
990	            Some(p) => {
991	                if p.configurable() {
992	                    b.props.remove(key);
993	                    Ok(true)
994	                } else {
995	                    Ok(false)
996	                }
997	            }
998	        }
999	    }
