1001	    pub fn delete_prop_of(&mut self, base: &Value, key: &PropKey, strict: bool) -> JsResult<bool> {
1002	        let o = match base {
1003	            Value::Obj(o) => o.clone(),
1004	            Value::Undefined | Value::Null => return self.throw_type("cannot convert undefined or null to object"),
1005	            other => self.to_object(other)?,
1006	        };
1007	        let r = self.delete(&o, key)?;
1008	        if !r && strict {
1009	            return self.throw_type(format!("cannot delete non-configurable property '{}'", key.to_display()));
1010	        }
1011	        Ok(r)
1012	    }
