1016	    pub fn own_property_keys(&mut self, o: &Obj) -> JsResult<Vec<PropKey>> {
1017	        if o.is_proxy() {
1018	            return proxy::proxy_own_keys(self, o);
1019	        }
1020	        if let ObjKind::Namespace(_) = &o.borrow().kind {
1021	            return Ok(crate::modules::namespace_keys(self, o));
1022	        }
1023	        Ok(self.ordinary_own_keys(o))
1024	    }
1025	
1026	    pub fn ordinary_own_keys(&self, o: &Obj) -> Vec<PropKey> {
1027	        let b = o.borrow();
1028	        match &b.kind {
1029	            ObjKind::Array(a) if !a.sparse => {
1030	                let mut out: Vec<PropKey> = Vec::with_capacity(a.dense.len() + b.props.len() + 1);
1031	                for (i, v) in a.dense.iter().enumerate() {
1032	                    if !v.is_empty() {
1033	                        out.push(PropKey::from_index(i as u32));
1034	                    }
1035	                }
1036	                out.push(self.intr.key_length.clone());
1037	                out.extend(b.props.ordered_keys());
1038	                out
1039	            }
1040	            ObjKind::Array(_) => {
1041	                let keys = b.props.ordered_keys();
1042	                let mut out = Vec::with_capacity(keys.len() + 1);
1043	                let mut inserted = false;
1044	                for k in keys {
1045	                    if !inserted && k.as_index().is_none() {
1046	                        out.push(self.intr.key_length.clone());
1047	                        inserted = true;
1048	                    }
1049	                    out.push(k);
1050	                }
1051	                if !inserted {
1052	                    out.push(self.intr.key_length.clone());
1053	                }
1054	                out
1055	            }
1056	            ObjKind::String(s) => {
1057	                let mut out: Vec<PropKey> = (0..s.len() as u32).map(PropKey::from_index).collect();
1058	                let keys = b.props.ordered_keys();
1059	                let mut rest = Vec::new();
1060	                for k in keys {
1061	                    if k.as_index().is_some() {
1062	                        out.push(k);
1063	                    } else {
1064	                        rest.push(k);
1065	                    }
1066	                }
1067	                out.push(self.intr.key_length.clone());
1068	                out.extend(rest);
1069	                out
1070	            }
1071	            ObjKind::TypedArray(t) => {
1072	                let n = t.len();
1073	                let mut out: Vec<PropKey> = (0..n as u32).map(PropKey::from_index).collect();
1074	                out.extend(b.props.ordered_keys());
1075	                out
1076	            }
1077	            _ => b.props.ordered_keys(),
1078	        }
1079	    }
