1094	    pub fn copy_data_properties(&mut self, target: &Obj, src: &Value, excluded: &[PropKey]) -> JsResult<()> {
1095	        let from = match src {
1096	            Value::Undefined | Value::Null => return Ok(()),
1097	            Value::Obj(o) => o.clone(),
1098	            other => self.to_object(other)?,
1099	        };
1100	        // fast path: ordinary source
1101	        let keys = self.own_property_keys(&from)?;
1102	        for k in keys {
1103	            if excluded.iter().any(|e| *e == k) {
1104	                continue;
1105	            }
1106	            let desc = self.get_own_property(&from, &k)?;
1107	            if let Some(d) = desc {
1108	                if d.enumerable == Some(true) {
1109	                    let v = self.get(&from, &k, &Value::Obj(from.clone()))?;
1110	                    self.create_data_property(target, k, v)?;
1111	                }
1112	            }
1113	        }
1114	        Ok(())
1115	    }
