1117	    /// Enumerable own string keys (for Object.keys etc.)
1118	    pub fn enumerable_own_keys(&mut self, o: &Obj) -> JsResult<Vec<JsStr>> {
1119	        let keys = self.own_property_keys(o)?;
1120	        let mut out = Vec::new();
1121	        let ordinary = !o.is_proxy();
1122	        for k in keys {
1123	            if let PropKey::Str(s) = &k {
1124	                if ordinary {
1125	                    if let Some(p) = self.ordinary_get_own(o, &k) {
1126	                        if p.enumerable() {
1127	                            out.push(s.clone());
1128	                        }
1129	                        continue;
1130	                    }
1131	                    if let ObjKind::Namespace(_) = &o.borrow().kind {
1132	                    } else {
1133	                        continue;
1134	                    }
1135	                }
1136	                if let Some(d) = self.get_own_property(o, &k)? {
1137	                    if d.enumerable == Some(true) {
1138	                        out.push(s.clone());
1139	                    }
1140	                }
1141	            }
1142	        }
1143	        Ok(out)
1144	    }
