1155	/// ValidateAndApplyPropertyDescriptor. If `o` is None, only validates.
1156	pub fn validate_and_apply(o: Option<&Obj>, key: &PropKey, extensible: bool, desc: &PropDesc, current: Option<Prop>) -> bool {
1157	    let cur = match current {
1158	        None => {
1159	            if !extensible {
1160	                return false;
1161	            }
1162	            if let Some(o) = o {
1163	                let prop = if desc.is_accessor() {
1164	                    Prop::Accessor {
1165	                        get: desc.get.clone().and_then(|v| v.as_obj().cloned()),
1166	                        set: desc.set.clone().and_then(|v| v.as_obj().cloned()),
1167	                        flags: desc.flags() & !WRITABLE,
1168	                    }
1169	                } else {
1170	                    Prop::Data { value: desc.value.clone().unwrap_or(Value::Undefined), flags: desc.flags() }
1171	                };
1172	                o.borrow_mut().props.insert(key.clone(), prop);
1173	            }
1174	            return true;
1175	        }
1176	        Some(c) => c,
1177	    };
1178	    if desc.is_generic() && desc.enumerable.is_none() && desc.configurable.is_none() {
1179	        return true;
1180	    }
1181	    let cur_conf = cur.configurable();
1182	    if !cur_conf {
1183	        if desc.configurable == Some(true) {
1184	            return false;
1185	        }
1186	        if let Some(e) = desc.enumerable {
1187	            if e != cur.enumerable() {
1188	                return false;
1189	            }
1190	        }
1191	        if !desc.is_generic() {
1192	            let cur_is_acc = matches!(cur, Prop::Accessor { .. });
1193	            if desc.is_accessor() != cur_is_acc {
1194	                return false;
1195	            }
1196	            match &cur {
1197	                Prop::Accessor { get, set, .. } => {
1198	                    if let Some(g) = &desc.get {
1199	                        let same = match (g, get) {
1200	                            (Value::Obj(a), Some(b)) => a.ptr_eq(b),
1201	                            (Value::Undefined, None) => true,
1202	                            _ => false,
1203	                        };
1204	                        if !same {
1205	                            return false;
1206	                        }
1207	                    }
1208	                    if let Some(s) = &desc.set {
1209	                        let same = match (s, set) {
1210	                            (Value::Obj(a), Some(b)) => a.ptr_eq(b),
1211	                            (Value::Undefined, None) => true,
1212	                            _ => false,
1213	                        };
1214	                        if !same {
1215	                            return false;
1216	                        }
1217	                    }
1218	                }
1219	                Prop::Data { value, flags } => {
1220	                    if flags & WRITABLE == 0 {
1221	                        if desc.writable == Some(true) {
1222	                            return false;
1223	                        }
1224	                        if let Some(v) = &desc.value {
1225	                            if !Value::same_value(v, value) {
1226	                                return false;
1227	                            }
1228	                        }
1229	                    }
1230	                }
1231	            }
1232	        }
1233	    }
1234	    let o = match o {
1235	        Some(o) => o,
1236	        None => return true,
1237	    };
1238	    // apply
1239	    let new_prop = match (&cur, desc.is_accessor(), desc.is_data()) {
1240	        (Prop::Data { flags, .. }, true, _) => {
1241	            let mut f = flags & (ENUMERABLE | CONFIGURABLE);
1242	            if let Some(e) = desc.enumerable {
1243	                f = if e { f | ENUMERABLE } else { f & !ENUMERABLE };
1244	            }
1245	            if let Some(c) = desc.configurable {
