const r = new Response("hello");
const s = r.body;
console.log("keys after body:", Object.getOwnPropertySymbols(r).map(String).join());
console.log("stream internals:", s._chunks.length, s._state, typeof s._source.start, typeof s._source.pull, typeof s._source.cancel, Object.keys(s._source).join());
const rd = s.getReader();
console.log("after getReader bodyUsed:", r.bodyUsed);
const p = rd.read();
console.log("after read() bodyUsed:", r.bodyUsed, s._chunks.length, s._state);
p.then(x => console.log("chunk same as _bodyBytes:", x.value === r._bodyBytes, x.value.buffer === r._bodyBytes.buffer));
// empty body
const r2 = new Response("");
const rd2 = r2.body.getReader();
rd2.read().then(x => console.log("empty:", x.done, x.value));
// body of null-body response
console.log("null body:", new Response().body);
// Request body
const rq = new Request("http://a/", { method: "POST", body: "abc" });
console.log("req body", rq.body instanceof ReadableStream, rq.bodyUsed);
const rq2 = new Request("http://a/");
console.log("req get body", rq2.body);
// stream source body
const src = new ReadableStream({ start(c) { c.enqueue(new Uint8Array([65, 66])); c.enqueue("str"); c.close(); } });
const r3 = new Response(src);
console.log("src body same:", r3.body === src);
r3.text().then(t => console.log("src text:", JSON.stringify(t)), e => console.log("src text err:", e.name, e.message));
