const base = "http://127.0.0.1:18471";
function hdrs(res) { return JSON.stringify([...res.headers]); }
async function t(path, init) {
  try {
    const res = await fetch(base + path, init);
    const body = await res.text();
    console.log(path, "=>", res.status, JSON.stringify(res.statusText), res.ok, res.url, res.redirected, hdrs(res), JSON.stringify(body));
  } catch (e) {
    console.log(path, "ERR", e && e.name, e && e.message, e && e.code, e && e.cause && e.cause.message);
  }
}
(async () => {
  await t("/clenshort");
  await t("/lf");
  await t("/echo", { method: "PUT", body: new Uint8Array([104, 105]), headers: [["X-A", "1"], ["x-b", "2"]] });
  await t("/echo", { method: "delete" });
  await t("/echo", { method: "HEAD" });
  await t("/echo", { method: "OPTIONS" });
  await t("/echo", { headers: { "Host": "example.com", "User-Agent": "mine", "Connection": "keep-alive", "Content-Length": "99" } });
  await t("/echo?x=1&y=%20z#hash");
  await t("/echo", { method: "POST", body: new URLSearchParams({ a: "1 2", b: "ü" }) });
  await t("/echo", { method: "POST", body: JSON.stringify({ a: 1 }), headers: { "content-type": "application/json" } });
  await t("/echo", { method: "POST", body: "" });
  await t("/echo", { method: "patch", body: "x" });
  await t("/status100");
})();

