const port = Number(process.argv[2] || 18500);
let n = 0;
const server = Lumen.serve({ port, hostname: "127.0.0.1", onListen(info) { console.log("listening", JSON.stringify(info)); } }, async (req) => {
  n++;
  const u = new URL(req.url);
  console.log("req", n, req.method, req.url, JSON.stringify([...req.headers]), "signal:", String(req.signal), "bodyUsed:", req.bodyUsed);
  const t = await req.text();
  console.log("body:", JSON.stringify(t));
  switch (u.pathname) {
    case "/text": return new Response("hello");
    case "/json": return Response.json({ a: 1 });
    case "/status": return new Response("nf", { status: 404, statusText: "Nope", headers: [["X-B", "2"], ["x-a", "1"], ["Set-Cookie", "a=1"]] });
    case "/empty": return new Response(null, { status: 204 });
    case "/nullbody": return new Response(null);
    case "/bytes": return new Response(new Uint8Array([0, 1, 2, 255]));
    case "/stream": return new Response(new ReadableStream({ start(c) { c.enqueue(new TextEncoder().encode("streamed")); c.close(); } }));
    case "/redirect": return Response.redirect("http://127.0.0.1:" + port + "/text", 301);
    case "/throw": throw new Error("handler failed");
    case "/notresponse": return "just a string";
    case "/undefined": return undefined;
    case "/cl": return new Response("abc", { headers: { "content-length": "3", "connection": "keep-alive", "server": "mine", "date": "x" } });
    case "/shutdown": setTimeout(() => server.shutdown(), 10); return new Response("bye");
  }
  return new Response("default " + u.pathname);
});
server.finished.then(() => console.log("finished"));

