const cp = require('child_process');
const out = cp.execSync('echo hello');
console.log(typeof out, out instanceof Buffer, JSON.stringify(String(out)));
console.log(JSON.stringify(cp.execSync('echo hi; echo err >&2', { encoding: 'utf8' })));
try { cp.execSync('exit 3'); } catch (e) { console.log('E1', e.message, e.status, JSON.stringify(Object.keys(e)), String(e.stderr), e.stdout); }
try { cp.execSync('nonexistentcmd_xyz'); } catch (e) { console.log('E2', e.message, e.status, JSON.stringify(String(e.stderr))); }
try { cp.execFileSync('nonexistentcmd_xyz'); } catch (e) { console.log('E3', e.message, e.code, e.errno, e.syscall, e.path, JSON.stringify(e.spawnargs), JSON.stringify(Object.keys(e))); }
try { cp.execFileSync('sh', ['-c', 'echo o; echo e >&2; exit 2']); } catch (e) { console.log('E4', e.message, e.status, JSON.stringify(Object.keys(e)), String(e.stdout), String(e.stderr)); }
const r = cp.spawnSync('sh', ['-c', 'echo out; echo err >&2; exit 5']);
console.log(JSON.stringify(Object.keys(r)));
console.log(r.status, r.signal, r.pid > 0, String(r.stdout), String(r.stderr), JSON.stringify(r.output && r.output.map(x => x && String(x))));
const r2 = cp.spawnSync('nonexistentcmd_xyz');
console.log(JSON.stringify(Object.keys(r2)), r2.status, r2.error && r2.error.message, r2.error && r2.error.code);
const r3 = cp.spawnSync('cat', { input: 'piped input' , encoding: 'utf8'});
console.log(JSON.stringify(r3.stdout), typeof r3.stdout, JSON.stringify(r3.stderr));
console.log(cp.execSync('pwd', { cwd: '/tmp', encoding: 'utf8' }));
console.log(cp.execSync('echo $FOO', { env: { FOO: 'bar' }, encoding: 'utf8' }));
console.log(cp.execFileSync('echo', ['a', 'b'], { encoding: 'utf8' }));
console.log(cp.execSync('cat', { input: 'from input' }).toString());
const r4 = cp.spawnSync('echo', ['$HOME'], { shell: true, encoding: 'utf8' });
console.log(JSON.stringify(r4.stdout));
const r5 = cp.spawnSync('sh', ['-c', 'kill -9 $$']);
console.log(r5.status, r5.signal);

