const port = Number(process.argv[2] || 18501);
const useOnError = process.argv[3] === "onerror";
const opts = { port, hostname: "127.0.0.1" };
if (useOnError) opts.onError = (e) => { console.log("onError called:", String(e), arguments.length); return new Response("custom error page: " + e.message, { status: 503 }); };
const server = Lumen.serve(opts, async (req) => {
  const u = new URL(req.url);
  console.log("req", req.method, u.pathname);
  switch (u.pathname) {
    case "/throwstr": throw "a string";
    case "/throwobj": throw { x: 1 };
    case "/throwundef": throw undefined;
    case "/reject": return Promise.reject(new RangeError("rejected"));
    case "/head": return new Response("body for head", { headers: { "x-h": "1" } });
    case "/sync": return new Response("sync");
    case "/delay": await new Promise(r => setTimeout(r, 300)); return new Response("delayed");
    case "/stream-async": return new Response(new ReadableStream({ start(c) { setTimeout(() => { c.enqueue(new Uint8Array([65])); c.close(); }, 10); } }));
    case "/stream-err": return new Response(new ReadableStream({ start(c) { c.error(new Error("stream broke")); } }));
    case "/shutdown": setTimeout(() => server.shutdown(), 10); return new Response("bye");
  }
  return new Response("default");
});

