const port = Number(process.argv[2] || 18502);
const server = Lumen.serve({ port, hostname: "127.0.0.1" }, async (req) => {
  const u = new URL(req.url);
  const body = await req.text();
  console.log("req", req.method, JSON.stringify(req.url), JSON.stringify([...req.headers]), JSON.stringify(body));
  if (u.pathname === "/shutdown") { setTimeout(() => server.shutdown(), 10); }
  return new Response("echo:" + body, { headers: { "x-h": "1" } });
});
server.finished.then(() => console.log("finished"));

