const cp = require('child_process');
const t0 = Date.now();
const el = () => Math.round((Date.now() - t0) / 100);
const child = cp.spawn('sh', ['-c', '(sleep 0.3; echo late) & echo early; exit 0']);
child.stdout.on('data', (d) => console.log('data', JSON.stringify(String(d)), el()));
child.stdout.on('end', () => console.log('end', el()));
child.on('exit', (code, sig) => console.log('exit', code, sig, el()));
child.on('close', (code, sig) => console.log('close', code, sig, el()));
const c2 = cp.spawn('sh', ['-c', 'echo a; sleep 0.5; echo b']);
c2.stdout.on('data', (d) => console.log('c2 data', JSON.stringify(String(d)), el()));
c2.on('exit', (code) => console.log('c2 exit', code, el()));

