// Recursive-descent JavaScript parser.

use crate::ast::*;
use crate::lexer::{LexError, Lexer, Tok, Token};
use std::rc::Rc;

#[derive(Debug, Clone)]
pub struct ParseError {
    pub msg: String,
    pub line: u32,
}

impl From<LexError> for ParseError {
    fn from(e: LexError) -> Self {
        ParseError { msg: e.msg, line: e.line }
    }
}

type PResult<T> = Result<T, ParseError>;

#[derive(Clone, Copy, Default)]
struct Ctx {
    in_function: bool,
    in_generator: bool,
    in_async: bool,
    strict: bool,
    in_class_body: bool,
    allow_super_call: bool,
    allow_super_prop: bool,
    allow_new_target: bool,
    in_field_init: bool,
    in_static_block: bool,
    allow_return: bool,
    in_params: bool,
}

#[derive(Clone)]
struct Label {
    name: Rc<str>,
    is_loop: bool,
}

pub struct Parser {
    lex: Lexer,
    tok: Token,
    prev_end: usize,
    prev_line: u32,
    ctx: Ctx,
    labels: Vec<Label>,
    breakable_depth: u32,
    loop_depth: u32,
    is_module: bool,
    source: Rc<str>,
    template_counter: usize,
    has_tla: bool,
    /// private names declared in enclosing class bodies
    private_scopes: Vec<Vec<Rc<str>>>,
    /// unresolved private name references (checked when class body closes)
    private_refs: Vec<Vec<Rc<str>>>,
    /// number of cover-initialized names seen ({a = 1} in object literal) that are not yet converted
    cover_init_count: usize,
    pub repl_mode: bool,
}

struct SavedState {
    pos: usize,
    line: u32,
    tok: Token,
    prev_end: usize,
    prev_line: u32,
    cover: usize,
}

fn is_reserved_strict(name: &str) -> bool {
    matches!(
        name,
        "implements" | "interface" | "let" | "package" | "private" | "protected" | "public" | "static" | "yield"
    )
}

static TEMPLATE_ID: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(1);

impl Parser {
    pub fn new(src: &str, is_module: bool) -> PResult<Parser> {
        let mut lex = Lexer::new(src, is_module);
        let tok = lex.next_token()?;
        Ok(Parser {
            lex,
            tok,
            prev_end: 0,
            prev_line: 1,
            ctx: Ctx { allow_return: false, strict: is_module, in_async: false, ..Default::default() },
            labels: Vec::new(),
            breakable_depth: 0,
            loop_depth: 0,
            is_module,
            source: Rc::from(src),
            template_counter: 0,
            has_tla: false,
            private_scopes: Vec::new(),
            private_refs: Vec::new(),
            cover_init_count: 0,
            repl_mode: false,
        })
    }

    // ---------- token helpers ----------

    fn err<T>(&self, msg: impl Into<String>) -> PResult<T> {
        Err(ParseError { msg: msg.into(), line: self.tok.line })
    }

    fn err_line<T>(&self, msg: impl Into<String>, line: u32) -> PResult<T> {
        Err(ParseError { msg: msg.into(), line })
    }

    fn unexpected<T>(&self) -> PResult<T> {
        let desc = match &self.tok.tok {
            Tok::Punct(p) => format!("Punct({:?})", p),
            Tok::Keyword(k) => format!("Keyword({:?})", k),
            Tok::Eof => "Eof".to_string(),
            Tok::Ident(n) => format!("Ident({:?})", n),
            Tok::Num(n) => format!("Num({:?})", n),
            Tok::Str(s) => format!("Str({:?})", String::from_utf16_lossy(s)),
            Tok::BigInt(s) => format!("BigInt({:?})", s),
            Tok::Template { .. } => "Template".to_string(),
            Tok::Regex { .. } => "Regex".to_string(),
            Tok::PrivateName(n) => format!("PrivateName({:?})", n),
        };
        self.err(format!("unexpected token {}", desc))
    }

    fn advance(&mut self) -> PResult<Token> {
        let next = self.lex.next_token()?;
        let old = std::mem::replace(&mut self.tok, next);
        self.prev_end = old.end;
        self.prev_line = old.line;
        Ok(old)
    }

Value::Sym(_) => self.throw_type("Cannot convert Symbol to a BigInt"),
            _ => self.throw_type("Cannot convert value to a BigInt"),
        }
    }

    // ---------------- operators ----------------

    pub fn op_add(&mut self, a: &Value, b: &Value) -> JsResult<Value> {
        let pa = self.to_primitive(a, Hint::Default)?;
        let pb = self.to_primitive(b, Hint::Default)?;
        if matches!(pa, Value::Str(_)) || matches!(pb, Value::Str(_)) {
            let sa = self.to_string(&pa)?;
            let sb = self.to_string(&pb)?;
            return Ok(Value::Str(JsStr::concat(&sa, &sb)));
        }
        let na = self.to_numeric(&pa)?;
        let nb = self.to_numeric(&pb)?;
        match (&na, &nb) {
            (Value::Num(x), Value::Num(y)) => Ok(Value::Num(x + y)),
            (Value::BigInt(x), Value::BigInt(y)) => Ok(Value::BigInt(Rc::new(x.add(y)))),
            _ => self.throw_type("Cannot mix BigInt and other types, use explicit conversions"),
        }
    }

    pub fn op_arith(&mut self, op: Op, a: &Value, b: &Value) -> JsResult<Value> {
        let na = self.to_numeric(a)?;
        let nb = self.to_numeric(b)?;
        match (&na, &nb) {
            (Value::Num(x), Value::Num(y)) => Ok(crate::vm::num_binop(op, *x, *y)),
            (Value::BigInt(x), Value::BigInt(y)) => {
                let r = match op {
                    Op::Sub => Ok(x.sub(y)),
                    Op::Mul => Ok(x.mul(y)),
                    Op::Div => x.div(y).ok_or(crate::bigint::BigIntError::DivisionByZero),
                    Op::Mod => x.rem(y).ok_or(crate::bigint::BigIntError::DivisionByZero),
                    Op::Exp => x.pow(y),
                    Op::Shl => x.shl(y),
                    Op::Shr => x.shr(y),
                    Op::BitAnd => Ok(x.bitand(y)),
                    Op::BitOr => Ok(x.bitor(y)),
                    Op::BitXor => Ok(x.bitxor(y)),
                    Op::UShr => return self.throw_type("BigInts have no unsigned right shift, use >> instead"),
                    _ => return self.throw_type("unsupported BigInt operator"),
                };
                match r {
                    Ok(v) => Ok(Value::BigInt(Rc::new(v))),
                    Err(e) => self.throw_range(e.message()),
                }
            }
            _ => self.throw_type("Cannot mix BigInt and other types, use explicit conversions"),
        }
    }

    /// returns Some(true/false) or None for undefined (NaN)
    fn less_than(&mut self, a: &Value, b: &Value, left_first: bool) -> JsResult<Option<bool>> {
        let (pa, pb) = if left_first {
            let pa = self.to_primitive(a, Hint::Number)?;
            let pb = self.to_primitive(b, Hint::Number)?;
            (pa, pb)
        } else {
            let pb = self.to_primitive(b, Hint::Number)?;
            let pa = self.to_primitive(a, Hint::Number)?;
            (pa, pb)
        };
        if let (Value::Str(x), Value::Str(y)) = (&pa, &pb) {
            return Ok(Some(x.units() < y.units()));
        }
        if let (Value::BigInt(x), Value::Str(y)) = (&pa, &pb) {
            return Ok(BigInt::parse(y.units()).map(|yb| **x < yb));
        }
        if let (Value::Str(x), Value::BigInt(y)) = (&pa, &pb) {
            return Ok(BigInt::parse(x.units()).map(|xb| xb < **y));
        }
        let na = self.to_numeric(&pa)?;
        let nb = self.to_numeric(&pb)?;
        Ok(match (&na, &nb) {
            (Value::Num(x), Value::Num(y)) => {
                if x.is_nan() || y.is_nan() {
                    None
                } else {
                    Some(x < y)
                }
            }
            (Value::BigInt(x), Value::BigInt(y)) => Some(x < y),
            (Value::BigInt(x), Value::Num(y)) => x.cmp_f64(*y).map(|o| o == std::cmp::Ordering::Less),
            (Value::Num(x), Value::BigInt(y)) => y.cmp_f64(*x).map(|o| o == std::cmp::Ordering::Greater),
            _ => None,
        })
    }

    pub fn op_compare(&mut self, op: Op, a: &Value, b: &Value) -> JsResult<bool> {
        Ok(match op {
            Op::Lt => self.less_than(a, b, true)? == Some(true),
            Op::Gt => self.less_than(b, a, false)? == Some(true),
            Op::Le => self.less_than(b, a, false)? == Some(false),
            Op::Ge => self.less_than(a, b, true)? == Some(false),
            _ => false,
        })
    }

    pub fn loose_eq(&mut self, a: &Value, b: &Value) -> JsResult<bool> {
    vm.set_tag(&at, "Atomics");
    vm.def_global("Atomics", Value::Obj(at));
}

pub fn ta_kind_index(k: TAKind) -> usize {
    TAKind::all().iter().position(|x| *x == k).unwrap()
}

fn kind_from_slot(a: &Args) -> TAKind {
    TAKind::all()[a.slot(0).as_num().unwrap() as usize]
}

// ---------------- ArrayBuffer ----------------

pub fn new_array_buffer(vm: &Vm, bytes: Vec<u8>) -> Obj {
    let data = Rc::new(RefCell::new(BufferData { bytes, detached: false, max_len: None, shared: false }));
    Obj::with_class(Some(vm.intr.array_buffer_proto.clone()), ObjKind::ArrayBuffer(data), "ArrayBuffer")
}

fn array_buffer_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.new_target.is_none() {
        return vm.throw_type("Constructor ArrayBuffer requires 'new'");
    }
    let len = vm.to_index(&a.arg(0))?;
    let mut max = None;
    if let Value::Obj(o) = a.arg(1) {
        let m = vm.get_str(&o, "maxByteLength")?;
        if !m.is_undefined() {
            let ml = vm.to_index(&m)?;
            if len > ml {
                return vm.throw_range("Invalid array buffer max length");
            }
            max = Some(ml);
        }
    }
    let proto = vm.proto_from_nt(&a.new_target, &vm.intr.array_buffer_proto.clone())?;
    if len > 0x7fff_ffff {
        return vm.throw_range("Array buffer allocation failed");
    }
    let data = Rc::new(RefCell::new(BufferData { bytes: vec![0; len], detached: false, max_len: max, shared: false }));
    Ok(Value::Obj(Obj::with_class(Some(proto), ObjKind::ArrayBuffer(data), "ArrayBuffer")))
}

fn shared_array_buffer_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.new_target.is_none() {
        return vm.throw_type("Constructor SharedArrayBuffer requires 'new'");
    }
    let len = vm.to_index(&a.arg(0))?;
    let mut max = None;
    if let Value::Obj(o) = a.arg(1) {
        let m = vm.get_str(&o, "maxByteLength")?;
        if !m.is_undefined() {
            let ml = vm.to_index(&m)?;
            if len > ml {
                return vm.throw_range("Invalid array buffer max length");
            }
            max = Some(ml);
        }
    }
    let proto = vm.proto_from_nt(&a.new_target, &vm.intr.shared_array_buffer_proto.clone())?;
    let data = Rc::new(RefCell::new(BufferData { bytes: vec![0; len], detached: false, max_len: max, shared: true }));
    Ok(Value::Obj(Obj::with_class(Some(proto), ObjKind::ArrayBuffer(data), "SharedArrayBuffer")))
}

fn this_buffer(vm: &mut Vm, v: &Value) -> JsResult<Rc<RefCell<BufferData>>> {
    match v {
        Value::Obj(o) => match &o.borrow().kind {
            ObjKind::ArrayBuffer(b) => Ok(b.clone()),
            _ => Err(vm.make_error("TypeError", "method called on incompatible receiver")),
        },
        _ => vm.throw_type("method called on incompatible receiver"),
    }
}

fn is_view(_vm: &mut Vm, a: &Args) -> JsResult<Value> {
    Ok(Value::Bool(matches!(&a.arg(0), Value::Obj(o) if matches!(o.borrow().kind, ObjKind::TypedArray(_) | ObjKind::DataView(_)))))
}

fn ab_byte_length(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let b = this_buffer(vm, &a.this)?;
    let b = b.borrow();
    Ok(Value::Num(if b.detached { 0.0 } else { b.bytes.len() as f64 }))
}

fn ab_max_byte_length(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let b = this_buffer(vm, &a.this)?;
    let b = b.borrow();
    if b.detached {
        return Ok(Value::Num(0.0));
    }
    Ok(Value::Num(b.max_len.unwrap_or(b.bytes.len()) as f64))
}

fn ab_resizable(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let b = this_buffer(vm, &a.this)?;
    let r = b.borrow().max_len.is_some();
    Ok(Value::Bool(r))
}

fn ab_detached(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let b = this_buffer(vm, &a.this)?;
    let r = b.borrow().detached;
    Ok(Value::Bool(r))
}

fn ab_slice(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let b = this_buffer(vm, &a.this)?;
    if b.borrow().detached {
        return vm.throw_type("Cannot perform ArrayBuffer.prototype.slice on a detached ArrayBuffer");
    }
    let len = b.borrow().bytes.len() as f64;
    let s = vm.to_integer_or_infinity(&a.arg(0))?;
    let first = if s < 0.0 { (len + s).max(0.0) } else { s.min(len) };
    let e = if a.arg(1).is_undefined() { len } else { vm.to_integer_or_infinity(&a.arg(1))? };
    let fin = if e < 0.0 { (len + e).max(0.0) } else { e.min(len) };
    let n = (fin - first).max(0.0) as usize;
    let shared = b.borrow().shared;
    let bytes = b.borrow().bytes[first as usize..first as usize + n].to_vec();
    let proto = if shared { vm.intr.shared_array_buffer_proto.clone() } else { vm.intr.array_buffer_proto.clone() };
    let data = Rc::new(RefCell::new(BufferData { bytes, detached: false, max_len: None, shared }));
    Ok(Value::Obj(Obj::with_class(Some(proto), ObjKind::ArrayBuffer(data), if shared { "SharedArrayBuffer" } else { "ArrayBuffer" })))
}

fn ab_resize(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let b = this_buffer(vm, &a.this)?;
    let max = match b.borrow().max_len {
        Some(m) => m,
        None => return Err(vm.make_error("TypeError", "Method ArrayBuffer.prototype.resize called on incompatible receiver")),
    };
    let n = vm.to_index(&a.arg(0))?;
    if b.borrow().detached {
        return vm.throw_type("Cannot perform ArrayBuffer.prototype.resize on a detached ArrayBuffer");
    }
    if n > max {
        return vm.throw_range("ArrayBuffer.prototype.resize: Invalid length parameter");
    }
    b.borrow_mut().bytes.resize(n, 0);
    Ok(Value::Undefined)
}

fn transfer_impl(vm: &mut Vm, a: &Args, fixed: bool) -> JsResult<Value> {
    let b = this_buffer(vm, &a.this)?;
    if b.borrow().shared {
        return vm.throw_type("Cannot transfer a SharedArrayBuffer");
    }
    let new_len = if a.arg(0).is_undefined() { b.borrow().bytes.len() } else { vm.to_index(&a.arg(0))? };
    if b.borrow().detached {
        return vm.throw_type("Cannot perform ArrayBuffer.prototype.transfer on a detached ArrayBuffer");
    }
    let mut bytes = std::mem::take(&mut b.borrow_mut().bytes);
    bytes.resize(new_len, 0);
    let max = if fixed { None } else { b.borrow().max_len };
    b.borrow_mut().detached = true;
    let data = Rc::new(RefCell::new(BufferData { bytes, detached: false, max_len: max, shared: false }));
    Ok(Value::Obj(Obj::with_class(Some(vm.intr.array_buffer_proto.clone()), ObjKind::ArrayBuffer(data), "ArrayBuffer")))
}

fn ab_transfer(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    transfer_impl(vm, a, false)
}
fn ab_transfer_fixed(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    transfer_impl(vm, a, true)
}

pub fn detach_buffer(o: &Obj) {
    if let ObjKind::ArrayBuffer(b) = &o.borrow().kind {
        let mut bb = b.borrow_mut();
        bb.bytes = Vec::new();
        bb.detached = true;
    }
}

// ---------------- DataView ----------------

fn data_view_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.new_target.is_none() {
        return vm.throw_type("Constructor DataView requires 'new'");
    }
    let (bo, buf) = match a.arg(0) {
        Value::Obj(o) => {
            let b = match &o.borrow().kind {
                ObjKind::ArrayBuffer(b) => Some(b.clone()),
                _ => None,
            };
            match b {
                Some(b) => (o.clone(), b),
                None => return vm.throw_type("First argument to DataView constructor must be an ArrayBuffer"),
            }
        }
        _ => return vm.throw_type("First argument to DataView constructor must be an ArrayBuffer"),
    };
    let off = vm.to_index(&a.arg(1))?;
    if buf.borrow().detached {
        return vm.throw_type("Cannot construct a DataView on a detached ArrayBuffer");
    }
    let blen = buf.borrow().bytes.len();
    if off > blen {
        return vm.throw_range("Start offset is outside the bounds of the buffer");
    }
    let tracking = a.arg(2).is_undefined() && buf.borrow().max_len.is_some();
    let length = if a.arg(2).is_undefined() {
        if tracking {
            None
        } else {
            Some(blen - off)
        }
    } else {
        let l = vm.to_index(&a.arg(2))?;
        if off + l > blen {
            return vm.throw_range("Invalid DataView length");
        }
        Some(l)
    };
    let proto = vm.proto_from_nt(&a.new_target, &vm.intr.data_view_proto.clone())?;
    Ok(Value::Obj(Obj::with_class(Some(proto), ObjKind::DataView(Box::new(DataViewData { buffer: bo, buf, offset: off, length })), "DataView")))
}

fn this_dv(vm: &mut Vm, v: &Value) -> JsResult<(Obj, Rc<RefCell<BufferData>>, usize, Option<usize>)> {
    match v {
        Value::Obj(o) => match &o.borrow().kind {
            ObjKind::DataView(d) => Ok((d.buffer.clone(), d.buf.clone(), d.offset, d.length)),
            _ => Err(vm.make_error("TypeError", "method called on incompatible receiver")),
        },
        _ => vm.throw_type("method called on incompatible receiver"),
    }
}

fn dv_view_len(vm: &mut Vm, buf: &Rc<RefCell<BufferData>>, off: usize, len: Option<usize>) -> JsResult<usize> {
    let b = buf.borrow();
    if b.detached {
        drop(b);
        return vm.throw_type("Cannot perform DataView operation on a detached ArrayBuffer");
    }
    let bl = b.bytes.len();
    match len {
        Some(l) => {
            if off + l > bl {
                drop(b);
                return vm.throw_type("DataView is out of bounds");
            }
            Ok(l)
        }
        None => {
            if off > bl {
                drop(b);
                return vm.throw_type("DataView is out of bounds");
            }
            Ok(bl - off)
        }
    }
}

fn dv_buffer(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (bo, _, _, _) = this_dv(vm, &a.this)?;
    Ok(Value::Obj(bo))
}
fn dv_byte_length(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (_, buf, off, len) = this_dv(vm, &a.this)?;
    Ok(Value::Num(dv_view_len(vm, &buf, off, len)? as f64))
}
fn dv_byte_offset(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (_, buf, off, len) = this_dv(vm, &a.this)?;
    dv_view_len(vm, &buf, off, len)?;
    Ok(Value::Num(off as f64))
}

fn dv_get(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let kind = kind_from_slot(a);
    let (_, buf, off, len) = this_dv(vm, &a.this)?;
    let idx = vm.to_index(&a.arg(0))?;
    let little = a.arg(1).truthy();
    let vl = dv_view_len(vm, &buf, off, len)?;
    if idx + kind.size() > vl {
        return vm.throw_range("Offset is outside the bounds of the DataView");
    }
    let b = buf.borrow();
    Ok(read_elem(&b.bytes, off + idx, kind, little))
}

fn dv_set(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let kind = kind_from_slot(a);
    let (_, buf, off, len) = this_dv(vm, &a.this)?;
    let idx = vm.to_index(&a.arg(0))?;
    let v = if kind.is_bigint() { Value::BigInt(vm.to_bigint(&a.arg(1))?) } else { Value::Num(vm.to_number(&a.arg(1))?) };
    let little = a.arg(2).truthy();
    let vl = dv_view_len(vm, &buf, off, len)?;
    if idx + kind.size() > vl {
        return vm.throw_range("Offset is outside the bounds of the DataView");
    }
    let mut b = buf.borrow_mut();
    write_elem(&mut b.bytes, off + idx, kind, &v, little);
    Ok(Value::Undefined)
}

// ---------------- typed array construction ----------------

fn typed_array_abstract_ctor(vm: &mut Vm, _a: &Args) -> JsResult<Value> {
    vm.throw_type("Abstract class TypedArray not directly constructable")
}

pub fn create_typed_array(vm: &mut Vm, kind: TAKind, len: usize, proto: Option<Obj>) -> JsResult<Obj> {
    if len > MAX_TA_LENGTH {
        return vm.throw_range("Invalid typed array length");
    }
    let buf = Rc::new(RefCell::new(BufferData { bytes: vec![0; len * kind.size()], detached: false, max_len: None, shared: false }));
    let bo = Obj::with_class(Some(vm.intr.array_buffer_proto.clone()), ObjKind::ArrayBuffer(buf.clone()), "ArrayBuffer");
    let p = proto.unwrap_or_else(|| vm.intr.ta_protos[ta_kind_index(kind)].clone());
    Ok(Obj::with_class(Some(p), ObjKind::TypedArray(Box::new(TypedArrayData { kind, buffer: bo, buf, offset: 0, length: Some(len) })), kind.name()))
}

pub fn typed_array_from_bytes(vm: &mut Vm, bytes: Vec<u8>) -> Obj {
    let len = bytes.len();
    let buf = Rc::new(RefCell::new(BufferData { bytes, detached: false, max_len: None, shared: false }));
    let bo = Obj::with_class(Some(vm.intr.array_buffer_proto.clone()), ObjKind::ArrayBuffer(buf.clone()), "ArrayBuffer");
    let p = vm.intr.ta_protos[1].clone();
    Obj::with_class(Some(p), ObjKind::TypedArray(Box::new(TypedArrayData { kind: TAKind::Uint8, buffer: bo, buf, offset: 0, length: Some(len) })), "Uint8Array")
}

fn ta_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let kind = kind_from_slot(a);
    if a.new_target.is_none() {
        return vm.throw_type("TypedArray constructor requires 'new'");
    }
    let proto = vm.proto_from_nt(&a.new_target, &vm.intr.ta_protos[ta_kind_index(kind)].clone())?;
    let first = a.arg(0);
    match &first {
        Value::Obj(o) => {
            enum Src {
                Buffer(Rc<RefCell<BufferData>>),
                Typed(TAKind, Vec<Value>),
                Other,
            }
            let src = match &o.borrow().kind {
                ObjKind::ArrayBuffer(b) => Src::Buffer(b.clone()),
                ObjKind::TypedArray(t) => {
                    let n = t.len();
                    let b = t.buf.borrow();
                    let vals: Vec<Value> = (0..n).map(|i| read_elem(&b.bytes, t.offset + i * t.kind.size(), t.kind, true)).collect();
                    Src::Typed(t.kind, vals)
                }
                _ => Src::Other,
            };
            match src {
                Src::Buffer(buf) => {
                    let off = vm.to_index(&a.arg(1))?;
                    if off % kind.size() != 0 {
                        return vm.throw_range("byteOffset is not aligned to the element size");
                    }
                    if buf.borrow().detached {
                        return vm.throw_type("Cannot construct a typed array on a detached ArrayBuffer");
                    }
                    let blen = buf.borrow().bytes.len();
                    let length = if a.arg(2).is_undefined() {
                        if buf.borrow().max_len.is_some() {
                            if off > blen {
                                return vm.throw_range("Start offset is outside the bounds of the buffer");
                            }
                            None
                        } else {
                            if blen % kind.size() != 0 {
                                return vm.throw_range("buffer length is not a multiple of the element size");
                            }
                            if off > blen {
                                return vm.throw_range("Start offset is outside the bounds of the buffer");
                            }
                            Some((blen - off) / kind.size())
                        }
                    } else {
                        let l = vm.to_index(&a.arg(2))?;
                        if off + l * kind.size() > blen {
                            return vm.throw_range("Invalid typed array length");
                        }
                        Some(l)
                    };
                    Ok(Value::Obj(Obj::with_class(Some(proto), ObjKind::TypedArray(Box::new(TypedArrayData { kind, buffer: o.clone(), buf, offset: off, length })), kind.name())))
                }
                Src::Typed(sk, vals) => {
                    if sk.is_bigint() != kind.is_bigint() {
                        return vm.throw_type("Content type mismatch between source and target typed arrays");
                    }
                    let t = create_typed_array(vm, kind, vals.len(), Some(proto))?;
                    fill_from_values(vm, &t, &vals)?;
                    Ok(Value::Obj(t))
                }
                Src::Other => {
                    let im = vm.get(o, &PropKey::Sym(vm.intr.sym_iterator.clone()), &first)?;
                    let vals = if !im.is_nullish() {
                        if !im.is_callable() {
                            return vm.throw_type("value is not iterable");
                        }
                        vm.iterate_to_vec(&first)?
                    } else {
                        crate::builtins::array::array_like_to_vec(vm, &first)?
                    };
                    let t = create_typed_array(vm, kind, vals.len(), Some(proto))?;
                    fill_from_values(vm, &t, &vals)?;
                    Ok(Value::Obj(t))
                }
            }
        }
        _ => {
            let n = if first.is_undefined() {
                0
            } else {
                let x = vm.to_integer_or_infinity(&first)?;
                if !(0.0..=9007199254740991.0).contains(&x) {
                    return vm.throw_range("index out of range");
                }
                x as usize
            };
            Ok(Value::Obj(create_typed_array(vm, kind, n, Some(proto))?))
        }
    }
}

fn fill_from_values(vm: &mut Vm, t: &Obj, vals: &[Value]) -> JsResult<()> {
    for (i, v) in vals.iter().enumerate() {
        ta_set_index(vm, t, i as f64, v)?;
    }
    Ok(())
}

pub fn this_ta(vm: &mut Vm, v: &Value) -> JsResult<(Obj, TAKind, usize)> {
    match v {
        Value::Obj(o) => {
            let r = match &o.borrow().kind {
                ObjKind::TypedArray(t) => Some((t.kind, t.len(), t.is_out_of_bounds())),
                _ => None,
            };
            match r {
                Some((k, l, oob)) => {
                    if oob {
                        return vm.throw_type("Cannot perform %TypedArray%.prototype method on a detached ArrayBuffer");
                    }
                    Ok((o.clone(), k, l))
                }
                None => vm.throw_type("this is not a typed array."),
            }
        }
        _ => vm.throw_type("this is not a typed array."),
    }
}

pub fn ta_values_vec(o: &Obj) -> Vec<Value> {
    let b = o.borrow();
    match &b.kind {
        ObjKind::TypedArray(t) => {
            let n = t.len();
            let bb = t.buf.borrow();
            (0..n).map(|i| read_elem(&bb.bytes, t.offset + i * t.kind.size(), t.kind, true)).collect()
        }
        _ => Vec::new(),
    }
}

pub fn ta_bytes(o: &Obj) -> Vec<u8> {
    let b = o.borrow();
    match &b.kind {
        ObjKind::TypedArray(t) => {
            let n = t.len() * t.kind.size();
            let bb = t.buf.borrow();
            bb.bytes[t.offset..t.offset + n].to_vec()
        }
        ObjKind::ArrayBuffer(bd) => bd.borrow().bytes.clone(),
        ObjKind::DataView(d) => {
            let bb = d.buf.borrow();
            let l = d.length.unwrap_or(bb.bytes.len() - d.offset);
            bb.bytes[d.offset..d.offset + l].to_vec()
        }
        _ => Vec::new(),
    }

