    super(parts, options);
    this[kFileName] = String(name);
    this[kFileLastMod] =
      options && options.lastModified !== undefined ? Number(options.lastModified) : Date.now();
  }
  get name() {
    return this[kFileName];
  }
  get lastModified() {
    return this[kFileLastMod];
  }
  get [Symbol.toStringTag]() {
    return "File";
  }
}

