                if let Err(e) = self.call(&f, Value::Undefined, &args) {
                    self.report_uncaught(e);
                }
            }
            Job::Native(f, v) => {
                if let Err(e) = f(self, v) {
                    self.report_uncaught(e);
                }
            }
        }
    }

    pub fn run_microtasks(&mut self) {
        while let Some(j) = self.jobs.pop_front() {
            self.run_job(j);
        }
    }

