        }
        match o.props.get(key) {
            Some(Prop::Data { value, .. }) => Some(value.clone()),
            _ => None,
        }
    }
    pub fn get_own_str(&self, key: &str) -> Option<Value> {
        self.get_own_data(&PropKey::from_str(key))
    }
