#!/bin/bash
# feed each line (alone) to repl; show output
BIN=${1:-/tmp/orig}
F=${2:-/tmp/cliagent/probe_cont2.txt}
while IFS= read -r line; do
  printf '%-40s => ' "$line"
  printf '%s\n' "$line" | timeout 5 $BIN repl 2>&1 | tail -n +2 | tr '\n' '|'
  echo
done < $F

