                }
                self.get(o, key, base)
            }
            Value::Str(s) => {
                if let Some(i) = key.as_index() {
                    if (i as usize) < s.len() {
                        return Ok(Value::Str(JsStr::from_units(vec![s.units()[i as usize]])));
                    }
                } else if key.eq_str("length") {
                    return Ok(Value::Num(s.len() as f64));
