q('re with custom', () => { const r = /x/; r[util.inspect.custom] = () => 'RCUSTOM'; return util.inspect(r); });
q('buffer with custom', () => { const b = Buffer.from('a'); b[util.inspect.custom] = () => 'BCUSTOM'; return util.inspect(b); });
q('circ with custom', () => { const o = { [util.inspect.custom]() { return 'OC'; } }; o.self = o; return util.inspect(o); });
q('circ custom returns this', () => { const o = { a: 1, [util.inspect.custom]() { return this; } }; return util.inspect({ o }); });
q('circ depth 0', () => { const a = { x: 1 }; a.a = a; return util.inspect(a, { depth: 0 }); });
q('circ arr depth 0', () => { const a = [1]; a.push(a); return util.inspect(a, { depth: 0 }); });
q('circ nested depth 1', () => { const a = { b: { c: {} } }; a.b.c.a = a; return util.inspect(a, { depth: 1 }); });
q('custom this', () => { const o = { tag: 'T', [util.inspect.custom]() { return this.tag; } }; return util.inspect([o]); });
q('custom getter', () => { const o = { get [util.inspect.custom]() { return () => 'GETTER'; } }; return util.inspect(o); });
q('custom on primitive wrapper', () => { const n = new Number(5); n[util.inspect.custom] = () => 'NUMC'; return util.inspect(n); });
q('custom returns symbol', () => util.inspect({ [util.inspect.custom]() { return Symbol('rs'); } }));
q('custom returns null', () => util.inspect({ k: { [util.inspect.custom]() { return null; } } }));
