pub fn array_push_raw(a: &Obj, v: Value) {
    let mut b = a.borrow_mut();
    if let ObjKind::Array(ad) = &mut b.kind {
        if !ad.sparse {
            if ad.dense.len() as u32 == ad.len {
                ad.dense.push(v);
                ad.len += 1;
                return;
            }
        }
        let i = ad.len;
        ad.len += 1;
        if !v.is_empty() {
            drop(b);
            a.set_prop(PropKey::from_index(i), v, WEC);
        }
    }
}

