#!/usr/bin/env python3
import socket, sys
port = int(sys.argv[1])
codes = list(range(200, 600)) + [0]
for code in codes:
    s = socket.socket()
    s.settimeout(3)
    s.connect(("127.0.0.1", port))
    s.sendall(b"GET /" + str(code).encode() + b" HTTP/1.1\r\nHost: x\r\n\r\n")
    resp = b""
    while True:
        try:
            c = s.recv(65536)
