const ca = new Intl.Collator('en', {sensitivity: 'accent'}).compare;
const cc = new Intl.Collator('en', {sensitivity: 'case'}).compare;
const ascii = [];
for (let i = 32; i < 127; i++) ascii.push(String.fromCharCode(i));
const tests = ['ß', 'æ', 'Æ', 'ø', 'Ø', 'ł', 'Ł', 'đ', 'Đ', 'ı', 'İ', 'ŀ', 'ĸ', 'þ', 'Þ', 'ð', 'Ð', 'œ', 'Œ', 'ŉ', 'ſ', 'ﬁ', '①', 'ｱ', 'Ａ', 'ａ', 'é', 'É', 'è', 'ê', 'ë', 'ē', 'ñ', 'Ñ', 'ç', 'å', 'Å', 'ä', 'ö', 'ü', 'ÿ', 'Ÿ', 'α', 'Α', 'ω', 'а', 'А', 'я', 'ё', 'Ё', '中', '一', '가', 'ا', 'א', '😀', '€', '£', '¥', '©', '®', '°', '±', '×', '÷', '¿', '¡', '«', '»', ' ', ' ', '​', '́', 'ǅ', 'ǆ', 'Ǆ', 'ﬀ', '²', '½', '™', 'ª', 'º', 'µ', 'Ω', 'Ω', 'Å', 'K', '\u0000', '﻿', '�', 'ꝺ', 'ɑ', 'ŋ', 'Ŋ', 'ə', 'ʃ'];
function pos(x) {
  // first ascii char that is > x at variant level
  let i = 0;
  while (i < ascii.length && cv(ascii[i], x) < 0) i++;
  const eqb = ascii.filter(a => cb(a, x) === 0).join('');
  const eqa = ascii.filter(a => ca(a, x) === 0).join('');
  const eqc = ascii.filter(a => cc(a, x) === 0).join('');
  return 'before ' + JSON.stringify(ascii[i] || 'END') + ' base=' + JSON.stringify(eqb) + ' accent=' + JSON.stringify(eqa) + ' case=' + JSON.stringify(eqc);
}
for (const t of tests) {
  console.log(JSON.stringify(t) + ' U+' + t.codePointAt(0).toString(16) + ': ' + pos(t));
}
// two-char expansions
const two = [];
for (const a of 'abcdefghijklmnopqrstuvwxyz') for (const b of 'abcdefghijklmnopqrstuvwxyz') two.push(a + b);
for (const t of ['ß', 'æ', 'œ', 'ﬁ', 'ﬀ', 'ǆ', 'ĳ', 'ŉ', 'Æ', 'ẞ']) {
  console.log(JSON.stringify(t) + ' base-eq two: ' + two.filter(x => cb(x, t) === 0).join(',') + ' | variant between: ' + (() => { let i = 0; while (i < two.length && cv(two[i], t) < 0) i++; return two[i - 1] + '<x<' + two[i]; })());
}

