fn array_from(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let items = a.arg(0);
    let mapfn = a.arg(1);
    let this_arg = a.arg(2);
    if !mapfn.is_undefined() && !mapfn.is_callable() {
        return vm.throw_type("Array.from: mapFn is not callable");
