const assert = require('assert');
const util = require('util');
const out = [];
function p(x) { out.push(x); }
function q(label, f) {
  try { f(); p(label + ': no throw'); }
  catch (e) { p(label + ' THREW ' + (e && e.name) + ' msg=' + JSON.stringify(e && e.message) + ' op=' + (e && e.operator) + (e instanceof assert.AssertionError ? ' act=' + util.inspect(e.actual).split('\n')[0] + ' exp=' + util.inspect(e.expected).split('\n')[0] : '') + (e && e.stack && e instanceof assert.AssertionError ? ' frames=' + e.stack.split('\n').slice(1, 4).map(s => s.trim()).join('|') : '')); }
}
q('ok num msg', () => assert.ok(false, 5));
q('ok obj msg', () => assert.ok(false, { a: 1 }));
q('ok empty msg', () => assert.ok(false, ''));
q('ok null msg', () => assert.ok(false, null));
q('ok sym msg', () => assert.ok(false, Symbol('s')));
q('strictEqual null msg', () => assert.strictEqual(1, 2, null));
q('strictEqual 0 msg', () => assert.strictEqual(1, 2, 0));
q('strictEqual empty msg', () => assert.strictEqual(1, 2, ''));
q('notStrictEqual NaN', () => assert.notStrictEqual(NaN, NaN));
q('notStrictEqual 0 -0', () => assert.notStrictEqual(0, -0));
q('fail num', () => assert.fail(5));
q('fail obj', () => assert.fail({ a: 1 }));
q('fail null', () => assert.fail(null));
q('fail empty', () => assert.fail(''));
q('throws msg num', () => assert.throws(() => {}, undefined, 5));
q('throws validator 1', () => assert.throws(() => { throw new Error('x'); }, () => 1));
q('throws validator undefined', () => assert.throws(() => { throw new Error('x'); }, () => undefined));
