const cp = require('child_process');
function run(cmd, cb) {
  const out = [];
  const child = cp.spawn('sh', ['-c', cmd]);
  child.stdout.on('data', (d) => out.push('out:' + JSON.stringify(String(d))));
  child.stderr.on('data', (d) => out.push('err:' + JSON.stringify(String(d))));
  child.stdout.on('end', () => out.push('out-end'));
  child.stderr.on('end', () => out.push('err-end'));
  child.on('exit', (c) => out.push('exit ' + c));
  child.on('close', (c) => { out.push('close ' + c); console.log(cmd, '=>', out.join(' ')); cb && cb(); });
}
run('echo e >&2; echo o', () =>
  run('echo o; echo e >&2', () =>
    run('echo e >&2; sleep 0.05; echo o', () =>
      run('echo o; sleep 0.05; echo e >&2; exit 2', () =>
        run('exec 2>&-; echo o', () =>
          run('exec 1>&-; echo e >&2; sleep 0.05', () =>
            run('true')))))));

