const cp = require('child_process');
function run(label, attach, cb) {
  const out = [];
  const child = cp.spawn('sh', ['-c', 'true']);
  attach(child, out);
  child.on('exit', (c) => out.push('exit ' + c));
  child.on('close', (c) => { setTimeout(() => { console.log(label, '=>', out.join(' ')); cb && cb(); }, 50); });
}
run('end-only', (child, out) => {
  child.stdout.on('end', () => out.push('out-end'));
  child.stderr.on('end', () => out.push('err-end'));
}, () => run('err-data-first', (child, out) => {
  child.stderr.on('data', () => {});
  child.stdout.on('data', () => {});
  child.stdout.on('end', () => out.push('out-end'));
  child.stderr.on('end', () => out.push('err-end'));
}, () => run('none', (child, out) => {
  child.stdout.on('end', () => out.push('out-end'));
}, () => {
  const c = cp.spawn('sh', ['-c', 'echo hi']);
  setTimeout(() => {
    console.log('late state', JSON.stringify(c.stdout._readableState));
    c.stdout.on('data', d => console.log('late data', String(d)));
    c.stdout.on('end', () => console.log('late end'));
  }, 100);
})));

