const cp = require('child_process');
const configs = [
  ['pipe', 'pipe', 'pipe'],
  ['ignore', 'pipe', 'pipe'],
  ['pipe', 'pipe', 'inherit'],
  ['ignore', 'pipe', 'inherit'],
  ['ignore', 'pipe', 'ignore'],
  ['pipe', 'pipe', 'ignore'],
];
let i = 0;
function next() {
  if (i >= configs.length) return;
  const cfg = configs[i++];
  const out = [];
  const c = cp.spawn('sh', ['-c', 'echo out'], { stdio: cfg });
  c.stdout.on('data', d => out.push('data'));
  c.stdout.on('end', () => out.push('end'));
  c.on('exit', () => out.push('exit'));
  c.on('close', () => { out.push('close'); setTimeout(() => { console.log(JSON.stringify(cfg), out.join(' ')); next(); }, 20); });
}
next();

