  transform(chunk, c) { L("transform " + chunk); c.enqueue(String(chunk).toUpperCase()); },
  flush(c) { L("flush"); c.enqueue("END"); },
});
const w = ts.writable.getWriter();
const r = ts.readable.getReader();
w.write("a").then(() => L("write a done"));
w.write("b").then(() => L("write b done"));
w.close().then(() => L("close done"));
(async () => {
  while (true) {
    const { value, done } = await r.read();
    L("read " + value + " " + done);
    if (done) break;
  }
})();
Promise.resolve().then(() => L("m1")).then(() => L("m2")).then(() => L("m3")).then(() => L("m4")).then(() => L("m5")).then(() => L("m6")).then(() => L("m7")).then(() => L("m8")).then(() => L("m9")).then(() => L("m10"));
