const cp = require('child_process');
if (process.argv[2] === 'child-send') {
  process.send({ from: 'child' });
  console.log('child after send');
} else if (process.argv[2] === 'child-listen') {
  process.on('message', (m) => { console.log('child got', JSON.stringify(m)); });
  console.log('child listening');
} else if (process.argv[2] === 'child-none') {
  console.log('child none', process.connected);
} else {
  const t0 = Date.now();
  const a = cp.fork(__filename, ['child-send']);
  a.on('message', m => console.log('A message', JSON.stringify(m)));
  a.on('exit', (c) => {
    console.log('A exit', c, Date.now() - t0 < 1500);
    const b = cp.fork(__filename, ['child-listen']);
    b.send({ x: 1 });
    setTimeout(() => b.send({ x: 2 }), 50);
    setTimeout(() => b.disconnect(), 100);
    b.on('exit', (c) => {
      console.log('B exit', c);
      const d = cp.fork(__filename, ['child-none'], { silent: true });
      d.stdout.on('data', x => console.log('D stdout', JSON.stringify(String(x))));
      d.on('exit', c => console.log('D exit', c, d.connected));
    });
  });
  setTimeout(() => { console.log('parent timeout, disconnecting A'); a.disconnect(); }, 1000);
}

