if (process.argv[2] === 'child') {
  process.on('message', (m) => { console.error('child got', JSON.stringify(m)); });
  process.on('disconnect', () => console.error('child disconnect event', process.connected));
  process.stdin.on && console.error('child stdin readable?', typeof process.stdin.on);
} else {
  const b = cp.fork(__filename, ['child']);
  b.send({ x: 1 }, (err) => console.log('send cb', err));
  b.send('str');
  b.send(undefined);
  b.send([1, 2]);
  setTimeout(() => b.disconnect(), 100);
  b.on('exit', (c) => {
    console.log('B exit', c, b.connected);
    try { console.log('send after', b.send({ late: 1 })); } catch (e) { console.log('send after throw', e.message); }
    b.on('error', e => console.log('B error', e.message, e.code));
  });
}

