// Extract DisplayNames tables: usage: gen_dn.js <locale>
const loc = process.argv[2] || 'en';
const A = 'abcdefghijklmnopqrstuvwxyz';
const U = A.toUpperCase();
const out = [];
const styles = ['long', 'short', 'narrow'];
function dn(type, style) { return new Intl.DisplayNames(loc, {type, style, fallback: 'none'}); }
function q(d, c) { try { return d.of(c); } catch (e) { return 'ERR'; } }
for (const style of styles) {
  // regions
  const r = dn('region', style);
  for (const a of U) for (const b of U) { const v = q(r, a + b); if (v !== undefined && v !== 'ERR') out.push(`region ${style} ${a}${b} ${v}`); }
  for (let i = 0; i < 1000; i++) { const c = String(i).padStart(3, '0'); const v = q(r, c); if (v !== undefined && v !== 'ERR') out.push(`region ${style} ${c} ${v}`); }
  // languages
  const l = dn('language', style);
  const ls = new Intl.DisplayNames(loc, {type: 'language', style, fallback: 'none', languageDisplay: 'standard'});
  const found = [];
  for (const a of A) for (const b of A) { const v = q(l, a + b); if (v !== undefined && v !== 'ERR') { out.push(`language ${style} ${a}${b} ${v}`); found.push(a + b); } }
  for (const a of A) for (const b of A) for (const c of A) { const v = q(l, a + b + c); if (v !== undefined && v !== 'ERR') { out.push(`language ${style} ${a}${b}${c} ${v}`); found.push(a + b + c); } }
  // dialects for found languages
  for (const f of found) {
    for (const a of U) for (const b of U) { const v = q(l, f + '-' + a + b); if (v !== undefined && v !== 'ERR') out.push(`language ${style} ${f}-${a}${b} ${v}`); const v2 = q(ls, f + '-' + a + b); if (v2 !== v) out.push(`languageStd ${style} ${f}-${a}${b} ${v2}`); }
    for (const s of ['Latn', 'Cyrl', 'Arab', 'Hans', 'Hant', 'Jpan', 'Kore', 'Deva', 'Grek']) { const v = q(l, f + '-' + s); if (v !== undefined && v !== 'ERR') out.push(`language ${style} ${f}-${s} ${v}`); }
    for (const rr of ['419', '001', '150']) { const v = q(l, f + '-' + rr); if (v !== undefined && v !== 'ERR') out.push(`language ${style} ${f}-${rr} ${v}`); }
  }
  // scripts
  const s = dn('script', style);
  for (const a of U) for (const b of A) for (const c of A) for (const d of A) { const v = q(s, a + b + c + d); if (v !== undefined && v !== 'ERR') out.push(`script ${style} ${a}${b}${c}${d} ${v}`); }
  // currencies
  const cu = dn('currency', style);
  for (const a of U) for (const b of U) for (const c of U) { const v = q(cu, a + b + c); if (v !== undefined && v !== 'ERR') out.push(`currency ${style} ${a}${b}${c} ${v}`); }
  // calendars
  const ca = dn('calendar', style);
  for (const c of ['buddhist', 'chinese', 'coptic', 'dangi', 'ethioaa', 'ethiopic', 'gregory', 'hebrew', 'indian', 'islamic', 'islamic-civil', 'islamic-rgsa', 'islamic-tbla', 'islamic-umalqura', 'iso8601', 'japanese', 'persian', 'roc', 'islamicc', 'ethiopic-amete-alem', 'gregorian', 'islamic-umalqura', 'bangla', 'gujarati', 'kannada', 'malayalam', 'marathi', 'odia', 'tamil', 'telugu', 'vietnam']) { const v = q(ca, c); if (v !== undefined && v !== 'ERR') out.push(`calendar ${style} ${c} ${v}`); }
  // date time fields
  const dt = dn('dateTimeField', style);
  for (const c of ['era', 'year', 'quarter', 'month', 'weekOfYear', 'weekday', 'day', 'dayPeriod', 'hour', 'minute', 'second', 'timeZoneName']) { const v = q(dt, c); if (v !== undefined && v !== 'ERR') out.push(`dtf ${style} ${c} ${v}`); }
}
console.log(out.join('\n'));

