import sys, json
# Parse the original's grapheme signature sweep and classify each range.
rows = []
for line in open('/tmp/intlagent/seg/s8.out'):
    line = line.rstrip('\n')
    rng, *cols = line.split(' ')
    a, b = rng.split('..')
    rows.append((int(a, 16), int(b, 16), cols))

def n(s):
    return len(s.split(','))

def classify(cols, astral):
    aX, Xa, Xext, XXX, XzwjC, XV, XT, LX, VX, TX, CRX, XLF, PX, CzX, LVX, LVTX, KX = cols
    if CRX == '2':
        return 'LF'
    if XLF == '2':
        return 'CR'
    if n(Xext) == 2:
        return 'Control'
    if n(XzwjC) == 1 and n(CzX) == 1:
        return 'ExtPict'
    if n(XXX) == 2:
        return 'RI'
    if n(aX) == 1:
        if n(KX) == 1:
            return 'ExtendLike'
        return 'ExtendLike?'
    if n(Xa) == 1:
        return 'Prepend'
    xv, xt, lx, xx = n(XV) == 1, n(XT) == 1, n(LX) == 1, n(XXX) == 1
    if xv and not xt and lx and xx:
        return 'L'  # L+L joins, L+V joins, L+T no
    if xv and xt and lx and xx:
        return 'V'
    if xv and xt and lx and not xx:
        return 'LV'
    if not xv and xt and lx:
        return 'LVT'
    if xt and not lx and xx:
        return 'T'
    return 'Other'

out = {}
for a, b, cols in rows:
    c = classify(cols, a >= 0x10000)
    out.setdefault(c, []).append((a, b, ' '.join(cols)))
for c, rs in out.items():
    print(c, len(rs), sum(b - a + 1 for a, b, _ in rs))
json.dump({c: [(a, b) for a, b, _ in rs] for c, rs in out.items()}, open('/tmp/intlagent/seg/orig_gcb.json', 'w'))
for c in out:
    sigs = sorted(set(s for _, _, s in out[c]))
    print(c, 'distinct sigs:', len(sigs))
    for s in sigs[:8]:
        print('   ', s)

