// Extract the original's likely-subtags data in a compact form.
const A = 'abcdefghijklmnopqrstuvwxyz';
const U = A.toUpperCase();
function loc(t) { try { return new Intl.Locale(t); } catch (e) { return null; } }
function max(t) { const l = loc(t); return l ? l.maximize().toString() : null; }
const out = [];
// 1. languages: canonical bare forms
const langMax = {};
function addLang(t) {
  const l = loc(t); if (!l) return;
  const c = l.toString();
  if (c.includes('-')) return;
  const m = l.maximize().toString();
  if (m === c) return;
  langMax[c] = m;
}
for (const a of A) for (const b of A) addLang(a + b);
for (const a of A) for (const b of A) for (const c of A) addLang(a + b + c);
for (const k of Object.keys(langMax).sort()) out.push('L ' + k + ' ' + langMax[k]);
// 2. und-script
const scripts = [];
for (const a of U) for (const b of A) for (const c of A) for (const d of A) {
  const s = a + b + c + d;
  const l = loc('und-' + s); if (!l || l.script !== s) continue;
  const m = l.maximize().toString();
  if (m !== 'en-' + s + '-US') { out.push('S ' + s + ' ' + m); scripts.push(s); }
}
console.log(out.join('\n'));

