const cp = require('child_process');
const res = [];
const cmds = (process.argv[2] || 'true').split(',');
function one(i) {
  if (i >= cmds.length) { console.log(res.join(' ')); return; }
  const t0 = performance.now();
  const c = cp.spawn('sh', ['-c', cmds[i]]);
  c.on('exit', () => { res.push(cmds[i] + '=' + (performance.now() - t0).toFixed(1)); one(i + 1); });
}
setTimeout(() => one(0), Number(process.argv[3] || 0));

