const path = require('path');
const dir = '/workspace/assets/test_runtime_compression';
const files = fs.readdirSync(dir).sort();
function pick(name) {
  if (name.endsWith('.gz')) return ['gunzipSync', 'gunzip', 'createGunzip'];
  if (name.endsWith('.zz')) return ['inflateSync', 'inflate', 'createInflate'];
  if (name.endsWith('.raw')) return ['inflateRawSync', 'inflateRaw', 'createInflateRaw'];
  if (name.endsWith('.br')) return ['brotliDecompressSync', 'brotliDecompress', 'createBrotliDecompress'];
  if (name.endsWith('.zst')) return ['zstdDecompressSync', 'zstdDecompress', 'createZstdDecompress'];
  return null;
}
for (const f of files) {
  const p = pick(f);
  const data = fs.readFileSync(path.join(dir, f));
  if (!p) { console.log(f, 'raw', data.length, zlib.crc32(data)); continue; }
