const zlib = require('zlib');
const fs = require('fs');
const log = (...a) => console.log(...a);
// 1. write/end with callbacks and event order
{
  const s = zlib.createGzip();
  s.on('data', d => log('1 data', d.length, d.toString('hex')));
  s.on('end', () => log('1 end'));
  s.on('finish', () => log('1 finish'));
  s.on('close', () => log('1 close'));
  log('1 write a', s.write('hello ', () => log('1 cb1')));
  log('1 write b', s.write(Buffer.from('world'), () => log('1 cb2')));
  s.end(() => log('1 cb3'));
  log('1 sync end');
}
// 2. codec error
{
  const s = zlib.createGunzip();
  s.on('error', e => log('2 error', e.message, Object.keys(e).length));
  s.on('end', () => log('2 end'));
  s.on('finish', () => log('2 finish'));
  s.on('data', d => log('2 data', d.length));
  s.end(Buffer.from('not gzip data'));
}
// 3. empty output
{
  const s = zlib.createGunzip();
  s.on('data', d => log('3 data', d.length));
  s.on('end', () => log('3 end'));
  s.end(zlib.gzipSync(''));
}
// 4. pipe from file
{
  const src = fs.createReadStream('/workspace/assets/test_runtime_compression/text.l6.gz');
  const g = zlib.createGunzip();
  let n = 0;
  src.pipe(g).on('data', d => { n += d.length; log('4 data', d.length); }).on('end', () => log('4 end', n));
  g.on('finish', () => log('4 finish'));
  src.on('end', () => log('4 src end'));
  src.on('close', () => log('4 src close'));
}
// 5. round trip piping compress -> decompress
{
  const c = zlib.createDeflate();
  const d = zlib.createInflate();
  c.pipe(d);
  let out = [];
  d.on('data', x => out.push(x));
  d.on('end', () => log('5 end', Buffer.concat(out).toString()));
  c.write('abc');
  c.write('def');
  c.end('ghi');
}
// 6. async iteration
(async () => {
  const s = zlib.createBrotliDecompress();
  s.end(zlib.brotliCompressSync('brotli stream test'));
  for await (const chunk of s) log('6 chunk', chunk.toString());
  log('6 done');
})();
// 7. read() mode
{
  const s = zlib.createZstdCompress();
  s.on('readable', () => { let c; while ((c = s.read()) !== null) log('7 read', c.length); });
  s.on('end', () => log('7 end'));
  s.end('zstd readable');
}
// 8. process.nextTick / setTimeout ordering with async
zlib.gzip('x', (e, r) => log('8 gzip cb', r.length));
process.nextTick(() => log('8 nextTick'));
setTimeout(() => log('8 timeout'), 0);
Promise.resolve().then(() => log('8 microtask'));
log('main done');

