const zlib = require('zlib');
const util = require('util');
const log = (...a) => console.log(...a);
// async with bad input
zlib.gunzip('bad data', (err, r) => log('A', err && err.message, r, arguments.length));
zlib.gunzip(5, (err, r) => log('B', err && err.name, err && err.message));
zlib.deflate('abc', {level: 1}, function (err, r) { log('C', err, r.toString('hex'), arguments.length, this === undefined); });
zlib.inflate(zlib.deflateSync('xyz'), 'not-a-fn', (err, r) => log('D', err, r.toString()));
// mutation after call is seen
const m = Buffer.from('aaaa');
zlib.deflateRaw(m, (e, r) => log('E', zlib.inflateRawSync(r).toString()));
m.write('bbbb');
// promisify
const gz = util.promisify(zlib.gzip);
gz('promisified').then(r => log('F', zlib.gunzipSync(r).toString()));
const gunz = util.promisify(zlib.gunzip);
gunz(Buffer.from('nope')).catch(e => log('G', e.message));
// returns undefined
log('ret', zlib.gzip('x', () => {}));
// throwing callback: called twice
let calls = 0;
zlib.gzip('t', (e, r) => { calls++; log('H call', calls, e ? e.message : 'ok'); if (!e) throw new Error('boom'); });
log('main end');

