const zlib = require('zlib');
const mode = process.argv[2];
if (mode === 'nocb') zlib.gzip('x');
if (mode === 'nocb2') zlib.gunzip('bad');
if (mode === 'noerrlistener') zlib.createGunzip().end('garbage');
if (mode === 'badchunk') { const s = zlib.createGzip(); console.log(s.write(5)); s.on('data', d => console.log('data')); s.end(); }
if (mode === 'stdout') { const s = zlib.createGunzip(); s.pipe(process.stdout); s.end(zlib.gzipSync('to stdout\n')); }
if (mode === 'stdout2') { const fs = require('fs'); fs.createReadStream('/workspace/assets/test_runtime_compression/underscore.min.js.gz').pipe(zlib.createGunzip()).pipe(process.stdout); }
if (mode === 'destroy') { const s = zlib.createGzip(); s.on('close', () => console.log('close')); s.on('error', e => console.log('err', e.message)); s.destroy(new Error('kaboom')); console.log('destroyed'); }
if (mode === 'twice') { zlib.gzip('t', (e, r) => { console.log('cb', e && e.message); throw new Error('again'); }); }
if (mode === 'writeafterend') { const s = zlib.createGzip(); s.end('a'); s.on('error', e => console.log('error', e.message)); s.write('b', (e) => console.log('wcb', e && e.message)); s.write('c'); }
if (mode === 'setenc') { const s = zlib.createGunzip(); s.setEncoding('utf8'); s.on('data', d => console.log(typeof d, d)); s.end(zlib.gzipSync('encoded')); }
if (mode === 'mutate') { const s = zlib.createDeflate(); const b = Buffer.from('aaaa'); s.write(b); b.fill(98); s.on('data', d => console.log(zlib.inflateSync(d).toString())); s.end(); }
if (mode === 'opts') { const s = zlib.createGzip({level: 9, chunkSize: 64}); s.on('data', d => console.log(d.length)); s.end('x'.repeat(1000)); console.log(Object.keys(s).join()); }
if (mode === 'pipeline') { const { pipeline } = require('stream'); console.log(typeof pipeline); }
if (mode === 'flush') { const s = zlib.createGzip(); try { s.flush(); } catch (e) { console.log(e.message); } }
if (mode === 'readall') { const s = zlib.createInflateRaw(); s.end(zlib.deflateRawSync('raw data')); setTimeout(() => { console.log(String(s.read())); }, 10); }

