// node:child_process — spawn / exec / execFile / fork (async, ChildProcess EventEmitter with
// stdio streams) and spawnSync / execSync / execFileSync, modelled on the reference runtime:
//
// * a child's stdout/stderr are read continuously by reader threads; chunks and EOFs reach the
//   event loop in the child's write order;
// * children are reaped by polling (try_wait) whenever child I/O is delivered and on a 20 ms
//   idle tick, so 'exit' normally follows the stdio data and simultaneous exits are reported in
//   spawn order; 'exit' is emitted from a promise reaction, 'close' one microtask later; the
//   signal argument is always null and kill() always SIGKILLs;
// * the sync APIs capture stdout/stderr (stdin is /dev/null unless `input` is given);
// * fork() talks to the child over its stdin/stdout with "\x1eLUMEN_IPC <json>\n" frames; a
//   process started with LUMEN_FORK_IPC=1 gets process.send / process.disconnect /
//   process.connected and 'message' events (see `setup`).

use crate::object::*;
use crate::runtime::nodestream::{buffer_call, call_method, closure, emit, getp, host_obj, key, new_buffer, plain_fn, queue_microtask, setp, string_of, with_host};
use crate::value::*;
use crate::vm::{JsResult, Vm};
use std::cell::{Cell, RefCell};
use std::collections::BTreeMap;
use std::io::{Read, Write};
use std::process::{Command, Stdio};
use std::sync::mpsc;

const IPC_PREFIX: &str = "\u{1e}LUMEN_IPC ";

/// The idle interval of the reaper poll.
const REAP_TICK_MS: u64 = 20;

// ============================================================================================
// native child registry
// ============================================================================================

enum Ev {
    Data(u8, Vec<u8>),
    Eof(u8),
}

struct ChildEntry {
    child: Option<std::process::Child>,
    stdin: Option<std::process::ChildStdin>,
    rx: Option<mpsc::Receiver<Ev>>,
    stdout: Value,
    stderr: Value,
    wait_resolve: Value,
    ipc: Value,
    ipc_buf: Vec<u8>,
    /// order of the last read activity per stream (stdout, stderr), for EOF tie-breaks
    seq: [u64; 2],
    counter: u64,
    eofs: u8,
    expected_eofs: u8,
}

thread_local! {
    static CHILDREN: RefCell<BTreeMap<u64, ChildEntry>> = RefCell::new(BTreeMap::new());
    static NEXT_ID: Cell<u64> = Cell::new(1);
    static TICKER: Cell<bool> = Cell::new(false);
    static CLASS: RefCell<Option<(Obj, Obj)>> = RefCell::new(None);
}

fn with_child<R>(id: u64, f: impl FnOnce(&mut ChildEntry) -> R) -> Option<R> {
    CHILDREN.with(|c| c.borrow_mut().get_mut(&id).map(f))
}

#[derive(Clone, Copy, PartialEq)]
enum Io {
    Pipe,
    Inherit,
    Ignore,
}

fn io_name(io: Io) -> &'static str {
    match io {
        Io::Pipe => "pipe",
        Io::Inherit => "inherit",
        Io::Ignore => "ignore",
    }
}

fn to_stdio(io: Io) -> Stdio {
    match io {
        Io::Pipe => Stdio::piped(),
        Io::Inherit => Stdio::inherit(),
        Io::Ignore => Stdio::null(),
    }
}

fn spawn_error(vm: &mut Vm, cmd: &str, e: &std::io::Error) -> Value {
    vm.make_error("Error", &format!("spawn {}: {}", cmd, e))
}

fn reader_thread(mut r: impl Read + Send + 'static, fd: u8, tx: mpsc::Sender<Ev>) {
    std::thread::spawn(move || {
        let mut buf = vec![0u8; 65536];
        loop {
            match r.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    if tx.send(Ev::Data(fd, buf[..n].to_vec())).is_err() {
                        return;
                    }
                }
                Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => break,
            }
        }
        let _ = tx.send(Ev::Eof(fd));
    });
}

/// Spawn a child; returns (childId, pid).
fn spawn_native(vm: &mut Vm, cmd: &str, argv: &[String], cwd: Option<String>, env: Option<Vec<(String, String)>>, stdio: [Io; 3]) -> JsResult<(u64, u32)> {
    let mut c = Command::new(cmd);
    c.args(argv);
    if let Some(d) = &cwd {
        c.current_dir(d);
    }
    if let Some(pairs) = &env {
        c.env_clear();
        for (k, v) in pairs {
            c.env(k, v);
        }
    }
    c.stdin(to_stdio(stdio[0]));
    c.stdout(to_stdio(stdio[1]));
    c.stderr(to_stdio(stdio[2]));
    let mut child = match c.spawn() {
        Ok(ch) => ch,
        Err(e) => return Err(spawn_error(vm, cmd, &e)),
    };
    let pid = child.id();
    let (tx, rx) = mpsc::channel::<Ev>();
    let mut readers = 0u8;
    if let Some(out) = child.stdout.take() {
        readers += 1;
        reader_thread(out, 1, tx.clone());
    }
    if let Some(err) = child.stderr.take() {
        readers += 1;
        reader_thread(err, 2, tx.clone());
    }
    drop(tx);
    let stdin = child.stdin.take();
    let id = NEXT_ID.with(|n| {
        let v = n.get();
        n.set(v + 1);
        v
    });
    CHILDREN.with(|c| {
        c.borrow_mut().insert(
            id,
            ChildEntry {
                child: Some(child),
                stdin,
                rx: Some(rx),
                stdout: Value::Undefined,
                stderr: Value::Undefined,
                wait_resolve: Value::Undefined,
                ipc: Value::Undefined,
                ipc_buf: Vec::new(),
                seq: [1, 0],
                counter: 1,
                eofs: 0,
                expected_eofs: readers,
            },
        )
    });
    if readers > 0 {
        recv_next(vm, id);
    }
    ensure_ticker(vm);
    Ok((id, pid))
}

/// Reap exited children (in spawn order) and settle their wait promises.
fn poll_children(vm: &mut Vm) {
    let exited: Vec<(Value, Option<i32>)> = CHILDREN.with(|c| {
        let mut out = Vec::new();
        for (_, e) in c.borrow_mut().iter_mut() {
            let st = match e.child.as_mut() {
                Some(ch) => ch.try_wait(),
                None => continue,
            };
            match st {
                Ok(Some(status)) => {
                    e.child = None;
                    out.push((std::mem::replace(&mut e.wait_resolve, Value::Undefined), status.code()));
                }
                Ok(None) => {}
                Err(_) => {
                    e.child = None;
                    out.push((std::mem::replace(&mut e.wait_resolve, Value::Undefined), None));
                }
            }
        }
        out
    });
    for (resolve, code) in exited {
        if resolve.is_callable() {
            let c = match code {
                Some(c) => Value::Num(c as f64),
                None => Value::Null,
            };
            if let Err(e) = vm.call(&resolve, Value::Undefined, &[c]) {
                crate::runtime::report_uncaught(vm, &e);
            }
        }
    }
}

fn any_alive() -> bool {
    CHILDREN.with(|c| c.borrow().values().any(|e| e.child.is_some()))
}

/// Keep a 20 ms idle tick running while children are alive (the loop's reaper poll).
fn ensure_ticker(vm: &mut Vm) {
    if TICKER.with(|t| t.get()) || !any_alive() {
        return;
    }
    TICKER.with(|t| t.set(true));
    crate::runtime::spawn_op(
        vm,
        || std::thread::sleep(std::time::Duration::from_millis(REAP_TICK_MS)),
        |vm: &mut Vm, _: ()| {
            TICKER.with(|t| t.set(false));
            poll_children(vm);
            ensure_ticker(vm);
        },
    );
}

/// Pull the next stdio event(s) of child `id` from its channel on a worker thread.
fn recv_next(vm: &mut Vm, id: u64) {
    let (rx, pair_eofs) = match with_child(id, |e| (e.rx.take(), e.expected_eofs.saturating_sub(e.eofs) >= 2)) {
        Some((Some(r), p)) => (r, p),
        _ => return,
    };
    crate::runtime::spawn_op(
        vm,
        move || {
            let mut batch = Vec::new();
            if let Ok(ev) = rx.recv() {
                let is_eof = matches!(ev, Ev::Eof(_));
                batch.push(ev);
                if is_eof && pair_eofs {
                    // both pipes usually close together when the child exits: take the other
                    // EOF too so their order can be decided deterministically
                    if let Ok(ev2) = rx.recv_timeout(std::time::Duration::from_millis(2)) {
                        batch.push(ev2);
                    }
                }
            }
            (batch, rx)
        },
        move |vm: &mut Vm, (batch, rx): (Vec<Ev>, mpsc::Receiver<Ev>)| {
            let empty = batch.is_empty();
            with_child(id, |e| e.rx = Some(rx));
            let mut batch = batch;
            if batch.len() == 2 {
                if let (Ev::Eof(a), Ev::Eof(b)) = (&batch[0], &batch[1]) {
                    let (sa, sb) = with_child(id, |e| (e.seq[(*a - 1) as usize], e.seq[(*b - 1) as usize])).unwrap_or((0, 0));
                    if sb < sa {
                        batch.swap(0, 1);
                    }
                }
            }
            let n = batch.len();
