    let mut readers = 0u8;
    if let Some(out) = child.stdout.take() {
        readers += 1;
        reader_thread(out, 1, tx.clone());
    }
    if let Some(err) = child.stderr.take() {
        readers += 1;
        reader_thread(err, 2, tx.clone());
    }
    drop(tx);
    let stdin = child.stdin.take();
    let id = NEXT_ID.with(|n| {
        let v = n.get();
        n.set(v + 1);
        v
    });
