        c.borrow_mut().insert(
            id,
            ChildEntry {
                child: Some(child),
                stdin,
                rx: Some(rx),
                stdout: Value::Undefined,
                stderr: Value::Undefined,
                wait_resolve: Value::Undefined,
                ipc: Value::Undefined,
                ipc_buf: Vec::new(),
                seq: [1, 0],
                counter: 1,
                eofs: 0,
                expected_eofs: readers,
