/// Reap exited children (in spawn order) and settle their wait promises.
fn poll_children(vm: &mut Vm) {
    let exited: Vec<(Value, Option<i32>)> = CHILDREN.with(|c| {
        let mut out = Vec::new();
        for (_, e) in c.borrow_mut().iter_mut() {
            let st = match e.child.as_mut() {
                Some(ch) => ch.try_wait(),
                None => continue,
            };
            match st {
                Ok(Some(status)) => {
                    e.child = None;
                    out.push((std::mem::replace(&mut e.wait_resolve, Value::Undefined), status.code()));
