    if seq.tag != asn1::TAG_SEQUENCE {
        return Err(asn1::malformed());
    }
    let k = asn1::children(seq.content)?;
    Ok(AsymKey::RsaPublic(RsaPublicKey { n: int_value(k.first())?, e: int_value(k.get(1))? }))
