const server = Lumen.serve({ port: 0, hostname: "127.0.0.1" }, (req) => {
  L("server got request");
  const sock = Lumen.upgradeWebSocket(req);
  sock.onmessage = (d, b) => L("server msg " + d);
  sock.onclose = (code, reason, clean) => L("server close " + code + " " + JSON.stringify(reason) + " " + clean);
  return new Response(null, { status: 101 });
});
