const cv = new Intl.Collator('en').compare;
const cb = new Intl.Collator('en', {sensitivity: 'base'}).compare;
const ca = new Intl.Collator('en', {sensitivity: 'accent'}).compare;
const cc = new Intl.Collator('en', {sensitivity: 'case'}).compare;
const arr = [];
for (let cp = 0; cp <= 0x10ffff; cp += 97) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  arr.push(String.fromCodePoint(cp));
}
for (let cp = 0x2f800; cp <= 0x2fa1d; cp++) arr.push(String.fromCodePoint(cp));
for (let cp = 0xf900; cp <= 0xfaff; cp++) arr.push(String.fromCodePoint(cp));
for (let cp = 0x1d15e; cp <= 0x1d1c0; cp++) arr.push(String.fromCodePoint(cp));
for (let cp = 0xd800; cp <= 0xdfff; cp += 31) arr.push(String.fromCharCode(cp));
arr.sort(cv);
const out = [];
for (let i = 0; i < arr.length; i++) {
  const cur = arr[i];
  let rel = '';
  if (i > 0) {
    const p = arr[i - 1];
    rel = [cb(p, cur), ca(p, cur), cc(p, cur), cv(p, cur)].map(x => x === 0 ? '=' : (x < 0 ? '<' : '>')).join('');
  }
  out.push(Array.from(cur).map(c => c.codePointAt(0).toString(16)).join('.') + ' ' + rel);
}
console.log(out.join('\n'));

