arguments.command:
cat > /tmp/nodeagent/recv_new.rs <<'EOF'
fn recv_next(vm: &mut Vm, id: u64) {
    let rx = match with_child(id, |e| e.rx.take()) {
        Some(Some(r)) => r,
        _ => return,
    };
    crate::runtime::spawn_op(
        vm,
        move || {
            let mut batch = Vec::new();
            if let Ok(ev) = rx.recv() {
                batch.push(ev);
                // everything already produced is delivered in the same turn
                while let Ok(ev) = rx.try_recv() {
                    batch.push(ev);
                }
            }
            (batch, rx)
        },
        move |vm: &mut Vm, (batch, rx): (Vec<Ev>, mpsc::Receiver<Ev>)| {
            let empty = batch.is_empty();
            with_child(id, |e| e.rx = Some(rx));
            let n = batch.len();
            for (i, ev) in batch.into_iter().enumerate() {
                handle_event(vm, id, ev);
                if i + 1 < n {
                    crate::runtime::checkpoint(vm);
                }
            }
            poll_children(vm);
            let done = empty || with_child(id, |e| e.eofs >= e.expected_eofs).unwrap_or(true);
            if done {
                with_child(id, |e| e.rx = None);
            } else {
                recv_next(vm, id);
            }
        },
    );
}
EOF
start=$(grep -n "^fn recv_next" src/runtime/child_process.rs | cut -d: -f1); end=$((start+63)); sed -n "${end}p" src/runtime/child_process.rs

