let seed = parseInt(process.argv[2] || '12345');
function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x80000000; }
const alphabet = ['a', 'b', 'e', 'o', 'u', 'z', 'A', 'B', 'E', 'O', 'U', 'Z', '0', '1', '2', '9', '0', '0', ' ', '-', '_', '.', ',', '!', '@', '~',
  'á', 'à', 'ä', 'Ä', 'ö', 'Ö', 'ü', 'Ü', 'é', 'É', 'ß', 'ẞ', 'æ', 'ø', 'å', 'ñ', '́', '̈', '̀', '̖', '̧', 'ǅ', 'ǆ', 'Ǆ',
  'α', 'Α', 'ω', 'я', 'Я', '가', '각', 'ᄀ', '中', '😀', '\ud800', '\udc00', '‐', ' ', ' ', '　', '¡', ';', '١', '２', '¹', 'İ', 'ı', 'K', 'Å', '\u0000', '\t', 'ﬁ'];
function rstr() {
  const n = Math.floor(rnd() * 6);
  let s = '';
  for (let i = 0; i < n; i++) s += alphabet[Math.floor(rnd() * alphabet.length)];
  return s;
}
const configs = [];
for (const loc of ['en', 'de', 'de-u-co-phonebk', 'th']) {
  for (const sensitivity of ['base', 'accent', 'case', 'variant']) {
    for (const numeric of [false, true]) {
      for (const caseFirst of ['false', 'upper']) {
        for (const ignorePunctuation of [false, true]) {
          for (const usage of ['sort', 'search']) {
            configs.push([loc, {sensitivity, numeric, caseFirst, ignorePunctuation, usage}]);
          }
        }
      }
    }
  }
}
const pairs = [];
for (let i = 0; i < 400; i++) {
  const a = rstr();
  let b = rnd() < 0.5 ? rstr() : a.split('').map(c => rnd() < 0.3 ? alphabet[Math.floor(rnd() * alphabet.length)] : c).join('');
  pairs.push([a, b]);
}
const lines = [];
for (const [loc, o] of configs) {
  const c = new Intl.Collator(loc, o).compare;
  let s = '';
  for (const [a, b] of pairs) { const r = c(a, b); s += r < 0 ? '<' : (r > 0 ? '>' : '='); }
  lines.push(loc + JSON.stringify(o) + ' ' + s);
}
// localeCompare default
let s = '';
for (const [a, b] of pairs) { const r = a.localeCompare(b); s += r < 0 ? '<' : (r > 0 ? '>' : '='); }
lines.push('localeCompare ' + s);
console.log(lines.join('\n'));

