            while let Ok(ev) = rx.try_recv() {
                batch.push(ev);
            }
            let eofs = batch.iter().filter(|e| matches!(e, Ev::Eof(_))).count();
            if eofs == 1 && pair_eofs {
                // both pipes usually close together when the child exits: take the other
