const { setTimeout: sleep, setImmediate: immediate, setInterval: every, scheduler } = require('node:timers/promises');
const log = (...a) => console.log(...a);
(async () => {
  log('start');
  const r = await sleep(5, 'slept');
  log(r);
  const order = [];
  const p1 = sleep(20).then(() => order.push('20'));
  const p2 = sleep(5).then(() => order.push('5'));
  const p3 = immediate().then(() => order.push('imm'));
  await Promise.all([p1, p2, p3]);
  log(order.join(','));
  let count = 0;
  const start = Date.now();
  for await (const v of every(10, 'tick')) {
    count++;
    log('iter', count, v);
    if (count === 3) break;
  }
  log('elapsed ok', Date.now() - start >= 25);
  const ac = new AbortController();
  const pending = sleep(1000, null, { signal: ac.signal });
  ac.abort(new Error('stop'));
  try { await pending; } catch (e) { log('caught', e.message); }
  await scheduler.wait(5);
  log('wait done');
  const it = every(5, 'v');
  const a = it.next();
  const b = it.next();
  log(JSON.stringify(await a), JSON.stringify(await b));
  log(JSON.stringify(await it.return('R')));
  log(JSON.stringify(await it.next()));
  const it2 = every(5);
  await it2.next();
  try { await it2.throw(new Error('T')); } catch (e) { log('throw rejected', e.message); }
  log(JSON.stringify(await it2.next()));
  const it3 = every(1000, 'x', { signal: AbortSignal.abort('pre') });
  try { await it3.next(); } catch (e) { log('pre-aborted interval', e); }
  const ac2 = new AbortController();
  const it4 = every(10, 'y', { signal: ac2.signal });
  setTimeout(() => ac2.abort(), 15);
  try { for await (const v of it4) log('it4', v); } catch (e) { log('it4 aborted', e.name); }
  const val = await immediate('imm-value');
  log(val);
  log('end');
})();

