297	    let largest = match largest {
298	        Some(UnitOpt::U(u)) => u,
299	        _ => default_largest,
300	    };
301	    if Unit::larger(largest, smallest) != largest {
302	        return vm.throw_range("smallestUnit is larger than largestUnit");
