const log = [];
const p = (s) => log.push(s);
function ticks(name, n) { let pr = Promise.resolve(); for (let i = 1; i <= n; i++) pr = pr.then(() => p(name + ' tick' + i)); }
async function caseA() {
  async function* g() { p('A start'); yield 1; p('A after yield'); }
  const it = g();
  const pr = it.next();
  ticks('A', 5);
  await pr; p('A got 1');
  const pr2 = it.next();
  ticks('A2', 5);
  await pr2; p('A got 2');
}
async function caseB() {
  const src = { [Symbol.asyncIterator]() { return { i: 0, next() { p('B next called'); return Promise.resolve({ value: this.i++, done: this.i > 2 }); } }; } };
  async function* g() { yield* src; }
  const it = g();
  const pr = it.next();
  ticks('B', 6);
  await pr; p('B got first');
  const pr2 = it.next();
  ticks('B2', 6);
  await pr2; p('B got second');
}
async function caseC() {
  async function* inner() { yield 1; p('C inner after yield'); }
  async function* g() { yield* inner(); }
  const it = g();
  const pr = it.next();
  ticks('C', 6);
  await pr; p('C got first');
  const pr2 = it.next();
  ticks('C2', 8);
  await pr2; p('C got second');
}
async function caseD() {
  async function* g() { const x = yield 1; p('D resumed with ' + x); }
  const it = g();
  await it.next();
  const pr = it.next('val');
  ticks('D', 4);
  await pr; p('D done');
}
async function caseE() {
  async function f() { return 1; }
  const pr = f();
  ticks('E', 4);
  await pr; p('E got');
  async function f2() { return Promise.resolve(1); }
  const pr2 = f2();
  ticks('E2', 5);
  await pr2; p('E2 got');
}
(async () => {
  await caseA(); p('---');
  await caseB(); p('---');
  await caseC(); p('---');
  await caseD(); p('---');
  await caseE();
  setTimeout(() => console.log(log.join('\n')), 5);
})();

