s=s[:bs]+'''fn build_keys(s: &[u16], cfg: &CollationConfig) -> Keys {
    let nfd = crate::unicode::normalize(s, crate::unicode::NormForm::Nfd);
    let mut cps = decode(&nfd);
    if cfg.ignore_punctuation {
        cps.retain(|&c| !is_ignorable_punct(c));
    }
    let n = cps.len();
    let mut keys = Keys { prims: Vec::with_capacity(n), sec: Vec::with_capacity(n), ter: Vec::with_capacity(n) };
    // digits of the numeric run being built (the last primary element)
    let mut run: Option<Vec<u8>> = None;
    let mut pending_e = false;
    fn flush_run(keys: &mut Keys, run: &mut Option<Vec<u8>>) {
        if let Some(d) = run.take() {
            let lead = d.iter().take_while(|&&b| b == b'0').count();
            let lead = if lead == d.len() { lead - 1 } else { lead };
            if let Some(p) = keys.prims.last_mut() {
                *p = Prim::Num(d[lead..].to_vec());
            }
        }
    }
    fn push_e(keys: &mut Keys) {
        keys.prims.push(Prim::Ch(0x65));
        keys.sec.push(0);
        keys.ter.push(false);
    }
    for i in 0..n {
        let c = cps[i];
        if ccc(c) != 0 && !keys.prims.is_empty() {
            keys.sec.push(c);
            continue;
        }
        if cfg.numeric && (0x30..=0x39).contains(&c) {
            if pending_e {
                pending_e = false;
                push_e(&mut keys);
            }
            match &mut run {
                Some(d) => d.push(c as u8),
                None => {
                    keys.prims.push(Prim::Num(Vec::new()));
                    run = Some(vec![c as u8]);
                }
            }
            keys.sec.push(0);
            keys.ter.push(false);
            continue;
        }
        flush_run(&mut keys, &mut run);
        if pending_e {
            pending_e = false;
            push_e(&mut keys);
        }
        let (l, up) = lower_and_upper(c);
        keys.prims.push(Prim::Ch(l));
        keys.sec.push(0);
        keys.ter.push(up);
        if cfg.expand_umlauts && matches!(l, 0x61 | 0x6F | 0x75) && i + 1 < n && cps[i + 1] == 0x308 {
            pending_e = true;
        }
    }
    flush_run(&mut keys, &mut run);
    if pending_e {
        push_e(&mut keys);
    }
    keys
}

