const langs = (process.argv[2] || 'ar,de,es,fr,gv,hi,it,ja,ko,ln,nl,pl,pt,ru,si,sl,sr,sv,th,zh').split(',');
const arr = [];
for (let cp = 0; cp <= 0xffff; cp++) { if (cp >= 0xd800 && cp <= 0xdfff) continue; arr.push(String.fromCharCode(cp)); }
const base = arr.slice().sort(new Intl.Collator('en', {ignorePunctuation: false}).compare);
for (const l of langs) {
  for (const usage of ['search']) {
    const c = new Intl.Collator(l, {usage, ignorePunctuation: false});
    const s = arr.slice().sort(c.compare);
    let diffs = 0, first = [];
    for (let i = 0; i < s.length; i++) if (s[i] !== base[i]) { diffs++; if (first.length < 10) first.push(i + ':' + s[i].charCodeAt(0).toString(16) + '/' + base[i].charCodeAt(0).toString(16)); }
    // also equality structure
    let eqd = 0;
    const cb = new Intl.Collator('en').compare;
    for (let i = 1; i < s.length; i++) if ((c.compare(s[i - 1], s[i]) === 0) !== (cb(s[i - 1], s[i]) === 0)) eqd++;
    console.log(l + ' ' + usage + ': ' + diffs + ' order diffs, ' + eqd + ' eq diffs ' + first.join(' '));
  }
}

