const log = [];
const p = (s) => log.push(s);
function ticks(name, n) { let pr = Promise.resolve(); for (let i = 1; i <= n; i++) pr = pr.then(() => p(name + i)); }
async function caseA() {
  async function* g() { p('start'); yield 1; p('after 1'); }
  const it = g();
  ticks('T', 8);
  const a = it.next();
  const b = it.next();
  a.then(r => p('a ' + JSON.stringify(r)));
  b.then(r => p('b ' + JSON.stringify(r)));
}
async function caseB() {
  async function* g() { p('start'); yield 1; p('after 1'); }
  const it = g();
  ticks('T', 8);
  const a = it.next();
  a.then(r => { p('a ' + JSON.stringify(r)); const b = it.next(); b.then(r => p('b ' + JSON.stringify(r))); });
}
async function caseC() {
  async function* g() { p('start'); const x = await 5; p('after await'); yield x; p('after 1'); }
  const it = g();
  ticks('T', 8);
  const a = it.next();
  const b = it.next();
  a.then(r => p('a ' + JSON.stringify(r)));
  b.then(r => p('b ' + JSON.stringify(r)));
}
caseA();
setTimeout(() => { log.push('---'); caseB(); }, 5);
setTimeout(() => { log.push('---'); caseC(); }, 10);
setTimeout(() => console.log(log.join('\n')), 20);

