use strict;
use warnings;
use Unicode::UCD qw(prop_invmap prop_invlist);
# Dump GCB, WB, SB, gc as ranges using inversion maps; ExtPict via inversion list.
for my $p ('GCB', 'WB', 'SB', 'gc', 'InCB') {
    my ($list, $map, $format, $default) = prop_invmap($p);
    if (!$list) { print STDERR "no prop $p\n"; next; }
    for my $i (0 .. $#$list) {
        my $s = $list->[$i];
        my $e = ($i < $#$list) ? $list->[$i + 1] - 1 : 0x10FFFF;
        my $v = $map->[$i];
        $v = join('|', @$v) if ref $v;
        printf "%s %x %x %s\n", $p, $s, $e, $v;
    }
}
my @ep = prop_invlist('Extended_Pictographic');
for (my $i = 0; $i < @ep; $i += 2) {
    my $s = $ep[$i];
    my $e = ($i + 1 < @ep) ? $ep[$i + 1] - 1 : 0x10FFFF;
    printf "EP %x %x Y\n", $s, $e;
}

