185	/// Run `f` with an extra (native) frame named `name` on the trace, so error stacks captured
186	/// inside show the frame the reference's JS implementation would have.
187	pub fn with_frame<T>(vm: &mut Vm, name: &str, f: impl FnOnce(&mut Vm) -> JsResult<T>) -> JsResult<T> {
188	    vm.trace.push(TraceEntry { name: JsStr::from_str(name) });
189	    let r = f(vm);
190	    vm.trace.pop();
191	    r
192	}
193	
194	/// The error a class constructor throws when called without `new`.
195	pub fn class_call_error<T>(vm: &mut Vm) -> JsResult<T> {
196	    vm.throw_type("Class constructor cannot be invoked without 'new'")
197	}
198	
199	/// Allocate `this` for a class-like native constructor (prototype from new.target).
200	pub fn new_this(vm: &mut Vm, a: &Args, fallback_proto: &str) -> JsResult<Obj> {
201	    if a.new_target.is_none() {
202	        return class_call_error(vm);
203	    }
204	    let fb = reg(vm, fallback_proto);
205	    let proto = vm.proto_from_nt(&a.new_target, &fb)?;
206	    Ok(Obj::new(Some(proto), ObjKind::Ordinary))
207	}
208	
209	/// Create a class-like constructor `name` (registered as `name` and `name.prototype`);
210	/// `parent` names a registered class to extend.
211	pub fn make_class(vm: &mut Vm, name: &'static str, proto_key: &'static str, len: u32, f: NativeFn, parent: Option<&str>) -> (Obj, Obj) {
212	    let parent_proto = match parent {
213	        Some(p) => reg_get(&format!("{}.prototype", p)).unwrap_or_else(|| vm.intr.object_proto.clone()),
214	        None => vm.intr.object_proto.clone(),
215	    };
216	    let proto = Obj::new(Some(parent_proto), ObjKind::Ordinary);
217	    let c = vm.native_ctor(name, len, f, &proto);
218	    if let Some(p) = parent {
219	        if let Some(pc) = reg_get(p) {
220	            c.borrow_mut().proto = Some(pc);
221	        }
222	    }
223	    reg_set(name, &c);
224	    reg_set(proto_key, &proto);
225	    (c, proto)
226	}
227	
228	pub fn method(vm: &mut Vm, target: &Obj, name: &str, len: u32, f: NativeFn) -> Obj {
229	    vm.def_method(target, name, len, f)
230	}
231	
232	pub fn getter(vm: &mut Vm, target: &Obj, name: &str, f: NativeFn) -> Obj {
233	    vm.def_getter(target, name, f)
234	}
235	
236	pub fn accessor(vm: &mut Vm, target: &Obj, name: &str, g: NativeFn, s: NativeFn) {
237	    vm.def_accessor(target, name, g, s)
238	}
239	
240	/// An ordinary (non-class) function: constructible, with a `prototype` object.
241	pub fn plain_fn(vm: &mut Vm, name: &str, len: u32, f: NativeFn) -> Obj {
242	    let inner = vm.native_fn(name, len, f);
243	    let outer = vm.native_closure(name, len, plain_fn_shim, vec![Value::Obj(inner)]);
244	    vm.make_ctor(&outer);
245	    let proto = vm.new_object();
246	    proto.set_prop(vm.intr.key_constructor.clone(), Value::Obj(outer.clone()), WC);
247	    outer.set_prop(vm.intr.key_prototype.clone(), Value::Obj(proto), WRITABLE);
248	    outer
249	}
250	
251	fn plain_fn_shim(vm: &mut Vm, a: &Args) -> JsResult<Value> {
252	    let inner = a.slot(0);
253	    match &a.new_target {
254	        None => vm.call(&inner, a.this.clone(), a.args),
255	        Some(nt) => {
256	            let fb = vm.intr.object_proto.clone();
257	            let proto = vm.proto_from_nt(&Some(nt.clone()), &fb)?;
258	            let obj = Value::Obj(Obj::new(Some(proto), ObjKind::Ordinary));
259	            let r = vm.call(&inner, obj.clone(), a.args)?;
260	            Ok(if r.is_object() { r } else { obj })
261	        }
262	    }
263	}
264	
265	/// A plain function carrying captured values (read with `a.slot(i)` inside `f`).
266	pub fn plain_closure(vm: &mut Vm, name: &str, len: u32, f: NativeFn, slots: Vec<Value>) -> Obj {
267	    let inner = vm.native_closure(name, len, f, slots);
268	    let outer = vm.native_closure(name, len, plain_closure_shim, vec![Value::Obj(inner)]);
269	    vm.make_ctor(&outer);
270	    let proto = vm.new_object();
271	    proto.set_prop(vm.intr.key_constructor.clone(), Value::Obj(outer.clone()), WC);
272	    outer.set_prop(vm.intr.key_prototype.clone(), Value::Obj(proto), WRITABLE);
273	    outer
274	}
