import json
from collections import Counter, defaultdict
N = 0x110000
def load(prefix):
    arr = [None] * N
    for line in open('/tmp/intlagent/seg/perl_props.txt'):
        p, s, e, v = line.rstrip('\n').split(' ', 3)
        if p != prefix:
            continue
        s, e = int(s, 16), int(e, 16)
        for c in range(s, e + 1):
            arr[c] = v
    return arr
gcb = load('GCB')
gc = load('gc')
ep = [False] * N
for line in open('/tmp/intlagent/seg/perl_props.txt'):
    p, s, e, v = line.rstrip('\n').split(' ', 3)
    if p == 'EP':
        for c in range(int(s, 16), int(e, 16) + 1):
            ep[c] = True
orig = [None] * N
for cls, rs in json.load(open('/tmp/intlagent/seg/orig_gcb.json')).items():
    for a, b in rs:
        for c in range(a, b + 1):
            orig[c] = cls
def expected(c):
    g = gcb[c]
    if g in ('Extend', 'SpacingMark', 'ZWJ'):
        return 'ExtendLike'
    if g in ('Control', 'CR', 'LF', 'L', 'V', 'T', 'LV', 'LVT'):
        return g
    if g == 'Regional_Indicator':
        return 'RI'
    if g == 'Prepend':
        return 'Prepend'
    if ep[c]:
        return 'ExtPict'
    return 'Other'
mism = defaultdict(list)
for c in range(N):
    if 0xD800 <= c <= 0xDFFF:
        continue
    e = expected(c)
    o = orig[c]
    if e != o:
        mism[(e, o, gcb[c], gc[c])].append(c)
def ranges(cs):
    out = []
    s = p = cs[0]
    for c in cs[1:]:
        if c == p + 1:
            p = c
            continue
        out.append((s, p)); s = p = c
    out.append((s, p))
    return out
for k, cs in sorted(mism.items(), key=lambda kv: -len(kv[1])):
    rs = ranges(cs)
    print(k, len(cs), ' '.join('%x-%x' % r if r[0] != r[1] else '%x' % r[0] for r in rs[:30]))

