const props = ['Extended_Pictographic', 'Emoji', 'Emoji_Presentation', 'Emoji_Modifier', 'Emoji_Component', 'Grapheme_Extend', 'Regional_Indicator', 'gc=Mc', 'gc=Mn', 'gc=Me', 'gc=Cc', 'gc=Cf', 'gc=Zl', 'gc=Zp', 'gc=Cn', 'gc=Co', 'gc=Cs', 'gc=Lo', 'Default_Ignorable_Code_Point', 'Alphabetic', 'gc=Nd', 'gc=L', 'gc=N', 'Ideographic', 'White_Space', 'gc=Zs', 'Lowercase', 'Uppercase', 'gc=Lt', 'gc=Lm', 'Sentence_Terminal', 'Terminal_Punctuation', 'gc=Ps', 'gc=Pe', 'gc=Pi', 'gc=Pf', 'Quotation_Mark', 'Dash', 'gc=Pd', 'gc=Po', 'gc=P', 'gc=S', 'gc=Sk', 'gc=Lu', 'gc=Ll'];
const out = [];
for (const p of props) {
  const re = new RegExp('\\p{' + p + '}', 'u');
  let inRun = false, start = 0;
  const rs = [];
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const m = (cp >= 0xd800 && cp <= 0xdfff) ? (p === 'gc=Cs') : re.test(String.fromCodePoint(cp));
    if (m && !inRun) { inRun = true; start = cp; }
    else if (!m && inRun) { inRun = false; rs.push(start.toString(16) + '-' + (cp - 1).toString(16)); }
  }
  if (inRun) rs.push(start.toString(16) + '-10ffff');
  out.push(p + ' ' + rs.join(','));
}
console.log(out.join('\n'));

