let seed = 4242;
function rnd(n) { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; }
function pick(a) { return a[rnd(a.length)]; }
const types = ['language', 'region', 'script', 'currency', 'calendar', 'dateTimeField'];
const codes = ['en', 'EN-us', 'en-GB', 'en-UK', 'de', 'zh-Hant', 'iw', 'sh', 'cmn', 'arb', 'xx', 'und', 'root', 'en-u-ca-gregory', 'en_US', '', 'US', 'us', 'GB', 'UK', '419', '001', 'XX', 'zz', 'Latn', 'latn', 'Hans', 'QAAI', 'Lat', 'USD', 'eur', 'XYZ', 'US1', 'gregory', 'ISLAMICC', 'ethiopic-amete-alem', 'roc', 'foo', 'fo', 'era', 'year', 'Era', 'weekOfYear', 'timeZoneName', 'week', 'abc', 'abcd', 'abcde', '123', 'zh-guoyu', 'art-lojban', 'sgn-DE', 'hy-arevela', null, undefined, 5, true];
const out = [];
for (let n = 0; n < 3000; n++) {
  const opts = {};
  if (rnd(8) !== 0) opts.type = pick(types.concat(['foo']));
  if (rnd(3) === 0) opts.style = pick(['long', 'short', 'narrow', 'bad']);
  if (rnd(3) === 0) opts.fallback = pick(['code', 'none', 'bad']);
  if (rnd(4) === 0) opts.languageDisplay = pick(['dialect', 'standard', 'bad']);
  if (rnd(6) === 0) opts.localeMatcher = pick(['lookup', 'best fit', 'bad']);
  const loc = pick(['en', 'de', 'ja', 'xx', 'zh-TW', undefined, 'fr-u-nu-arab']);
  let r;
  try {
    const d = new Intl.DisplayNames(loc, opts);
    const c = pick(codes);
    let v;
    try { v = JSON.stringify(d.of(c)); } catch (e) { v = 'ERR ' + e.constructor.name + ': ' + e.message; }
