//! toLocaleString for the Temporal types (via the Intl.DateTimeFormat
//! subset in `crate::datetime`).

use super::calendar::Cal;
use super::iso::*;
use super::*;
use crate::builtins::intl;
use crate::datetime as dt;

fn ms_of(d: &IsoDate, t: &Time) -> f64 {
    (utc_epoch_ns(d, t).div_euclid(1_000_000)) as f64
}

fn check_calendar(vm: &mut Vm, cal: Cal, opts: &dt::DateTimeFormatOptions, allow_iso: bool) -> JsResult<()> {
    let fmt_cal = opts.calendar.clone().unwrap_or_else(|| "gregory".to_string());
    let ok = cal.id() == fmt_cal || (allow_iso && cal == Cal::Iso8601);
    if !ok {
        return vm.throw_range(format!("calendar mismatch: {} vs {}", cal.id(), fmt_cal));
    }
    Ok(())
}

fn dt_result(vm: &mut Vm, r: Result<String, dt::DateTimeError>) -> JsResult<Value> {
    match r {
        Ok(s) => Ok(Value::str(&s)),
        Err(e) => intl::throw_dt_error(vm, e),
    }
}

pub fn to_locale_string(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = match slot_of(&a.this) {
        Some(s) => s,
        None => return vm.throw_type("toLocaleString called on a non-Temporal receiver"),
    };
    if let Slot::Duration(d) = &s {
        let d = *d;
        let _ = intl::locale_list(vm, &a.arg(0))?;
        return Ok(Value::str(&duration_to_locale(&d)));
    }
    let locales = intl::locale_list(vm, &a.arg(0))?;
    let mut opts = intl::read_dtf_options(vm, &a.arg(1))?;
    match s {
        Slot::Date(d, cal) => {
            check_calendar(vm, cal, &opts, true)?;
            if opts.time_style.is_some() {
                return vm.throw_type("timeStyle cannot format a date-only Temporal value");
            }
            opts.time_zone = Some("UTC".to_string());
            let t = ms_of(&d, &Time::MIDNIGHT);
            let r = dt::to_locale_date_string(t, &locales, &opts);
            dt_result(vm, r)
        }
        Slot::Time(t) => {
            if opts.date_style.is_some() {
                return vm.throw_type("dateStyle cannot format a time-only Temporal value");
            }
            opts.time_zone = Some("UTC".to_string());
            let ms = ms_of(&IsoDate::new(1970, 1, 1), &t);
            let r = dt::to_locale_time_string(ms, &locales, &opts);
            dt_result(vm, r)
        }
        Slot::DateTime(d, cal) => {
            check_calendar(vm, cal, &opts, true)?;
            opts.time_zone = Some("UTC".to_string());
            let ms = ms_of(&d.date, &d.time);
            let r = dt::to_locale_string(ms, &locales, &opts);
            dt_result(vm, r)
        }
        Slot::YearMonth(d, cal) => {
            check_calendar(vm, cal, &opts, false)?;
            opts.time_zone = Some("UTC".to_string());
            let ms = ms_of(&d, &Time::MIDNIGHT);
            let r = dt::to_locale_date_string(ms, &locales, &opts);
            dt_result(vm, r)
        }
        Slot::MonthDay(d, cal) => {
            check_calendar(vm, cal, &opts, false)?;
            opts.time_zone = Some("UTC".to_string());
            let ms = ms_of(&d, &Time::MIDNIGHT);
            let r = dt::to_locale_date_string(ms, &locales, &opts);
            dt_result(vm, r)
        }
        Slot::Instant(ns) => {
            let ms = ns.div_euclid(1_000_000) as f64;
            let r = dt::to_locale_string(ms, &locales, &opts);
            dt_result(vm, r)
        }
        Slot::Zoned(ns, tz, cal) => {
            if opts.time_zone.is_some() {
                return vm.throw_type("the timeZone option is not allowed for Temporal.ZonedDateTime.prototype.toLocaleString");
            }
            check_calendar(vm, cal, &opts, true)?;
            opts.time_zone = Some(tz.id());
            if opts.time_zone_name.is_none() && opts.date_style.is_none() && opts.time_style.is_none() {
                let _ = opts.set("timeZoneName", "short");
            }
            let ms = ns.div_euclid(1_000_000) as f64;
            let r = dt::to_locale_string(ms, &locales, &opts);
            dt_result(vm, r)
        }
        Slot::Duration(_) => Ok(Value::Undefined),
    }
}

/// Intl.DurationFormat "short" style subset
pub fn duration_to_locale(d: &dur::Dur) -> String {
    let units: [(f64, &str, &str); 10] = [
        (d.years, "yr", "yrs"),
        (d.months, "mth", "mths"),
        (d.weeks, "wk", "wks"),
        (d.days, "day", "days"),
        (d.hours, "hr", "hr"),
        (d.minutes, "min", "min"),
        (d.seconds, "sec", "sec"),
        (d.milliseconds, "ms", "ms"),
        (d.microseconds, "μs", "μs"),
        (d.nanoseconds, "ns", "ns"),
    ];
    let mut parts = Vec::new();
    for (v, one, many) in units {
        if v != 0.0 {
            let n = crate::numconv::number_to_string(v);
            parts.push(format!("{} {}", n, if v.abs() == 1.0 { one } else { many }));
        }
    }
    if parts.is_empty() {
        return "0 sec".to_string();
    }
    parts.join(", ")
}

