//! Non-Gregorian calendars (placeholder: ISO arithmetic).

use super::calendar::{Cal, MonthCode};
use super::dur::DateDur;
use super::fields::Fields;
use super::iso::*;
use super::*;

pub fn from_iso(_cal: Cal, d: &IsoDate) -> (i64, u8, u8) {
    (d.year, d.month, d.day)
}

pub fn to_iso(_cal: Cal, y: i64, m: u8, d: u8) -> IsoDate {
    IsoDate::new(y, m, d)
}

pub fn months_in_year(_cal: Cal, _y: i64) -> u8 {
    12
}

pub fn days_in_month(_cal: Cal, y: i64, m: u8) -> u8 {
    iso::days_in_month(y, m)
}

pub fn days_in_year(_cal: Cal, y: i64) -> u16 {
    iso::days_in_year(y)
}

pub fn in_leap_year(_cal: Cal, y: i64) -> bool {
    is_leap(y)
}

pub fn month_code(_cal: Cal, _y: i64, m: u8) -> MonthCode {
    MonthCode { num: m, leap: false }
}

pub fn ordinal_of_code(_cal: Cal, _y: i64, mc: MonthCode) -> Option<u8> {
    if !mc.leap && (1..=12).contains(&mc.num) {
        Some(mc.num)
    } else {
        None
    }
}

pub fn code_valid(_cal: Cal, mc: MonthCode) -> bool {
    !mc.leap && (1..=12).contains(&mc.num)
}

pub fn constrain_code(_cal: Cal, _y: i64, mc: MonthCode) -> u8 {
    mc.num.clamp(1, 12)
}

pub fn era_of(_cal: Cal, _d: &IsoDate) -> Option<(String, i64)> {
    None
}

pub fn year_from_era(_cal: Cal, _era: &str, _ey: i64) -> Option<i64> {
    None
}

pub fn month_day_to_iso_reference(_cal: Cal, f: &Fields, overflow: Overflow) -> TRes<IsoDate> {
    let r = super::calendar::regulate_iso_date(f.year.unwrap_or(1972.0), f.month.unwrap_or(1.0), f.day.unwrap_or(1.0), overflow)?;
    Ok(IsoDate::new(1972, r.month, r.day))
}

pub fn date_add(_cal: Cal, d: &IsoDate, dd: &DateDur, overflow: Overflow) -> TRes<IsoDate> {
    super::calendar::date_add(Cal::Iso8601, d, dd, overflow)
}

pub fn date_until(_cal: Cal, one: &IsoDate, two: &IsoDate, largest: Unit) -> DateDur {
    super::calendar::date_until(Cal::Iso8601, one, two, largest)
}

