fn species(_vm: &mut Vm, a: &Args) -> JsResult<Value> {
    Ok(a.this.clone())
}

fn incompatible<T>(vm: &mut Vm) -> JsResult<T> {
    vm.throw_type("method called on an incompatible receiver")
}

fn this_map(vm: &mut Vm, a: &Args) -> JsResult<Obj> {
