    }
    let t = vm.construct(&c, &[Value::Num(a.args.len() as f64)], None)?;
    for (i, v) in a.args.iter().enumerate() {
        vm.set_prop_of(&t, PropKey::from_index(i as u32), v.clone(), true)?;
    }
    Ok(t)
