const zlib = require('zlib');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const dir = '/workspace/assets/test_runtime_compression';
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
const ref = fs.readFileSync(path.join(dir, 'random.bin'));
console.log('random.bin', ref.length, sha(ref));
for (const f of fs.readdirSync(dir).sort()) {
  const data = fs.readFileSync(path.join(dir, f));
  let fn = null;
  if (f.endsWith('.gz')) fn = 'gunzipSync';
  else if (f.endsWith('.zz')) fn = 'inflateSync';
  else if (f.endsWith('.raw')) fn = 'inflateRawSync';
  else if (f.endsWith('.br')) fn = 'brotliDecompressSync';
  else if (f.endsWith('.zst')) fn = 'zstdDecompressSync';
  if (!fn) continue;
