const c = require('crypto');
const util = require('util');
const show = (k) => {
  const a = k._asym;
  const o = {};
  for (const p of Object.keys(a)) { const v = a[p]; o[p] = typeof v === 'bigint' ? 'bigint:' + v.toString(16).slice(0, 16) : v instanceof Uint8Array ? v.constructor.name + '(' + v.length + ')' : v; }
  return JSON.stringify(o);
};
for (const [t, opts] of [['ed25519'], ['x25519'], ['ec', {namedCurve: 'P-256'}], ['rsa', {modulusLength: 512}]]) {
  const {publicKey, privateKey} = c.generateKeyPairSync(t, opts);
  console.log(t, Object.keys(publicKey).join(), publicKey._material, show(publicKey), show(privateKey));
  console.log(t, publicKey.type, privateKey.type, publicKey.asymmetricKeyType, util.inspect(publicKey.asymmetricKeyDetails), publicKey.symmetricKeySize);
  console.log(t, typeof publicKey.export({format: 'pem', type: 'spki'}), publicKey.export({format: 'der', type: 'spki'}).length, JSON.stringify(Object.keys(publicKey.export({format: 'jwk'}))));
  console.log(t, privateKey.export({format: 'pem', type: 'pkcs8'}).split('\n')[0], JSON.stringify(Object.keys(privateKey.export({format: 'jwk'}))));
}

