const util = require('util');
function lcsDiff(a, b, variant) {
  const n = a.length, m = b.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = 1; i <= n; i++) for (let j = 1; j <= m; j++) dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  let i = n, j = m; const res = [];
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && a[i - 1] === b[j - 1]) { res.push([0, a[i - 1]]); i--; j--; }
    else if (j === 0 || (i > 0 && (variant.ge ? dp[i - 1][j] >= dp[i][j - 1] : dp[i - 1][j] > dp[i][j - 1]))) { res.push([1, a[i - 1]]); i--; }
    else { res.push([-1, b[j - 1]]); j--; }
  }
  return res.reverse();
}
// forward DP from the start (suffix LCS)
function lcsFwd(a, b, variant) {
  const n = a.length, m = b.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  let i = 0, j = 0; const res = [];
  while (i < n || j < m) {
    if (i < n && j < m && a[i] === b[j]) { res.push([0, a[i]]); i++; j++; }
    else if (j === m || (i < n && (variant.ge ? dp[i + 1][j] >= dp[i][j + 1] : dp[i + 1][j] > dp[i][j + 1]))) { res.push([1, a[i]]); i++; }
    else { res.push([-1, b[j]]); j++; }
  }
  return res;
}
const cases = [['aaa', 'aa'], ['abcabba', 'cbabac'], ['kitten', 'sitting'], ['abcd', 'acbd'], ['ab', 'ba'], ['hello world', 'hello there'], ['12345', '2345'], ['abc', 'xyz'], ['12345', '1234']];
for (const [a, b] of cases) {
  const want = JSON.stringify(util.diff(a, b));
