// deterministic pseudo-random URL fuzzing
let seed = Number(process.argv[2] || 1);
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const pieces = ['http', 'https', 'ftp', 'ws', 'wss', 'file', 'mailto', 'data', 'custom', 'HTTP', 'a+b', ':', '//', '/', '?', '#', '@', '[', ']', '::1', 'user', 'pw', 'host', 'HOST', '.', '..', '%20', '%zz', ' ', '\t', '\\', '80', '443', '8080', '0', '65536', 'x', 'ü', 'é', '&', '=', '+', '\u0000', 'localhost', '127.0.0.1', 'a.b.c', '-', '_', '~', '*'];
const bases = [undefined, 'http://base.com/a/b?q#f', 'file:///dir/file', 'custom:opaque', 'custom://h/p/q', 'mailto:x@y', 'not a base', ''];
const N = Number(process.argv[3] || 2000);
for (let i = 0; i < N; i++) {
  let s = '';
  const len = 1 + Math.floor(rnd() * 8);
  for (let j = 0; j < len; j++) s += pick(pieces);
  const base = pick(bases);
  let out;
  try {
    const u = base === undefined ? new URL(s) : new URL(s, base);
    out = u.href + ' | ' + [u.protocol, u.username, u.password, u.host, u.hostname, u.port, u.pathname, u.search, u.hash, u.origin].join(' | ');
    u.searchParams.append('k', s);
    out += ' || ' + u.href;
  } catch (e) {
    out = 'ERR ' + e.name + ': ' + e.message;
  }
  console.log(JSON.stringify(s), JSON.stringify(base), out);
}

