  const rs = new ReadableStream({ start(c) { c.enqueue(1); c.enqueue(2); c.error(new Error("mid")); } });
  try { for await (const x of rs) L("x " + x); } catch (e) { L("caught " + e.message); }
  const rs2 = new ReadableStream({ start(c) { c.enqueue(1); }, pull(c) { c.error(new Error("pull err")); } });
  const r2 = rs2.getReader();
  L(JSON.stringify(await r2.read()));
  try { await r2.read(); } catch (e) { L("r2 " + e.message); }
  const ts = new TransformStream({ flush() { throw new Error("flush failed"); } });
  const w = ts.writable.getWriter();
  try { await w.close(); } catch (e) { L("close err " + e.message + " ws=" + ts.writable._state + " rs=" + ts.readable._state); }
  const ws = new WritableStream({ write(c) { L("w " + c); } }, { highWaterMark: 2 });
  const wr = ws.getWriter();
  L("ds " + wr.desiredSize);
  await wr.ready;
  const p = wr.write("a");
  L("ds after write " + wr.desiredSize);
  await p;
  L("ds after done " + wr.desiredSize);
  await wr.close();
  L("ds closed " + wr.desiredSize);
  const rs3 = new ReadableStream({ start(c) { c.enqueue("z"); } });
  const r3 = rs3.getReader();
  r3.releaseLock();
  L("closed after release: " + await r3.closed.then(() => "resolved", () => "rejected"));
  const rs4 = new ReadableStream({ cancel(reason) { L("cancel reason " + reason); } });
  await rs4.cancel("my reason");
  L("rs4 state " + rs4._state);
  const rs5 = new ReadableStream({ pull(c) { L("pull called desired=" + c.desiredSize); c.enqueue("p"); } }, { highWaterMark: 5, size() { return 1; } });
  L("rs5 created");
  L(JSON.stringify(await rs5.getReader().read()));
})();
//// misc3.js
const L = (s) => console.log(s);
(async () => {
  // reading body twice via different methods
  const r = new Response("abc");
  const t = await r.text();
  try { await r.arrayBuffer(); } catch (e) { L(e.message); }
  try { await r.json(); } catch (e) { L(e.message); }
  try { await r.blob(); } catch (e) { L(e.message); }
  try { await r.bytes(); } catch (e) { L(e.message); }
  L(t + " " + r.bodyUsed);
  // Response body piping into a writable
  const chunks = [];
  await new Response("piped data").body.pipeTo(new WritableStream({ write(c) { chunks.push(c.length); } }));
  L("piped " + chunks);
  // json with BOM
  const j = await new Response(new Uint8Array([0xef, 0xbb, 0xbf, 0x7b, 0x7d])).json();
  L("bom json " + JSON.stringify(j));
  // text with invalid utf8
  L(JSON.stringify(await new Response(new Uint8Array([0x61, 0xff, 0x62])).text()));
  // response from TransformStream readable
  const ts = new TransformStream({ transform(chunk, c) { c.enqueue(new TextEncoder().encode(chunk.toUpperCase())); } });
  const w = ts.writable.getWriter();
  w.write("hello ");
  w.write("world");
  w.close();
  try { L(await new Response(ts.readable).text()); } catch (e) { L("ts body err " + e.message); }
  // headers getters after set-cookie
  const h = new Headers();
  h.append("a", "1");
  h.append("A", "2");
  L(h.get("a"));
})();
//// misc4.js
const L = (s) => console.log(s);
const { ReadableStream: RS, WritableStream: WS, TextEncoderStream: TES } = require("stream/web");
L((RS === ReadableStream) + " " + (WS === WritableStream) + " " + (TES === TextEncoderStream));
L(Object.keys(require("stream/web")).join());

