const util = require('util');
const fs = require('fs');
const assert = require('assert');
const readFile = util.promisify(fs.readFile);
const sleep = util.promisify(setTimeout);
(async () => {
  try {
    const data = await readFile(__filename, 'utf8');
    console.log('read ok', data.length > 0);
  } catch (e) { console.log('read err', e.message); }
  try { await readFile('/nonexistent/file'); } catch (e) { console.log('read missing', e.code, e.name); }
  const t0 = Date.now();
  await sleep(10).catch((e) => console.log('sleep err', e.message));
  console.log('slept');
  await assert.rejects(async () => { throw new TypeError('boom'); }, TypeError);
  console.log('rejects ok');
