let seed = Number(process.argv[2] || 1);
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const chars = ['a', 'b', '=', '&', '?', '+', '%', '%2', '%20', '%41', '%E2%82%AC', '%FF', ' ', 'é', '😀', '#', '/', ';', '~', '*', "'", '(', 'x', 'y', 'k'];
const str = () => { let s = ''; const n = Math.floor(rnd() * 6); for (let i = 0; i < n; i++) s += pick(chars); return s; };
const N = Number(process.argv[3] || 300);
for (let i = 0; i < N; i++) {
  const sp = new URLSearchParams(str());
  const log = [];
  for (let j = 0; j < 6; j++) {
    const op = pick(['append', 'set', 'delete', 'get', 'getAll', 'has', 'sort', 'toString', 'size']);
    const k = pick(['a', 'b', 'k', str()]);
    try {
      let r;
      if (op === 'append' || op === 'set') r = sp[op](k, str());
      else if (op === 'size') r = sp.size;
      else if (op === 'toString' || op === 'sort') r = sp[op]();
      else r = sp[op](k);
      log.push(op + '(' + JSON.stringify(k) + ')=' + JSON.stringify(r));
    } catch (e) { log.push(op + ' ERR ' + e.message); }
  }
  console.log(log.join(' ; '), '=>', sp.toString(), JSON.stringify([...sp]));
}
// URL setters fuzz
const setters = ['hostname', 'port', 'pathname', 'search', 'hash', 'href'];
for (let i = 0; i < N; i++) {
  const u = new URL(pick(['http://u:p@h.com:81/a/b?c=d#e', 'file:///x/y', 'custom://h/p', 'mailto:a@b', 'https://h/']));
  const s = pick(setters);
  const v = str() + pick(['', '1', 'host.com', '/p', '?q', '#f', 'http://z/']);
  try { u[s] = v; console.log(s, JSON.stringify(v), u.href, u.searchParams.toString()); } catch (e) { console.log(s, JSON.stringify(v), 'ERR', e.message); }
}

