let seed = Number(process.argv[2] || 1);
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const toks = ['/', ':id', ':name', '*', '(\\d+)', '(a|b)', '{', '}', '?', '+', '.', 'x', 'api', '-', ':', '(', ')', '\\', 'v1', ':a(', '{x}?', '{y}+', '$', '^', '[', ']'];
const pat = () => { let s = ''; const n = 1 + Math.floor(rnd() * 6); for (let i = 0; i < n; i++) s += pick(toks); return s; };
const urls = ['https://example.com/api/v1/123', 'http://a.b.c/x/y/z?q=1#h', 'https://example.com/', 'http://h/123', 'http://h/a', 'http://h/b-c', 'https://u:p@h:8080/api/x.png'];
const N = Number(process.argv[3] || 300);
const comps = ['protocol', 'username', 'password', 'hostname', 'port', 'pathname', 'search', 'hash'];
for (let i = 0; i < N; i++) {
  const kind = Math.floor(rnd() * 3);
  let input;
  if (kind === 0) input = { pathname: pat() };
  else if (kind === 1) input = { hostname: pat(), pathname: pat(), search: pat() };
  else input = pick(['https://', 'http://', '', '*://']) + pick(['example.com', '*.example.com', 'h', ':sub.h']) + pat() + pick(['', '?q=:v', '#*']);
  let p;
  try { p = new URLPattern(input); } catch (e) { console.log('ctor ERR', e.name, e.message, JSON.stringify(input)); continue; }
  const desc = JSON.stringify(input) + ' ' + comps.map(c => p[c] + '=>' + p._parts[c].regex.source + JSON.stringify(p._parts[c].names)).join(' ');
  const res = urls.map(u => { try { const r = p.exec(u); return r ? JSON.stringify(comps.map(c => r[c].groups)) : 'null'; } catch (e) { return 'ERR ' + e.message; } });
  console.log(desc, '::', res.join(' '));
}

