    default: return pick([new Error('x'), new TypeError('x'), Buffer.from('a')]);
  }
}
function mutate(v, d) {
  if (rnd() < 0.5) return v;
  if (v && typeof v === 'object' && !(v instanceof Date) && !(v instanceof RegExp) && rnd() < 0.7 && d < 3) {
    if (Array.isArray(v)) return v.map(x => mutate(x, d + 1));
    if (v instanceof Map) { const m = new Map(); for (const [k, x] of v) m.set(k, mutate(x, d + 1)); return m; }
    if (v instanceof Set) return new Set(v);
    if (Object.getPrototypeOf(v) === Object.prototype) { const o = {}; for (const k of Object.keys(v)) o[k] = mutate(v[k], d + 1); return o; }
