  try { r.push(url.domainToUnicode(s)); } catch (e) { r.push('ERR ' + e.message); }
  try { r.push(url.fileURLToPath(s)); } catch (e) { r.push('ERR ' + e.message); }
  try { r.push(url.pathToFileURL(s).href); } catch (e) { r.push('ERR ' + e.message); }
  try { r.push(btoa(s)); } catch (e) { r.push('ERR ' + e.message); }
  try { r.push(JSON.stringify(atob(s))); } catch (e) { r.push('ERR ' + e.message); }
  try { r.push(new TextEncoder().encode(s).join(',')); } catch (e) { r.push('ERR ' + e.message); }
  const bytes = new Uint8Array(Math.floor(rnd() * 8)).map(() => Math.floor(rnd() * 256));
