let seed = Number(process.argv[2] || 1);
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const url = require('url');
const pieces = ['a', 'b', 'z', '0', '9', '-', '.', 'ü', 'ß', 'é', '日', '本', '語', '中', '文', 'я', 'ж', 'ä', 'ö', '😀', '🎉', '。', '．', '｡', 'A', 'Ü', 'xn--', 'XN--', '@', 'ñ', 'ç', 'ø', 'α', 'β', '́', 'Ж'];
for (let i = 0; i < Number(process.argv[3] || 500); i++) {
  let s = '';
  const n = 1 + Math.floor(rnd() * 10);
  for (let j = 0; j < n; j++) s += pick(pieces);
  let a, b, c;
  try { a = url.domainToASCII(s); } catch (e) { a = 'ERR ' + e.name + ' ' + e.message; }
  try { b = url.domainToUnicode(a); } catch (e) { b = 'ERR ' + e.name + ' ' + e.message; }
  try { c = url.domainToUnicode(s); } catch (e) { c = 'ERR ' + e.name + ' ' + e.message; }
  console.log(JSON.stringify(s), JSON.stringify(a), JSON.stringify(b), JSON.stringify(c));
}
const bad = ['xn--', 'xn--a', 'xn--zz', 'xn--99999999999', 'xn--ü', 'xn--a-', 'xn---', 'xn--abc-', 'xn--abc-0', 'xn--abc-ü', 'xn--9999999999999999999999a'];
for (const s of bad) { try { console.log(s, JSON.stringify(url.domainToUnicode(s))); } catch (e) { console.log(s, 'ERR', e.name, e.message); } }

