const log = (...a) => console.log(...a);
// async ordering
c.generateKeyPair('ed25519', (e, pub, priv) => log('gkp cb', e, pub.type, priv.type, arguments.length));
c.generateKeyPair('ec', {namedCurve: 'P-256', publicKeyEncoding: {type: 'spki', format: 'pem'}}, (e, pub, priv) => log('gkp ec', typeof pub, priv.type));
c.generateKeyPair('dsa', {}, (e) => log('gkp err', e.message));
try { c.generateKeyPair('ed25519'); } catch (e) { log('gkp nocb', e.message); }
c.sign(null, Buffer.from('x'), c.generateKeyPairSync('ed25519').privateKey, (e, s) => log('sign cb', e, s.length));
c.verify(null, Buffer.from('x'), c.generateKeyPairSync('ed25519').publicKey, Buffer.alloc(64), (e, ok) => log('verify cb', e, ok));
c.checkPrime(7n, (e, r) => log('checkPrime cb', e, r));
c.checkPrime(Buffer.from([8]), {checks: 3}, (e, r) => log('checkPrime cb2', e, r));
c.generatePrime(16, (e, p) => log('generatePrime cb', e, p instanceof ArrayBuffer, p.byteLength));
c.generatePrime(16, {bigint: true}, (e, p) => log('generatePrime bigint', typeof p, p > 32768n));
Promise.resolve().then(() => log('micro'));
log('sync');
log(c.checkPrimeSync(17n), c.checkPrimeSync(18n), c.checkPrimeSync(Buffer.from([0x0b])), c.checkPrimeSync(new Uint8Array([1, 1])), c.checkPrimeSync(-7n), c.checkPrimeSync(0n), c.checkPrimeSync(2n));
const p = c.generatePrimeSync(32, {bigint: true});
log(typeof p, c.checkPrimeSync(p), p.toString(2).length);
const ps = c.generatePrimeSync(32, {safe: true, bigint: true});
log(c.checkPrimeSync(ps), c.checkPrimeSync((ps - 1n) / 2n));
const pa = c.generatePrimeSync(24, {add: 12n, rem: 7n, bigint: true});
log(pa % 12n, c.checkPrimeSync(pa));
log(Buffer.from(c.generatePrimeSync(64)).length);
for (const bad of [[3, {add: 4n, rem: 2n}], [8, {add: 4n, rem: 6n}], [8, {add: -1n}], [1.5], ['8'], [8, {add: Buffer.from([4]), rem: Buffer.from([1])}]]) {
  try { const r = c.generatePrimeSync(...bad); log('gp', bad[0], typeof r); } catch (e) { log('gp', bad[0], e.name, e.message); }
}
