    'ArrayIterator': 'Target::Intr(|i| i.array_iterator_proto.clone())',
    'MapIterator': 'Target::Intr(|i| i.map_iterator_proto.clone())',
    'SetIterator': 'Target::Intr(|i| i.set_iterator_proto.clone())',
    'StringIterator': 'Target::Intr(|i| i.string_iterator_proto.clone())',
    'RegExpStringIterator': 'Target::Intr(|i| i.regexp_string_iterator_proto.clone())',
    'IteratorHelper': 'Target::Intr(|i| i.iterator_helper_proto.clone())',
    'WrapForValidIterator': 'Target::Intr(|i| i.wrap_iterator_proto.clone())',
    'Generator': 'Target::Intr(|i| i.generator_proto.clone())',
    'GeneratorFunction': 'Target::Intr(|i| i.generator_function_proto.clone())',
    'AsyncGenerator': 'Target::Intr(|i| i.async_generator_proto.clone())',
    'AsyncGeneratorFunction': 'Target::Intr(|i| i.async_generator_function_proto.clone())',
    'AsyncFunction': 'Target::Intr(|i| i.async_function_proto.clone())',
    'AsyncIterator': 'Target::Intr(|i| i.async_iterator_proto.clone())',
    'globalThis': 'Target::Global',
}
out = []
for ln in lines:
    label, _, keys = ln.partition(': ')
    keys = keys.split(',') if keys else []
    conv = []
    for k in keys:
        m = re.match(r'Symbol\((Symbol\.\w+)\)$', k)
        if m:
            conv.append('@' + m.group(1))
        else:
            conv.append(k)
    if label in special:
        tgt = special[label]
    elif label.endswith('.prototype'):
        tgt = 'Target::Proto("%s")' % label[:-len('.prototype')]
    else:
        tgt = 'Target::Glob("%s")' % label
    out.append('    (%s, &[%s]),' % (tgt, ', '.join('"%s"' % c.replace('\\', '\\\\').replace('"', '\\"') for c in conv)))
