const store = new WeakMap();
globalThis.Blob = class Blob {
  constructor(parts = [], o = {}) { store.set(this, new TextEncoder().encode(parts.join(""))); this._t = o.type || ""; }
  get type() { return this._t; }
  get size() { return store.get(this).length; }
  async arrayBuffer() { const b = store.get(this); return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength); }
  stream() { throw new Error("no stream"); }
};
const b = new Blob(["hello blob"], { type: "text/x" });
const r = new Response(b);
console.log(r.headers.get("content-type"));
r.text().then((t) => console.log("text:", t));
globalThis.Blob = class Blob2 {
  constructor(parts = []) { this._p = parts.join(""); }
  get type() { return ""; }
  arrayBuffer() { return new Promise((res) => setTimeout(() => res(new ArrayBuffer(1)), 1)); }
  stream() { const s = this._p; return new ReadableStream({ start(c) { c.enqueue(s); c.close(); } }); }
};
new Response(new Blob(["via stream"])).text().then((t) => console.log("text2:", t));

