    if indent.is_empty() {
        return text;
    }
    let mut out: Vec<u16> = Vec::with_capacity(text.len() + indent.len());
    out.extend_from_slice(indent);
    for c in text {
        out.push(c);
        if c == b'\\n' as u16 {
            out.extend_from_slice(indent);
        }
    }
    out
