567	fn units_for_encoding(vm: &mut Vm, s: &Value, e: Enc, interpreted: bool) -> JsResult<Vec<u16>> {
568	    if let Value::Str(st) = s {
569	        return Ok(st.units().to_vec());
570	    }
571	    match e {
572	        Enc::Utf8 => match s {
573	            Value::Undefined => Ok(Vec::new()),
574	            Value::Sym(sym) => Ok(sym.descriptive_string().encode_utf16().collect()),
575	            other => Ok(vm.to_string(other)?.units().to_vec()),
