600	fn encode_form_data(vm: &mut Vm, fd: &Value) -> JsResult<(Vec<u8>, String)> {
601	    let boundary = format!("----lumenFormBoundary{}", random_hex(32));
602	    let mut out: Vec<u8> = Vec::new();
603	    let entries = vm.iterate_to_vec(fd)?;
604	    for e in entries {
605	        let name = get(vm, &e, "0")?;
606	        let value = get(vm, &e, "1")?;
607	        let name = js_string(vm, &name)?.to_rust_string();
608	        out.extend_from_slice(format!("--{}\r\n", boundary).as_bytes());
609	        if let Value::Str(s) = &value {
610	            out.extend_from_slice(format!("Content-Disposition: form-data; name=\"{}\"\r\n\r\n", escape_form_name(&name)).as_bytes());
611	            out.extend_from_slice(&str_to_utf8(s.units()));
612	        } else {
613	            let fname = get(vm, &value, "name")?;
614	            let fname = if fname.is_undefined() || fname.is_null() { "blob".to_string() } else { str_value(vm, &fname)? };
615	            let ty = get(vm, &value, "type")?;
616	            let ty = if ty.truthy() { str_value(vm, &ty)? } else { "application/octet-stream".to_string() };
617	            out.extend_from_slice(
618	                format!("Content-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\nContent-Type: {}\r\n\r\n", escape_form_name(&name), fname.replace('"', "%22"), ty)
619	                    .as_bytes(),
