    let r = (|| -> JsResult<Value> {
        let o = match a.arg(0) {
            Value::Obj(o) => o,
            _ => return vm.throw_type("argument must be an object"),
        };
        let resolve = get_promise_resolve(vm, &c)?;
        let keys = vm.own_property_keys(&o)?;
        let mut entries = Vec::new();
        for k in keys {
            if let Some(d) = vm.get_own_property(&o, &k)? {
                if d.enumerable == Some(true) {
                    let v = vm.get(&o, &k, &Value::Obj(o.clone()))?;
                    entries.push((k, v));
                }
            }
        }
        let key_vals: Vec<Value> = entries
            .iter()
            .map(|(k, _)| match k {
                PropKey::Str(s) => Value::Str(s.clone()),
                PropKey::Sym(s) => Value::Sym(s.clone()),
            })
            .collect();
        let keys_arr = vm.new_array(key_vals);
        let finisher = Value::Obj(vm.native_closure("", 1, keyed_finish, vec![Value::Obj(keys_arr), cap.resolve.clone()]));
        let state = combinator_state(0);
        for (index, (_, v)) in entries.into_iter().enumerate() {
            with_comb(&state, |s| s.values.borrow_mut().push(Value::Undefined));
            let next_p = vm.call(&resolve, c.clone(), &[v])?;
            with_comb(&state, |s| s.remaining.set(s.remaining.get() + 1));
