                (Value::Obj(f), Value::Obj(r))
            } else {
                let f = vm.native_closure("", 1, all_resolve_element, vec![state.clone(), idx, finisher.clone(), called]);
                (Value::Obj(f), cap.reject.clone())
            };
            let then = vm.get_prop_of(&next_p, &vm.intr.key_then.clone())?;
            vm.call(&then, next_p, &[onf, onr])?;
        }
        let remaining = with_comb(&state, |s| {
            s.remaining.set(s.remaining.get() - 1);
            s.remaining.get()
        });
        if remaining == 0 {
            let vals = with_comb(&state, |s| s.values.borrow().clone());
            let arr = vm.new_array(vals);
            vm.call(&finisher, Value::Undefined, &[Value::Obj(arr)])?;
        }
        Ok(cap.promise.clone())
    })();
    match r {
        Ok(p) => Ok(p),
        Err(e) => {
            vm.call(&cap.reject, Value::Undefined, &[e])?;
