const N = Number(process.argv[2] || 1000);
const mode = process.argv[3] || "forawait";
let t0 = Date.now();
(async () => {
  if (mode === "forawait") {
    const rs = new ReadableStream({ start(c) { for (let i = 0; i < N; i++) c.enqueue(i); c.close(); } });
    let sum = 0;
    for await (const x of rs) sum += x;
    console.log("forawait ms", Date.now() - t0, sum);
  } else if (mode === "ts") {
    const ts = new TransformStream({ transform(ch, c) { c.enqueue(ch * 2); } });
    const w = ts.writable.getWriter();
    for (let i = 0; i < N; i++) w.write(i);
    console.log("writes queued ms", Date.now() - t0);
    w.close();
    let s2 = 0;
    const r = ts.readable.getReader();
    for (;;) { const { value, done } = await r.read(); if (done) break; s2 += value; }
    console.log("ts ms", Date.now() - t0, s2);
  } else if (mode === "ws") {
    const ws = new WritableStream({ write(c) {} });
    const w = ws.getWriter();
    for (let i = 0; i < N; i++) w.write(i);
    console.log("ws queued ms", Date.now() - t0);
    await w.close();
    console.log("ws ms", Date.now() - t0);
  } else if (mode === "chain") {
    let p = Promise.resolve();
    for (let i = 0; i < N; i++) p = p.then(() => {}).then(() => {});
    await p;
    console.log("chain ms", Date.now() - t0);
  }
})();

