// Extract calendar tables from the original
const which = process.argv[2];
function epochDays(pd) {
  const iso = pd.withCalendar('iso8601');
  return Math.round(Date.UTC(iso.year, iso.month - 1, iso.day) / 86400000);
}
if (which === 'umalqura') {
  const out = [];
  for (let y = 1300; y <= 1600; y++) {
    const d0 = Temporal.PlainDate.from({ year: y, monthCode: 'M01', day: 1, calendar: 'islamic-umalqura' });
    let mask = 0;
    for (let m = 1; m <= 12; m++) {
      const dm = d0.with({ month: m });
      if (dm.daysInMonth === 30) mask |= 1 << (m - 1);
      else if (dm.daysInMonth !== 29) throw new Error('bad len');
    }
    out.push(`${epochDays(d0)},${mask}`);
  }
  console.log(out.join(';'));
} else if (which === 'chinese' || which === 'dangi') {
  const from = Number(process.argv[3]), to = Number(process.argv[4]);
  const out = [];
  for (let y = from; y <= to; y++) {
    const d0 = Temporal.PlainDate.from({ year: y, monthCode: 'M01', day: 1, calendar: which });
    const miy = d0.monthsInYear;
    let mask = 0, leap = 0;
    for (let m = 1; m <= miy; m++) {
      const dm = d0.with({ month: m });
      if (dm.daysInMonth === 30) mask |= 1 << (m - 1);
      else if (dm.daysInMonth !== 29) throw new Error('bad len ' + y + ' ' + m + ' ' + dm.daysInMonth);
      if (dm.monthCode.endsWith('L')) leap = m;
    }
    if (d0.month !== 1) throw new Error('M01 not first ' + y);
    out.push(`${epochDays(d0)},${miy},${mask},${leap}`);
  }
  console.log(out.join(';'));
} else if (which === 'persian') {
  const from = Number(process.argv[3]), to = Number(process.argv[4]);
  const out = [];
  for (let y = from; y <= to; y++) {
    const d0 = Temporal.PlainDate.from({ year: y, monthCode: 'M01', day: 1, calendar: 'persian' });
    out.push(`${y}:${epochDays(d0)}:${d0.inLeapYear ? 1 : 0}`);
  }
  console.log(out.join('\n'));
}

