function cps(s) { return Array.from(s).map(c => { const p = c.codePointAt(0); return p < 128 ? c : '<' + p.toString(16).toUpperCase() + '>'; }).join(''); }
const nums = [0, -0, 1, -1, 1.5, -1234.567, 1e6];
const curs = ['USD', 'EUR', 'JPY', 'GBP', 'CNY', 'CAD', 'AUD', 'INR', 'KRW', 'CHF', 'BHD', 'KWD', 'CLP', 'ISK', 'HKD', 'TWD', 'NZD', 'MXN', 'BRL', 'XAF', 'XXX'];
for (const loc of ['en', 'de', 'fr', 'ja', 'es', 'ar', 'zh', 'hi', 'ru']) {
  for (const disp of ['symbol', 'narrowSymbol', 'code', 'name']) {
    const out = [];
    for (const c of curs) {
      const f = new Intl.NumberFormat(loc, {style: 'currency', currency: c, currencyDisplay: disp});
      out.push(c + ':' + cps(f.format(-1234.567)));
    }
    console.log(loc + ' ' + disp + ': ' + out.join(' '));
  }
}
for (const loc of ['en', 'de', 'fr', 'ja', 'es']) {
  for (const sign of ['standard', 'accounting']) {
    for (const sd of ['auto', 'always', 'never', 'exceptZero', 'negative']) {
      const f = new Intl.NumberFormat(loc, {style: 'currency', currency: 'USD', currencySign: sign, signDisplay: sd});
      console.log(loc + ' ' + sign + ' ' + sd + ': ' + nums.map(n => cps(f.format(n))).join(' | '));
    }
  }
}
for (const sd of ['auto', 'always', 'never', 'exceptZero', 'negative']) {
  const f = new Intl.NumberFormat('en', {signDisplay: sd});
  const g = new Intl.NumberFormat('en', {signDisplay: sd, style: 'percent'});
  console.log('decimal ' + sd + ': ' + [0, -0, 1, -1, 0.0001, -0.0001, NaN, Infinity, -Infinity].map(n => cps(f.format(n))).join(' | ') + ' || ' + [0, -0, 0.5, -0.5].map(n => cps(g.format(n))).join(' | '));
}

