const util = require('util');
const assert = require('assert');
function nest(n, arr) { let o = arr ? [] : {}; const r = o; for (let i = 0; i < n; i++) { const c = arr ? [] : {}; if (arr) o.push(c); else o.n = c; o = c; } return r; }
function works(f) { try { f(); return true; } catch (e) { if (e instanceof RangeError) return false; throw e; } }
function search(f) { let lo = 1, hi = 100000; while (lo < hi) { const mid = Math.floor((lo + hi + 1) / 2); if (works(() => f(mid))) lo = mid; else hi = mid - 1; } return lo; }
console.log('inspect obj', search((n) => util.inspect(nest(n), { depth: Infinity })));
console.log('inspect arr', search((n) => util.inspect(nest(n, true), { depth: Infinity })));
console.log('format %o', search((n) => util.format('%o', nest(n))));
console.log('deepStrictEqual', search((n) => assert.deepStrictEqual(nest(n), nest(n))));
console.log('deepEqual', search((n) => assert.deepEqual(nest(n), nest(n))));
console.log('isDeepStrictEqual', search((n) => util.isDeepStrictEqual(nest(n), nest(n))));
function rec(n) { return n === 0 ? 0 : 1 + rec(n - 1); }
console.log('plain recursion', search((n) => rec(n)));

