function cps(s) { return Array.from(s).map(c => { const p = c.codePointAt(0); return p < 128 ? c : '<' + p.toString(16).toUpperCase() + '>'; }).join(''); }
const combos = ['kilometer-per-hour', 'meter-per-second', 'mile-per-hour', 'liter-per-kilometer', 'mile-per-gallon', 'kilogram-per-liter', 'byte-per-second', 'kilobyte-per-second', 'gram-per-liter', 'foot-per-second', 'percent-per-day', 'day-per-week', 'second-per-meter', 'kilometer-per-liter', 'megabit-per-second', 'meter-per-meter'];
for (const l of ['en', 'de', 'fr', 'ja', 'pl', 'ru']) {
  for (const u of combos) {
    const out = [];
    for (const d of ['short', 'long', 'narrow']) {
      const f = new Intl.NumberFormat(l, {style: 'unit', unit: u, unitDisplay: d});
      out.push(d + ':' + [1, 2, 5].map(n => cps(f.format(n))).join(' | '));
    }
    console.log(l + ' ' + u + ' => ' + out.join(' ;; '));
  }
}

