// currency digits and symbols for all AAA..ZZZ codes
const keys = ['en','ar','de','es','fr','gv','hi','it','ja','ko','ln','nl','pl','pt','ru','si','sl','sr','sv','th','zh','zh-TW','en-IN','pt-PT','ar-MA'];
const digits = {};
const special = {};
for (let a = 65; a <= 90; a++) for (let b = 65; b <= 90; b++) for (let c = 65; c <= 90; c++) {
  const code = String.fromCharCode(a, b, c);
  const f = new Intl.NumberFormat('en', {style: 'currency', currency: code});
  const ro = f.resolvedOptions();
  if (ro.minimumFractionDigits !== 2) digits[code] = ro.minimumFractionDigits;
  for (const k of keys) {
    for (const d of ['symbol', 'narrowSymbol', 'name', 'code']) {
      const parts = new Intl.NumberFormat(k, {style: 'currency', currency: code, currencyDisplay: d}).formatToParts(1);
      const cur = parts.filter(p => p.type === 'currency').map(p => p.value).join('|');
      const expected = code + ' ';
      if (cur !== expected) (special[code] = special[code] || []).push(k + '/' + d + '=' + JSON.stringify(cur));
    }
  }
}
console.log(JSON.stringify(digits));
for (const c in special) console.log(c + ': ' + special[c].join(' '));

