const net = require('net');
const log = (...a) => console.log(a.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
const step = process.argv[2] || 'a';
if (step === 'a') {
  const c = net.connect(80, 'nonexistent.invalid');
  c.on('error', (e) => log('error', e.name, e.message, e.code, e.syscall, e.hostname, JSON.stringify(Object.keys(e))));
} else if (step === 'b') {
  const server = net.createServer((sock) => { sock.destroy(); });
  server.listen(0, () => {
    const c = net.connect(server.address().port, () => {
      setTimeout(() => {
        c.write('after reset', (err) => log('write cb', err && err.message, err && err.code));
      }, 100);
    });
    c.on('error', (e) => log('error', e.message, e.code, JSON.stringify(Object.keys(e))));
    c.on('end', () => log('end'));
    c.on('close', (h) => { log('close', h); server.close(); });
  });
} else if (step === 'c') {
  try { net.connect({ port: 70000 }); } catch (e) { log('throw', e.name, e.message); }
  try { net.connect({ port: -1 }); } catch (e) { log('throw', e.name, e.message); }
  try { net.connect('abc'); } catch (e) { log('throw path', e.name, e.message); }
  const c = net.connect({ path: '/nonexistent/sock' });
  c.on('error', (e) => log('path error', e.message, e.code, JSON.stringify(Object.keys(e))));
} else if (step === 'd') {
  const server = net.createServer((sock) => {
    sock.write('hello from server');
    sock.end();
  });
  server.listen(0, () => {
    const c = net.connect(server.address().port);
    c.setEncoding('utf8');
    let all = '';
    c.on('data', (d) => all += d);
    c.on('end', () => { log('got', all); });
    c.on('close', () => { log('client closed'); server.close(); });
  });
} else if (step === 'e') {
  const server = net.createServer({ allowHalfOpen: true }, (sock) => {
    sock.on('data', d => log('S data', String(d)));
    sock.on('end', () => { log('S end'); setTimeout(() => sock.end('late reply'), 20); });
    sock.on('close', () => { log('S close'); server.close(); });
  });
  server.listen(0, () => {
    const c = net.connect(server.address().port, () => c.end('req'));
    c.on('data', d => log('C data', String(d)));
    c.on('end', () => log('C end'));
    c.on('close', () => log('C close'));
  });
}

