/// Arithmetic year from (era, eraYear); None = unknown era
pub fn year_from_era(cal: Cal, era: &str, era_year: i64) -> Option<i64> {
    match cal {
        Cal::Gregory => match era {
            "ce" | "ad" | "gregory" => Some(era_year),
            "bce" | "bc" | "gregory-inverse" => Some(1 - era_year),
            _ => None,
        },
        Cal::Buddhist => match era {
            "be" => Some(era_year),
            _ => None,
        },
        Cal::Roc => match era {
            "roc" | "minguo" => Some(era_year),
            "broc" | "before-roc" | "minguo-qian" => Some(1 - era_year),
            _ => None,
        },
        Cal::Japanese => {
            if let Some(e) = JAPANESE_ERA_YEAR_ONE.iter().find(|e| e.0 == era) {
                return Some(e.1 + era_year - 1);
            }
            match era {
                "ce" | "ad" | "japanese" => Some(era_year),
                "bce" | "bc" | "japanese-inverse" => Some(1 - era_year),
                _ => None,
            }
        }
        _ => super::cals::year_from_era(cal, era, era_year),
    }
}

