340	    if cal.has_eras() {
341	        match (&f.era, f.era_year) {
342	            (Some(era), Some(ey)) => {
343	                let era = era.clone();
344	                match year_from_era(cal, &era, f2i64(ey)) {
345	                    None => return rerr(format!("{} is not a valid era in calendar {}", era, cal.id())),
346	                    Some(y) => {
347	                        if let Some(yy) = f.year {
348	                            if f2i64(yy) != y {
349	                                return rerr("year and era/eraYear disagree");
350	                            }
351	                        }
352	                        f.year = Some(y as f64);
353	                    }
354	                }
355	            }
356	            (Some(_), None) | (None, Some(_)) => {
357	                if f.year.is_some() {
358	                    return terr("era and eraYear must be provided together");
359	                }
360	                if kind != FieldKind::MonthDay {
361	                    return terr("missing field 'year'");
362	                }
363	            }
364	            _ => {}
365	        }
366	    }
367	    if kind != FieldKind::MonthDay && f.year.is_none() {
368	        return terr("missing field 'year'");
369	    }
370	    if f.month.is_none() && f.month_code.is_none() {
371	        return terr("missing field 'month'");
372	    }
373	    if kind != FieldKind::YearMonth && f.day.is_none() {
374	        return terr("missing field 'day'");
375	    }
376	    if let Some(mc) = &f.month_code {
377	        let code = MonthCode::parse(mc);
378	        if !code_valid_for_calendar(cal, code) {
379	            return rerr("invalid monthCode for this calendar");
380	        }
381	        if cal.is_gregorian_based() {
382	            if let Some(m) = f.month {
383	                if m != code.num as f64 {
384	                    return rerr("month and monthCode disagree");
385	                }
386	            }
387	            f.month = Some(code.num as f64);
388	        }
389	        // non-ISO calendars resolve the code against the year later
390	    } else if kind == FieldKind::MonthDay && cal != Cal::Iso8601 && f.year.is_none() {
391	        return terr("year is required to interpret an ordinal month");
392	    }
393	    Ok(())
394	}
