396	/// RegulateISODate
397	pub fn regulate_iso_date(year: f64, month: f64, day: f64, overflow: Overflow) -> TRes<IsoDate> {
398	    let y = f2i64(year);
399	    match overflow {
400	        Overflow::Constrain => {
401	            let m = month.clamp(1.0, 12.0) as u8;
402	            let dim = days_in_month(y, m) as f64;
403	            Ok(IsoDate::new(y, m, day.clamp(1.0, dim) as u8))
404	        }
405	        Overflow::Reject => {
406	            if !(1.0..=12.0).contains(&month) {
407	                return rerr("month out of range");
408	            }
409	            let m = month as u8;
410	            if day < 1.0 || day > days_in_month(y, m) as f64 {
411	                return rerr("day out of range");
412	            }
413	            Ok(IsoDate::new(y, m, day as u8))
414	        }
415	    }
416	}
