            }
            Stmt::ForIn(f) | Stmt::ForOf(f) => {
                // right side evaluated in a scope with TDZ bindings for let/const names
                let id = self.push_scope(ScopeKind::Block, self.strict());
                f.scope.set(id as u32);
                if let ForHead::Decl(k, p) = &f.head {
                    if *k != VarKind::Var {
