                        let mut names = Vec::new();
                        pattern_names(p, &mut names);
                        for (n, l) in names {
                            self.declare(id, &n, bk, l)?;
                        }
                    }
                }
                if let Some(vi) = &f.var_init {
                    self.walk_expr(vi)?;
                }
