const util = require('util');
function nest(n, mk, leaf) { const r = mk(); let o = r; for (let i = 0; i < n; i++) { const c = i === n - 1 ? leaf() : mk(); if (Array.isArray(o)) o.push(c); else if (o instanceof Map) o.set(1, c); else o.n = c; o = c; } return r; }
function works(f) { try { f(); return true; } catch (e) { if (e instanceof RangeError) return false; throw e; } }
function search(f) { let lo = 1, hi = 5000; while (lo < hi) { const mid = Math.floor((lo + hi + 1) / 2); if (works(() => f(mid))) lo = mid; else hi = mid - 1; } return lo; }
const I = (v) => util.inspect(v, { depth: Infinity });
console.log('obj/{}', search((n) => I(nest(n, () => ({}), () => ({})))));
