  log(String(n), JSON.stringify(c.getCipherInfo(n)), JSON.stringify(c.getCipherInfo(n, {keyLength: 16})), JSON.stringify(c.getCipherInfo(n, {ivLength: 16})), JSON.stringify(c.getCipherInfo(n, {ivLength: '12'})));
}
const k = c.createPrivateKey(fx('rsa1024.pem'));
