}
for (const [alg, opts] of [['sha256', {padding: 5}], ['sha512-224', {}], ['md5', {padding: 6, saltLength: 1000}], ['sha1', {padding: 6, saltLength: -1}], ['sha1', {padding: 6, saltLength: -2}]]) {
