log(x.asymmetricKeyType, x.export({format: 'jwk'}).x, c.createPublicKey(x).export({format: 'der', type: 'spki'}).toString('hex'));
try { c.sign(null, Buffer.from('x'), x); } catch (e) { log(e.message); }
try { c.verify(null, Buffer.from('x'), x, Buffer.alloc(1)); } catch (e) { log(e.message); }
const y = c.createPrivateKey({key: {kty: 'OKP', crv: 'X25519', d: 'XasIfmJKikt54X-Lg4AO5m87sSkmGLb9HC_LJ_-I4Os'}, format: 'jwk'});
log(c.diffieHellman({privateKey: x, publicKey: c.createPublicKey(y)}).toString('hex'));
const edj = c.createPrivateKey({key: {kty: 'OKP', crv: 'Ed25519', d: 'nWGxne_9WmC6hEr0kuwsxERJxWl7MmkZcDusAxyuf2A'}, format: 'jwk'});
log(edj.export({format: 'jwk'}).x, c.sign(null, Buffer.from(''), edj).toString('hex'));
