    }
    let sc = crate::runtime::nodestream::classes(vm);
    // net.Socket extends Duplex
    let (socket, sp) = make_class(vm, "Socket", 0, socket_ctor, Some((&sc.duplex, &sc.duplex_proto)));
    let sm: &[(&str, u32, NativeFn)] = &[
