        ("_clearTimeout", 0, sock_clear_timeout),
        ("_resetTimeout", 0, sock_reset_timeout),
        ("setNoDelay", 0, sock_set_no_delay),
        ("setKeepAlive", 0, sock_set_keep_alive),
