    let (blocklist, blp) = make_class(vm, "BlockList", 0, blocklist_ctor, None);
    let blm: &[(&str, u32, NativeFn)] = &[("addAddress", 1, bl_add_address), ("addRange", 2, bl_add_range), ("addSubnet", 2, bl_add_subnet), ("check", 2, bl_check)];
    for (n, l, f) in blm {
