    let (dgram_socket, dsp) = make_class(vm, "Socket", 2, dgram_socket_ctor, Some((&sc.ee, &sc.ee_proto)));
    let dm: &[(&str, u32, NativeFn)] = &[
        ("bind", 0, dgram_bind),
        ("_ensureBound", 0, dgram_ensure_bound),
        ("_recvLoop", 0, noop),
        ("send", 0, dgram_send),
        ("connect", 3, dgram_connect),
        ("disconnect", 0, dgram_disconnect),
