        ("dropSourceSpecificMembership", 3, noop),
        ("ref", 0, return_this),
        ("unref", 0, return_this),
        ("getRecvBufferSize", 0, |_vm, _a| Ok(Value::Num(212992.0))),
        ("getSendBufferSize", 0, |_vm, _a| Ok(Value::Num(212992.0))),
