    t(`${i} ${cal} with-year ${a}`, () => a.with({ year: a.year + ri(-5, 5) }));
    t(`${i} ${cal} ym ${a}`, () => { const ym = a.toPlainYearMonth(); return ym.toString() + ' ' + ym.add({ months: ri(-20, 20) }) + ' ' + ym.until(b.toPlainYearMonth(), { largestUnit: pick(['year', 'month']) }); });
    t(`${i} ${cal} md ${a}`, () => { const md = a.toPlainMonthDay(); return md.toString() + ' ' + md.toPlainDate({ year: b.year }); });
    t(`${i} ${cal} round ${d}`, () => d.round({ largestUnit: pick(units), smallestUnit: pick(units), relativeTo: a, roundingMode: pick(modes) }));
    t(`${i} ${cal} total ${d}`, () => d.total({ unit: pick(units), relativeTo: a }));
    t(`${i} ${cal} from ${a}`, () => Temporal.PlainDate.from({ year: a.year, monthCode: a.monthCode, day: a.day + ri(-3, 3), calendar: cal }, { overflow: pick(['constrain', 'reject']) }));
    t(`${i} ${cal} fromm ${a}`, () => Temporal.PlainDate.from({ year: a.year, month: ri(1, 14), day: ri(1, 32), calendar: cal }));
  }
}

