const util = require('util');
const assert = require('assert');

class Temperature {
  constructor(c) { this.celsius = c; }
  get fahrenheit() { return this.celsius * 9 / 5 + 32; }
  [util.inspect.custom](depth, options) { return `Temperature<${this.celsius}°C>`; }
}
const temps = [new Temperature(20), new Temperature(-5)];
console.log(util.inspect(temps));
console.log(util.format('Temps: %o', temps));
console.dir({ temps, meta: { count: temps.length, nested: { deep: { deeper: true } } } }, { depth: 1 });
console.table(temps.map(t => ({ c: t.celsius, f: t.fahrenheit })));
console.group('Results');
console.log('inside group');
console.table({ a: { x: 1 }, b: { y: 2 } });
console.groupEnd();
const results = [];
function test(name, fn) {
  try { fn(); results.push({ name, status: 'pass' }); }
  catch (e) { results.push({ name, status: 'fail', error: e.message }); }
}
test('equal', () => assert.strictEqual(1 + 1, 2));
test('deep', () => assert.deepStrictEqual({ a: [1, 2] }, { a: [1, 2] }));
test('fail deep', () => assert.deepStrictEqual({ a: [1, 2] }, { a: [1, 3] }));
test('throws', () => assert.throws(() => JSON.parse('{'), SyntaxError));
test('throws wrong', () => assert.throws(() => JSON.parse('{'), TypeError));
test('match', () => assert.match('hello world', /wor/));
test('not ok', () => assert.ok(''));
console.table(results);
console.log(JSON.stringify(results));
const counts = {};
for (const w of 'the quick brown fox jumps over the lazy dog the end'.split(' ')) counts[w] = (counts[w] || 0) + 1;
console.log(util.inspect(counts));
console.log(util.inspect(new Map(Object.entries(counts))));
console.log(util.isDeepStrictEqual(counts, { ...counts }));
const sleep = util.promisify((ms, cb) => setTimeout(() => cb(null, ms), ms));
sleep(5).then((v) => console.log('slept', v));
console.count('x'); console.count('x'); console.count();
console.assert(1 === 2, 'math is broken: %d', 3);

