const zlib = require('zlib');
const fs = require('fs');
const crypto = require('crypto');
const out = '/tmp/zcagent/out_' + process.argv[2] + '.gz';
const src = '/workspace/assets/test_runtime_compression/random.bin';
const ws = fs.createWriteStream(out);
fs.createReadStream(src).pipe(zlib.createGzip()).pipe(ws);
ws.on('finish', () => {
  const gz = fs.readFileSync(out);
  console.log('gz', gz.length, crypto.createHash('sha256').update(gz).digest('hex'));
  const back = zlib.gunzipSync(gz);
  console.log('back', back.length, back.equals(fs.readFileSync(src)));
  // decompress via stream to another file
  const out2 = out + '.out';
  const ws2 = fs.createWriteStream(out2);
  fs.createReadStream(out).pipe(zlib.createGunzip()).pipe(ws2).on('finish', () => {
    console.log('file2', fs.readFileSync(out2).length);
    fs.unlinkSync(out); fs.unlinkSync(out2);
  });
});
ws.on('close', () => console.log('ws close'));

