1	// Recursive-descent JavaScript parser.
2	
3	use crate::ast::*;
4	use crate::lexer::{LexError, Lexer, Tok, Token};
5	use std::rc::Rc;
6	
7	#[derive(Debug, Clone)]
8	pub struct ParseError {
9	    pub msg: String,
10	    pub line: u32,
11	}
12	
13	impl From<LexError> for ParseError {
14	    fn from(e: LexError) -> Self {
15	        ParseError { msg: e.msg, line: e.line }
16	    }
17	}
18	
19	type PResult<T> = Result<T, ParseError>;
20	
21	#[derive(Clone, Copy, Default)]
22	struct Ctx {
23	    in_function: bool,
24	    in_generator: bool,
25	    in_async: bool,
26	    strict: bool,
27	    in_class_body: bool,
28	    allow_super_call: bool,
29	    allow_super_prop: bool,
30	    allow_new_target: bool,
31	    in_field_init: bool,
32	    in_static_block: bool,
33	    allow_return: bool,
34	    in_params: bool,
35	}
36	
37	#[derive(Clone)]
38	struct Label {
39	    name: Rc<str>,
40	    is_loop: bool,
41	}
42	
43	pub struct Parser {
44	    lex: Lexer,
45	    tok: Token,
46	    prev_end: usize,
47	    prev_line: u32,
48	    ctx: Ctx,
49	    labels: Vec<Label>,
50	    breakable_depth: u32,
51	    loop_depth: u32,
52	    is_module: bool,
53	    source: Rc<str>,
54	    template_counter: usize,
55	    has_tla: bool,
56	    /// private names declared in enclosing class bodies
57	    private_scopes: Vec<Vec<Rc<str>>>,
58	    /// unresolved private name references (checked when class body closes)
59	    private_refs: Vec<Vec<Rc<str>>>,
60	    /// number of cover-initialized names seen ({a = 1} in object literal) that are not yet converted
61	    cover_init_count: usize,
62	    pub repl_mode: bool,
63	}
64	
65	struct SavedState {
66	    pos: usize,
67	    line: u32,
68	    tok: Token,
69	    prev_end: usize,
70	    prev_line: u32,
71	    cover: usize,
72	}
73	
74	fn is_reserved_strict(name: &str) -> bool {
75	    matches!(
76	        name,
77	        "implements" | "interface" | "let" | "package" | "private" | "protected" | "public" | "static" | "yield"
78	    )
79	}
80	
81	static TEMPLATE_ID: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(1);
82	
83	impl Parser {
84	    pub fn new(src: &str, is_module: bool) -> PResult<Parser> {
85	        let mut lex = Lexer::new(src, is_module);
86	        let tok = lex.next_token()?;
87	        Ok(Parser {
88	            lex,
89	            tok,
90	            prev_end: 0,
91	            prev_line: 1,
92	            ctx: Ctx { allow_return: false, strict: is_module, in_async: false, ..Default::default() },
93	            labels: Vec::new(),
94	            breakable_depth: 0,
95	            loop_depth: 0,
96	            is_module,
97	            source: Rc::from(src),
98	            template_counter: 0,
99	            has_tla: false,
100	            private_scopes: Vec::new(),
101	            private_refs: Vec::new(),
102	            cover_init_count: 0,
103	            repl_mode: false,
104	        })
105	    }
106	
107	    // ---------- token helpers ----------
108	
109	    fn err<T>(&self, msg: impl Into<String>) -> PResult<T> {
110	        Err(ParseError { msg: msg.into(), line: self.tok.line })
111	    }
112	
113	    fn err_line<T>(&self, msg: impl Into<String>, line: u32) -> PResult<T> {
114	        Err(ParseError { msg: msg.into(), line })
115	    }
116	
117	    fn unexpected<T>(&self) -> PResult<T> {
118	        let desc = match &self.tok.tok {
119	            Tok::Punct(p) => format!("Punct({:?})", p),
120	            Tok::Keyword(k) => format!("Keyword({:?})", k),
121	            Tok::Eof => "Eof".to_string(),
122	            Tok::Ident(n) => format!("Ident({:?})", n),
123	            Tok::Num(n) => format!("Num({:?})", n),
124	            Tok::Str(s) => format!("Str({:?})", String::from_utf16_lossy(s)),
125	            Tok::BigInt(s) => format!("BigInt({:?})", s),
126	            Tok::Template { .. } => "Template".to_string(),
127	            Tok::Regex { .. } => "Regex".to_string(),
128	            Tok::PrivateName(n) => format!("PrivateName({:?})", n),
129	        };
130	        self.err(format!("unexpected token {}", desc))
131	    }
132	
133	    fn advance(&mut self) -> PResult<Token> {
134	        let next = self.lex.next_token()?;
135	        let old = std::mem::replace(&mut self.tok, next);
136	        self.prev_end = old.end;
137	        self.prev_line = old.line;
138	        Ok(old)
139	    }
140	
141	    fn is_punct(&self, p: &str) -> bool {
142	        matches!(&self.tok.tok, Tok::Punct(q) if *q == p)
143	    }
144	    fn is_kw(&self, k: &str) -> bool {
145	        matches!(&self.tok.tok, Tok::Keyword(q) if *q == k)
146	    }
147	    fn is_ident_named(&self, n: &str) -> bool {
148	        matches!(&self.tok.tok, Tok::Ident(q) if q == n) && !self.tok.escaped
149	    }
150	    fn eat_punct(&mut self, p: &str) -> PResult<bool> {
151	        if self.is_punct(p) {
152	            self.advance()?;
153	            Ok(true)
154	        } else {
155	            Ok(false)
156	        }
157	    }
158	    fn expect_punct(&mut self, p: &str) -> PResult<()> {
159	        if self.is_punct(p) {
160	            self.advance()?;
161	            Ok(())
162	        } else {
163	            self.err(format!("expected '{}'", p))
164	        }
165	    }
166	    fn eat_kw(&mut self, k: &str) -> PResult<bool> {
167	        if self.is_kw(k) {
168	            self.advance()?;
169	            Ok(true)
170	        } else {
171	            Ok(false)
172	        }
173	    }
174	
175	    fn save(&self) -> SavedState {
176	        SavedState {
177	            pos: self.lex.pos,
178	            line: self.lex.line,
179	            tok: self.tok.clone(),
180	            prev_end: self.prev_end,
181	            prev_line: self.prev_line,
182	            cover: self.cover_init_count,
183	        }
184	    }
185	    fn restore(&mut self, s: SavedState) {
186	        self.lex.pos = s.pos;
187	        self.lex.line = s.line;
188	        self.tok = s.tok;
189	        self.prev_end = s.prev_end;
190	        self.prev_line = s.prev_line;
191	        self.cover_init_count = s.cover;
192	    }
193	
194	    fn consume_semicolon(&mut self) -> PResult<()> {
195	        if self.is_punct(";") {
196	            self.advance()?;
197	            return Ok(());
198	        }
199	        if self.is_punct("}") || matches!(self.tok.tok, Tok::Eof) || self.tok.nl_before {
200	            return Ok(());
201	        }
202	        self.err("expected ';'")
203	    }
204	
205	    fn peek_token(&mut self) -> PResult<Token> {
206	        let s = self.save();
207	        self.advance()?;
208	        let t = self.tok.clone();
209	        self.restore(s);
210	        Ok(t)
211	    }
212	
213	    fn ident_name_of_tok(&self) -> Option<String> {
214	        match &self.tok.tok {
215	            Tok::Ident(n) => Some(n.clone()),
216	            Tok::Keyword(k) => Some(k.to_string()),
217	            _ => None,
218	        }
219	    }
220	
221	    /// current token is a binding identifier in the current context?
222	    fn is_binding_ident(&self) -> bool {
223	        match &self.tok.tok {
224	            Tok::Ident(n) => {
225	                if n == "yield" && (self.ctx.in_generator || self.ctx.strict) {
226	                    return false;
227	                }
228	                if n == "await" && (self.ctx.in_async || self.is_module || self.ctx.in_static_block) {
229	                    return false;
230	                }
231	                true
232	            }
233	            _ => false,
234	        }
235	    }
236	
237	    fn check_binding_name(&self, name: &str, line: u32) -> PResult<()> {
238	        if self.ctx.strict {
239	            if name == "eval" || name == "arguments" {
240	                return self.err_line(format!("'{}' cannot be used as a binding in strict mode", name), line);
241	            }
242	            if is_reserved_strict(name) {
243	                return self.err_line(format!("'{}' is a reserved word in strict mode", name), line);
244	            }
245	        }
246	        Ok(())
247	    }
248	
249	    fn binding_ident(&mut self) -> PResult<Ident> {
250	        if !self.is_binding_ident() {
251	            return self.err("expected binding identifier");
252	        }
253	        let line = self.tok.line;
254	        let name = match self.advance()?.tok {
255	            Tok::Ident(n) => n,
256	            _ => unreachable!(),
257	        };
258	        self.check_binding_name(&name, line)?;
259	        Ok(Ident { name: Rc::from(name.as_str()), line })
260	    }
