268	            self.ctx.in_async = false;
269	        }
270	        let (body, strict) = self.parse_directives_and_body(true, strict)?;
271	        Ok(Program {
272	            body,
273	            strict,
274	            is_module: self.is_module,
275	            scope: ScopeId::new(),
