285	    /// Parses statements until EOF (top) or '}' (function body), handling directive prologue.
286	    fn parse_directives_and_body(&mut self, top: bool, mut strict: bool) -> PResult<(Vec<Stmt>, bool)> {
287	        let mut body = Vec::new();
288	        let mut in_prologue = true;
289	        let mut octal_before: Option<u32> = None;
290	        loop {
291	            if top {
292	                if matches!(self.tok.tok, Tok::Eof) {
293	                    break;
294	                }
295	            } else if self.is_punct("}") {
296	                break;
297	            }
298	            if in_prologue {
299	                if let Tok::Str(s) = &self.tok.tok {
300	                    let raw = self.lex.slice(self.tok.start, self.tok.end);
301	                    let is_use_strict = raw == "\"use strict\"" || raw == "'use strict'";
302	                    let s = s.clone();
303	                    let had_octal = self.tok.octal_escape;
304	                    let line = self.tok.line;
305	                    // check it's an expression statement consisting only of the string
306	                    let next = self.peek_token()?;
307	                    let ends = matches!(next.tok, Tok::Punct(";") | Tok::Punct("}") | Tok::Eof) || next.nl_before;
308	                    let continues_expr = matches!(&next.tok, Tok::Punct(p) if *p != ";" && *p != "}")
309	                        && !next.nl_before;
310	                    if ends && !continues_expr {
311	                        if had_octal && octal_before.is_none() {
312	                            octal_before = Some(line);
313	                        }
314	                        if is_use_strict {
315	                            strict = true;
316	                            self.ctx.strict = true;
317	                            if let Some(l) = octal_before {
318	                                return self.err_line("octal escape sequences are not allowed in strict mode", l);
319	                            }
320	                        }
321	                        let _ = s;
322	                        let st = self.parse_statement_list_item()?;
323	                        body.push(st);
324	                        continue;
325	                    }
326	                }
327	                in_prologue = false;
328	            }
329	            let st = self.parse_statement_list_item()?;
330	            body.push(st);

