1	// node:crypto and the global WebCrypto object.
2	//
3	// The reference implements most of node:crypto in JavaScript; this binding reproduces its
4	// observable behaviour on top of the pure-Rust primitives in `crate::crypto`:
5	// * instances keep the reference's own properties (`Hash` has `_reg`, `_chunks`, `_used`, a
6	//   `KeyObject` has `_type`, `_material`, `_asym`, ...) and data passed to `update()` is kept
7	//   by reference until it is consumed, like the reference does;
8	// * plain `function`s are constructible and own a `prototype`, arrows are not;
9	// * async variants compute synchronously and deliver `(err, result)` from one promise-based
10	//   microtask (queueMicrotask semantics);
11	// * error messages, codes and the internal frames in error stacks (`at toBytes`,
12	//   `at resolveHash`, `at codedError`, ...) follow the reference; its interpreter eliminates
13	//   tail calls until a function has run 8 times, which a few helpers emulate.
14	
15	use crate::builtins::typedarray::{ta_bytes, MAX_TA_LENGTH};
16	use crate::crypto::{self as cr, CryptoError, HashAlg};
17	use crate::object::*;
18	use crate::runtime::buffer::{self, with_frames};
19	use crate::value::*;
20	use crate::vm::{JsResult, Vm};
21	use std::cell::{Cell, RefCell};
22	use std::collections::HashMap;
23	
24	const TIER_UP_CALLS: u32 = 8;
25	
26	#[derive(Default, Clone)]
27	struct State {
28	    exports: Option<Obj>,
29	    regs: HashMap<&'static str, Obj>,
30	    hash_ctor: Option<Obj>,
31	    hash_proto: Option<Obj>,
32	    hmac_ctor: Option<Obj>,
33	    keyobject_ctor: Option<Obj>,
34	    keyobject_proto: Option<Obj>,
35	    cipher_proto: Option<Obj>,
36	    decipher_proto: Option<Obj>,
37	    sign_ctor: Option<Obj>,
38	    verify_ctor: Option<Obj>,
39	    dh_ctor: Option<Obj>,
40	    dh_proto: Option<Obj>,
41	    dhgroup_ctor: Option<Obj>,
42	    ecdh_ctor: Option<Obj>,
43	    x509_ctor: Option<Obj>,
44	    x509_proto: Option<Obj>,
45	    certificate_ctor: Option<Obj>,
46	    webcrypto: Option<Obj>,
47	    subtle: Option<Obj>,
48	}
49	
50	thread_local! {
51	    static ST: RefCell<State> = RefCell::new(State::default());
52	    static TOBYTES_CALLS: Cell<u32> = Cell::new(0);
53	    static DIGEST_CALLS: Cell<u32> = Cell::new(0);
54	    static HMAC_DIGEST_CALLS: Cell<u32> = Cell::new(0);
55	    static CUPDATE_CALLS: Cell<u32> = Cell::new(0);
56	    static CFINAL_CALLS: Cell<u32> = Cell::new(0);
57	    static CSETAAD_CALLS: Cell<u32> = Cell::new(0);
58	    static GRV_CALLS: Cell<u32> = Cell::new(0);
59	    static UUID_CALLS: Cell<u32> = Cell::new(0);
60	}
61	
62	fn bump(c: &'static std::thread::LocalKey<Cell<u32>>) -> u32 {
63	    c.with(|c| {
64	        let n = c.get();
65	        c.set(n.saturating_add(1));
66	        n
67	    })
68	}
69	
70	/// Frames of a `return f(...)` tail call: none while the caller is interpreted.
71	fn tail<'a>(calls: u32, name: &'a str) -> Vec<&'a str> {
72	    if calls >= TIER_UP_CALLS {
73	        vec![name]
74	    } else {
75	        vec![]
76	    }
77	}
78	
79	fn st<R>(f: impl FnOnce(&State) -> R) -> R {
80	    ST.with(|s| f(&s.borrow()))
81	}
82	
83	fn key(s: &str) -> PropKey {
84	    PropKey::from_str(s)
85	}
86	
87	fn get(vm: &mut Vm, v: &Value, k: &str) -> JsResult<Value> {
88	    vm.get_prop_of(v, &key(k))
89	}
90	
91	fn set(vm: &mut Vm, v: &Value, k: &str, x: Value) -> JsResult<()> {
92	    vm.set_prop_of(v, key(k), x, true)
93	}
94	
95	fn call_member(vm: &mut Vm, x: &Value, prop: &str, args: &[Value]) -> JsResult<Value> {
96	    let f = vm.get_prop_of(x, &key(prop))?;
97	    if !f.is_callable() {
98	        let m = buffer::not_callable_msg(true, prop, &f);
99	        return vm.throw_type(m);
100	    }
101	    vm.call(&f, x.clone(), args)
102	}
103	
104	fn num(n: f64) -> Value {
105	    Value::Num(n)
106	}
107	
108	// ============================================================================================
109	// errors
110	// ============================================================================================
111	
112	/// `codedError(Ctor, message, code)`: the error gets an own enumerable `code`.
113	fn coded(vm: &mut Vm, kind: &str, msg: &str, code: &str) -> Value {
114	    with_frames(vm, &["codedError"], |vm| {
115	        let e = vm.make_error(kind, msg);
116	        if let Value::Obj(o) = &e {
117	            o.set_prop(key("code"), Value::str(code), WEC);
118	        }
119	        Ok(e)
120	    })

