syms={}
for u,disps in hi.items():
    s=pat2str(disps['short']['other'])
    assert s.startswith('{0} '), (u,s)
    syms[u]=s[4:]
print({u:s for u,s in syms.items() if s!=u})
# verify rule for all fallback locales
for k in ['gv','hi','ln','si','sl','sr','sv','th']:
    bad=0
    for u,disps in d['units'][k].items():
        sym=syms[u]
        for disp,cats in disps.items():
            for c,p in cats.items():
                s=pat2str(p)
                if disp=='short': exp='{0} '+sym
                elif disp=='narrow': exp='{0}'+sym
                else: exp='{0} '+u+('' if c=='one' else 's')
                if s!=exp:
                    bad+=1
                    if bad<5: print('MISMATCH',k,u,disp,c,repr(s),repr(exp))
    print(k,'bad',bad)
EOF

