const zlib = require('zlib');
const crypto = require('crypto');
// deterministic pseudo-random data
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const out = [];
for (let t = 0; t < 40; t++) {
  const n = Math.floor(rnd() * 5000);
  const alpha = 1 + Math.floor(rnd() * 255);
  const b = Buffer.alloc(n);
  for (let i = 0; i < n; i++) b[i] = rnd() < 0.3 && i > 10 ? b[i - 1 - Math.floor(rnd() * 10)] : Math.floor(rnd() * alpha);
  const view = b.subarray(Math.floor(n / 4));
  for (const f of ['gzipSync', 'deflateSync', 'deflateRawSync', 'brotliCompressSync', 'zstdCompressSync']) {
    const c = zlib[f](view);
    out.push(f + ' ' + n + ' ' + c.length + ' ' + crypto.createHash('md5').update(c).digest('hex'));
  }
  out.push('crc ' + zlib.crc32(view) + ' ' + zlib.crc32(b, 7));
}
console.log(out.join('\n'));

