const net = require('net');
const log = (...a) => console.log(a.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
const step = process.argv[2] || 'a';
const server = net.createServer((sock) => {
  if (step === 'a') {
    setTimeout(() => {
      log('S attach data, state', JSON.stringify(sock._readableState.ended), sock._sawEof, sock.readable, sock._writableState.ended);
      sock.on('data', (d) => log('S data', String(d)));
    }, 100);
  } else {
    sock.on('data', (d) => log('S data', String(d)));
  }
  sock.on('end', () => {
    log('S end', sock._writableState.ended, sock._writableState.finished);
    let n = 0;
    const tick = () => { n++; if (n < 8) { log('  tick', n, sock._writableState.ended, sock._writableState.finished); Promise.resolve().then(tick); } };
    Promise.resolve().then(tick);
  });
  sock.on('finish', () => log('S finish'));
  sock.on('close', (h) => { log('S close', h); server.close(); });
});
server.listen(0, () => {
  const c = net.connect({ port: server.address().port }, () => { c.end('bye'); });
  c.on('close', (h) => log('C close', h));
});

