        let f = vm.get_prop_of(&v, &PropKey::from_str("toLocaleString"))?;
        let r = vm.call(&f, v, &[])?;
        let s = vm.to_string(&r)?;
        out.extend_from_slice(s.units());
    }
    Ok(Value::Str(JsStr::from_units(out)))
}

