const dgram = require('dgram');
const log = (...a) => console.log(a.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
const server = dgram.createSocket('udp4');
server.on('message', (msg, rinfo) => {
  log('server got', String(msg), rinfo.address, rinfo.family, typeof rinfo.port, rinfo.size);
  server.send('pong:' + msg, rinfo.port, rinfo.address, (err, n) => log('server sent', err, n));
});
server.on('listening', () => {
  const a = server.address();
  log('server listening', a.address, a.family, typeof a.port);
  const client = dgram.createSocket({ type: 'udp4' });
  client.on('message', (msg) => { log('client got', String(msg)); client.close(() => log('client closed')); server.close(); });
  client.send(Buffer.from('ping'), a.port, '127.0.0.1', (err, bytes) => log('client sent', err, bytes));
});
server.on('close', () => log('server close'));
server.bind(0, '127.0.0.1');
try { dgram.createSocket('udp5'); } catch (e) { log(e.name, e.message, e.code); }
const s = dgram.createSocket('udp4');
try { s.address(); } catch (e) { log(e.message, e.code); }
try { s.setTTL(0); } catch (e) { log(e.name, e.message, e.code); }
try { s.send('x', 0); } catch (e) { log('send port0', e.name, e.message, e.code); }
s.close();
try { s.close(); } catch (e) { log('double close', e.message, e.code); }
log(JSON.stringify(Object.keys(dgram.createSocket('udp6'))));

