const { Readable, Writable, Transform, Duplex, PassThrough, pipeline, finished } = require('stream');
const log = (...a) => console.log(a.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));

class Counter extends Readable {
  constructor(opts) { super(opts); this.n = 0; }
  _read() { this.n++; if (this.n > 3) this.push(null); else this.push(String(this.n)); }
}
const c = new Counter();
c.on('data', d => log('counter data', String(d)));
c.on('end', () => log('counter end'));
log('counter keys', Object.keys(c));

class Upper extends Transform {
  _transform(chunk, enc, cb) { this.push(String(chunk).toUpperCase()); cb(); }
  _flush(cb) { this.push('!'); cb(); }
}
const u = new Upper();
const out = [];
u.on('data', d => out.push(String(d)));
u.on('end', () => log('upper out', out));
u.write('abc');
u.end('def');

class Sink extends Writable {
  constructor() { super({ objectMode: true }); this.items = []; }
  _write(chunk, enc, cb) { this.items.push(chunk); cb(); }
  _final(cb) { log('sink final', this.items); cb(); }
}
const s = new Sink();
s.on('finish', () => log('sink finish'));
s.write({ a: 1 });
s.write([1, 2]);
s.end(null);

const failing = new Writable({ write(chunk, enc, cb) { cb(new Error('write failed: ' + chunk)); } });
failing.on('error', e => log('failing error', e.message));
failing.on('close', () => log('failing close'));
log('failing write ret', failing.write('x'));

const tf = new Transform({ transform(chunk, enc, cb) { cb(new Error('transform failed')); } });
tf.on('error', e => log('tf error', e.message));
tf.write('y');

const r = new Readable({ read() {} });
r.setEncoding('utf8');
r.push(Buffer.from('héllo'));
r.on('readable', () => log('readable event', r.readableLength));
log('read str', r.read());
r.push(null);
r.on('end', () => log('r end'));
r.resume();

const pt = new PassThrough({ objectMode: true });
pt.write({ x: 1 });
pt.write({ x: 2 });
pt.end();
(async () => {
  for await (const o of pt) log('pt obj', o);
  log('pt done');
})();

const d = new Duplex({
  read() {},
  write(chunk, enc, cb) { this.push('echo:' + chunk); cb(); },
  final(cb) { this.push(null); cb(); },
});
d.on('data', x => log('duplex data', String(x)));
d.on('end', () => log('duplex end'));
d.write('1');
d.end('2');
setTimeout(() => log('timeout'), 5);

