        Ok(p) => {
            let _ = vm.call(&cap.resolve, Value::Undefined, &[p]);
        }
        Err(e) => {
            // settle failures after as many jobs as a successful import, so import()
            // promises settle in call order
            let rc = vm.new_promise_capability_intrinsic();
            let _ = vm.call(&rc.reject, Value::Undefined, &[e]);
            if let Value::Obj(rp) = &rc.promise {
                if let Ok(p2) = crate::builtins::promise::promise_then(vm, rp, Value::Undefined, Value::Undefined) {
                    let _ = vm.call(&cap.resolve, Value::Undefined, &[p2]);
                    return cap.promise;
