const sleep = (ms, v) => new Promise(r => setTimeout(() => r(v), ms));
const log = (...a) => console.log(...a);
async function fetchUser(id) {
  await sleep(5);
  if (id < 0) throw new RangeError(`bad id ${id}`);
  return { id, name: `user${id}` };
}
async function main() {
  log('start');
  const u = await fetchUser(1);
  log('got', JSON.stringify(u));
  try { await fetchUser(-1); } catch (e) { log('caught', e.name, e.message); }
  const results = await Promise.allSettled([fetchUser(2), fetchUser(-2), sleep(1, 'quick')]);
  log(results.map(r => r.status + ':' + (r.value ? JSON.stringify(r.value) : r.reason.message)).join(' | '));
  const winner = await Promise.race([sleep(20, 'slow'), sleep(2, 'fast')]);
  log('race', winner);
  const any = await Promise.any([Promise.reject(new Error('a')), sleep(3, 'b')]);
  log('any', any);
  let ticks = 0;
  await new Promise(resolve => {
    const iv = setInterval(() => { ticks++; log('tick', ticks); if (ticks === 3) { clearInterval(iv); resolve(); } }, 2);
  });
  async function* countdown(n) { while (n > 0) { await sleep(1); yield n--; } }
  for await (const n of countdown(3)) log('countdown', n);
  const queue = [];
  const producer = (async () => { for (let i = 0; i < 3; i++) { await sleep(1); queue.push(i); } })();
  await producer;
  log('queue', queue);
  const timeout = (p, ms) => Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))]);
  try { await timeout(sleep(50), 5); } catch (e) { log('timeout error', e.message); }
  log('end');
}
setTimeout(() => log('timer 0'), 0);
setImmediate(() => log('immediate'));
process.nextTick(() => log('nextTick'));
Promise.resolve().then(() => log('microtask'));
main().then(() => log('main resolved')).catch(e => log('main failed', e));
log('sync done');

