// Randomized RelativeTimeFormat differential test.
let seed = Number(process.argv[2] || 3);
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
function pick(a) { return a[Math.floor(rnd() * a.length)]; }
const locs = ['en','ar','de','es','fr','gv','hi','it','ja','ko','ln','nl','pl','pt','ru','si','sl','sr','sv','th','zh','zh-TW','en-IN','pt-PT','ar-MA','pl-PL','xx','en-u-nu-thai','ar-u-nu-latn','pl-u-nu-arab','de-u-nu-hanidec', undefined, ['xx', 'pl']];
const units = ['second','seconds','minute','minutes','hour','hours','day','days','week','weeks','month','months','quarter','quarters','year','years'];
function val() {
  const r = rnd();
  if (r < 0.1) return pick([0, -0, 1, -1, 2, -2, 5, 22, 12, 1.5, -1.5]);
  if (r < 0.15) return pick(['3', '-2.5', '1e3', ' 7 ']);
  const mag = Math.floor(rnd() * 12) - 4;
  let x = rnd() * Math.pow(10, mag);
  if (rnd() < 0.5) x = Math.round(x);
  if (rnd() < 0.5) x = -x;
  return x;
}
for (let i = 0; i < 4000; i++) {
  const l = pick(locs);
  const o = {};
  if (rnd() < 0.5) o.style = pick(['long', 'short', 'narrow']);
  if (rnd() < 0.5) o.numeric = pick(['always', 'auto']);
  if (rnd() < 0.1) o.numberingSystem = pick(['arab', 'latn', 'thai', 'foo', 'deva']);
  const v = val();
  const u = rnd() < 0.03 ? pick(['millisecond', 'Days', 'fortnight']) : pick(units);
  let out;
  try {
    const f = new Intl.RelativeTimeFormat(l, o);
    out = f.format(v, u) + ' || ' + f.formatToParts(v, u).map(p => p.type + ':' + p.value + (p.unit ? '@' + p.unit : '')).join('|') + ' || ' + JSON.stringify(f.resolvedOptions());
  } catch (e) { out = 'ERR ' + e.constructor.name + ': ' + e.message; }
  console.log(i + ' ' + JSON.stringify(l) + ' ' + JSON.stringify(o) + ' ' + JSON.stringify(v) + ' ' + u + ' => ' + out);
}

