function t(label, f) {
  try { const r = f(); console.log(label + ' => ' + (typeof r === 'object' && r !== null ? JSON.stringify(r) : String(r))); }
  catch (e) { console.log(label + ' => ERR ' + (e && e.constructor && e.constructor.name) + ': ' + (e && e.message)); }
}
