function fib(n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }
let t0 = Date.now();
console.log(fib(30), Date.now() - t0);
function main() {
  function add(a, b) { return a + b; }
  let x = 0;
  t0 = Date.now();
  for (let i = 0; i < 2000000; i++) x = add(x, i);
  console.log('calls', x, Date.now() - t0);
  const o = { v: 1, get g() { return this.v; } };
  t0 = Date.now();
  for (let i = 0; i < 1000000; i++) x += o.g;
  console.log('getter', Date.now() - t0);
  t0 = Date.now();
  const arr = [];
  for (let i = 0; i < 200000; i++) arr.push(i);
  const m = arr.map(v => v * 2).filter(v => v % 3).reduce((a, b) => a + b, 0);
  console.log('hof', m, Date.now() - t0);
}
main();

