// Randomized DurationFormat differential test.
let seed = Number(process.argv[2] || 3);
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
function pick(a) { return a[Math.floor(rnd() * a.length)]; }
const locs = ['en', 'de', 'fr', 'es', 'es-MX', 'ja', 'zh', 'zh-TW', 'ko', 'ar', 'ar-MA', 'hi', 'en-IN', 'pt', 'pt-PT', 'ru', 'pl', 'sv', 'it', 'nl', 'gv', 'sl', 'xx', 'en-u-nu-thai', 'de-CH', 'si', 'ln', 'sr'];
const units = ['years', 'months', 'weeks', 'days', 'hours', 'minutes', 'seconds', 'milliseconds', 'microseconds', 'nanoseconds'];
for (let i = 0; i < 4000; i++) {
  const o = {};
  if (rnd() < 0.8) o.style = pick(['long', 'short', 'narrow', 'digital']);
  for (const u of units) {
    if (rnd() < 0.08) o[u] = pick(['long', 'short', 'narrow', 'numeric', '2-digit']);
    if (rnd() < 0.08) o[u + 'Display'] = pick(['auto', 'always']);
  }
  if (rnd() < 0.15) o.fractionalDigits = Math.floor(rnd() * 10);
  if (rnd() < 0.05) o.numberingSystem = pick(['arab', 'thai', 'latn', 'hanidec']);
  const l = pick(locs);
  let d;
  const r = rnd();
  if (r < 0.1) {
