// option value and field value sweeps
function show(v) {
  try {
    if (typeof v === 'object' && v !== null) return String(v);
    if (typeof v === 'bigint') return v + 'n';
    if (typeof v === 'symbol') return v.toString();
    return JSON.stringify(v);
  } catch (e) { return '<' + e.constructor.name + '>'; }
}
function t(label, f) {
  try { const r = f(); console.log(label, 'OK', show(r)); }
  catch (e) { console.log(label, e.constructor.name + ': ' + e.message); }
}
const vals = [null, true, 0, -1, 1.5, NaN, Infinity, -Infinity, 1e10, 10n, Symbol('x'), '', 'bogus', 'AUTO', 'Day', 'days', { toString() { return 'day'; } }, { valueOf() { return 2; } }, [], ['day']];
const pd = Temporal.PlainDate.from('2024-03-15');
const pdt = Temporal.PlainDateTime.from('2024-03-15T10:20:30.123456789');
const z = Temporal.ZonedDateTime.from('2024-03-15T10:20:30.123456789[Europe/Paris]');
const ins = z.toInstant();
const pt = pdt.toPlainTime();
const d = Temporal.Duration.from('P1DT2H3M4.5S');
for (const v of vals) {
  const s = show(v);
  t(`overflow ${s}`, () => pd.add({ days: 1 }, { overflow: v }));
  t(`disamb ${s}`, () => pdt.toZonedDateTime('UTC', { disambiguation: v }));
  t(`offset ${s}`, () => Temporal.ZonedDateTime.from('2024-03-15T10:20[UTC]', { offset: v }));
  t(`calName ${s}`, () => pd.toString({ calendarName: v }));
  t(`tzName ${s}`, () => z.toString({ timeZoneName: v }));
  t(`showOffset ${s}`, () => z.toString({ offset: v }));
  t(`fsd ${s}`, () => pdt.toString({ fractionalSecondDigits: v }));
  t(`rm ${s}`, () => pdt.round({ smallestUnit: 'minute', roundingMode: v }));
  t(`ri ${s}`, () => pdt.round({ smallestUnit: 'minute', roundingIncrement: v }));
  t(`su ${s}`, () => pdt.until(pdt.add({ days: 3 }), { smallestUnit: v }));
  t(`lu ${s}`, () => pdt.until(pdt.add({ days: 3 }), { largestUnit: v }));
  t(`dsu ${s}`, () => d.round({ smallestUnit: v }));
  t(`dlu ${s}`, () => d.round({ largestUnit: v }));
  t(`unit ${s}`, () => d.total({ unit: v }));
  t(`dir ${s}`, () => z.getTimeZoneTransition({ direction: v }));
  t(`rel ${s}`, () => d.total({ unit: 'hour', relativeTo: v }));
  t(`ptsu ${s}`, () => pt.toString({ smallestUnit: v }));
  t(`isu ${s}`, () => ins.toString({ smallestUnit: v }));
  t(`itz ${s}`, () => ins.toString({ timeZone: v }));
  t(`dts ${s}`, () => d.toString({ smallestUnit: v }));
  // fields
  t(`year ${s}`, () => Temporal.PlainDate.from({ year: v, month: 1, day: 1 }));
  t(`month ${s}`, () => Temporal.PlainDate.from({ year: 2024, month: v, day: 1 }));
  t(`day ${s}`, () => Temporal.PlainDate.from({ year: 2024, month: 1, day: v }));
  t(`mc ${s}`, () => Temporal.PlainDate.from({ year: 2024, monthCode: v, day: 1 }));
  t(`hour ${s}`, () => Temporal.PlainTime.from({ hour: v }));
  t(`ns ${s}`, () => Temporal.PlainTime.from({ nanosecond: v }));
  t(`era ${s}`, () => Temporal.PlainDate.from({ era: v, eraYear: 1, month: 1, day: 1, calendar: 'gregory' }));
  t(`eraYear ${s}`, () => Temporal.PlainDate.from({ era: 'ce', eraYear: v, month: 1, day: 1, calendar: 'gregory' }));
  t(`offsetf ${s}`, () => Temporal.ZonedDateTime.from({ year: 2024, month: 1, day: 1, timeZone: 'UTC', offset: v }));
  t(`tzf ${s}`, () => Temporal.ZonedDateTime.from({ year: 2024, month: 1, day: 1, timeZone: v }));
  t(`calf ${s}`, () => Temporal.PlainDate.from({ year: 2024, month: 1, day: 1, calendar: v }));
  t(`durf ${s}`, () => Temporal.Duration.from({ days: v }));
  t(`ctorD ${s}`, () => new Temporal.Duration(v));
  t(`ctorPD ${s}`, () => new Temporal.PlainDate(v, 1, 1));
  t(`ctorPT ${s}`, () => new Temporal.PlainTime(v));
  t(`fromEpochMs ${s}`, () => Temporal.Instant.fromEpochMilliseconds(v));
  t(`fromEpochNs ${s}`, () => Temporal.Instant.fromEpochNanoseconds(v));
}

