function ri(a, b) { return a + Math.floor(rnd() * (b - a + 1)); }
function pick(arr) { return arr[ri(0, arr.length - 1)]; }
function pad(n, w) { return String(n).padStart(w, '0'); }
function t(label, f) {
  try { const r = f(); console.log(label, 'OK', typeof r === 'object' && r !== null ? String(r) : JSON.stringify(r)); }
  catch (e) { console.log(label, e.constructor.name + ': ' + e.message); }
}
function year() {
  const r = rnd();
  if (r < 0.7) return pad(ri(0, 9999), 4);
  if (r < 0.8) return '+' + pad(ri(0, 275760), 6);
  if (r < 0.9) return '-' + pad(ri(0, 271821), 6);
  return pick(['-000000', '+000000', '12345', '999', '+27576', '-271821', '+275760']);
}
function date() {
  const sep = rnd() < 0.8 ? '-' : '';
