// All zones: offsets at sample instants, transitions, equality
const fs = require('fs');
const zones = fs.readFileSync('/tmp/temporalagent/zones.txt', 'utf8').trim().split('\n');
const part = Number(process.argv[2] || 0), parts = Number(process.argv[3] || 1);
const instants = [-5e9, -2e9, -1e9, 0, 5e8, 1e9, 1.3e9, 1.7e9, 2.1e9, 2.5e9].map((s) => BigInt(s) * 1000000000n);
for (let zi = part; zi < zones.length; zi += parts) {
  const name = zones[zi];
  let line = name + ':';
  try {
    for (const ns of instants) {
      const z = new Temporal.ZonedDateTime(ns, name);
      line += ' ' + z.offset;
    }
    const z0 = new Temporal.ZonedDateTime(0n, name);
    let n = z0.getTimeZoneTransition('next');
    line += ' next=' + (n ? n.toString() : 'null');
    let p = z0.getTimeZoneTransition('previous');
    line += ' prev=' + (p ? p.toString() : 'null');
    const z1 = new Temporal.ZonedDateTime(1700000000000000000n, name);
    n = z1.getTimeZoneTransition('next');
    line += ' next2=' + (n ? n.toString() : 'null');
    p = z1.getTimeZoneTransition('previous');
    line += ' prev2=' + (p ? p.toString() : 'null');
    line += ' id=' + z0.timeZoneId + ' hid=' + z1.hoursInDay + ' sod=' + z1.startOfDay().toString();
    line += ' eqUTC=' + z0.equals(new Temporal.ZonedDateTime(0n, 'UTC'));
  } catch (e) { line += ' ERR ' + e.message; }
  console.log(line);
}

