// Scenario-style tests
const { PlainDate, PlainDateTime, PlainTime, ZonedDateTime, Duration, Instant, Now } = Temporal;

// 1. Business days
function addBusinessDays(date, n) {
  let d = date;
  while (n > 0) {
    d = d.add({ days: 1 });
    if (d.dayOfWeek <= 5) n--;
  }
  return d;
}
console.log('business', addBusinessDays(PlainDate.from('2024-12-20'), 10).toString());

// 2. Meeting across time zones
const meeting = ZonedDateTime.from({ year: 2024, month: 11, day: 3, hour: 9, timeZone: 'America/New_York' });
for (const tz of ['Europe/London', 'Asia/Tokyo', 'Australia/Sydney', 'America/Los_Angeles', 'Asia/Kolkata']) {
  const local = meeting.withTimeZone(tz);
  console.log('meeting', tz, local.toString(), local.toPlainTime().toString({ smallestUnit: 'minute' }), local.offset);
}

// 3. Age
function age(birth, today) {
  const d = PlainDate.from(birth).until(today, { largestUnit: 'years' });
  return `${d.years}y ${d.months}m ${d.days}d`;
}
console.log('age', age('1990-02-28', '2024-02-29'), age('2000-02-29', '2023-02-28'), age('2000-02-29', '2024-02-29'));

// 4. Countdown
const now = Instant.from('2024-12-25T08:30:15.5Z');
const target = ZonedDateTime.from('2025-01-01T00:00[America/Chicago]');
const remaining = now.until(target.toInstant(), { largestUnit: 'day', smallestUnit: 'second', roundingMode: 'floor' });
console.log('countdown', remaining.toString(), remaining.days, remaining.hours, remaining.minutes, remaining.seconds);
console.log('countdown2', remaining.round({ largestUnit: 'hour' }).toString(), remaining.total('minutes'));

// 5. Parsing user input
for (const input of ['2024-02-30', '2024-13-01', 'tomorrow', '2024-02-29', '02/29/2024', '2024-W09-4', '2024-060', '20240229']) {
  try { console.log('parse', input, PlainDate.from(input).toString()); }
  catch (e) { console.log('parse', input, e.name, e.message); }
}

// 6. Durations formatting
const durations = ['PT90M', 'PT3600S', 'P1DT36H', 'PT0.5S', 'P2W', 'P1Y6M', '-PT45M'].map((s) => Duration.from(s));
for (const d of durations) {
  console.log('dur', d.toString(), d.sign, d.blank, d.total({ unit: 'hours', relativeTo: '2024-01-01' }), d.round({ largestUnit: 'days', relativeTo: '2024-01-01' }).toString(), d.toLocaleString());
}
console.log('sorted', durations.slice().sort((a, b) => Duration.compare(a, b, { relativeTo: '2024-01-01' })).join(','));

// 7. Month iteration
let ym = Temporal.PlainYearMonth.from('2024-01');
const months = [];
for (let i = 0; i < 12; i++) { months.push(`${ym.toString()}:${ym.daysInMonth}`); ym = ym.add({ months: 1 }); }
console.log('months', months.join(' '));

// 8. DST handling
const before = ZonedDateTime.from('2024-03-10T01:30[America/New_York]');
console.log('dst', before.add({ hours: 1 }).toString(), before.add({ days: 1 }).toString(), before.hoursInDay, before.with({ hour: 2, minute: 30 }).toString());
const fall = ZonedDateTime.from('2024-11-03T01:30[America/New_York]');
console.log('dst2', fall.toString(), fall.add({ hours: 1 }).toString(), fall.hoursInDay, fall.with({ hour: 1 }, { disambiguation: 'later' }).toString());

// 9. Calendar conversions
const d = PlainDate.from('2024-10-02');
for (const cal of ['hebrew', 'islamic-umalqura', 'chinese', 'japanese', 'persian', 'buddhist', 'ethiopic']) {
  const c = d.withCalendar(cal);
  console.log('cal', cal, c.toString(), c.year, c.month, c.monthCode, c.day, c.era, c.eraYear, c.daysInMonth, c.monthsInYear);
}

// 10. Instant math
const i1 = Instant.fromEpochMilliseconds(0);
const i2 = Instant.fromEpochNanoseconds(1700000000123456789n);
console.log('inst', i1.until(i2).toString(), i2.since(i1, { largestUnit: 'hours' }).toString(), i2.round({ smallestUnit: 'second' }).toString(), Instant.compare(i1, i2));
console.log('inst2', i2.toString({ timeZone: 'Asia/Shanghai' }), i2.toZonedDateTimeISO('Europe/Berlin').toString({ smallestUnit: 'millisecond' }));

// 11. PlainTime ranges
const open = PlainTime.from('09:00'), close = PlainTime.from('17:30');
const t = PlainTime.from('12:45');
console.log('time', PlainTime.compare(open, t) <= 0 && PlainTime.compare(t, close) < 0, close.since(open).toString(), open.until(close, { largestUnit: 'minutes' }).toString());

// 12. JSON roundtrip
const obj = { date: PlainDate.from('2024-01-15'), time: PlainTime.from('08:00'), zdt: ZonedDateTime.from('2024-01-15T08:00[Europe/Paris]'), dur: Duration.from('PT2H') };
const json = JSON.stringify(obj);
console.log('json', json);
const back = JSON.parse(json, (k, v) => k === 'date' ? PlainDate.from(v) : k === 'zdt' ? ZonedDateTime.from(v) : k === 'dur' ? Duration.from(v) : v);
console.log('json2', back.date.equals(obj.date), back.zdt.equals(obj.zdt), Duration.compare(back.dur, obj.dur));

