import json
d=json.load(open('/tmp/intlagent/x3.json'))
def pat2str(pat): return ''.join('{0}' if p['type']=='NUM' else p['value'] for p in pat)
hi=d['units']['hi']
for k in ['gv','sl','th']:
    diff=0
    for u in hi:
        for disp in hi[u]:
            for c in ['one','other']:
                if c not in d['units'][k][u][disp]: continue
                if pat2str(d['units'][k][u][disp][c]) != pat2str(hi[u][disp][c]): diff+=1
    print(k, 'diffs vs hi:', diff)
