// Duration locale data extraction
const locs = ['en', 'de', 'fr', 'es', 'it', 'pt', 'nl', 'ja', 'ko', 'zh', 'zh-TW', 'ru', 'pl', 'ar', 'hi'];
const units = ['years', 'months', 'weeks', 'days', 'hours', 'minutes', 'seconds', 'milliseconds', 'microseconds', 'nanoseconds'];
const ns = [1, 2, 3, 4, 5, 11, 12, 21, 22, 25, 100, 101, 102, 111, 1000, 1001, 1002, 1000000];
const out = {};
for (const loc of locs) {
  out[loc] = {};
  for (const style of ['short', 'long', 'narrow']) {
    const st = {};
    for (const u of units) {
      st[u] = ns.map((n) => Temporal.Duration.from({ [u]: n }).toLocaleString(loc, { style }));
      st[u + '_neg'] = Temporal.Duration.from({ [u]: -2 }).toLocaleString(loc, { style });
    }
    // lists of 2, 3, 4 items
    st.list2 = Temporal.Duration.from({ hours: 5, minutes: 6 }).toLocaleString(loc, { style });
    st.list3 = Temporal.Duration.from({ hours: 5, minutes: 6, seconds: 7 }).toLocaleString(loc, { style });
    st.list4 = Temporal.Duration.from({ days: 4, hours: 5, minutes: 6, seconds: 7 }).toLocaleString(loc, { style });
    st.listneg = Temporal.Duration.from({ hours: -5, minutes: -6 }).toLocaleString(loc, { style });
    out[loc][style] = st;
  }
  const dg = {};
  for (const s of ['PT5H6M7S', 'P4DT5H6M7S', 'P1Y2M3W4DT5H6M7.008009010S', '-PT5H6M7S', 'PT0S', 'PT12345H', 'P2Y', 'PT1.5S']) {
    dg[s] = Temporal.Duration.from(s).toLocaleString(loc, { style: 'digital' });
  }
  out[loc].digital = dg;
}
console.log(JSON.stringify(out));

