const which = process.argv[2];
if (which === 'cp') {
  const c = require('child_process').spawn('echo', ['hi']);
  c.stdout.on('data', () => { throw new Error('thrown in data listener'); });
  c.on('close', () => console.log('close'));
} else if (which === 'cpexit') {
  const c = require('child_process').spawn('true');
  c.on('exit', () => { throw new Error('thrown in exit listener'); });
  c.on('close', () => console.log('close still emitted'));
} else if (which === 'exec') {
  require('child_process').exec('echo hi', () => { throw new Error('thrown in exec cb'); });
  setTimeout(() => console.log('after'), 100);
} else if (which === 'stdin') {
  process.stdin.on('data', () => { throw new Error('thrown in stdin data'); });
  process.stdin.on('end', () => console.log('stdin end'));
} else if (which === 'rl') {
  const rl = require('readline').createInterface({ input: process.stdin });
  rl.on('line', (l) => { throw new Error('thrown in line ' + l); });
  rl.on('close', () => console.log('rl close'));
} else if (which === 'http') {
  const http = require('http');
  const s = http.createServer((req, res) => res.end('ok'));
  s.listen(0, () => {
    http.get({ port: s.address().port }, (res) => { s.close(); throw new Error('thrown in response cb'); });
  });
} else if (which === 'net') {
  const net = require('net');
  const s = net.createServer((sock) => { sock.end('hello'); s.close(); });
  s.listen(0, () => {
    const c = net.connect(s.address().port);
    c.on('data', () => { throw new Error('thrown in socket data'); });
  });
} else if (which === 'dns') {
  require('dns').lookup('localhost', () => { throw new Error('thrown in lookup cb'); });
}

