/// parts before the first and after the last differing part.
fn range_parts(
    p1: &[dt::DateTimePart],
    p2: &[dt::DateTimePart],
    textual: bool,
) -> Vec<(dt::DateTimePart, &'static str)> {
    let mut out: Vec<(dt::DateTimePart, &'static str)> = Vec::new();
    if p1 == p2 {
        for p in p1 {
            out.push((p.clone(), SRC_SHARED));
        }
