// Month-end / DST heavy ZonedDateTime differences and duration rounding
let seed = Number(typeof process !== 'undefined' && process.argv[2] || 1);
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
function ri(a, b) { return a + Math.floor(rnd() * (b - a + 1)); }
function pick(arr) { return arr[ri(0, arr.length - 1)]; }
function t(label, f) {
  try { const r = f(); console.log(label, 'OK', typeof r === 'object' && r !== null ? String(r) : JSON.stringify(r)); }
  catch (e) { console.log(label, e.constructor.name + ': ' + e.message); }
}
const zones = ['America/New_York', 'Europe/Berlin', 'Australia/Lord_Howe', 'America/Santiago', 'UTC', 'Asia/Tehran'];
const units = ['year', 'month', 'week', 'day', 'hour', 'minute'];
const modes = ['ceil', 'floor', 'expand', 'trunc', 'halfCeil', 'halfFloor', 'halfExpand', 'halfTrunc', 'halfEven'];
function rz() {
  return Temporal.ZonedDateTime.from({ year: ri(2000, 2030), month: ri(1, 12), day: ri(26, 31), hour: ri(0, 23), minute: pick([0, 15, 30, 59]), timeZone: pick(zones) });
}
for (let i = 0; i < 300; i++) {
  const a = rz();
  const b = rnd() < 0.5 ? rz().withTimeZone(a.timeZoneId) : a.add({ months: ri(-30, 30), hours: ri(0, 30) * (rnd() < 0.5 ? 1 : 0) });
  const opts = { largestUnit: pick(units), smallestUnit: pick(units), roundingMode: pick(modes), roundingIncrement: pick([1, 1, 2, 3]) };
  t(`${i} until ${a} ${b} ${JSON.stringify(opts)}`, () => a.until(b, opts));
  t(`${i} since ${a} ${b} ${JSON.stringify(opts)}`, () => a.since(b, opts));
  const d = a.until(b, { largestUnit: pick(['year', 'month', 'day']) });
  t(`${i} round ${d}`, () => d.round({ largestUnit: pick(units), smallestUnit: pick(units), relativeTo: a, roundingMode: pick(modes) }));
  t(`${i} total ${d}`, () => d.total({ unit: pick(units), relativeTo: a }));
  t(`${i} total2 ${d}`, () => d.total({ unit: pick(units), relativeTo: a.toPlainDateTime() }));
  t(`${i} add ${d}`, () => a.add(d).equals(b));
}

