const { Readable, Writable, PassThrough } = require('stream');
const log = (...a) => console.log(a.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
const src = new Readable({ read() {}, highWaterMark: 4 });
const seen = [];
const slow = new Writable({
  highWaterMark: 4,
  write(chunk, enc, cb) { seen.push(String(chunk)); log('write', String(chunk), this.writableLength); setTimeout(cb, 2); },
});
slow.on('drain', () => log('drain'));
slow.on('finish', () => log('finish', seen.join('|')));
src.on('pause', () => log('pause'));
src.pipe(slow);
for (const c of ['aa', 'bb', 'cc', 'dd', 'ee']) log('push', c, src.push(c));
src.push(null);
const pt = new PassThrough({ highWaterMark: 2 });
log('pt write', pt.write('xyz'), pt.writableLength, pt.readableLength);
setTimeout(() => log('pt later', pt.writableLength, pt.readableLength, pt.isPaused()), 10);

