                let (idx, target) = match self.find_break_target(label.as_ref(), true) {
                    Some(x) => x,
                    None => return cerr("illegal 'continue' statement", 0),
                };
                self.unwind_to(idx + 1)?;
                self.emit_jump(Op::Jump(0), target);
