/// FormatNumericRange of the original (ASCII digits throughout):
/// identical results -> "~" + result; Portuguese joins with " - ",
/// shortens a currency start to its digits and strips the end up to its
/// first digit when the start has a sign; elsewhere ranges join with "–",
/// except currencies: " – ", or "–" with the end stripped up to its first
/// digit when the start has a sign.
fn range_parts(vm: &mut Vm, a: &Args) -> JsResult<Vec<(Part, &'static str)>> {
    let o = branded_this(vm, &a.this, "__nf")?;
    let (s, e) = (a.arg(0), a.arg(1));
    if s.is_undefined() || e.is_undefined() {
        return vm.throw_type("formatRange requires two arguments");
    }
    let x = to_math_value(vm, &s)?;
    let y = to_math_value(vm, &e)?;
    if x.is_nan() || y.is_nan() {
        return vm.throw_range("formatRange arguments must not be NaN");
    }
    let cfg = NfConfig::from_slots(&o);
    let (l1, loc) = layout(&cfg, &x);
    let (l2, _) = layout(&cfg, &y);
    let text = |l: &Layout| -> String {
        match l {
            Layout::Whole(s, _) => s.clone(),
            Layout::Unit(p, n, x) => format!("{}{}{}", p, n, x),
        }
    };
    let (s1, s2) = (text(&l1), text(&l2));
    let mut out = Vec::new();
    if s1 == s2 {
        out.push((Part::new("approximatelySign", "~"), "shared"));
        for p in format_parts_ascii(&cfg, &x) {
            out.push((p, "shared"));
        }
        return Ok(out);
    }
    let currency = cfg.style == Style::Currency;
    let signed = s1.starts_with('-') || s1.starts_with('+');
    let pt = cfg.lang == "pt";
    let sep = if pt {
        " - "
    } else if currency && !signed {
        " \\u{2013} "
    } else {
        "\\u{2013}"
    };
    let trim_start = pt && currency;
    let strip_end = signed && (pt || currency);
    // re-tokenize a (possibly shortened) side
    let side = |l: &Layout, start: bool| -> Vec<Part> {
        match l {
            Layout::Whole(s, ts) => {
                let mut t: &str = s;
                if start && trim_start {
                    t = to_last_digit(t);
                }
                if !start && strip_end {
                    t = from_first_digit(t);
                }
                tokenize(t, *ts, &loc)
            }
            Layout::Unit(p, n, x) => {
                let mut l2 = Layout::Unit(p.clone(), n.clone(), x.clone());
                if !start && strip_end {
                    l2 = Layout::Unit(String::new(), from_first_digit(n).to_string(), x.clone());
                }
                unit_layout_parts(&l2, &loc)
            }
        }
    };
    for p in side(&l1, true) {
        out.push((p, "startRange"));
    }
    out.push((Part::new("literal", sep), "shared"));
    for p in side(&l2, false) {
        out.push((p, "endRange"));
    }
    Ok(out)
}

