    fn member_prop(&mut self, p: &MemberProp) {
        match p {
            MemberProp::Computed(e) => self.expr(e),
            MemberProp::Private(_) => self.hit(),
            MemberProp::Name(_) => {}
        }
    }

    fn expr(&mut self, e: &Expr) {
        if self.found {
            return;
        }
        match e {
            Expr::Template { exprs, .. } => {
                for x in exprs {
                    self.expr(x);
                }
            }
            Expr::TaggedTemplate { tag, exprs, .. } => {
                self.hit();
                self.expr(tag);
                for x in exprs {
                    self.expr(x);
                }
            }
            Expr::SuperMember(p) => {
                if self.main() || self.arrow_chain {
                    self.found = true;
                }
                self.member_prop(p);
            }
            Expr::SuperCall(args) => {
                if self.main() || self.arrow_chain {
                    self.found = true;
                }
                self.args(args);
            }
            Expr::NewTarget => {
                if self.main() || self.arrow_chain {
                    self.found = true;
                }
            }
            Expr::Array(elems) => {
                for el in elems {
                    match el {
                        None => self.hit(),
                        Some(ArrayElem::Expr(x)) => self.expr(x),
                        Some(ArrayElem::Spread(x)) => {
                            self.hit();
                            self.expr(x);
                        }
                    }
                }
            }
            Expr::Object(props) => {
                for p in props {
                    match p {
                        PropDef::KeyValue(k, v) => {
                            match k {
                                PropKey::Num(_) => self.hit(),
                                PropKey::Computed(ke) => {
                                    if !matches!(ke.unparen(), Expr::Str(_)) {
                                        self.hit();
                                    }
                                    self.expr(ke);
                                }
                                _ => {}
                            }
                            self.expr(v);
                        }
                        PropDef::Shorthand(_) => {}
                        PropDef::Method { key, func, .. } => {
                            self.hit();
                            if let PropKey::Computed(k) = key {
                                self.expr(k);
                            }
                            self.func(func);
                        }
                        PropDef::Spread(x) | PropDef::Proto(x) => {
                            self.hit();
                            self.expr(x);
                        }
                    }
                }
            }
            Expr::Function(f) | Expr::Arrow(f) => self.func(f),
            Expr::Class(c) => {
                self.hit();
                self.class(c);
            }
            Expr::Unary(op, x) => {
                if *op == UnaryOp::Delete && matches!(x.unparen(), Expr::Ident(_)) {
                    self.hit();
                }
                self.expr(x);
            }
            Expr::Update { target, .. } => self.expr(target),
            Expr::Binary(_, a, b) | Expr::Logical(_, a, b) => {
                self.expr(a);
                self.expr(b);
            }
            Expr::Assign { op, target, value } => {
                if matches!(op, AssignOp::Logical(_)) {
                    self.hit();
                }
                self.assign_target(target);
                self.expr(value);
            }
            Expr::Cond(a, b, c) => {
                self.expr(a);
                self.expr(b);
                self.expr(c);
            }
            Expr::Call { callee, args, .. } => {
                if let Expr::Ident(id) = &**callee {
                    if &*id.name == "eval" {
                        // direct eval, also from nested functions
                        self.found = true;
                    }
                }
                self.expr(callee);
                self.args(args);
            }
            Expr::New { callee, args } => {
                self.expr(callee);
                if self.args(args) {
                    self.hit();
                }
            }
            Expr::Member { obj, prop, .. } => {
                self.expr(obj);
                self.member_prop(prop);
            }
            Expr::OptChain(x) | Expr::Paren(x) | Expr::Await(x) => self.expr(x),
            Expr::Seq(v) => {
                for x in v {
                    self.expr(x);
                }
            }
            Expr::Yield { arg: Some(x), .. } => self.expr(x),
            Expr::PrivateIn(_, x) => {
                self.hit();
                self.expr(x);
            }
            Expr::ImportCall(a, b) => {
                self.hit();
                self.expr(a);
                if let Some(b) = b {
                    self.expr(b);
                }
            }
            _ => {}
        }
    }
}

