import random, sys
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 300
names = ["a", "b", "x", "y", "foo", "bar", "Item", "T", "K", "value", "data", "type", "as", "id"]
prims = ["number", "string", "boolean", "any", "unknown", "void", "null", "undefined", "never", "T", "Foo", "Bar.Baz", "'lit'", '"x"', "1", "true", "`t${string}`"]
def typ(d=0):
    r = random.random()
    if d > 3 or r < 0.35:
        return random.choice(prims)
    if r < 0.45:
        return typ(d+1) + " | " + typ(d+1)
    if r < 0.52:
        return typ(d+1) + " & " + typ(d+1)
    if r < 0.6:
        return random.choice(["Array", "Promise", "Map", "Record", "Partial"]) + "<" + ", ".join(typ(d+1) for _ in range(random.randint(1, 2))) + ">"
    if r < 0.67:
        return typ(d+1) + "[]"
    if r < 0.74:
        return "[" + ", ".join(typ(d+1) for _ in range(random.randint(1, 3))) + "]"
    if r < 0.82:
        return "{ " + random.choice([";", ","]).join(" %s%s: %s" % (random.choice(names), random.choice(["", "?"]), typ(d+1)) for _ in range(random.randint(1, 3))) + " }"
    if r < 0.9:
        return "(" + ", ".join("%s: %s" % (random.choice(names), typ(d+1)) for _ in range(random.randint(0, 2))) + ") => " + typ(d+1)
    if r < 0.95:
        return "keyof " + typ(d+1)
    return typ(d+1) + " extends " + typ(d+1) + " ? " + typ(d+1) + " : " + typ(d+1)
def expr(d=0):
    r = random.random()
    if d > 3 or r < 0.3:
        return random.choice(["1", "x", "'s'", '"d"', "`t${x}`", "null", "true", "[]", "{}", "y.z", "f()"])
    if r < 0.4:
        return expr(d+1) + " " + random.choice(["+", "-", "*", "<", ">", "===", "&&", "||", "??"]) + " " + expr(d+1)
    if r < 0.5:
        return expr(d+1) + " ? " + expr(d+1) + " : " + expr(d+1)
    if r < 0.6:
        return random.choice(names) + "(" + ", ".join(expr(d+1) for _ in range(random.randint(0, 2))) + ")"
    if r < 0.7:
        return "(" + expr(d+1) + " as " + typ(d+1) + ")"
    if r < 0.78:
        return "{ " + ", ".join("%s: %s" % (random.choice(names), expr(d+1)) for _ in range(random.randint(1, 2))) + " }"
    if r < 0.86:
        return "(" + ", ".join("%s%s" % (random.choice(names), random.choice(["", ": " + typ(d+1)])) for _ in range(random.randint(0, 2))) + ")" + random.choice(["", ": " + typ(d+1)]) + " => " + expr(d+1)
    if r < 0.92:
        return "[" + ", ".join(expr(d+1) for _ in range(random.randint(0, 3))) + "]"
    return expr(d+1) + " satisfies " + typ(d+1)
def params():
    return ", ".join("%s%s%s%s" % (random.choice(["", "", "", "..."]), random.choice(names), random.choice(["", "?"]) + random.choice(["", ": " + typ()]), random.choice(["", "", " = " + expr()])) for _ in range(random.randint(0, 3)))
def stmt(d=0):
    r = random.random()
    kw = random.choice(["let", "const", "var"])
    if r < 0.2:
        return "%s %s%s = %s;" % (kw, random.choice(names), random.choice(["", ": " + typ()]), expr())
    if r < 0.32:
        return "function %s%s(%s)%s { %s }" % (random.choice(names), random.choice(["", "<T>"]), params(), random.choice(["", ": " + typ()]), stmt(d+1) if d < 2 else "return 1;")
    if r < 0.42:
        return "const %s = (%s)%s => %s;" % (random.choice(names), params(), random.choice(["", ": " + typ()]), expr())
    if r < 0.5:
        return "interface %s { %s }" % (random.choice(names), "; ".join("%s%s: %s" % (random.choice(names), random.choice(["", "?"]), typ()) for _ in range(random.randint(0, 3))))
    if r < 0.58:
        return "%stype %s = %s;" % (random.choice(["", "export "]), random.choice(names), typ())
    if r < 0.66:
        return "x = %s;" % expr()
    if r < 0.74:
        return "if (%s) { %s } else { %s }" % (expr(), stmt(d+1) if d < 2 else "1;", stmt(d+1) if d < 2 else "2;")
    if r < 0.82:
        return "class %s { %s(%s)%s { %s } }" % (random.choice(names), random.choice(names), params(), random.choice(["", ": " + typ()]), stmt(d+1) if d < 2 else "")
    if r < 0.88:
        return "for (const %s of %s) { %s }" % (random.choice(names), expr(), stmt(d+1) if d < 2 else "")
    if r < 0.94:
        return "switch (%s) { case %s: %s break; default: %s }" % (expr(), expr(), stmt(d+1) if d < 2 else "", stmt(d+1) if d < 2 else "")
    return "// comment: %s\n%s" % (typ(), stmt(d+1) if d < 2 else "")
cases = []
for i in range(N):
    sep = random.choice(["\n", " ", "\n\n"])
    cases.append(sep.join(stmt() for _ in range(random.randint(1, 4))))
print("\n---\n".join(cases))

