                }
                Some(0x5d) => {
                    self.i += 1;
                    break;
                }
                _ => return Err("Expected ',' or ']' in JSON array"),
            }
        }
        Ok(Value::Obj(vm.new_array(items)))
    }
    fn object(&mut self, vm: &mut Vm) -> PR<Value> {
        self.i += 1;
        let o = vm.new_object();
        self.ws();
        if self.peek() == Some(0x7d) {
            self.i += 1;
            return Ok(Value::Obj(o));
        }
        loop {
