import random, sys
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 200
tags = ["div", "span", "p", "a", "Foo", "Foo.Bar", "my-el", "x:y", "_u", "$d", "h1", "Bar"]
attrs = ["a", "b", "className", "data-x", "aria-label", "on:click", "_p", "key", "ref", "x1"]
texts = ["hi", " ", "  hello world  ", "\n  line\n  ", "a > b", "it's", '"q"', "&amp;", "x\ty", "\\back", "}", "multi\n\n  para", "", "😀", "é"]
exprs = ["x", "1 + 2", "'s'", '"d"', "`t${x}`", "[1, 2].map(i => i)", "fn(a, b)", "a ? b : c", "/* c */", "", " ", "obj.p", "{a: 1}", "x => x", "...rest", "() => {}", "// c\n"]
def attr():
    r = random.random()
    n = random.choice(attrs)
    if r < 0.25: return n
    if r < 0.5: return '%s="%s"' % (n, random.choice(["v", "a b", "x'y", "1", "", "line\nbreak", "&lt;"]))
    if r < 0.6: return "%s='%s'" % (n, random.choice(["v", 'q"q', ""]))
    if r < 0.8: return "%s={%s}" % (n, random.choice(exprs))
    if r < 0.9: return "{...%s}" % random.choice(["props", "x", " o "])
    return "%s=%s" % (n, elem(3))
def elem(d=0):
    if random.random() < 0.1:
        tag = ""
    else:
        tag = random.choice(tags)
    at = " ".join(attr() for _ in range(random.randint(0, 3))) if tag else ""
    sp = random.choice([" ", "", "\n  "])
    if tag and random.random() < 0.3:
        return "<%s%s%s/>" % (tag, (" " + at) if at else "", sp)
    kids = []
    for _ in range(random.randint(0, 3 if d < 3 else 0)):
        r = random.random()
        if r < 0.4: kids.append(random.choice(texts))
        elif r < 0.7: kids.append("{%s}" % random.choice(exprs))
        else: kids.append(elem(d + 1))
    return "<%s%s>%s</%s>" % (tag, (" " + at) if at else "", "".join(kids), tag)
cases = [elem() for _ in range(N)]
print("\n---\n".join(cases))

