        let pk = vm.to_property_key(&key)?;
        match groups.iter_mut().find(|(g, _)| *g == pk) {
            Some((_, list)) => list.push(v),
            None => groups.push((pk, vec![v])),
        }
        k += 1;
    }
    for (g, list) in groups {
        let arr = vm.new_array(list);
        out.set_prop(g, Value::Obj(arr), WEC);
    }
    Ok(Value::Obj(out))
}

