fn sentence_bounds(units: &[u16]) -> Vec<usize> {
    let mut bounds = vec![0];
    let n = units.len();
    let mut i = 0;
    while i < n {
        let u = units[i];
        i += 1;
        if u == b'.' as u16 || u == b'!' as u16 || u == b'?' as u16 {
            while i < n && (units[i] == 0x20 || units[i] == 0x0A) {
                i += 1;
            }
            bounds.push(i);
        }
    }
    if *bounds.last().unwrap() != n {
        bounds.push(n);
    }
    bounds
}

