// Inventory system
class Item {
  #id;
  static count = 0;
  constructor(name, price, qty = 1) {
    this.#id = ++Item.count;
    this.name = name;
    this.price = price;
    this.qty = qty;
  }
  get id() { return this.#id; }
  get total() { return +(this.price * this.qty).toFixed(2); }
  toString() { return `Item#${this.#id}(${this.name} x${this.qty} @ ${this.price})`; }
  toJSON() { return { id: this.#id, name: this.name, total: this.total }; }
  static compare(a, b) { return a.total - b.total || a.name.localeCompare(b.name); }
}
class Perishable extends Item {
  constructor(name, price, qty, days) { super(name, price, qty); this.days = days; }
  get total() { return this.days < 3 ? +(super.total * 0.5).toFixed(2) : super.total; }
  toString() { return super.toString() + `[${this.days}d]`; }
}
const inv = [
  new Item('hammer', 12.5, 2),
  new Perishable('milk', 1.99, 3, 2),
  new Item('nails', 0.05, 200),
  new Perishable('cheese', 7.25, 1, 10),
  new Item('saw', 25),
];
inv.sort(Item.compare);
for (const it of inv) console.log(String(it), it.total);
console.log(JSON.stringify(inv));
const byType = Object.groupBy(inv, it => it.constructor.name);
console.log(Object.keys(byType), byType.Perishable.map(p => p.name).join('|'));
const totals = new Map(inv.map(it => [it.name, it.total]));
console.log([...totals.entries()].map(([k, v]) => `${k}=${v}`).join(', '));
const sum = inv.reduce((s, it) => s + it.total, 0);
console.log('sum', sum.toFixed(2), Math.round(sum * 100) / 100);
const expensive = inv.filter(({ total }) => total > 10).map(({ name }) => name.toUpperCase());
console.log(expensive);
const { name, ...rest } = inv[0];
console.log(name, rest, Object.keys(rest));
try { inv[0].id = 5 } catch (e) { console.log(e.constructor.name, e.message) }
console.log(inv[0].id, Item.count, Object.getOwnPropertyNames(Item.prototype));
console.log(inv.map(i => i instanceof Perishable), Perishable.count, Object.hasOwn(Perishable, 'count'));
label: for (const a of inv) { for (const b of inv) { if (a !== b && a.total === b.total) { console.log('dup', a.name, b.name); break label; } } }
console.log([..."hello world"].reduce((m, c) => (m[c] = (m[c] || 0) + 1, m), {}));
const words = 'the quick brown fox jumps over the lazy dog the end'.split(' ');
const freq = words.reduce((m, w) => m.set(w, (m.get(w) ?? 0) + 1), new Map());
console.log([...freq].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 3));
console.log(Array.from({ length: 5 }, (_, i) => i ** 2).join(' '), [3, 1, 2].toSorted(), [1, 2, 3].at(-1));
function* fibGen() { let [a, b] = [0, 1]; while (true) { yield a; [a, b] = [b, a + b]; } }
const fibs = []; for (const f of fibGen()) { if (f > 100) break; fibs.push(f); }
console.log(fibs.join(','));
console.log(Iterator.from(fibGen()).filter(x => x % 2).take(5).toArray());
