const sleep = (ms, v) => new Promise(r => setTimeout(() => r(v), ms));
const log = (...a) => console.log(...a);
async function worker(id, jobs, results) {
  for (const job of jobs) {
    await sleep(job.ms);
    if (job.fail) throw new Error(`job ${job.name} failed in worker ${id}`);
    results.push(`${id}:${job.name}`);
  }
  return id;
}
async function main() {
  const results = [];
  const jobs = [[{ name: 'a', ms: 5 }, { name: 'b', ms: 1 }], [{ name: 'c', ms: 2 }, { name: 'd', ms: 2 }], [{ name: 'e', ms: 1, fail: true }]];
  const settled = await Promise.allSettled(jobs.map((j, i) => worker(i, j, results)));
  log(settled.map(s => s.status + ':' + (s.value ?? s.reason.message)).join(' | '));
  log(results.join(','));
  const first = await Promise.race([sleep(10, 'slow'), sleep(1, 'fast')]);
  log('race', first);
  const any = await Promise.any([Promise.reject(new Error('x')), sleep(3, 'any-ok')]);
  log('any', any);
  try { await Promise.any([Promise.reject(new Error('x1')), Promise.reject(new Error('x2'))]) } catch (e) { log(e.constructor.name, e.message, e.errors.map(x => x.message)) }
  const order = [];
  setTimeout(() => order.push('timeout'), 0);
  queueMicrotask(() => order.push('micro1'));
  Promise.resolve().then(() => order.push('then1')).then(() => order.push('then2'));
  process.nextTick(() => order.push('tick'));
  await null;
  order.push('after-await');
  await sleep(5);
  log(order.join(' '));
  async function* gen() { for (let i = 0; i < 3; i++) { await sleep(1); yield i * 10; } }
  const collected = [];
  for await (const v of gen()) collected.push(v);
  log('agen', collected);
  const { promise, resolve } = Promise.withResolvers();
  setTimeout(resolve, 2, 'resolved-later');
  log(await promise);
  const timeoutP = (p, ms) => Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))]);
  try { await timeoutP(sleep(50), 5) } catch (e) { log('caught', e.message) }
  const results2 = await Promise.all([1, Promise.resolve(2), sleep(1, 3), { then(r) { r(4) } }]);
  log(results2);
  const it = setInterval(() => { order.push('iv'); }, 1);
  await sleep(10);
  clearInterval(it);
  log('intervals>0', order.filter(x => x === 'iv').length > 0);
  return 'done';
}
main().then(v => log('main', v), e => log('main error', e));
log('sync end');

