const log = (...a) => console.log(...a);
const ares = (n, fail) => ({ async [Symbol.asyncDispose]() { log('adispose start', n); await null; log('adispose end', n); if (fail) throw new Error('afail ' + n) } });
const sres = (n, fail) => ({ [Symbol.dispose]() { log('sdispose', n); if (fail) throw new Error('sfail ' + n) } });
async function a1() {
  await using x = ares('x');
  using y = sres('y');
  await using z = ares('z');
  log('body a1');
  return 'a1 ret';
}
async function a2() {
  try {
    await using x = ares('x2', true);
    await using y = ares('y2', true);
    throw new Error('body2');
  } catch (e) {
    log('a2 caught', e.constructor.name, e.error && e.error.message, e.suppressed && (e.suppressed.message || (e.suppressed.error && e.suppressed.error.message)));
  }
}
async function a3() {
  for await (const v of [1, 2]) {
    await using r = ares('loop' + v);
    log('loop body', v);
  }
  for (await using r of [ares('of1'), ares('of2')]) { log('for-await-using body'); }
}
function* g1() {
  using r = sres('gen');
  yield 1;
  yield 2;
}
async function main() {
  log(await a1());
  await a2();
  await a3();
  const it = g1();
  log(it.next().value);
  log(it.return('early').value);
  const it2 = g1();
  it2.next();
  try { it2.throw(new Error('gen throw')) } catch (e) { log('gen caught', e.message) }
  log('ticks');
  const order = [];
  const p = (async () => { await using q = { async [Symbol.asyncDispose]() { order.push('dispose') } }; order.push('body'); })();
  Promise.resolve().then(() => order.push('t1')).then(() => order.push('t2')).then(() => order.push('t3'));
  await p;
  await null; await null;
  log(order.join(' '));
  {
    using n1 = null, n2 = undefined;
    log('nulls fine');
  }
  try { await (async () => { await using bad = 5 })() } catch (e) { log(e.constructor.name, e.message) }
  label: { using l = sres('label'); if (true) break label; log('not reached') }
  outer: for (let i = 0; i < 2; i++) { using c = sres('cont' + i); if (i === 0) continue outer; log('i1') }
}
main().then(() => log('main done'), e => log('main error', e));

