fn species_constructor(vm: &mut Vm, o: &Obj, default: &Value) -> JsResult<Value> {
    let c = vm.get(o, &vm.intr.key_constructor.clone(), &Value::Obj(o.clone()))?;
    if c.is_undefined() {
