fn ab_resize(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let b = match &a.this {
        Value::Obj(o) => match &o.borrow().kind {
            ObjKind::ArrayBuffer(b) => Some(b.clone()),
            _ => None,
        },
        _ => None,
    };
    let b = match b {
        Some(b) => b,
        None => return vm.throw_type("ArrayBuffer is not resizable"),
    };
    let max = match b.borrow().max_len {
        Some(m) if !b.borrow().detached && !b.borrow().immutable => m,
        _ => return Err(vm.make_error("TypeError", "ArrayBuffer is not resizable")),
    };
    let n = vm.to_index_msg(&a.arg(0), "ArrayBuffer resize out of range")?;
    if n > max {
        return vm.throw_range("ArrayBuffer resize out of range");
    }
    b.borrow_mut().bytes.resize(n, 0);
    Ok(Value::Undefined)
}

