1544	fn ta_to_locale_string(vm: &mut Vm, a: &Args) -> JsResult<Value> {
1545	    let (o, _, len) = this_ta(vm, &a.this)?;
1546	    let mut out: Vec<u16> = Vec::new();
1547	    for i in 0..len {
1548	        if i > 0 {
1549	            out.push(b',' as u16);
1550	        }
1551	        let v = ta_get(&o, i);
1552	        let f = vm.get_prop_of(&v, &PropKey::from_str("toLocaleString"))?;
1553	        let r = vm.call(&f, v, &[])?;
1554	        let s = vm.to_string(&r)?;
1555	        out.extend_from_slice(s.units());
1556	    }
1557	    Ok(Value::Str(JsStr::from_units(out)))
1558	}
