1563	    match v {
1564	        Value::Obj(o) if matches!(&o.borrow().kind, ObjKind::TypedArray(t) if t.kind == TAKind::Uint8) => Ok(o.clone()),
1565	        _ => vm.throw_type("this is not a Uint8Array"),
