1569	fn u8_to_base64(vm: &mut Vm, a: &Args) -> JsResult<Value> {
1570	    let o = this_u8(vm, &a.this)?;
1571	    let mut url = false;
1572	    let mut omit = false;
1573	    if let Value::Obj(opts) = a.arg(0) {
1574	        let al = vm.get_str(&opts, "alphabet")?;
1575	        if let Value::Str(s) = al {
1576	            url = s.eq_str("base64url");
1577	        }
1578	        omit = vm.get_str(&opts, "omitPadding")?.truthy();
1579	    }
1580	    let bytes = ta_bytes(&o);
1581	    let mut s = crate::runtime::encoding::base64_encode(&bytes, url);
1582	    if omit {
1583	        while s.ends_with('=') {
1584	            s.pop();
1585	        }
1586	    }
1587	    Ok(Value::str(&s))
1588	}
