1619	fn u8_set_from(vm: &mut Vm, a: &Args, bytes: Option<Vec<u8>>) -> JsResult<Value> {
1620	    let o = this_u8(vm, &a.this)?;
1621	    let bytes = match bytes {
1622	        Some(b) => b,
1623	        None => return vm.throw_syntax("invalid input string"),
1624	    };
1625	    let len = match &o.borrow().kind {
1626	        ObjKind::TypedArray(t) => t.len(),
1627	        _ => 0,
1628	    };
1629	    let n = bytes.len().min(len);
1630	    for (i, b) in bytes.iter().take(n).enumerate() {
1631	        ta_set_index(vm, &o, i as f64, &Value::Num(*b as f64))?;
1632	    }
1633	    let r = vm.new_object();
1634	    r.set_str("read", Value::Num(0.0), WEC);
1635	    r.set_str("written", Value::Num(n as f64), WEC);
1636	    Ok(Value::Obj(r))
1637	}
