1659	fn atomic_target(vm: &mut Vm, a: &Args) -> JsResult<(Obj, TAKind, usize)> {
1660	    let (o, k, len) = match &a.arg(0) {
1661	        Value::Obj(o) => {
1662	            let r = match &o.borrow().kind {
1663	                ObjKind::TypedArray(t) => Some((t.kind, t.len())),
1664	                _ => None,
1665	            };
1666	            match r {
1667	                Some((k, l)) => (o.clone(), k, l),
1668	                None => return vm.throw_type("Atomics: not an integer TypedArray"),
1669	            }
1670	        }
1671	        _ => return vm.throw_type("Atomics: not an integer TypedArray"),
1672	    };
1673	    if matches!(k, TAKind::Float16 | TAKind::Float32 | TAKind::Float64 | TAKind::Uint8C) {
1674	        return vm.throw_type("Atomics requires an integer TypedArray");
1675	    }
1676	    let idx = vm.to_index_msg(&a.arg(1), "Atomics: index out of range")?;
1677	    if idx >= len {
1678	        return vm.throw_range("Atomics: index out of range");
1679	    }
